window.__D("text/zohar-hebrew-translation/c012",{"p":[[9522011521,"<p>רַבִּי שִׁמְעוֹן הֵרִים יָדָיו, וּבָכָה וְאָמַר, אוֹי לְמִי שֶׁיִּזְדַּמֵּן בְּאוֹתוֹ זְמַן, וְאַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיִּזְדַּמֵּן בְּאוֹתוֹ זְמַן. אוֹי לְמִי שֶׁיִּזְדַּמֵּן בְּאוֹתוֹ זְמַן - מִשּׁוּם שֶׁכְּשֶׁיָּבֹא הַקָּדוֹשׁ בָּרוּךְ הוּא לִפְקֹד אֶת הָאַיָּלָה, יִסְתַּכֵּל מִי הֵם אוֹתָם שֶׁעָמְדוּ עִמָּהּ, בְּכָל אוֹתָם שֶׁנִּמְצָאִים עִמָּהּ, בְּכָל מַעֲשֵׂי כָּל אֶחָד וְאֶחָד, וְלֹא יִמָּצֵא צַדִּיק, שֶׁכָּתוּב (ישעיה סג) וְאַבִּיט וְאֵין עוֹזֵר. וְכַמָּה צָרוֹת עַל צָרוֹת לְיִשְׂרָאֵל.</p>\n<p>אַשְׁרֵי מִי שֶׁיִּזְדַּמֵּן וְיִמָּצֵא בְּאוֹתוֹ הַזְּמַן - מִשּׁוּם שֶׁאוֹתוֹ שֶׁיַּעֲמֹד בְּאוֹתוֹ זְמַן בֶּאֱמוּנָה, יִזְכֶּה לְאוֹתוֹ אוֹר שֶׁל שִׂמְחַת הַמֶּלֶךְ, וְעַל אוֹתוֹ זְמַן כָּתוּב (זכריה יג) וּצְרַפְתִּים כִּצְרֹף אֶת הַכֶּסֶף וּבְחַנְתִּים כִּבְחֹן אֶת הַזָּהָב וְגוֹ'.</p>\n<p>לְאַחַר שֶׁאוֹתָן צָרוֹת יִתְעוֹרְרוּ עַל יִשְׂרָאֵל, וְכָל הָעַמִּים וּמַלְכֵיהֶם יִתְיָעֲצוּ כְּאֶחָד עֲלֵיהֶם, וּמְעוֹרְרִים כַּמָּה גְזֵרוֹת רָעוֹת, וְכֻלָּם עוֹלִים בְּעֵצָה אַחַת עֲלֵיהֶם, וְיָבאוּ צָרָה עַל צָרָה, אַחֲרוֹנוֹת מְשַׁכְּחוֹת אֶת הָרִאשׁוֹנוֹת, אָז יִתְרָאֶה עַמּוּד אֵשׁ אֶחָד עוֹמֵד מִלְמַעְלָה לְמַטָּה אַרְבָּעִים יוֹם, וְכָל עַמֵּי הָאָרֶץ רוֹאִים אוֹתוֹ.</p>\n<p>בְּאוֹתוֹ זְמַן יִתְעוֹרֵר מֶלֶךְ הַמָּשִׁיחַ לָצֵאת מִתּוֹךְ גַּן עֵדֶן מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא קַ\"ן צִפּוֹ\"ר, וְיִתְעוֹרֵר בְּאֶרֶץ הַגָּלִיל. וְאוֹתוֹ יוֹם שֶׁיֵּצֵא לְשָׁם, יִתְרַגֵּז כָּל הָעוֹלָם, וְכָל בְּנֵי הָעוֹלָם מִתְחַבְּאִים בְּתוֹךְ מְעָרוֹת וּסְלָעִים שֶׁלֹּא יַחְשְׁבוּ לְהִנָּצֵל, וְעַל אוֹתוֹ זְמַן כָּתוּב (ישעיה ב) וּבָאוּ בִּמְעָרוֹת צֻרִים וּבִמְחִלּוֹת עָפָר מִפְּנֵי פַּחַד ה' וּמֵהֲדַר גְּאוֹנוֹ בְּקוּמוֹ לַעֲרֹץ הָאָרֶץ.</p>\n<p>מִפְּנֵי פַּחַד ה' - זֶהוּ אוֹתוֹ רֹגֶז שֶׁל כָּל הָעוֹלָם. וּמֵהֲדַר גְּאוֹנוֹ - זֶה מָשִׁיחַ. בְּקוּמוֹ לַעֲרֹץ הָאָרֶץ - כְּשֶׁיָּקוּם וְיִתְגַּלֶּה בְּאֶרֶץ הַגָּלִיל, מִשּׁוּם שֶׁהוּא מָקוֹם רִאשׁוֹן שֶׁנֶּחֱרַב בָּאָרֶץ הַקְּדוֹשָׁה, וְלָכֵן יִתְגַּלֶּה שָׁם רִאשׁוֹן לְכָל מָקוֹם, וּמִשָּׁם יְעוֹרֵר קְרָבוֹת לְכָל הָעוֹלָם.</p>\n<p>אַחַר אַרְבָּעִים יוֹם שֶׁעַמּוּד יַעֲמֹד מֵאֶרֶץ לַשָּׁמַיִם לְעֵינֵי כָּל הָעוֹלָם וְיִתְגַּלֶּה הַמָּשִׁיחַ, יָקוּם מִצַּד מִזְרָח כּוֹכָב אֶחָד לוֹהֵט בְּכָל הַגְוָנִים, וְשִׁבְעָה כוֹכָבִים אֲחֵרִים שֶׁסּוֹבְבִים אוֹתוֹ הַכּוֹכָב, וְיַעַרְכוּ בוֹ קְרָב בְּכָל הַצְּדָדִים שָׁלֹשׁ פְּעָמִים בְּיוֹם, עַד שִׁבְעִים יוֹם, וְכָל בְּנֵי הָעוֹלָם רוֹאִים.</p>\n<p>וְאוֹתוֹ כּוֹכָב יַעֲרֹךְ בָּהֶם קְרָב בְּלַפִּידֵי אֵשׁ לוֹהֲטִים וְנוֹצְצִים לְכָל עֵבֶר, וּמַכֶּה בָהֶם עַד שֶׁבּוֹלֵעַ אוֹתָם בְּכָל עֶרֶב וְעֶרֶב, וּבַיּוֹם מוֹצִיא אוֹתָם. וְיַעַרְכוּ קְרָב לְעֵינֵי כָּל הָעוֹלָם, וְכֵן בְּכָל יוֹם עַד שִׁבְעִים יוֹם. לְאַחַר שִׁבְעִים יוֹם יִגָּנֵז אוֹתוֹ כּוֹכָב, וְיִגָּנֵז הַמָּשִׁיחַ עַד שְׁנֵים עָשָׂר חֳדָשִׁים, וְיַחֲזר אוֹתוֹ עַמּוּד אֵשׁ כְּמוֹ מִקֹּדֶם, וּבוֹ יִגָּנֵז הַמָּשִׁיחַ, וְאוֹתוֹ עַמּוּד לֹא יִתְרָאֶה.</p>\n<p>לְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ יַעֲלוּ אֶת הַמָּשִׁיחַ בְּאוֹתוֹ הָעַמּוּד לְתוֹךְ הָרָקִיעַ, וְשָׁם יְקַבֵּל חֹזֶק וַעֲטֶרֶת מַלְכוּת. וּכְשֶׁיֵּרֵד, יִתְרָאֶה אוֹתוֹ עַמּוּד אֵשׁ כְּמוֹ מִקֹּדֶם לְעֵינֵי כָּל הָעוֹלָם, וְאַחַר כָּךְ יִתְגַּלֶּה הַמָּשִׁיחַ, וְיִתְכַּנְּסוּ אֵלָיו עַמִּים רַבִּים, וִיעוֹרֵר קְרָבוֹת בְּכָל הָעוֹלָם. וּבְאוֹתוֹ זְמַן יְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת גְּבוּרָתוֹ לְכָל עַמֵּי הָעוֹלָם, וּמֶלֶךְ הַמָּשִׁיחַ יִוָּדַע בְּכָל הָעוֹלָם, וְכָל מַלְכֵי הָעוֹלָם יִתְעוֹרְרוּ לְהִתְחַבֵּר לַעֲרֹךְ בּוֹ קְרָב.</p>\n<p>וְכַמָּה (עמים) מִפָּרִיצֵי הַיְּהוּדִים יִתְהַפְּכוּ לַחֲזֹר אֲלֵיהֶם, וְיָבֹאוּ עִמָּהֶם לַעֲרֹךְ קְרָב עַל מֶלֶךְ הַמָּשִׁיחַ, וְאָז יֶחְשַׁךְ כָּל הָעוֹלָם חֲמִשָּׁה עָשָׂר יוֹם, וְרַבִּים מֵעַם יִשְׂרָאֵל יָמוּתוּ בְּאוֹתוֹ חֹשֶׁךְ. וְעַל זֶה כָּתוּב (ישעיה ס) כִּי הִנֵּה הַחֹשֶׁךְ יְכַסֶּה אֶרֶץ וַעֲרָפֶל לְאֻמִּים.</p>\n<p>פָּתַח וְאָמַר, (דברים כב) כִּי יִקָּרֵא קַן צִפּוֹר לְפָנֶיךְ בַּדֶּרֶךְ בְּכָל עֵץ אוֹ עַל הָאָרֶץ אֶפְרֹחִים אוֹ בֵיצִים וְהָאֵם רֹבֶצֶת וְגוֹ', שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם וְגוֹ'. פָּסוּק זֶה בֵּאַרְנוּ אוֹתוֹ, וְהוּא אֶחָד מִמִּצְווֹת הַתּוֹרָה הַגְּנוּזוֹת, וְלָנוּ יֵשׁ בּוֹ סוֹדוֹת תּוֹרָה גְּנוּזִים, שְׁבִילִים וּדְרָכִים יְדוּעוֹת לַחֲבֵרִים בְּאוֹתָם שְׁלֹשִׁים וּשְׁנַיִם נְתִיבוֹת הַתּוֹרָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אֶלְעָזָר בְּנוֹ, אֶלְעָזָר, בִּזְמַן שֶׁיִּתְעוֹרֵר מֶלֶךְ הַמָּשִׁיחַ, כַּמָּה אוֹתוֹת וְנִסִּים אֲחֵרִים יִתְעוֹרְרוּ בָּעוֹלָם. בֹּא רְאֵה, בְּגַן עֵדֶן שֶׁלְּמַטָּה יֵשׁ מָקוֹם אֶחָד גָּנוּז וְשָׁמוּר שֶׁלֹּא נוֹדָע, וְהוּא מְרֻקָּם בְּכַמָּה גְוָנִים, וּבוֹ גְנוּזִים אֶלֶף הֵיכָלוֹת שֶׁל כִּסּוּפִים, וְאֵין מִי שֶׁיִּכָּנֵס בָּהֶם פְּרָט לַמָּשִׁיחַ, שֶׁהוּא עוֹמֵד תָּמִיד בְּגַן עֵדֶן.</p>\n<p>וְכָל הַגָּן מֻקָּף בְּמֶרְכָּבוֹת רַבּוֹת שֶׁל צַדִּיקִים, וּמָשִׁיחַ עוֹמֵד עֲלֵיהֶם וְעַל כַּמָּה חֲיָלוֹת וּמַחֲנוֹת שֶׁל נִשְׁמוֹת צַדִּיקִים שָׁם, וּבְרָאשֵׁי חֳדָשִׁים וְחַגִּים וְשַׁבָּתוֹת נִכְנָס מָשִׁיחַ לְאוֹתוֹ מָקוֹם לְהִשְׁתַּעֲשֵׁעַ בְּכָל אוֹתָם הֵיכָלוֹת.</p>\n<p>לִפְנַי וְלִפְנִים מִכָּל אוֹתָם הֵיכָלוֹת יֵשׁ מָקוֹם אַחֵר טָמִיר וְגָנוּז שֶׁלֹּא נוֹדָע כְּלָל, וְנִקְרָא עֵדֶן, וְאֵין מִי שֶׁיָּכוֹל לָדַעַת אוֹתוֹ, וּמָשִׁיחַ גָּנוּז בַּחוּץ סְבִיב אוֹתוֹ מָקוֹם, עַד שֶׁנִּתְגַּלָּה לוֹ מָקוֹם אֶחָד שֶׁנִּקְרָא קַן צִפּוֹר, וְהוּא מָקוֹם שֶׁמַּכְרִיזָה עָלָיו אוֹתָהּ צִפּוֹר שֶׁמִּתְעוֹרֶרֶת בְּגַן עֵדֶן בְּכָל יוֹם.</p>\n<p>וּבְאוֹתוֹ מָקוֹם רְקוּמִים דְּיוֹקְנָאוֹת שֶׁל כָּל שְׁאָר הָעַמִּים שֶׁהִתְכַּנְּסוּ עַל יִשְׂרָאֵל לְהָרַע לָהֶם. נִכְנָס לְאוֹתוֹ מָקוֹם, מֵרִים עֵינָיו וְרוֹאֶה אֶת הָאָבוֹת שֶׁנִּכְנָסִים לְחֻרְבַּן בֵּית הָאֱלֹהִים, עַד שֶׁרוֹאֶה אֶת רָחֵל שֶׁדִּמְעוֹתֶיהָ בְּפָנֶיהָ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְנַחֵם אוֹתָהּ, וְלֹא מַסְכִּימָה לְקַבֵּל תַּנְחוּמִים, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) מֵאֲנָה לְהִנָּחֵם עַל בָּנֶיהָ. אָז מָשִׁיחַ מֵרִים קוֹלוֹ וּבוֹכֶה, וּמִזְדַּעֲזֵעַ כָּל גַּן הָעֵדֶן, וְכָל אוֹתָם צַדִּיקִים שֶׁשָּׁם גּוֹעִים וּבוֹכִים עִמּוֹ.</p>\n<p>גּוֹעָה וּבוֹכֶה פַּעַם שְׁנִיָּה, וּמִזְדַּעֲזֵעַ אוֹתוֹ רָקִיעַ שֶׁעַל גַּבֵּי הַגָּן, אֶלֶף וַחֲמֵשׁ מֵאוֹת רִבּוֹא מַחֲנוֹת עֶלְיוֹנִים, עַד שֶׁמַּגִּיעַ לְתוֹךְ הַכִּסֵּא הָעֶלְיוֹן, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹמֵז לְאוֹתָהּ צִפּוֹר, וְנִכְנֶסֶת לְאוֹתוֹ קֵן שֶׁלָּהּ וְיוֹשֶׁבֶת אֵצֶל הַמָּשִׁיחַ, וְקוֹרֵא מַה שֶּׁקּוֹרֵא, וּמִתְעוֹרֵר מַה שֶּׁמִּתְעוֹרֵר.</p>\n<p>עַד שֶׁמִּתּוֹךְ הַכִּסֵּא הַקָּדוֹשׁ נִקְרָא שָׁלֹשׁ פְּעָמִים אוֹתוֹ קַן צִפּוֹר, וְהַמָּשִׁיחַ, וְכֻלָּם עוֹלִים לְמַעְלָה, וּמַשְׁבִּיעַ אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִיר מַלְכוּת הָרִשְׁעָה מִן הָעוֹלָם עַל יְדֵי הַמָּשִׁיחַ וְלִנְקֹם אֶת נִקְמוֹת יִשְׂרָאֵל, וְכָל אוֹתָן טוֹבוֹת שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לְעַמּוֹ. וְשָׁב אוֹתוֹ קַן צִפּוֹר וְהַמָּשִׁיחַ לִמְקוֹמוֹ, וְשָׁב הַמָּשִׁיחַ וְנִגְנָז לְתוֹךְ אוֹתוֹ מָקוֹם כְּמוֹ מִקֹּדֶם.</p>\n<p>וּבִזְמַן שֶׁיִּתְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא לְתַקֵּן אֶת הָעוֹלָמוֹת וּמְאִירוֹת אוֹתִיּוֹת שְׁמוֹ בִּשְׁלֵמוּת, יוֹ\"ד בְּהֵ\"א (לתקן) וָא\"ו בְּהֵ\"א, לִהְיוֹת הַכֹּל בִּשְׁלֵמוּת אַחַת, אָז יִתְעוֹרֵר כּוֹכָב אֶחָד מַפְחִיד בְּאֶמְצַע הָרָקִיעַ כְּגוֹן אַרְגָּמָן, לוֹהֵט וְנוֹצֵץ בַּיּוֹם לְעֵינֵי כָּל הָעוֹלָם.</p>\n<p>וְתָקוּם שַׁלְהֶבֶת אֵשׁ אַחַת מִצַּד צָפוֹן, תּוֹךְ הָרָקִיעַ, וְתָקוּם זֶה כְּנֶגֶד זֶה אַרְבָּעִים יוֹם, וְיִבָּהֲלוּ כָּל בְּנֵי הָעוֹלָם. לְסוֹף אַרְבָּעִים יוֹם יַעַרְכוּ קְרָב הַכּוֹכָב וְהַשַּׁלְהֶבֶת לְעֵינֵי הַכֹּל, וְתִתְפַּשֵּׁט אוֹתָהּ שַׁלְהֶבֶת בִּשְׂרֵפַת אֵשׁ מִצַּד הַצָּפוֹן, תּוֹךְ הָרָקִיעַ, וְיַחְשּב לִבְלֹעַ אוֹתוֹ כּוֹכָב, וְכַמָּה שַׁלִּיטִים וּמְלָכִים וְאֻמּוֹת וְעַמִּים יִתְבַּהֲלוּ מִזֶּה.</p>\n<p>אָז יִסְתַּלֵּק אוֹתוֹ כּוֹכָב לְצַד דָּרוֹם וְיִשְׁלֹט עַל אוֹתָהּ שַׁלְהֶבֶת, וְאוֹתָהּ שַׁלְהֶבֶת תִּבָּלַע מְעַט מְעַט בָּרָקִיעַ מִלִּפְנֵי אוֹתוֹ כּוֹכָב, עַד שֶׁלֹּא תֵרָאֶה כְּלָל. אָז אוֹתוֹ כּוֹכָב יַעֲשֶׂה דְרָכִים בָּרָקִיעַ בִּשְׁנֵים עָשָׂר תְּחוּמִים, וְעוֹמְדִים אוֹתָם אוֹרוֹת בָּרָקִיעַ שְׁנֵים עָשָׂר יָמִים נוֹסָפִים.</p>\n<p>אַחַר שְׁנֵים עָשָׂר יָמִים נוֹסָפִים יִזְדַּעְזְעוּ כָּל בְּנֵי הָעוֹלָם, וְיֶחְשַׁךְ הַשֶּׁמֶשׁ בַּחֲצוֹת הַיּוֹם, כְּמוֹ שֶׁנֶּחְשַׁךְ בַּיּוֹם שֶׁחָרַב בֵּית הַמִּקְדָּשׁ, עַד שֶׁלֹּא יֵרָאוּ שָׁמַיִם וָאָרֶץ. וְיִתְעוֹרֵר קוֹל אֶחָד בִּרְעָמִים וּבְרָקִים, וְתִתְחַלְחֵל הָאָרֶץ מֵאוֹתוֹ קוֹל, וְכַמָּה חֲיָלוֹת וּמַחֲנוֹת יָמוּתוּ מִמֶּנּוּ.</p>\n<p>וְאוֹתוֹ יוֹם תִּתְעוֹרֵר בָּעִיר רוֹמִי רַבָּתִי שַׁלְהֶבֶת אֵשׁ אַחַת, בְּאוֹתוֹ קוֹל שֶׁיִּתְעוֹרֵר בְּכָל הָעוֹלָם, וְיִשְׂרֹף כַּמָּה מִגְדָּלִים וְכַמָּה הֵיכָלוֹת, וְכַמָּה מִגְדָּלִים יִפְּלוּ, וְכַמָּה גְדוֹלִים וְשָׂרִים יִפְּלוּ בְּאוֹתוֹ יוֹם, וְכֻלָּם יִתְכַּנְּסוּ עָלֶיהָ לְרַע, וְכָל בְּנֵי הָעוֹלָם לֹא יוּכְלוּ (יחשבו) לְהִנָּצֵל.</p>\n<p>מֵאוֹתוֹ יוֹם וְעַד שְׁנֵים עָשָׂר חֳדָשִׁים יִתְיָעֲצוּ כָּל הַמְּלָכִים וְיִגְזְרוּ כַּמָּה גְזֵרוֹת וְכַמָּה שְׁמָדוֹת עַל יִשְׂרָאֵל, וְיַצְלִיחוּ בָהֶם, כְּמוֹ שֶׁנִּתְבָּאֵר אַשְׁרֵי מִי שֶׁיִּהְיֶה שָׁם וְאַשְׁרֵי מִי שֶׁלֹּא יִהְיֶה שָׁם, וְכָל הָעוֹלָם יִהְיֶה בְּעִרְבּוּבְיָה גְדוֹלָה.</p>\n<p>לְסוֹף שְׁנֵים עָשָׂר חֳדָשִׁים יָקוּם שֵׁבֶט מִיִּשְׂרָאֵל, זֶה מֶלֶךְ הַמָּשִׁיחַ שֶׁיִּתְעוֹרֵר תּוֹךְ גַּן הָעֵדֶן, וְכָל אוֹתָם הַצַּדִּיקִים יְעַטְּרוּ אוֹתוֹ שָׁם, וְיַחְגְּרוּ לוֹ כְּלֵי זַיִן בְּאוֹתִיּוֹת רְשׁוּמוֹת שֶׁל כֵּלִים שֶׁל הַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>וְקוֹל יִתְפּוֹצֵץ בְּעַנְפֵי עֲצֵי הַגָּן, קוֹרֵא בְחַיִל וְאוֹמֵר: הִתְעוֹרְרוּ קְדוֹשִׁים עֶלְיוֹנִים, קוּמוּ מִלִּפְנֵי הַמָּשִׁיחַ, הֲרֵי זְמַן שֶׁתִּתְחַבֵּר אִשָּׁה בְּבַעְלָהּ, וּבַעְלָהּ רוֹצֶה לִנְקֹם לָהּ נְקָמוֹת בָּעוֹלָם וְלַהֲקִימָהּ, וּלְנַעֵר אוֹתָהּ מִן הֶעָפָר.</p>\n<p>אָז יָקוּמוּ כֻלָּם וְיַחְגְּרוּ אוֹתוֹ כְּמוֹ מִקֹּדֶם בִּכְלֵי זֵינוֹ. אַבְרָהָם מִימִינוֹ, יִצְחָק מִשְּׂמֹאלוֹ, יַעֲקֹב לְפָנָיו. מֹשֶׁה רוֹעֶה הַנֶּאֶמָן עַל כָּל אֵלּוּ הַצַּדִּיקִים הוֹלֵךְ וְרוֹקֵד בְּתוֹךְ גַּן הָעֵדֶן.</p>\n<p>כֵּיוָן שֶׁנִּתְקָן מָשִׁיחַ עַל יְדֵי צַדִּיקֵי גַּן הָעֵדֶן, יִכָּנֵס לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא קַ\"ן צִפּוֹ\"ר כְּמוֹ מִקֹּדֶם, וְרוֹאֶה שָׁם אוֹתוֹ דְיוֹקָן שֶׁל חֻרְבַּן בֵּית הַמִּקְדָּשׁ, וְכָל הַצַּדִּיקִים שֶׁנֶּהֶרְגוּ בוֹ, וְאָז נוֹטֵל מִשָּׁם (עשרה) לְבוּשִׁים, וְהֵם (נקראים) עֲשָׂרָה לְבוּשֵׁי קִנְאָה, וְיִגָּנֵז שָׁם אַרְבָּעִים יוֹם שֶׁלֹּא יִתְגַּלֶּה כְּלָל.</p>\n<p>לְסוֹף אַרְבָּעִים יוֹם קוֹל אֶחָד יִתְעוֹרֵר, וְיִקְרָא מִתּוֹךְ הַכִּסֵּא הָעֶלְיוֹן, אוֹתוֹ קַ\"ן צִפּוֹ\"ר בַּמֶּלֶךְ הַמָּשִׁיחַ שֶׁנִּגְנָז בּוֹ, וְאָז מַעֲלִים אוֹתוֹ לְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה אֶת מֶלֶךְ הַמָּשִׁיחַ מִתְלַבֵּשׁ בִּלְבוּשׁ נְקָמָה וְחָגוּר כְּלֵי קְרָב, נוֹטֵל אוֹתוֹ וּמְנַשֵּׁק אוֹתוֹ עַל רֹאשׁוֹ.</p>\n<p>אָז מִזְדַּעְזְעִים שְׁלֹשׁ מֵאוֹת וְתִשְׁעִים רְקִיעִים, וְרוֹמֵז הַקָּדוֹשׁ בָּרוּךְ הוּא לְרָקִיעַ אֶחָד מֵאוֹתָם שֶׁהָיוּ גְנוּזִים מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית, וּמוֹצִיא מֵהֵיכָל אֶחָד שֶׁבְּאוֹתוֹ רָקִיעַ כֶּתֶר חָקוּק אֶחָד, מְחֻקָּק בַּשֵּׁמוֹת הַקְּדוֹשִׁים. בְּאוֹתָהּ עֲטָרָה הִתְעַטֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁעָבְרוּ יִשְׂרָאֵל אֶת הַיָּם, לִטֹּל נְקָמוֹת מִכָּל מַרְכְּבוֹת פַּרְעֹה וּפָרָשָׁיו, וּמְעַטֵּר אֶת מֶלֶךְ הַמָּשִׁיחַ בָּהּ.</p>\n<p>כֵּיוָן שֶׁהִתְעַטֵּר וְהִתְתַּקֵּן בְּכָל הַתִּקּוּנִים הַלָּלוּ, נוֹטֵל אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וּמְנַשֵּׁק אוֹתוֹ כְּמוֹ מִקֹּדֶם. מִי רָאָה מֶרְכָּבוֹת קְדוֹשׁוֹת וּמַחֲנוֹת עֶלְיוֹנִים שֶׁסּוֹבְבִים אוֹתוֹ וְנוֹתְנִים לוֹ מַתָּנוֹת וּמוֹתָרוֹת רַבּוֹת, וְיִתְעַטֵּר מִכֻּלָּם.</p>\n<p>נִכְנָס לְשָׁם לְהֵיכָל אֶחָד, וְרוֹאֶה כָּל אוֹתָם מַלְאָכִים עֶלְיוֹנִים שֶׁנִּקְרָאֵים אֲבֵלֵי צִיּוֹן, אוֹתָם שֶׁבָּכוּ עַל חֻרְבַּן בֵּית הַמִּקְדָּשׁ, וּבוֹכִים תָּמִיד, וְהֵם נוֹתְנִים לוֹ לְבוּשׁ אָדם אֶחָד לַעֲשׂוֹת נְקָמוֹת. אָז הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹנֵז אוֹתוֹ בְּאוֹתוֹ קַן צִפּוֹר, וּמִתְכַּסֶּה שָׁם שְׁלֹשִׁים יוֹם.</p>\n<p>לְאַחַר שְׁלֹשִׁים יוֹם, בְּאוֹתוֹ קַן צִפּוֹר, יֵרֵד מְעֻטָּר בְּכָל אוֹתָם תִּקּוּנִים מִמַּעְלָה וּמִמַּטָּה, כַּמָּה מַחֲנוֹת קְדוֹשִׁים סְבִיבוֹ, וְיִרְאוּ כָּל הָעוֹלָם אוֹר אֶחָד תָּלוּי מֵהָרָקִיעַ לָאָרֶץ, וְיַעֲמֹד שִׁבְעָה יָמִים, וְכָל בְּנֵי הָעוֹלָם יִתְמְהוּ וְיִבָּהֲלוּ, וְלֹא יֵדְעוּ כְּלָל, פְּרָט לְאוֹתָם חֲכָמִים שֶׁיּוֹדְעִים בַּסּוֹדוֹת הַלָּלוּ, אַשְׁרֵי חֶלְקָם.</p>\n<p>וְכָל אוֹתָם שִׁבְעָה יָמִים יִתְיַצֵּב (יתעטר) בָּאָרֶץ בְּאוֹתוֹ קַ\"ן צִפּוֹ\"ר. בְּאֵיזֶה מָקוֹם? בַּדֶּרֶךְ, זוֹ קְבוּרַת רָחֵל שֶׁעוֹמֶדֶת בְּפָרָשַׁת דְּרָכִים. וִיבַשֵּׂר לָהּ וִינַחֵם אוֹתָהּ, וְאָז תְּקַבֵּל תַּנְחוּמִים, וְתָקוּם וּתְנַשֵּׁק אוֹתוֹ.</p>\n<p>אַחַר כָּךְ יָקוּם אוֹתוֹ אוֹר מֵאוֹתוֹ מָקוֹם, וְשׁוֹרֶה בִּירִיחוֹ עִיר הָאִילָנוֹת. בְּכָל עֵץ - זֶה יְרִיחוֹ. אוֹ עַל הָאָרֶץ - זוֹ יְרוּשָׁלַיִם. וְיִהְיֶה גָנוּז בְּאוֹתוֹ אוֹר שֶׁל קַ\"ן צִפּוֹ\"ר שְׁנֵים עָשָׂר חֹדֶשׁ.</p>\n<p>אַחַר שְׁנֵים עָשָׂר חֹדֶשׁ יִזְדַּקֵּף אוֹתוֹ אוֹר בֵּין שָׁמַיִם וָאָרֶץ, וְיִשְׁרֶה בְּאֶרֶץ הַגָּלִיל, שֶׁשָּׁם הָיְתָה רֵאשִׁית גָּלוּת יִשְׂרָאֵל, וְשָׁם יִתְגַּלֶּה מֵאוֹתוֹ אוֹר שֶׁל קַן צִפּוֹר, וְשָׁב לִמְקוֹמוֹ. וְאוֹתוֹ יוֹם תִּזְדַּעֲזַע כָּל הָאָרֶץ כְּמוֹ מִקֹּדֶם מִסּוֹף הַשָּׁמַיִם עַד סוֹף הַשָּׁמַיִם, וְאָז יִרְאוּ (ידעו) כָּל הָעוֹלָם שֶׁהֲרֵי הִתְגַּלָּה מֶלֶךְ הַמָּשִׁיחַ בְּאֶרֶץ הַגָּלִיל.</p>\n<p>וְיִתְכַּנְּסוּ אֵלָיו כָּל אֵלּוּ שֶׁעוֹסְקִים בַּתּוֹרָה, וְהֵם מְעַטִּים בָּעוֹלָם. וּבִזְכוּת תִּינוֹקוֹת שֶׁל בֵּית רַבָּן יִתְחַזֵּק כֹּחוֹ לְהִתְגַּבֵּר, וְסוֹד זֶה אֶפְרֹחִים. וְאִם לֹא יִמָּצְאוּ אֵלּוּ, הֲרֵי תִּינוֹקוֹת שֶׁיּוֹשְׁבִים בְּתֹקֶף אִמָּם וְיוֹנְקִים, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כח) גְּמוּלֵי מֵחָלָב עַתִּיקֵי מִשָּׁדָיִם. וְהַיְנוּ אוֹ בֵיצִים, שֶׁבִּשְׁבִיל אֵלֶּה שׁוֹרָה שְׁכִינָה עִם יִשְׂרָאֵל בַּגָּלוּת.</p>\n<p>שֶׁהֲרֵי מְעַטִּים הַחֲכָמִים שֶׁיִּמָּצְאוּ בְּאוֹתוֹ זְמַן, וְהַיְנוּ (דברים כב) וְהָאֵם רֹבֶצֶת עַל הָאֶפְרֹחִים אוֹ עַל הַבֵּיצִים, לֹא תִקַּח הָאֵם עַל הַבָּנִים, (שהרי בו לא עומד הדבר להוציא מן הגלות אלא במלך העליון, שכיון שהם ילדים ותינוקות, נותנים תקף למלך המשיח, אז האמא העליונה, שהיא רובצת עליהם, מתעוררת לגבי בעלה) וְיִתְעַכֵּב (כך) עַד שְׁנֵים עָשָׂר חֳדָשִׁים אֲחֵרִים. אַחַר כָּךְ יָבֹא בַעְלָהּ וְיָקִים אוֹתָהּ מֵהֶעָפָר, כְּמוֹ שֶׁנֶּאֱמַר (עמוס ט) אָקִים אֶת סֻכַּת דָּוִיד הַנֹּפֶלֶת.</p>\n<p>בְּאוֹתוֹ יוֹם מֶלֶךְ הַמָּשִׁיחַ יַתְחִיל וְיִכְנֹס הַגָּלוּת מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (דברים ל) אִם יִהְיֶה נִדַּחֲךְ בִּקְצֵה הַשָּׁמָיִם וְגוֹ'. מֵאוֹתוֹ יוֹם כָּל הָאוֹתוֹת וְהַנִּסִּים וְהַגְּבוּרוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם, יַעֲשֶׂה אוֹתָם לְיִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּנִי, כָּל הַדְּבָרִים הַלָּלוּ תִּמְצָא בְּסוֹד שֶׁל שְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וְעַד שֶׁהַנִּסִּים הַלָּלוּ לֹא יִתְעוֹרְרוּ בָעוֹלָם, לֹא יִשְׁתַּלֵּם סוֹד הַשֵּׁם הַקָּדוֹשׁ וְלֹא תִתְעוֹרֵר לְאַהֲבָה, כְּמוֹ שֶׁנֶּאֱמַר (שיר ב) הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלם בִּצְבָאוֹת. בִּצְבָאוֹת - זֶה מֶלֶךְ (המשיח) שֶׁנִּקְרָא צְבָאוֹת. אוֹ בְּאַיְלוֹת הַשָּׂדֶה - שְׁאָר הַחֲיָלוֹת וְהַמַּחֲנוֹת שֶׁלְּמַטָּה. אִם תָּעִירוּ וְאִם תְּעוֹרְרוּ אֶת הָאַהֲבָה - זֶה יָמִין שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּקְרָא אַהֲבָ\"ה. עַד שֶׁתֶּחְפָּץ - אוֹתָהּ שֶׁשּׁוֹכֶבֶת לֶעָפָר, וְיִהְיֶה רְצוֹן הַמֶּלֶךְ בָּהּ. אַשְׁרֵי מִי שֶׁיִּזְכֶּה לְאוֹתוֹ דּוֹר. אַשְׁרָיו בָּעוֹלָם הַזֶּה וְאַשְׁרָיו בָּעוֹלָם הַבָּא.</p>\n<p>רַבִּי שִׁמְעוֹן הֵרִים יָדָיו בִּתְפִלָּה לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְהִתְפַּלֵּל תְּפִלָּתוֹ. אַחֲרֵי שֶׁהִתְפַּלֵּל תְּפִלָּתוֹ, בָּאוּ רַבִּי אֶלְעָזָר בְּנוֹ וְרַבִּי אַבָּא וְיָשְׁבוּ לְפָנָיו. עַד שֶׁהָיוּ יוֹשְׁבִים לְפָנָיו, רָאוּ אוֹר יוֹם אֶחָד שֶׁנֶּחְשָׁךְ וְנִשְׁקָע צִנּוֹר (צרור) אֶחָד שֶׁל שַׁלְהֶבֶת אֵשׁ בְּתוֹךְ הַיָּם שֶׁל טְבֶרְיָה, וְהִזְדַּעֲזַע כָּל אוֹתוֹ מָקוֹם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי עַכְשָׁו הוּא זְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִזְכָּר בְּבָנָיו וּמוֹרִיד שְׁתֵּי דְמָעוֹת לַיָּם הַגָּדוֹל, וְכַאֲשֶׁר יוֹרְדוֹת, הֵן פּוֹגְעוֹת בַּצִּנּוֹר הַזֶּה שֶׁל שַׁלְהֶבֶת אֵשׁ, וְיִשְׁתַּקְּעוּ זֶה בָּזֶה בַּיָּם. בָּכָה רַבִּי שִׁמְעוֹן וּבָכוּ הַחֲבֵרִים.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי הִתְעוֹרַרְנוּ בְּסוֹדוֹת הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ בְּסֵתֶר הַהִתְעוֹרְרוּת שֶׁלּוֹ אֶל בָּנָיו, אֲבָל עַכְשָׁו יֵשׁ לִי לְגַלּוֹת מַה שֶּׁלֹּא נִתְּנָה רְשׁוּת לְשׁוּם אָדָם אַחֵר לְגַלּוֹת, אֶלָּא זְכוּת הַדּוֹר הַזֶּה תַּעֲמִיד אֶת הָעוֹלָם עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ. אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אֶלְעָזָר בְּנוֹ וּלְרַבִּי אַבָּא, עִמְדוּ בְּעָמְדְכֶם. קָמוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא. בָּכָה רַבִּי שִׁמְעוֹן פַּעַם אַחֶרֶת וְאָמַר, אוֹי מִי יַעֲמֹד בְּמַה שֶּׁאָמַרְתִּי (שראיתי) שֶׁתִּמָּשֵׁךְ הַגָּלוּת, מִי יָכוֹל לִסְבֹּל?</p>\n<p>אַף הוּא קָם וְאָמַר, (עמוס ט) ה' אֱלֹהֵינוּ בְּעָלוּנוּ אֲדנִים זוּלָתֶךְ לְבַד בְּךְ נַזְכִּיר שְׁמֶךְ. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ, אֲבָל בְּפָסוּק זֶה יֵשׁ סוֹד עֶלְיוֹן בְּתוֹךְ הָאֱמוּנָה. ה' אֱלֹהֵינוּ - זֶהוּ רֵאשִׁית הַסּוֹדוֹת הָעֶלְיוֹנִים, מָקוֹם שֶׁמִּשָּׁם יוֹצְאִים כָּל הָאוֹרוֹת שֶׁל כָּל הַנֵּרוֹת כֻּלָּם לְהַדְלִיק, וְשָׁם תָּלוּי כָּל סוֹד הָאֱמוּנָה, שֵׁם זֶה שׁוֹלֵט עַל הַכֹּל.</p>\n<p>בְּעָלוּנוּ אֲדנִים זוּלָתֶךְ - שֶׁהֲרֵי עַל עַם יִשְׂרָאֵל אֵין מִי שֶׁשּׁוֹלֵט עָלָיו פְּרָט לַשֵּׁם הָעֶלְיוֹן הַזֶּה, וְעַכְשָׁו בַּגָּלוּת שׁוֹלֵט עָלָיו הַצַּד הָאַחֵר.</p>\n<p>לְבַד בְּ\"ךְ נַזְכִּיר שְׁמֶךְ - סוֹד הַשֵּׁם הַקָּדוֹשׁ, כְּלָל שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת, וּכְנֶסֶת יִשְׂרָאֵל לֹא מִתְבָּרֶכֶת אֶלָּא מִתּוֹךְ שֵׁם זֶה שֶׁנִּקְרָא בְּךְ, כְּמוֹ שֶׁנֶּאֱמַר (שמות לב) אֲשֶׁר נִשְׁבַּעְתָּ לָהֶם בָּךְ. (בראשית מח) בְּךְ יְבָרֵךְ יִשְׂרָאֵל. כִּי בְּךְ אָרוּץ גְּדוּד. וּבִזְמַן שֶׁנִּמְצֵאת שְׁלֵמוּת, לֹא הָיָה נִפְרָד זֶה מִזֶּה, וְאָסוּר לְהַפְרִיד זֶה מִזֶּה, אִשָּׁה מִבַּעְלָהּ, לֹא בְּרַעְיוֹנוֹת וְלֹא בְּאַזְכָּרָה, כְּדֵי לֹא לְהַרְאוֹת פֵּרוּד, וְעַכְשָׁו בַּגָּלוּת נִמְצָא פֵּרוּד, שֶׁמִּתּוֹךְ צָרָה שֶׁל כָּל זְמַן וּזְמַן אָנוּ עוֹשִׂים פֵּרוּד לְהַזְכִּיר אוֹתוֹ שֵׁם, פְּרָט לְבַעְלָהּ, מִשּׁוּם שֶׁהִיא שׁוֹכֶבֶת לֶעָפָר, וְהַיְנוּ לְבַד בְּךְ נַזְכִּיר שְׁמֶךְ.</p>\n<p>פְּרָט לְבַעְלָהּ, אָנוּ זוֹכְרִים שֵׁם זֶה בְּפֵרוּד מִשּׁוּם שֶׁאָנוּ רְחוֹקִים מִמְּךְ וַאֲחֵרִים שׁוֹלְטִים עָלֵינוּ, וְשִׁמְךְ הוּא בְּפֵרוּד מִן הַשֵּׁם שֶׁנִּקְרָא בְּךְ, וְזֶה בִּימֵי הַגָּלוּת.</p>\n<p>מִשּׁוּם שֶׁגָּלוּת רִאשׁוֹנָה הָיְתָה מִבַּיִת רִאשׁוֹן, וּבַיִת רִאשׁוֹן הוּא סוֹד שֶׁל ה' רִאשׁוֹנָה, וּכְנֶגֶד שִׁבְעִים שָׁנָה שֶׁלָּהּ גָּלוּת שֶׁל בַּיִת רִאשׁוֹן הָיְתָה שִׁבְעִים שָׁנָה, וְאוֹתָם שִׁבְעָה שָׁנָה לֹא נִמְצֵאת הָאֵם רוֹבֶצֶת עֲלֵיהֶם, וְהָיָה פֵּרוּד מִן הַשֵּׁם הָעֶלְיוֹן, סוֹד שֶׁל ה' הָעֶלְיוֹנָה. וְאָז יוֹ\"ד, סוֹד עֶלְיוֹן, הִתְעַלָּה לְמַעְלָה לְמַעְלָה לְאֵין סוֹף, וְהַבַּיִת הָרִאשׁוֹן הָעֶלְיוֹן הַקָּדוֹשׁ לֹא הִנְבִּיעַ נְבִיעַת מַיִם חַיִּים, שֶׁהֲרֵי מְקוֹרָהּ הִסְתַּלֵּק.</p>\n<p>וְהִיא שִׁבְעִים שָׁנָה בַּגָּלוּת, מִשּׁוּם שֶׁהִיא נִקְרֵאת שֶׁבַע שָׁנִים, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ו) וַיִּבְנֵהוּ שֶׁבַע שָׁנִים. וְאִם תֹּאמַר שֶׁשָּׁלְטָה מַלְכות בָּבֶל לְמַעְלָה בְּסוֹד שֶׁל שִׁבְעִים שָׁנָה - חַס וְחָלִילָה. אֶלָּא בִּזְמַן שֶׁהָיָה בֵּית הַמִּקְדָּשׁ קַיָּם, הָאוֹר וּנְבִיעַת הָאֵם הָעֶלְיוֹנָה (בינה) הָיָה מֵאִיר וְיוֹרֵד לְמַטָּה. כֵּיוָן שֶׁחָטְאוּ יִשְׂרָאֵל וְנֶחֱרַב הַמִּקְדָּשׁ וְשָׁלְטָה מַלְכוּת בָּבֶל, הָיָה מְכַסֶּה וּמַחְשִׁיךְ אוֹתוֹ אוֹר, וְהַתַּחְתּוֹנִים הַקְּדוֹשִׁים לֹא הָיוּ מְאִירִים.</p>\n<p>כֵּיוָן שֶׁהַתַּחְתּוֹנִים לֹא הָיוּ מְאִירִים, מִשּׁוּם (מתוך) שִׁלְטוֹן מַלְכוּת בָּבֶל, הִסְתַּלֵּק אוֹתוֹ אוֹר, וְאוֹתוֹ מַעְיָן עֶלְיוֹן שֶׁהָיָה נוֹבֵעַ סוֹד שֶׁל י' הִסְתַּלֵּק לְמַעְלָה לְמַעְלָה לְאֵין סוֹף, אָז אוֹתָם שִׁבְעִים שָׁנָה לֹא הָיוּ מְאִירִים, מִשּׁוּם אוֹתוֹ אוֹר שֶׁנִּמְנָע. וְזוֹהִי וַדַּאי גָּלוּת שֶׁל שִׁבְעִים שָׁנָה.</p>\n<p>וְכֵּיוָן שֶׁהָעֳבַר שִׁלְטוֹן בָּבֶל, וְהִתְחִילָה הֵ\"א תַּחְתּוֹנָה לְהָאִיר, לֹא כָּל יִשְׂרָאֵל חָזְרוּ לְהִטָּהֵר (לשלט) לִהְיוֹת סְגֻלָּה שְׁלֵמָה כְּמוֹ מִקֹּדֶם, אֶלָּא מְעַט מְעַט (בערבוביה), וְכֵיוָן שֶׁלֹּא נִמְצְאָה שְׁלֵמוּת, (ושרתה ה\"א תחתונה לשלט) אָז י', מַעְיָן עֶלְיוֹן, לֹא יָרַד כָּל כָּךְ לְהָאִיר כְּמוֹ שֶׁהָיָה מִקֹּדֶם, אֶלָּא לְאַט לְאַט בְּעִרְבּוּבְיָה, שֶׁלֹּא הָיוּ טְהוֹרִים כְּמוֹ קֹדֶם כְּמוֹ שֶׁרָאוּי, וְעַל כָּךְ מַעְיָן הָעֶלְיוֹן לֹא נוֹבֵעַ וְלֹא מֵאִיר, אֶלָּא שֶׁחָזַר לְהָאִיר מְעַט מְעַט מִתּוֹךְ דּחַק (של השמאל) שֶׁל הַשֵּׁם (של גלות והדין).</p>\n<p>וְלָכֵן הִתְגָּרוּ בְיִשְׂרָאֵל קְרָבוֹת רַבִּים, עַד שֶׁהַחֹשֶׁךְ יְכַסֶּה אֶרֶץ, וְה' הַתַּחְתּוֹנָה נֶחְשְׁכָה וְנָפְלָה לָאָרֶץ, וְהַמַּעְיָן הָעֶלְיוֹן הִסְתַּלֵּק כְּמוֹ מִקֹּדֶם, מִשּׁוּם שֶׁמַּלְכוּת אֱדוֹם הִתְחַזְּקָה, וְיִשְׂרָאֵל חָזְרוּ לְסִרְח וֹנָם.</p>\n<p>וְעַל ה' הַ את בַּיִת שֵׁנִי נֶחֱרַב, וְכָל אוֹתָם תְּרֵיסַר שְׁבָטִים שֶׁלָּהּ כְּחֶשְׁבּוֹן מַחֲנוֹתֵיהֶם הֵם בַּגָּלוּת שֶׁל מַלְכוּת אֱדוֹם, וְהַמַּעְיָן הָעֶלְיוֹן הִסְתַּלֵּק מֵאוֹתוֹ מַעְיָן שֶׁעָמַד עָלֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נז) הַצַּדִּיק אָבָד. אָבַד אוֹתוֹ מַעְיָן שֶׁל מָקוֹר עֶלְיוֹן שֶׁהָיָה שׁוֹפֵעַ וּמוֹשֵׁךְ מִלְמַעְלָה. (קרבות גדולים ומלכות יון שלטה עליהם, ולאחר שחזרו בתשובה, התחזקו עליהם והתקיפו אותם, ומשום שישראל חזרו לסרחונם, מלכות אדום התחזקה ובית שני נחרב, וה\"א תחתונה נחשכה ונפלה לארץ, והמעין העליון נסתלק מאותו מעין שעומד עליו, כמו שגאמר הצדיק אבד. אבד אותו מעין של המקור העליון שהיה שופך ומושך עליו מלמעלה. מה הטעם, ' משום שהחשך יכסה ארץ).</p>\n<p>וְאָז הָיָה פֵּרוּד בְּהֵ\"א, בַּיִת שֵׁנִי, וְהִיא בְּגָלוּת אֱדוֹם, בְּכָל אוֹתָם תְּרֵיסַר שְׁבָטִים (שלה) וּמַחֲנוֹת שֶׁלָּהֶם, שְׁנֵים עָשָׂר שְׁבָטִים עוֹלִים לְחֶשְׁבּוֹן גָּדוֹל, וְעַל שֶׁסּוֹד (ועל זה סוד) שֶׁל ה' הָיָה בָהֶם בְּכָל אוֹתוֹ (ועל זה סוד של ה' בכל אותו) חֶשְׁבּוֹן, (חשך) נִמְשְׁכָה הַגָּלוּת.</p>\n<p>סוֹד הַסּוֹדוֹת לְחַכְמֵי הַלֵּב נִמְסָר. עֲשָׂרָה שְׁבָטִים אֶלֶף שָׁנִים, שְׁנֵי שְׁבָטִים מָאתַיִם שָׁנָה. הִתְחִילוּ הַדְּמָעוֹת לִפֹּל, פָּתַח וְאָמַר, (איכה א) בָּכֹה תִבְכֶּה בַּלַּיְלָה וְדִמְעָתָהּ עַל לֶחֱיָהּ. לְסוֹף שְׁנֵים עָשָׂר הַשְּׁבָטִים שֶׁל הַגָּלוּת, הַלַּיְלָה נֶחְשָׁךְ לְיִשְׂרָאֵל, עַד שֶׁיִּתְעוֹרֵר וָא\"ו לִזְמַן שִׁשִּׁים וְשֵׁשׁ שָׁנָה.</p>\n<p>לְאַחַר שְׁנֵים עָשָׂר שְׁבָטִים, שֶׁהֵם אֶלֶף וּמָאתַיִם שְׁנוֹת גָּלוּת, וְאַחַר שִׁשִּׁים וְשֵׁשׁ שָׁנָה בְּחֹשֶׁךְ הַלַּיְלָה, אָז (ויקרא כו) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב. זוֹ הִתְעוֹרְרוּת הָאוֹת ו', שֶׁהִיא נֶפֶשׁ שֶׁל בֵּית יַעֲקֹב. וְסוֹד זֶה - (בראשית מו) כָּל הַנֶּפֶשׁ הַבָּאָה לְיַעֲקֹב מִצְרַיְמָה וְגוֹ' שִׁשִּׁים וָשֵׁשׁ. וְהוּא ו', נֶפֶשׁ שֶׁל בַּית שֵׁנִי, סוֹד שֶׁל ה' תַּחְתּוֹנָה, וְזֶה ו' סוֹד שֶׁל שִׁשִּׁים וָשֵׁשׁ. שִׁשִּׁים - לְהִתְעוֹרְרוּת יַעֲקֹב, וָשֵׁשׁ - לְהִתְעוֹרְרוּת יוֹסֵף. וְלָכֵן הוּא ו\"ו, שֶׁהֵם שְׁנַיִם בְּחִבּוּר אֶחָד וְסוֹד אֶחָד.</p>\n<p>מִשָּׁם וָהָלְאָה יִתְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתָם נִסִּים וְאוֹתוֹת שֶׁאָמַרְנוּ, וְיִתְעוֹרְרוּ עַל יִשְׂרָאֵל אוֹתָן צָרוֹת שֶׁאָמַרְנוּ, וְאָז !- (וסוד זה) וְאַף אֶת בְּרִיתִי יִצְחָק. אַחַר כָּךְ יַעֲרֹךְ מֶלֶךְ הַמָּשִׁיחַ קְרָבוֹת בְּכָל הָעוֹלָם בִּימִין הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (שמות טו) יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ. אָז, וְאַף אֶת בְּרִיתִי אַבְרָהָם אֶזְכֹּר, וְאַחַר כָּךְ וְהָאָרֶץ אֶזְכֹּר, זוֹ ה' אַחֲרוֹנָה. בְּאוֹתוֹ זְמַן כָּתוּב, (זכריה יד) וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>לְסוֹף שִׁשִּׁים וְשֵׁשׁ שָׁנִים אֲחֵרוֹת, שֶׁהֵם מֵאָה וּשְׁלֹשִׁים וּשְׁתַּיִם שָׁנִים, יֵרָאוּ אוֹתִיּוֹת בַּשֵּׁם הַקָּדוֹשׁ חֲקוּקִים בִּשְׁלֵמוּת לְמַעְלָה וּלְמַטָּה כָּרָאוּי, וְסוֹד זֶה ה\"ה עֶלְיוֹנָה וְתַחְתּוֹנָה, וְכָל אוֹתָן דְּרָכִים שֶׁהֵם שְׁלֹשִׁים וּשְׁתַּיִם שָׁנִים הַכְּלוּלוֹת בַּסּוֹד שֶׁל אוֹת ו', הו\"ה, (יוה\"ה) סוֹד שֶׁל שְׁלֵמוּת מֵאָה וּשְׁלֹשִׁים וּשְׁתַּיִם.</p>\n<p>לְסוֹף מֵאָה וּשְׁלֹשִׁים וּשְׁתַּיִם שָׁנִים אֲחֵרוֹת יִתְקַיֵּם, לֶאֱחֹז בְּכַנְפוֹת הָאָרֶץ, וְיִנָּעֲרוּ הָרְשָׁעִים מִמֶּנָּה, וְתִטָּהֵר הָאָרֶץ הַקְּדוֹשָׁה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יְעוֹרֵר אֶת הַמֵּתִים בָּאָרֶץ הַקְּדוֹשָׁה, וְיָקוּמוּ חֲיָלוֹת חֲיָלוֹת בְּאֶרֶץ הַגָּלִיל.</p>\n<p>וְאָז יִתְעוֹרֵר סֵתֶר הַמַּעְיָן הָעֶלְיוֹן אוֹת י', וְיִתְקַיְּמוּ שְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים בִּשְׁלֵמוּת לְהַשְׁפִּיעַ לְמַטָּה, וְכָל אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ יִתְקַיְּמוּ בְקִיּוּמָם יהו\"ה, שֶׁעַד עַכְשָׁו לֹא הָיוּ בִּשְׁלֵמוּת.</p>\n<p>עַד הַזְּמַן שֶׁיַּשְׁפִּיעַ וְיִמָּשֵׁךְ אוֹתוֹ מַעְיָן עֶלְיוֹן בְּחִבּוּר הָאוֹתִיּוֹת לְתוֹךְ ה' (ו\"ה) אַחֲרוֹנָה, וְזֶהוּ לְסוֹף תַּשְׁלוּם מֵאָה וְאַרְבָּעִים וְאַרְבַּע שָׁנִים אֲחֵרוֹת שֶׁיִּשְׁתַּלְּמוּ. וְיִתְעוֹרְרוּ שְׁאָר מֵתֵי יִשְׂרָאֵל שֶׁבִּשְׁאָר הָאֲרָצוֹת.</p>\n<p>שֶׁיִּמָּצֵא כָּל זֶה בְּחֶשְׁבּוֹן חֵ\"ת, שֶׁהִתְיַשֵּׁב הָעוֹלָם וְיִתְבַּשֵּׂם, וְיַעֲבֹר הַצַּד הָאַחֵר (הגחש הרע) מִן הָעוֹלָם. וְהֵ\"א תַּחְתּוֹנָה תִּתְמַלֵּא מִתּוֹךְ הַמַּעְיָן הָעֶלְיוֹן, וְתִתְעַטֵּר וְתָאִיר בִּשְׁלֵמוּת, וְאָז כָּתוּב (ישעיה ל) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם.</p>\n<p>עֵד שֶׁתִּהְיֶה שַׁבָּת לַה' לִלְקֹט נְפָשׁוֹת בְּתַעֲנוּגֵי קְדֻשָּׁה, (זו ה' אחרונה) כָּל אוֹתוֹ אֶלֶף שְׁבִיעִי, וְזוֹהִי הִתְעוֹרְרוּת שֶׁל רוּחוֹת קְדוֹשׁוֹת שֶׁל עַם יִשְׂרָאֵל, לְהִתְלַבֵּשׁ אַחַר שַׁבָּת בְּגוּפוֹת אֲחֵרִים קְדוֹשִׁים, לְהִקָּרֵא קְדוֹשִׁים, שֶׁכָּתוּב וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלם קָדוֹשׁ יֵאָמֶר לוֹ. עַד כָּאן דִּבְרֵי סוֹדוֹת נִסְתָּרִים.</p>"],[9522011522,"<p>וַיָּקָם מֶלֶךְ חָדָשׁ. רַבִּי יוֹסֵי אָמַר, בְּכָל יוֹם עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא מַלְאָכִים שְׁלוּחִים עַל הָעוֹלָם, שֶׁכָּתוּב (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת. עָשָׂה לֹא כָתוּב, אֶלָּא עוֹשֶׂה, מִשּׁוּם שֶׁכָּל יוֹם וָיוֹם עוֹשֶׂה. וּבְאוֹתוֹ זְמַן הִתְמַנָּה מְמֻנֶּה אֶחָד עַל מִצְרַיִם, וְזֶהוּ שֶׁכָּתוּב וַיָּקָם מֶלֶךְ חָדָשׁ, חָדָשׁ וַדַּאי.</p>\n<p>אֲשֶׁר לֹא יָדַע אֶת יוֹסֵף, שֶׁהֲרֵי מִמָּקוֹם שֶׁל פֵּרוּד הָיוּ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) וּמִשָּׁם יִפָּרֵד. וְהָרִאשׁוֹן מֵאוֹתוֹ הַפֵּרוּד הוּא נְהַר מִצְרַיִם, וְלָכֵן אֲשֶׁר לֹא יָדַע אֶת יוֹסֵף, מָקוֹם שֶׁכָּל הַיִּחוּד שׁוֹרֶה בּוֹ, שֶׁנִּקְרָא צַדִּיק.</p>"],[9522011523,"<p>רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ, וְהִקְדִּימוּ לָלֶכֶת בָּאוֹר. רָאוּ כּוֹכָב אֶחָד שֶׁהָיָה רָץ מִצַּד זֶה, וְכוֹכָב אַחֵר מִצַּד זֶה. אָמַר רַבִּי אֶלְעָזָר, עַכְשָׁו הִגִּיעַ זְמַן שֶׁל כּוֹכְבֵי הַבֹּקֶר לְשַׁבֵּחַ אֶת אֲדוֹנָם, וְהֵם רָצִים מִפַּחַד וְאֵימַת רִבּוֹנָם לְשַׁבֵּחַ וּלְזַמֵּר לוֹ. זֶהוּ שֶׁכָּתוּב (איוב לח) בְּרָן יַחַד כּוֹכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. מִשּׁוּם שֶׁכֻּלָּם בְּיִחוּד אֶחָד מְשַׁבְּחִים אוֹתוֹ.</p>\n<p>פָּתַח וְאָמַר, (תהלים כב) לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר מִזְמוֹר לְדָוִד. אַיֶּלֶת הַשַּׁחַר - שֶׁכְּשֶׁמְּאִירִים פְּנֵי הַמִּזְרָח וְנִפְרָד חֹשֶׁךְ הַלַּיְלָה, יֵשׁ מְמֻנֶּה אֶחָד לְצַד מִזְרָח, וּמוֹשֵׁךְ חוּט אֶחָד שֶׁל חֹשֶׁךְ לְצַד דָּרוֹם, עַד שֶׁבָּא וְיוֹצֵא הַשֶּׁמֶשׁ, וּבוֹקֵעַ בְּאוֹתָם חַלּוֹנֵי הָרָקִיעַ וּמֵאִיר לָעוֹלָם, וְאוֹתוֹ חוּט מַפְרִיד אֶת חֹשֶׁךְ הַלַּיְלָה.</p>\n<p>אָז בָּאָה אַיֶּלֶת הַשַּׁחַר, וּבָא אוֹר שָׁחֹר בְּקַדְרוּת לְהִתְחַבֵּר בַּיּוֹם, וּמֵאִיר הַיּוֹם. וְאוֹר הַיּוֹם כָּלוּל וְשָׁאוּב בְּתוֹכוֹ אֶת אוֹתָהּ הָאַיֶּלֶת. וְעַל הָאַיֶּלֶת הַ את, כְּשֶׁנִּפְרָד מֵהַיּוֹם אַחַר שֶׁכָּלָל אוֹתָהּ, אָמַר דָּוִד שִׁירָה, שֶׁכָּתוּב לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר.</p>\n<p>וּמָה אָמַר? אֵלִי אֵלִי לָמָּה עֲזַבְתָּנִי. שֶׁהֲרֵי נִפְרְדָה אַיֶּלֶת הַשַּׁחַר מֵאוֹר הַיּוֹם. עַד שֶׁהָיוּ הוֹלְכִים, הֵאִיר הַיּוֹם וְהִגִּיעַ זְמַן תְּפִלָּה. אָמַר רַבִּי אֶלְעָזָר, נִתְפַּלֵּל תְּפִלָּה וְנֵלֵךְ. יָשְׁבוּ וְהִתְפַּלְלוּ, אַחַר כָּךְ קָמוּ וְהָלְכוּ.</p>"],[9522011524,"<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (קהלת ח) יֶשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ אֲשֶׁר יֵשׁ צַדִּיקִים אֲשֶׁר מַגִּיעַ אֲלֵהֶם כְּמַעֲשֵׂה הָרְשָׁעִים וְגוֹ' אָמַרְתִּי שֶׁגַּם זֶה הָבֶל. פָּסוּק זֶה פֵּרְשׁוּהוּ וְנִתְבָּאֵר, אֲבָל יֵשׁ הֶבֶל, שְׁלֹמֹה הַמֶּלֶךְ עָשָׂה סֵפֶר זֶה וְהֵקִים אוֹתוֹ עַל שִׁבְעָה הֲבָלִים שֶׁהָעוֹלָם עוֹמֵד עֲלֵיהֶם.</p>\n<p>וְהֵם שִׁבְעָה עַמּוּדִים תּוֹמְכִים שֶׁל הָעוֹלָם כְּנֶגֶד שִׁבְעָה רְקִיעִים, וְאֵלּוּ הֵם: וִילוֹ\"ן. רָקִי\"עַ. שְׁחָקִי\"ם. זְבוּ\"ל. מָעוֹ\"ן. מָכוֹ\"ן. עֲרָבוֹ\"ת. וּכְנֶגְדָּם אָמַר קֹהֶלֶת הֲבֵל הֲבָלִים הַכֹּל הָבֶל.</p>\n<p>כְּמוֹ שֶׁאוֹתָם שִׁבְעָה רְקִיעִים, וְיֵשׁ אֲחֵרִים שֶׁנִּדְבָּקִים בָּהֶם וּמִתְפַּשְּׁטִים וְיוֹצְאִים מֵהֶם, כָּךְ גַּם יֵשׁ הֲבָלִים אֲחֵרִים שֶׁמִּתְפַּשְּׁטִים וְיוֹצְאִים מֵאֵלֶּה, וְכֻלָּם אָמַר שְׁלֹמֹה.</p>\n<p>וְכָאן יֵשׁ בּוֹ סוֹד הַחָכְמָה. יֵשׁ הֶבֶל שֶׁיּוֹצֵא מֵאוֹתָם הֲבָלִים עֶלְיוֹנִים, שֶׁהָעוֹלָם עוֹמֵד עֲלֵיהֶם, וְזֶה נַעֲשָׂה עַל הָאָרֶץ, וְהִתְקַיֵּם בְּקִיּוּמוֹ וְהִתְחַזֵּק בְּתָקְפּוֹ בְּמַעֲשֵׂי הָאָרֶץ וּבָעֲלִיָּה שֶׁעוֹלֶה מֵהָאָרֶץ, וְזֶה הִתְמַנָּה עַל הָאָרֶץ, וְכָל תֹּקֶף וְקִיּוּם שֶׁלּוֹ בְּאוֹתָן נִשְׁמוֹת הַצַּדִּיקִים שֶׁנִּלְקְטוּ מִן הָאָרֶץ כְּשֶׁהֵם צַדִּיקִים, עַד שֶׁלֹּא סָרְחוּ, בְּעוֹד שֶׁנּוֹתְנִים רֵיחַ טוֹב כְּמוֹ חֲנוֹךְ, שֶׁכָּתוּב בּוֹ וְאֵינֶנּוּ כִּי לָקַח אֹתוֹ אֱלֹהִים. וְנָטַל אוֹתוֹ כְּשֶׁעֲדַיִן לֹא הִגִּיעַ זְמַנּוֹ, וּמִשְׁתַּעֲשֵׁעַ בּוֹ, וְכֵן שְׁאָר צַדִּיקֵי עוֹלָם.</p>\n<p>שֶׁשָּׁנִינוּ, עַל שְׁנֵי דְבָרִים צַדִּיקִים מִסְתַּלְּקִים מִן הָעוֹלָם טֶרֶם הִגִּיעַ זְמַנָּם, אֶחָד עַל חֲטָאֵי הַדּוֹר, שֶׁכְּשֶׁמִּתְרַבִּים רְשָׁעִים בָּעוֹלָם, אוֹתָם צַדִּיקִים שֶׁנִּמְצָאִים בֵּינֵיהֶם נִתְפָּסִים בַּחֲטָאֵיהֶם. וְאֶחָד כְּשֶׁמִּתְגַּלֶּה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּסְרְחוּ אַחַר כָּךְ, הוּא מְסַלֵּק אוֹתָם מֵהָעוֹלָם טֶרֶם הִגִּיעַ זְמַנָּם. זֶהו שֶׁכָּתוּב אֲשֶׁר יֵשׁ צַדִּיקִים אֲשֶׁר מַגִּיעַ אֲלֵהֶם כְּמַעֲשֵׂה הָרְשָׁעִים. מַגִּיעַ עֲלֵיהֶם דִּין שֶׁלְּמַעְלָה כְּאִלּוּ עָשׂוּ חֲטָאִים וּמַעֲשִׂים שֶׁל רְשָׁעִים.</p>\n<p>שֶׁהֲרֵי פַּעַם אַחַת שָׁאַל רַבִּי יוֹסֵי בַּר רַבִּי יַעֲקֹב, אִישׁ כְּפַר אוֹנוֹ, בִּזְמַן שֶׁרַבִּי עֲקִיבָא וַחֲבֵרָיו הִסְתַּלְּקוּ מִן הָעוֹלָם וּמֵתוּ בְּאוֹתוֹ אֹפֶן, אֶת רַבִּי מֵאִיר, אָמַר לוֹ, וְכִי זֶה כָּתוּב בְּכָל הַתּוֹרָה כֻּלָּהּ? אָמַר לוֹ, וָלֹא? וַהֲרֵי אָמַר שְׁלֹמֹה אֲשֶׁר יֵשׁ צַדִּיקִים אֲשֶׁר מַגִּיעַ אֲלֵהֶם כְּמַעֲשֵׂה הָרְשָׁעִים, מַגִּיעַ עֲלֵיהֶם דִּין מִלְמַעְלָה כְּאִלּוּ עָשׂוּ חֲטָאִים וּמַעֲשִׂים שֶׁל רְשָׁעִים. וְיֵשׁ רְשָׁעִים שֶׁמַּגִּיעַ אֲלֵהֶם כְּמַעֲשֵׂה הַצַּדִּיקִים, יוֹשְׁבִים בְּשֶׁקֶט וְשָׁלוֹם בָּעוֹלָם הַזֶּה, דִּין לֹא מַגִּיעַ אֲלֵיהֶם, כְּאִלּוּ עָשׂוּ מַעֲשִׂים שֶׁל צַדִּיקִים.</p>\n<p>לָמָּה? אִם מִשּׁוּם שֶׁגָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיָּשׁוּבוּ בִּתְשׁוּבָה אוֹ שֶׁיֵּצֵא מֵהֶם זֶרַע שֶׁיִּהְיֶה אֱמֶת בָּעוֹלָם, כְּמוֹ תֶּרַח שֶׁיָּצָא מִמֶּנּוּ זֶרַע אֱמֶת - אַבְרָהָם. אָחָז שֶׁיָּצָא מִמֶּנּוּ חִזְקִיָּהוּ, וּשְׁאָר הָרְשָׁעִים שֶׁל הָעוֹלָם. וְלָכֵן, בְּצַד זֶה וּבְצַד זֶה, הֶבֶל שֶׁאָמַרְנוּ נַעֲשָׂה וְנִתְחַזֵּק עַל הָאָרֶץ, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>דָּבָר אַחֵר יֶשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ, כְּפִי שֶׁאָמַרְנוּ שֶׁהִתְחַזֵּק (והתחזק) עַל הָעוֹלָם. בַּמֶּה? מִשּׁוּם שֶׁיֵּשׁ צַדִּיקִים אֲשֶׁר מַגִּיעַ אֲלֵהֶם כְּמַעֲשֵׂה הָרְשָׁעִים, מַגִּיעַ לִידֵיהֶם כְּאוֹתָם מַעֲשֵׂי הָרְשָׁעִים כְּמוֹ בַּת עוֹבְדֵי עֲבוֹדָה זָרָה, אוֹ אֶחָד מֵאוֹתָם מַעֲשִׂים שֶׁהֵם מִמַּעֲשֵׂה הָרְשָׁעִים, וְהֵם עוֹמְדִים בְּקִיּוּמָם מִפַּחַד רִבּוֹנָם, וְלֹא רוֹצִים לְהִטָּמֵא כְּמוֹ כַּמָּה צַדִּיקֵי אֱמֶת שֶׁבָּאוּ לִידֵיהֶם כַּמַּעֲשִׂים הַלָּלוּ, וְהֵם גִּבּוֹרֵי כֹחַ שֶׁעוֹשִׂים רְצוֹן אֲדוֹנָם וְלֹא חָטְאוּ, וְעַל זֶה הֶבֶל נַעֲשָׂה עַל הָאָרֶץ וּמִתְחַזֵּק בְּתָקְפּוֹ.</p>\n<p>וְיִשִׁ רְשָׁעִים שֶׁמַּגִּיעַ אֲלֵהֶם כְּמַעֲשֵׂה הַצַּדִּיקִים, בָּאָה לִידֵיהֶם מִצְוָה אַחַת שֶׁהִיא מַעֲשֶׂה שֶׁל צַדִּיקִים, וְזוֹכִים בָּהּ וְעוֹשִׂים אוֹתָהּ, כְּמוֹ לִסְטִים מְקַפֵּחַ שֶׁהָיָה נִמְצָא בֶהָרִים יַחַד עִם לִסְטִים עוֹבְדֵי עֲבוֹדָה זָרָה, וּכְשֶׁהָיָה עוֹבֵר שָׁם יְהוּדִי, הָיָה מַצִּיל אוֹתוֹ וְשׁוֹמֵר אוֹתוֹ מֵהֶם, וְהָיָה קוֹרֵא עָלָיו רַבִּי עֲקִיבָא: יֵשׁ רְשָׁעִים אֲשֶׁר מַגִּיעַ אֲלֵהֶם כְּמַעֲשֵׂה הַצַּדִּיקִים.</p>\n<p>וּכְמוֹ אוֹתוֹ רָשָׁע שֶׁהָיָה בִּסְבִיבָתוֹ שֶׁל רַבִּי חִיָּיא, שֶׁלַּיְלָה אֶחָד פָּגַשׁ אֶת אוֹתָהּ אִשָּׁה שֶׁהָיְתָה הוֹלֶכֶת לְבֵית בִּתָּהּ, רָצָה לִתְקֹף אוֹתָהּ. אָמְרָה לוֹ, בְּבַקָּשָׁה מִמְּךְ, כַּבֵּד אֶת רִבּוֹנְךְ וְאַל תֶּחֱטָא עִמִּי. עָזַב אוֹתָהּ וְלֹא חָטָא בָהּ. הֱוֵי אוֹמֵר, וְיֵשׁ רְשָׁעִים אֲשֶׁר מַגִּיעַ אֲלֵהֶם כְּמַעֲשֵׂה הַצַּדִּיקִים אָמַרְתִּי שֶׁגַּם זֶה הָבֶל. כְּמוֹ שֶׁהִתְחַזֵּק אוֹתוֹ הֶבֶל עִם אוֹתָם הַצַּדִּיקִים שֶׁבָּאוּ לִידֵיהֶם מַעֲשֵׂי רְשָׁעִים וְלֹא חָטְאוּ, אַף כָּךְ הִתְחַזֵּק עִם אוֹתָם רְשָׁעִים שֶׁהִגִּיעוּ לִידֵיהֶם מַעֲשֵׂי אוֹתָם הַצַּדִּיקִים וְעוֹשִׂים אוֹתָם.</p>\n<p>שֶׁשָּׁנִינוּ, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא צַדִּיקִים וּרְשָׁעִים בָּעוֹלָם, וּכְמוֹ שֶׁהוּא מִתְכַּבֵּד בָּעוֹלָם בְּמַעֲשֵׂי הַצַּדִּיקִים, כָּךְ גַּם הוּא מִתְכַּבֵּד בָּרְשָׁעִים כְּשֶׁעוֹשִׂים מַעֲשֶׂה טוֹב בָּעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ג) אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ. אוֹי לָרָשָׁע כְּשֶׁעוֹשֶׂה אֶת עַצְמוֹ רַע וּמִתְחַזֵּק בְּחֶטְאוֹ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ג) אוֹי לָרָשָׁע רָע וְגוֹ'.</p>\n<p>עוֹד פָּתַח וְאָמַר, (קהלת ז) אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי וְגוֹ'. פָּסוּק זֶה אַף כָּךְ בֵּאֲרוּהוּ הַחֲבֵרִים, אֲבָל כַּאֲשֶׁר נִתְּנָה חָכְמָה לִשְׁלֹמֹה, רָאָה הַכֹּל בִּזְמַן שֶׁשּׁוֹלֶטֶת הַלְּבָנָה. יֵשׁ צַדִּיק - זֶה עַמּוּד הָעוֹלָם. אֹבֵד - כְּמוֹ שֶׁנֶּאֱמַר הַצַּדִּיק אָבָד, בִּזְמַן הַגָּלוּת. בְּצִדְקוֹ - מִשּׁוּם שֶׁהִיא שׁוֹכֶבֶת לֶעָפָר. צֶדֶק זֶה, כָּל זְמַן שֶׁיִּשְׂרָאֵל בַּגָּלוּת, הִיא עִמָּם בַּגָּלוּת, וּמִשּׁוּם כָּךְ, צַדִּיק אֹבֵד בְּצִדְקוֹ, שֶׁהֲרֵי אֵין מַגִּיעוֹת אֵלָיו אוֹתָן בְּרָכוֹת עֶלְיוֹנוֹת.</p>\n<p>וְיִשִׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ - זֶה סָמָאֵ\"ל, שֶׁהֶאֱרִיךְ שֶׁקֶט וְשַׁלְוָה לֶאֱדוֹם, בַּמֶּה? בְּרָעָתוֹ, בְּאוֹתָהּ רָעָה אִשְׁתּוֹ, (אשה רעה אשת זנונים) נָחָשׁ הַתַּקִּיף, שֶׁהֲרֵי לֹא מַגִּיעַ עֲלֵיהֶם שֶׁקֶט וְשַׁלְוָה אֶלָּא רַק מִשּׁוּם שֶׁנִּדְבָּק בְּאוֹתָהּ נְקֵבָה. כְּמוֹ זֶה לִשְׁאָר הַמַּלְכֻיּוֹת, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָקִים מִן הֶעָפָר אֶת אוֹתָהּ סֻכַּת דָּוִד הַנּוֹפֶלֶת, שֶׁכָּתוּב (עמוס ט) אָקִים אֶת סֻכַּת דָּוִיד הַנֹּפֶלֶת.</p>"],[9522011525,"<p>וַיֵּלֶךָ אִישׁ מִבֵּית לֵוִי. רַבִּי יוֹסֵי פָּתַח, (שיר ו) דּוֹדִי יָרַד לְגַנּוֹ לַעֲרֻגוֹת הַבֹּשֶׂם וְגוֹ'. לְגַנּוֹ - זוֹ כְּנֶסֶת יִשְׂרָאֵל, מִשּׁוּם שֶׁהִיא עֲרוּגַת הַבֹּשֶׂם, שֶׁהִיא כְּלוּלָה מִכָּל צִדְדֵי (מיני) בְשָׂמִים וְרֵיחוֹת שֶׁל הָעוֹלָם הַבָּא. בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֵד לַגָּן הַזֶּה (של עדן), כָּל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים מִתְעַטְּרוֹת שָׁם, כֻּלָּן נוֹתְנוֹת רֵיחַ, כְּמוֹ שֶׁנֶּאֱמַר וְרֵיחַ שְׁמָנַיִךְ מִכָּל בְּשָׂמִים (וריח אפך כתפוחים) - אֵלּוּ הֵם נִשְׁמוֹת הַצַּדִּיקִים, שֶׁאָמַר רַבִּי יִצְחָק, כָּל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים שֶׁהָיוּ בָּעוֹלָם הַזֶּה וְכָל אוֹתָן הַנְּשָׁמוֹת שֶׁעֲתִידוֹת לָרֶדֶת לָעוֹלָם הַזֶּה, כֻּלָּן (עומדות בגן הזה).</p>\n<p>בַּגָּן שֶׁבָּאָרֶץ כֻּלָּם עוֹמְדִים בִּדְיוֹקָן וְצִיּוּר שֶׁהָיוּ עוֹמְדִים בָּעוֹלָם הַזֶּה, וְסֵתֶר וְסוֹד זֶה נִמְסָר לַחֲכָמִים. רוּחַ שֶׁיּוֹרֶדֶת לִבְנֵי אָדָם, שֶׁהוּא מִצַּד הַנְּקֵבָה, נֶחְקְקָה תָּמִיד בַּחֲקִיקָה כַּחוֹתָם הַזֶּה. צִיּוּר הַגּוּף שֶׁל אָדָם בָּעוֹלָם הַזֶּה בּוֹלֵט הַחוּצָה, וְרוּחַ נֶחְקְקֶת פְּנִימָה. כְּשֶׁמִּתְפַּשֶּׁטֶת הָרוּחַ מִן הַגּוּף, אוֹתָהּ רוּחַ בּוֹלֶטֶת בַּגָּן שֶׁל הָאָרֶץ בְּצִיּוּר וּדְיוֹקָן שֶׁל גּוּפוֹ מַמָּשׁ שֶׁבָּעוֹלָם הַזֶּה, מִשּׁוּם שֶׁהָיָה תָּמִיד כְּמוֹ חוֹתָם.</p>\n<p>וְעַל זֶה הִיא אָמְרָה (שיר ח) שִׂימֵנִי כַחוֹתָם. מַה חוֹתָם חָקוּק בַּחֲקִיקָה פְּנִימָה וּמִצְטַיֵּר בְּצִיּוּר בּוֹלֵט הַחוּצָה, אַף כָּךְ הִיא הָרוּחַ שֶׁהָיְתָה מִצַּד שֶׁלָּהּ, כְּמוֹ זֶה מַמָּשׁ בָּעוֹלָם הַזֶּה חָקוּק בַּחֲקִיקָה פְּנִימָה, וּכְשֶׁמִּתְפַּשֵּׁט מֵהַגּוּף וְנִכְנָס לַגָּן שֶׁבָּאָרֶץ, הָאֲוִיר שֶׁשָּׁם בּוֹלֵט אוֹתוֹ חֲקִיקָה לְהִצְטַיֵּר הַחוּצָה, וּמִצְטַיֵּר בְּצִיּוּר בּוֹלֵט הַחוּצָה, כְּמוֹ שֶׁצִּיּוּר שֶׁל הַגּוּף בָּעוֹלָם הַזֶּה (למעלה).</p>\n<p>הַנְּשָׁמָה שֶׁהִיא מֵעֵץ הַחַיִּים מִצְטַיֶּרֶת שָׁם לְמַעְלָה בְּאוֹתוֹ צְרוֹר הַחַיִּים לְהִתְעַנֵּג בְּנֹעַם ה', כְּמוֹ שֶׁנֶּאֱמַר (תהלים כז) לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ.</p>\n<p>וַיֵּלֶךָ אִישׁ מִבֵּית לֵוִי - זֶה גַּבְרִיאֵל, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ט) וְהָאִישׁ גַּבְרִיאֵל אֲשֶׁר רָאִיתִי בֶחָזוֹן וְגוֹ'. מִבֵּית לֵוִי - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁבָּאָה מִצַּד הַשְּׂמֹאל. וַיִּקַּח אֶת בַּת לֵוִי - זוֹ הַנְּשָׁמָה.</p>\n<p>שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁנּוֹלָד גּוּף שֶׁל צַדִּיק בָּעוֹלָם הַזֶּה, הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא לְגַבְרִיאֵל וְנוֹטֵל אוֹתָהּ נְשָׁמָה (של צדיק) שֶׁבַּגָּן, וּמוֹרִיד אוֹתָהּ לַגּוּף הַזֶּה שֶׁל הַצַּדִּיק שֶׁנּוֹלָד בָּעוֹלָם הַזֶּה, וְהוּא נִפְקָד עָלֶיהָ וְשׁוֹמֵר אוֹתָהּ.</p>\n<p>וְאִם תֹּאמַר, אוֹתוֹ מַלְאָךְ שֶׁהִתְמַנָּה עַל רוּחוֹת הַצַּדִּיקִים שְׁמוֹ לַיְלָה, וְאַתָּה אוֹמֵר שֶׁשְּׁמוֹ גַּבְרִיאֵל? כָּךְ הוּא וַדַּאי, מִשּׁוּם שֶׁבָּא מִצַּד הַשְּׂמֹאל, וְכָל מִי שֶׁבָּא מִצַּד הַשְּׂמֹאל כָּךְ נִקְרָא.</p>\n<p>וַיֵּלֶךָ אִישׁ - זֶה עַמְרָם. וַיִּקַּח אֶת בַּת לֵוִי - זוֹ יוֹכֶבֶד. וּבַת קוֹל יָרְדָה וְאָמְרָה לוֹ לְהִזְדַּוֵּג בָּהּ, שֶׁהֲרֵי קָרֵב זְמַן גְּאֻלַּת יִשְׂרָאֵל עַל יְדֵי הַבֵּן שֶׁנּוֹלַד מֵהֶם.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא סִיַּע בּוֹ, שֶׁשָּׁנִינוּ, שְׁכִינָה שָׁרְתָה עַל מִטָּתָם, וְהָרָצוֹן שֶׁלָּהֶם בִּדְבֵקוּת אַחַת הָיְתָה בַּשְּׁכִינָה, וְלָכֵן לֹא זָזָה שְׁכִינָה מֵאוֹתוֹ בֵּן שֶׁהוֹלִידוּ, לְקַיֵּם מַה שֶׁכָּתוּב (ויקרא כ) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים. בֶּן אָדָם שֶׁמְּקַדֵּשׁ עַצְמוֹ מִלְּמַטָּה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַדֵּשׁ אוֹתוֹ מִלְמַעְלָה. כְּמוֹ שֶׁהָרָצוֹן שֶׁלָּהֶם הָיָה בַּדְּבֵקוּת שֶׁל הַשְּׁכִינָה, כָּךְ הַשְּׁכִינָה נִדְבְּקָה מַמָּשׁ בְּאוֹתוֹ מַעֲשֶׂה שֶׁעָשׂוּ.</p>\n<p>אָמַר רַבִּי יִצְחָק, אַשְׁרֵי הַצַּדִּיקִים שֶׁהָרָצוֹן שֶׁלָּהֶם בַּדְּבֵקוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא תָּמִיד. וּכְמוֹ שֶׁהֵם מִתְדַּבְּקִים בּוֹ תָּמִיד, כָּךְ גַּם הוּא נִדְבָּק בָּהֶם וְלֹא עוֹזֵב אוֹתָם לְעוֹלָמִים. אוֹי לָרְשָׁעִים שֶׁהָרָצוֹן שֶׁלָּהֶם וְהַדְּבֵקוּת שֶׁלָּהֶם מְרֻחֶקֶת מִמֶּנּוּ, וְלֹא דַי לָהֶם שֶׁמִּתְרַחֲקִים מִמֶּנּוּ, אֶלָּא שֶׁנִּדְבָּקִים בַּצַּד הָאַחֵר. בֹּא רְאֵה, עַמְרָם שֶׁנִּדְבַּק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, יָצָא מִמֶּנּוּ מֹשֶׁה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא זָז מִמֶּנּוּ לְעוֹלָמִים, וּשְׁכִינָה נִדְבְּקָה עִמּוֹ תָּמִיד. אַשְׁרֵי חֶלְקוֹ.</p>\n<p>וַתַּהַר הָאִשָּׁה וַתֵּלֶד בֵּן וַתֵּרֶא אֹתוֹ כִּי טוֹב הוּא. מַה זֶּה כִּי טוֹב הוּא? אָמַר רַבִּי חִיָּיא, שֶׁנּוֹלַד מָהוּל. מִשּׁוּם שֶׁסּוֹד הַבְּרִית נִקְרָא טוֹב, שֶׁכָּתוּב (ישעיה ג) אִמְרוּ צַדִּיק כִּי טוֹב.</p>\n<p>רַבִּי יוֹסֵי אָמַר, רָאֲתָה בּוֹ אוֹר הַשְּׁכִינָה שֶׁמֵּאִיר בּוֹ, שֶׁבְּשָׁעָה שֶׁנּוֹלַד, הִתְמַלֵּא כָּל הַבַּיִת אוֹר, שֶׁכָּתוּב וַתֵּרֶא אֹתוֹ כִּי טוֹב הוּא, וְכָתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וְעַל זֶה כָּתוּב כִּי טוֹב הוּא, וְהַכֹּל הָיָה.</p>"],[9522011526,"<p>וַתִּצְפְּנֵהוּ שְׁלֹשָׁה יְרָחִים. מָה אוֹמְרִים שְׁלֹשָׁה יְרָחִים? אָמַר רַבִּי יְהוּדָה, רֶמֶז הוּא שֶׁרָמַז, שֶׁלֹּא נוֹדַע מֹשֶׁה בְּזֹהַר עֶלְיוֹן עַד שְׁלֹשָׁה יְרָחִים, שֶׁכָּתוּב (שמות יט) בַּחֹדֶשׁ הַשְּׁלִישִׁי, שֶׁהֲרֵי אָז נִתְּנָה תוֹרָה עַל יָדוֹ, וּשְׁכִינָה הִתְגַּלְּתָה וְשָׁרְתָה עָלָיו לְעֵינֵי כֻלָּם, שֶׁכָּתוּב וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים וַיִּקְרָא אֵלָיו ה'. וְלֹא יָכְלָה עוֹד הַצְּפִינוֹ, שֶׁעַד אוֹתָהּ שָׁעָה לֹא נוֹדַע דִּבּוּרוֹ בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, וְכָתוּב מֹשֶׁה יְדַבֵּר וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל.</p>\n<p>וַתִּקַּח לוֹ תֵּבַת עֲצֵי גֹמֶא, רֶמֶז עַל הָאָרוֹן שֶׁלּוּחוֹת הַבְּרִית נִכְנָסִים לְתוֹכוֹ. תֵּבַת גֹּמֶא הִיא אֲרוֹן הַבְּרִית. וַתַּחְמְרָה בַחֵמָר וּבַזָּפֶת, (שאותה תבה שהוא) שֶׁהֲרֵי הָאָרוֹן הָיָה מְצֻפֶּה מִבִּפְנִים וּמִבַּחוּץ. רַבִּי יְהוּדָה אָמַר, זוֹהִי הַתּוֹרָה שֶׁהֶחְמִירָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְווֹת עֲשֵׂה וּבְמִצְווֹת לֹא תַעֲשֶׂה.</p>\n<p>וַתָּשֶׂם בָּהּ אֶת הַיֶּלֶד - אֵלּוּ יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר (הושע יא) כִּי נַעַר יִשְׂרָאֵל וָאֹהֲבֵהוּ. וַתָּשֶׂם בַּסּוּף - שֶׁלֹּא הָיוּ מִצְווֹת הַתּוֹרָה חֹמֶר לַעֲשׂוֹת עַד סוֹף, שֶׁנִּכְנְסוּ יִשְׂרָאֵל לָאָרֶץ לְסוֹף אַרְבָּעִים שָׁנָה. עַל שְׂפַת הַיְאֹר - עַל מַאֲמָר שֶׁל אוֹתָם שֶׁמּוֹרִים תּוֹרָה וְחֻקָּה לְיִשְׂרָאֵל. (רבי חזקיה אמר, כך למדנו).</p>\n<p>דָּבָר אַחֵר וַיֵּלֶךְ אִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב ה' אִישׁ מִלְחָמָה. מִבֵּית לֵוִי - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, הַמָּקוֹם שֶׁהַחָכְמָה הָעֶלְיוֹנָה וְאוֹתוֹ נָהָר מִתְחַבְּרִים כְּאֶחָד וְלֹא נִפְרָדִים לְעוֹלָמִים. מִבֵּית לֵוִי - שֶׁהִשְׁרָה לִוְיָתָן (כל שמחה) לְשִׂמְחָה בָּעוֹלָם, זֶהוּ שֶׁכָּתוּב (תהלים קד) לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. וַיִּקַּח אֶת בַּת לֵוִי - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, מָקוֹם שֶׁאוֹר הַלְּבָנָה מֵאִיר.</p>\n<p>וַתַּהַר הָאִשָּׁה וַתֵּלֶד בֵּן. הָאִשָּׁה וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר לְזֹאת יִקָּרֵא אִשָּׁה. בַּתְּחִלָּה בַּת לֵוִי, וְכָךְ זֶה וַדַּאי. וְכִי בַּת לֵוִי בַּתְּחִלָּה וְעַכְשָׁו אִשָּׁה? אֶלָּא כָּךְ זֶה בְּוַדַּאי, וְכָךְ לָמַדְנוּ, עַד שֶׁלֹּא הִזְדַּוְּגָה אִשָּׁה, הִיא נִקְרֵאת בַּת פְּלוֹנִי. אַחַר שֶׁהִזְדַּוְּגָה, נִקְרֵאת אִשָּׁה. וְכָאן בַּת וְאִשָּׁה, דַּרְגָּה אַחַת הִיא.</p>\n<p>וַתִּצְפְּנֵהוּ שְׁלֹשָׁה יְרָחִים - אֵלּוּ שְׁלֹשֶׁת הַיְרָחִים שֶׁהַדִּין הַקָּשֶׁה שָׁרוּי בָּעוֹלָם, וְאֵלּוּ הֵם: תַּמּוּז, אָב וְטֵבֵת (שבט). מַה מַּשְׁמִיעַ? שֶׁעַד שֶׁלֹּא יָרַד מֹשֶׁה לָעוֹלָם, הוּא הָיָה מָצוּי לְמַעְלָה, וְעַל זֶה הִזְדַּוְּגָה בּוֹ שְׁכִינָה מִיּוֹם שֶׁנּוֹלַד. מִכָּאן, אָמַר רַבִּי שִׁמְעוֹן, שֶׁרוּחוֹת הַצַּדִּיקִים מְצוּיוֹת הֵן לְמַעְלָה עַד שֶׁלֹּא יוֹרְדוֹת לָעוֹלָם.</p>\n<p>וְלֹא יָכְלָה עוֹד הַצְּפִינוֹ וְגוֹ'. מַה זֶּה וַתִּקַּח לוֹ תֵּבַת גֹּמֶא? שֶׁכִּסְּתָה אוֹתוֹ בְּסִימָנֶיהָ לִהְיוֹת שָׁמוּר מֵאוֹתָם הַדָּגִים שֶׁל הַיָּם שֶׁשָּׁטִים בַּיָּם הַגָּדוֹל, שֶׁכָּתוּב (תהלים קד) שָׁם רֶמֶשׂ וְאֵין מִסְפָּר. וְהִיא כִּסְּתָה אוֹתוֹ לִהְיוֹת שָׁמוּר מֵהֶם בְּכִסּוּי (בצד היובל) (טיסת הרוכל) (טס הכברה) נִכְבָּד שֶׁל שְׁנֵי גְוָנִים, לָבָן וְשָׁחֹר, וְהִנִּיחָה אֶת מֹשֶׁה בֵּינֵיהֶם שֶׁיִּוָּדַע עִמָּהֶם, מִשּׁוּם שֶׁעָתִיד לַעֲלוֹת (ביניהם) פַּעַם אַחֶרֶת לְקַבֵּל תּוֹרָה.</p>\n<p>וַתֵּרֶד בַּת פַּרְעֹה לִרְחֹץ עַל הַיְאֹר - זוֹהִי שֶׁבָּאָה מִצַּד הַשְּׂמֹאל שֶׁל הַדִּין הַקָּשֶׁה, כְּמוֹ שֶׁנֶּאֱמַר (שמות כ) לִרְחֹץ עַל הַיְאֹר. עַל הַיְאֹר דַּוְקָא, וְלֹא עַל הַיָּם.</p>\n<p>וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב וּמַטְּךְ אֲשֶׁר הִכִּיתָ בּוֹ אֶת הַיְאֹר, וּמֹשֶׁה לֹא הִכָּה אֶלָּא עַל הַיָּם, וְקָרְאוּ לוֹ יְאֹר? אֶלָּא יְאֹר הָיָה שֶׁהִכָּה אַהֲרֹן עַל יְדֵי מֹשֶׁה, וְהֶחֱשִׁיב אוֹתוֹ הַכָּתוּב שֶׁהוּא עָשָׂה זאת.</p>\n<p>כְּמוֹ זֶה וַיִּמָּלֵא שִׁבְעַת יָמִים אַחֲרֵי הַכּוֹת ה' אֶת הַיְאֹר. וְאַהֲרֹן הִכָּהוּ. אֶלָּא עַל שֶׁבָּא מִצַּד הַקָּדוֹשׁ בָּרוּךְ הוּא קְרָאוֹ הַכָּתוּב אַחֲרֵי הַכּוֹת ה', אַחַר כָּךְ קְרָאוֹ בְּשֵׁם מֹשֶׁה. וְנַעֲרֹתֶיהָ הֹלְכֹת עַל יַד הַיְאֹר - אֵלּוּ שְׁאָר הַמַּחֲנוֹת שֶׁבָּאִים מֵהַצַּד הַזֶּה.</p>"],[9522011527,"<p>וַתִּפְתַּח וַתִּרְאֵהוּ אֶת הַיֶּלֶד. וַתִּרְאֵהוּ?! וַתֵּרֶא הָיָה צָרִיךְ (לכתב) ! מַה זֶּה וַתִּרְאֵהוּ? אָמַר רַבִּי שִׁמְעוֹן, אֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁאֵין בּוֹ סוֹדוֹת עֶלְיוֹנִים וְנִכְבָּדִים. אֶלָּא כָּךְ לָמַדְנוּ, רֹשֶׁם הַמֶּלֶךְ וְהַגְּבִירָה נִמְצָא בּוֹ, וְהוּא רֹשֶׁם שֶׁל וָא\"ו הֵ\"א. וּמִיָּד - וַתַּחְמֹל עָלָיו וְגוֹ'. עַד כָּאן לְמַעְלָה. מִכָּאן וָהָלְאָה לְמַטָּה, חוּץ מֵהַכָּתוּב הַזֶּה.</p>\n<p>וַתֵּתַצַב אֲחֹתוֹ מֵרָחֹק וְגוֹ'. וַתֵּתַצַּב אֲחֹתוֹ, אֲחוֹתוֹ שֶׁל מִי? אֲחוֹתוֹ שֶׁל אוֹתוֹ שֶׁקָּרָא לִכְנֶסֶת יִשְׂרָאֵל אֲחוֹתִי, כְּמוֹ שֶׁנֶּאֱמַר (שיר ה) פִּתְחִי לִי אֲחֹתִי רַעְיָתִי. מֵרָחֹק, כְּמוֹ שֶׁנֶּאֱמַר מֵרָחוֹק ה' נִרְאָה לִי.</p>\n<p>(איך) מַשְׁמָע שֶׁאוֹתָם צַדִּיקִים, עַד שֶׁלֹּא יָרְדוּ לָעוֹלָם, נוֹדָעִים הֵם לְמַעְלָה אֶל הַכֹּל, וְכָל שֶׁכֵּן מֹשֶׁה. וּמַשְׁמָע גַּם כֵּן שֶׁנִּשְׁמוֹת הַצַּדִּיקִים נִמְשָׁכוֹת מִמָּקוֹם עֶלְיוֹן, כְּמוֹ שֶׁבֵּאַרְנוּ, וְסוֹד הַדָּבָר לָמַדְנוּ, שֶׁמַּשְׁמָע שֶׁיֵּשׁ לַנְּשָׁמָה אָב וָאֵם, כְּמוֹ שֶׁיֵּשׁ לַגּוּף אָב וָאֵם בָּאָרֶץ, וּמַשְׁמָע שֶׁבְּכָל הַצְּדָדִים, בֵּין לְמַעְלָה בֵּין לְמַטָּה, הַכֹּל בָּא מִזָּכָר וּנְקֵבָה וְנִמְצָאִים. וַהֲרֵי בֵּאֲרוּ אֶת הַסּוֹד, שֶׁכָּתוּב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה. הָאָרֶץ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. נֶפֶשׁ חַיָּה - נֶפֶשׁ שֶׁל אָדָם הָרִאשׁוֹן הָעֶלְיוֹן כְּמוֹ שֶׁנִּתְבָּאֵר. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ. אָמַר, וַדַּאי יָפֶה אָמַרְתָּ, וְכָךְ הוּא וַדַּאי. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה הַנָּבִיא הַנֶּאֱמָן עַל כָּל שְׁאָר נְבִיאֵי הָעוֹלָם.</p>\n<p>דָּבָר אַחֵר וַתֵּתַצַּב אֲחֹתוֹ - זוֹהִי חָכְמָה, כְּמוֹ שֶׁנֶּאֱמַר (משלי ז) אֱמֹר לַחָכְמָה אֲחֹתִי אָתְּ. אָמַר רַבִּי יִצְחָק, מֵעוֹלָם לֹא הָעָבְרָה (התעוררה) מִדַּת הַדִּין מִן הָעוֹלָם, שֶׁהֲרֵי בְּשָׁעָה שֶׁהָיוּ יִשְׂרָאֵל חוֹטְאִים, הָיָה הַדִּין מְקַטְרֵג עִמָּם, וְאָז וַתֵּתַצַּב אֲחֹתוֹ מֵרָחֹק, כְּמוֹ שֶׁנֶּאֱמַר מֵרָחוֹק ה' נִרְאָה לִי.</p>"],[9522011528,"<p>וַתֵּרֶד בַּת פַּרְעֹה לִרְחֹץ עַל הַיְאֹר. בְּשָׁעָה שֶׁהָיוּ יִשְׂרָאֵל פּוֹסְקִים מִן הַתּוֹרָה, מִיָּד - וַתֵּרֶד בַּת פַּרְעֹה לִרְחֹץ עַל הַיְאֹר. הָיְתָה יוֹרֶדֶת מִדַּת הַדִּין לִרְחֹץ מִדַּם יִשְׂרָאֵל עַל עֶלְבּוֹן הַתּוֹרָה. וְנַעֲרֹתֶיהָ הֹלְכֹת עַל יַד הַיְאֹר - אֵלּוּ הָאֱמּוֹת שֶׁהֵם הוֹלְכִים וְרוֹדְפִים אַחֲרֵיהֶם. עַל יַד הַיְאֹר - עַל סִבַּת עֶלְבּוֹן הַתּוֹרָה, וְאוֹתָם שֶׁמּוֹרִים (שישנים) בָּהּ, שֶׁרָפוּ יְדֵיהֶם מִמֶּנָּה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּל דִּבְרֵי הָעוֹלָם תְּלוּיִים בִּתְשׁוּבָה וּבִתְפִלָּה שֶׁמִּתְפַּלֵּל אָדָם לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְכָל שֶׁכֵּן מִי שֶׁשּׁוֹפֵךְ דְּמָעוֹת בִּתְפִלָּתוֹ, שֶׁאֵין לְךְ שַׁעַר שֶׁלֹּא נִכְנָסִים אוֹתָן דְּמָעוֹת. מַה כָּתוּב? וַתִּפְתַּח וַתִּרְאֵהוּ אֶת הַיֶּלֶד. וַתִּפְתַּח - זוֹ שְׁכִינָה שֶׁעוֹמֶדֶת עַל יִשְׂרָאֵל כְּאֵם עַל הַבָּנִים, וְהִיא תָּמִיד פּוֹתַחַת בִּזְכוּתָם שֶׁל יִשְׂרָאֵל.</p>\n<p>כֵּיוָן שֶׁפָּתְחָה - וַתִּרְאֵהוּ אֶת הַיֶּלֶד, יֶלֶד שַׁעֲשׁוּעִים, שֶׁהֵם יִשְׂרָאֵל, שֶׁמִּתְחַטְּאִים לִפְנֵי מַלְכָּם (מאביהם) בַּכֹּל, וּמִיָּד שֶׁמִּתְחַנְּנִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, חוֹזְרִים בִּתְשׁוּבָה וּבוֹכִים לְפָנָיו כְּמוֹ בֵּן שֶׁבּוֹכֶה לִפְנֵי אָבִיו. מַה כָּתוּב? וְהִנֵּה נַעַר בֹּכֶה. כֵּיוָן שֶׁבָּכָה, הָעָבְרוּ (נשתברו) כָּל הַגְּזֵרוֹת הָרָעוֹת שֶׁל הָעוֹלָם. מַה כְּתוּב? וַתַּחְמֹל עָליו, הִתְעוֹרְרָה עָלָיו בְּרַחֲמִים וְרִחֲמָה עָלָיו.</p>\n<p>וַתֹּאמֶר מִיַּלְדֵי הָעִבְרִים זֶה, שֶׁהֵם רַכֵּי לֵב, וְלֹא מִיַּלְדֵי הָעַכּוּ\"ם שֶׁהֵם קְשֵׁי עֹרֶף וּקְשֵׁי לֵב. מִיַּלְדֵי הָעִבְרִים רַכֵּי לֵב מֵאָבוֹת וּמֵאִמָּהוֹת לָשׁוּב לִפְנֵי רִבּוֹנָם. וַתִּקְרָא אֶת אֵם הַיָּלֶד, שֶׁהָיְתָה בּוֹכָה. זֶהוּ שֶׁכָּתוּב (ירמיה לא) קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי תַמְרוּרִים רָחֵל מְבַכָּה עַל בָּנֶיהָ וְגוֹ'. הוּא בּוֹכֶה, וְאֵם הַיֶּלֶד הִיא בּוֹכָה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, לֶעָתִיד לָבֹא מַה כָּתוּב? בִּבְכִי יָבאוּ וּבְתַחֲנוּנִים וְגוֹ'. מַהוּ בִּבְכִי יָבֹאוּ? בִּזְכוּת בְּכִי שֶׁל אֵם הַיֶּלֶד, שֶׁהִיא רָחֵל, יָבוֹאוּ וְיִתְכַּנְּסוּ מֵהַגָּלוּת. וְאָמַר רַבִּי יִצְחָק, הַגְּאֻלָּה שֶׁל יִשְׂרָאֵל לֹא תְלוּיָה אֶלָּא רַק בִּבְכִי, כְּשֶׁיֻּשְׁלְמוּ וְיִכְלוּ בְּכִי הַדְּמָעוֹת שֶׁבָּכָה עֵשָׂו לִפְנֵי אָבִיו, שֶׁכָּתוּב (בראשית כז) וַיִּשָּׂא עֵשָׂו קֹלוֹ וַיֵּבְךָּ. (אמר רבי יוסי, אותו בכי שבכה עשו) וְאוֹתָן דְּמָעוֹת הוֹרִידוּ אֶת יִשְׂרָאֵל לַגָּלוּת. כֵּיוָן שֶׁיִּכְלוּ אוֹתָן דְּמָעוֹת בַּבְּכִיָּה שֶׁל יִשְׂרָאֵל, יֵצְאוּ מִגָּלוּתוֹ, זֶהוּ שֶׁכָּתוּב (ירמיה לא) בִּבְכִי יָבֹאוּ וּבְתַחֲנוּנִים אוֹבִילֵם.</p>"],[9522011529,"<p>וַיִּפֶן כֹּה וָכֹה, רָאָה בְּאוֹתָן חֲמִשִּׁים אוֹתִיּוֹת שֶׁמְּיַחֲדִים אוֹתוֹ יִשְׂרָאֵל בְּכָל יוֹם שְׁמַע יִשְׂרָאֵל פַּעֲמַיִם, שֶׁיֵּשׁ בָּהֶם כ\"ה כ\"ה פַּעֲמַיִם, וְלֹא רָאָה אוֹתָם בּוֹ. וַיִּפֶן כֹּה וָכֹה וְגוֹ'. כֹּה וָכֹה, אָמַר רַבִּי אַבָּא, כֹּה - רָאָה אִם הָיוּ בוֹ מַעֲשִׂים כְּשֵׁרִים. וָכֹה - אִם עָתִיד לָצֵאת מִמֶּנּוּ בֵּן מְעֻלֶּה. מִיָּד - וַיַּרְא כִּי אֵין אִישׁ. רָאָה בְּרוּחַ הַקֹּדֶשׁ שֶׁלֹּא עָתִיד לָצֵאת מִמֶּנּוּ בֵּן מְעֻלֶּה.</p>\n<p>שֶׁאָמַר רַבִּי אַבָּא, כַּמָּה רְשָׁעִים הֵם בָּעוֹלָם שֶׁמּוֹצִיאִים בָּנִים מְעֻלִּים יוֹתֵר מֵאוֹתָם צַדִּיקִים, וְאוֹתוֹ בֵּן מְעֻלֶּה שֶׁיּוֹצֵא מִן הָרָשָׁע הוּא מְעֻלֶּה יוֹתֵר, לִהְיוֹת טָהוֹר מִטָּמֵא, אוֹר מִתּוֹךְ חֲשֵׁכָה, חָכְמָה מִתּוֹךְ טִפְּשׁוּת, וְזֶהוּ הַמְעֻלֶּה מֵהַכֹּל.</p>"],[9522011530,"<p>וַיַּרְא וַיַּרְא שֶׁל כָּאן, הַכֹּל בְּרוּחַ הַקֹּדֶשׁ הִסְתַּכֵּל וְרָאָה, וּמִשּׁוּם כָּךְ הִסְתַּכֵּל וְהָרַג אוֹתוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא סִבֵּב הַכֹּל לָלֶכֶת לְאוֹתָהּ בְּאֵר, כְּמוֹ שֶׁהָלַךְ יַעֲקֹב לְאוֹתָהּ בְּאֵר, שֶׁכָּתוּב וַיֵּשֶׁב עַל הַבְּאֵר. בְּיַעֲקֹב כָּתוּב (בראשית כט) וַיַּרְא וְהִנֵּה בְאֵר. בְּמֹשֶׁה כָּתוּב וַיֵּשֶׁב בְּאֶרֶץ מִדְיָן וַיֵּשֶׁב עַל הַבְּאֵר. מִשּׁוּם שֶׁמֹּשֶׁה וְיַעֲקֹב, אַף עַל גַּב שֶׁבְּדַרְגָּה אַחַת הָיוּ, הִתְעַלָּה מֹשֶׁה בָּזֶה יוֹתֵר מִמֶּנּוּ.</p>\n<p>רַבִּי יוֹסֵי וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי, אוֹתָהּ בְּאֵר שֶׁרָאָה יַעֲקֹב וְרָאה מֹשֶׁה, הַאִם זוֹ הָיְתָה אוֹתָהּ בְּאֵר שֶׁחָפְרוּ אַבְרָהָם וְיִצְחָק? אָמַר לוֹ, לֹא. אֶלָּא בְּשָׁעָה שֶׁנִּבְרָא הָעוֹלָם, נִבְרְאָה הַבְּאֵר הַ את, וּבְעֶרֶב שַׁבָּת בֵּין הַשְּׁמָשׁוֹת נִבְרָא הַפֶּה שֶׁלָּהּ, וְזוֹהִי הַבְּאֵר שֶׁרָאוּ יַעֲקֹב וּמֹשֶׁה.</p>\n<p>מִשְׁנָה, אוֹתָם רוֹדְפֵי אֱמֶת, אוֹתָם הַמְבַקְשִׁים סוֹד הָאֱמוּנָה, אוֹתָם שֶׁדְּבֵקִים בְּקֶשֶׁר נֶאֱמָן, אוֹתָם שֶׁיּוֹדְעִים דַּרְכֵי הַמֶּלֶךְ הָעֶלְיוֹן, קִרְבוּ וְשִׁמְעוּ.</p>\n<p>כְּשֶׁעָלוּ שְׁנַיִם וְיָצְאוּ לְמוּל אֶחָד, מְקַבְּלִים אוֹתוֹ בֵּין שְׁתֵּי זְרוֹעוֹת. שְׁנַיִם יוֹרְדִים לִשְׁלֹשָׁה (למטה) הֵם שְׁנַיִם, אֶחָד מֵהֶם הוּא שְׂדֵה תַפּוּחִים קְדוֹשִׁים, מֵהַבְּאֵר הַזֹּאת יוֹשְׁבִים (שנים יושבים) הַמּוֹשָׁב שֶׁהַנְּבִיאִים (בניו) יוֹנְקִים מֵהֶם. אֶחָד בֵּינֵיהֶם הוּא חִבּוּר שֶׁל הַכֹּל, וְהוּא נוֹטֵל מֵהַכֹּל.</p>\n<p>אוֹתָהּ בְּאֵר קְדוֹשָׁה עוֹמֶדֶת תַּחְתֵּיהֶם, שְׂדֵה תַפּוּחִים (הקדושים) הִיא. מֵהַבְּאֵר הַהִיא נִשְׁקִים הָעֲדָרִים שֶׁרָעָה מֹשֶׁה בַּמִּדְבָּר, מֵהַבְּאֵר הַזאת נִשְׁקוּ הָעֲדָרִים שֶׁבֵּרַר יַעֲקֹב כַּאֲשֶׁר בֵּרַר אוֹתָם לְתוֹךְ חֶלְקוֹ כָּל אוֹתָן מֶרְכָּבוֹת וְכָל אוֹתָם בַּעֲלֵי הַכְּנָפַיִם. שְׁלשָה עוֹמְדִים רוֹבְצִים עַל הַבְּאֵר הַ את. בְּאֵר זוֹ מִתְמַלֵּאת מֵהֶם, וְנִקְרֵאת אֲדֹנָ\"י, עַל זֶה כָּתוּב (דברים ג) אֲדנָי אֱלֹהִים אַתָּה הַחִלּוֹתָ וְגוֹ'. וְכָתוּב (דניאל ט) וְהָאֵר פָּנֶיךְ עַל מִקְדָּשְׁךְ הַשָּׁמֵם לְמַעַן אֲדנָי, אֲדוֹן כָּל הָאָרֶץ, זֶהוּ שֶׁכָּתוּב (יהושע ג) הִנֵּה אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ. בָּהּ גָּנוּז מָקוֹר קָדוֹשׁ שֶׁנּוֹבֵעַ בָּהּ תָּמִיד, וּמְמַלֵּא אוֹתָהּ, שֶׁנִּקְרָא ה' צְבָאוֹת. בָּרוּךְ הוּא לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>\n<p>וּלְכֹהֵן מִדְיָן שֶׁבַע בָּנוֹת וַתָּבֹאנָה וַתִּדְלֶנָה וְגוֹ'. אָמַר רַבִּי יְהוּדָה, אִם בְּאֵר זוֹ שֶׁהִיא בְּאֵר יַעֲקֹב, הֲרֵי כָּתוּב בָּהּ (בראשית כט) וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים וְגָלֲלוּ וְגוֹ'. וְכָאן בְּנוֹת יִתְרוֹ לֹא הִצְטָרְכוּ אֶת זֶה, אֶלָּא וַתָּבאנָה וַתִּדְלֶנָה, בְּלִי טֹרַח אַחֵר.</p>\n<p>אָמַר רַבִּי חִיָּיא, יַעֲקֹב הֵזִיז אוֹתָהּ מִן הַבְּאֵר, שֶׁהֲרֵי כָּתוּב, כְּשֶׁמִּתְכַּנְּסִים שָׁם כָּל הָעֲדָרִים, וְהֵשִׁיבוּ אֶת הָאֶבֶן. וּבְיַעֲקֹב לֹא כָתוּב וַיָּשֶׁב אֶת הָאֶבֶן, שֶׁהֲרֵי לֹא הִצְטָרֵךְ אַחַר כָּךְ, שֶׁהֲרֵי בַּתְּחִלָּה הַמַּיִם לֹא הָיוּ עוֹלִים. כֵּיוָן שֶׁבָּא יַעֲקֹב, עָלוּ הַמַּיִם אֵלָיו, (ומשה אף כך עלו המים אליו) וְאוֹתָהּ הָאֶבֶן לֹא הָיְתָה עַל פִּי הַבְּאֵר, וּמִשּׁוּם כָּךְ וַתָּבאנָה וַתִּדְלֶנָה.</p>\n<p>רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא הָיוּ הוֹלְכִים מִטְּבֶרְיָה לְצִפּוֹרִי. עַד שֶׁהָיוּ הוֹלְכִים, פָּגַע בָּהֶם יְהוּדִי אֶחָד. הִתְחַבֵּר עִמָּם. אָמַר רַבִּי אֶלְעָזָר, כָּל אֶחָד יֹאמַר דְּבַר תּוֹרָה.</p>"],[9522011531,"<p>פָּתַח הוּא וְאָמַר, (יחזקאל לז) וַיֹּאמֶר אֵלַי הִנָּבֵא אֶל הָרוּחַ הִנָּבֵא בֶן אָדָם וְאָמַרְתָּ אֶל הָרוּחַ וְגוֹ'. מִפָּסוּק זֶה יָדַעְתִּי מָקוֹם שֶׁהָרוּחַ יוֹצֵאת מִמֶּנּוּ, וְכִי יָכוֹל הָיָה יְחֶזְקֵאל לְנַבֵּא עַל הָרוּחַ, וַהֲרֵי כָּתוּב, אֵין אָדָם שׁוֹלֵט בָּרוּחַ לִכְלֹא אֶת הָרוּחַ. אֶלָּא, בֶּן אָדָם לֹא יָכוֹל לִשְׁלֹט בָּרוּחַ, אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא שׁוֹלֵט בַּכֹּל, וְעַל מַאֲמָרוֹ הָיָה מִתְנַבֵּא הַנָּבִיא יְחֶזְקֵאל. וְעוֹד, שֶׁהֲרֵי רוּחַ הָיְתָה בַּגּוּף בָּעוֹלָם הַזֶּה, וְלָכֵן הִתְנַבֵּא עָלֶיהָ מֵאַרְבַּע רוּחוֹת בּאִי הָרוּחַ, מֵאוֹתוֹ מָקוֹם שֶׁנִּתְחָם בְּעַמּוּדָיו בְּאַרְבַּעַת הַצְּדָדִים שֶׁל הָעוֹלָם.</p>\n<p>קָפַץ אוֹתוֹ יְהוּדִי לְפָנָיו, אָמַר לוֹ, רַבִּי אֶלְעָזָר, מָה רָאִיתָ? אָמַר, דָּבָר רָאִיתִי. אָמַר לוֹ, מָה? אָמַר לוֹ, רוּחַ בְּנֵי אָדָם אִם מִתְלַבֵּשׁ בְּגַן עֵדֶן בִּלְבוּשׁ שֶׁל דְּיוֹקָן בְּגוּף שֶׁל הָעוֹלָם הַזֶּה, הָיָה לוֹ לִכְתֹּב: כֹּה אָמַר ה' מִגַּן עֵדֶן בּאִי הָרוּחַ. מַהוּ מֵאַרְבַּע רוּחוֹת?</p>\n<p>אָמַר לוֹ, רוּחַ לֹא יוֹרֶדֶת לָעוֹלָם הַזֶּה עַד שֶׁעוֹלָה מֵהַגָּן שֶׁבָּאָרֶץ לְתוֹךְ הַכִּסֵּא שֶׁעוֹמֵד עַל אַרְבָּעָה עַמּוּדִים. כֵּיוָן שֶׁעוֹלָה שָׁם, נִשְׁאֶבֶת מִתּוֹךְ אוֹתוֹ הַכִּסֵּא שֶׁל הַמֶּלֶךְ, וְיוֹרֶדֶת לָעוֹלָם הַזֶּה, הַגּוּף נִטָּל מֵאַרְבָּעָה צִדְדֵי הָעוֹלָם. אַף הָרוּחַ כָּךְ נִטֶּלֶת מֵאַרְבָּעָה צִדְדֵי הַכִּסֵּא שֶׁמְּתֻקָּן עֲלֵיהֶם.</p>\n<p>אָמַר לוֹ אוֹתוֹ הָאִישׁ, הַקְּפִיצָה שֶׁקָּפַצְתִּי לִפְנֵיכֶם, דָּבָר רָאִיתִי מִצַּד זֶה. מִשּׁוּם שֶׁיּוֹם אֶחָד הָיִיתִי הוֹלֵךְ בַּמִּדְבָּר, וְרָאִיתִי עֵץ אֶחָד נֶחְמָד לְמַרְאֶה וּמְעָרָה אַחַת תַּחְתָּיו. קָרַבְתִּי אֵלָיו, וְרָאִיתִי אוֹתָהּ מְעָרָה שֶׁמַּעֲלָה רֵיחוֹת מִכָּל מִינֵי רֵיחוֹת שֶׁל הָעוֹלָם. הִתְחַזַּקְתִּי בְעַצְמִי וְנִכְנַסְתִּי לְאוֹתָהּ מְעָרָה, וְיָרַדְתִּי בְמַדְרֵגוֹת יְדוּעוֹת לְתוֹךְ מָקוֹם אֶחָד שֶׁהָיוּ בוֹ עֵצִים גְּדוֹלִים וְרֵיחוֹת וּבְשָׂמִים שֶׁלֹּא יָכֹלְתִּי לִסְבֹּל.</p>\n<p>וְשָׁם רָאִיתִי אִישׁ אֶחָד, וְשַׁרְבִיט אֶחָד בְּיָדוֹ, וְהָיָה עוֹמֵד בְּפֶתַח אֶחָד. כֵּיוָן שֶׁרָאָה אוֹתִי, תָּמַהּ וְעָמַד אֵלַי. אָמַר לִי, מָה אַתָּה עוֹשֶׂה כָּאן וּמֵאֵיפֹה אַתָּה, אֲנִי פָּחַדְתִּי הַרְבֵּה. אָמַרְתִּי לוֹ, מוֹרִי, אֲנִי מִן הַחֲבֵרִים, וְכָךְ וְכָךְ רָאִיתִי בַּמִּדְבָּר, וְנִכְנַסְתִּי לַמְּעָרָה הַזּוֹ, וְיָרַדְתִּי לְכָאן.</p>\n<p>אָמַר לִי, הוֹאִיל וְאַתָּה מִן הַחֲבֵרִים, קַח אֶת הַכְּתָבִים הַקְּשׁוּרִים הַלָּלוּ וְתֵן אוֹתָם לַחֲבֵרִים, אוֹתָם שֶׁיּוֹדְעִים הַסּוֹדוֹת שֶׁל רוּחוֹת הַצַּדִּיקִים. הִכָּה בִּי בְּאוֹתוֹ שַׁרְבִיט, וְנִרְדַּמְתִּי. בֵּין כָּךְ רָאִיתִי כַּמָּה חֲיָלוֹת וּמַחֲנוֹת בְּתוֹךְ הַשֵּׁנָה שֶׁהָיוּ בָאִים בַּדֶּרֶךְ לְאוֹתוֹ מָקוֹם, וְאוֹתוֹ אִישׁ הִכָּה בְּאוֹתוֹ שַׁרְבִיט וְאָמַר, לְכוּ בַּדֶּרֶךְ שֶׁל הָאִילָנוֹת. בֵּין כָּךְ שֶׁהָיוּ הוֹלְכִים, פָּרְחוּ בָאֲוִיר וְעָלוּ, וְלֹא יָדַעְתִּי לְאֵיפֹה. וְשָׁמַעְתִּי קוֹלוֹת שֶׁל מַחֲנוֹת גְּדוֹלִים, וְלֹא יָדַעְתִּי מֵהֵיכָן (לאיזה מקום) הוּא. הִתְעוֹרַרְתִּי וְלֹא רָאִיתִי דָבָר, וּפָחַדְתִּי בְּאוֹתוֹ מָקוֹם.</p>\n<p>בֵּין כָּךְ רָאִיתִי אוֹתוֹ אִישׁ. אָמַר לִי, רָאִיתָ דָּבָר? אָמַרְתִּי לוֹ, רָאִיתִי בְּתוֹךְ שְׁנָתִי כָּךְ וְכָךְ. אָמַר, בְּאוֹתָהּ דֶּרֶךְ הוֹלְכוֹת רוּחוֹת הַצַּדִּיקִים לְתוֹךְ הַגָּן עֵדֶן לְהִכָּנֵס לְשָׁם, וּמַה שֶּׁשָּׁמַעְתָּ מֵהֶם, הוּא שֶׁעוֹמְדִים בַּגָּן בִּדְיוֹקָן שֶׁל הָעוֹלָם הַזֶּה, וּשְׂמֵחִים בְּרוּחוֹת הַצַּדִּיקִים שֶׁנִּכְנָסִים לְשָׁם.</p>\n<p>וּכְמוֹ שֶׁגּוּף נִבְנֶה בָּעוֹלָם הַזֶּה מִקֶּשֶׁר שֶׁל אַרְבָּעָה יְסוֹדוֹת וּמִצְטַיֵּר בָּעוֹלָם הַזֶּה, אַף כָּךְ הָרוּחַ מִצְטַיֶּרֶת בַּגָּן מִקֶּשֶׁר שֶׁל אַרְבַּע רוּחוֹת שֶׁעוֹמְדוֹת בַּגָּן. וְאוֹתָהּ רוּחַ מִתְלַבֶּשֶׁת שָׁם וּמִצְטַיֶּרֶת מֵהֶם בְּצִיּוּר שֶׁל דְּמוּת הַגּוּף שֶׁהִצְטַיֵּר בָּעוֹלָם הַזֶּה. וְאִלְמָלֵא אוֹתָן אַרְבַּע רוּחוֹת שֶׁהֵן אֲוִירִים שֶׁל הַגָּן, הָרוּחַ לֹא מִצְטַיֶּרֶת בְּצִיּוּר כְּלָל, וְלֹא מִתְלַבֶּשֶׁת בָּהֶם.</p>\n<p>אוֹתָן אַרְבַּע רוּחוֹת קְשׁוּרוֹת אֵלֶּה בְּאֵלֶּה כְּאֶחָד, וְאוֹתָהּ רוּחַ מִצְטַיֶּרֶת וּמִתְלַבֶּשֶׁת בָּהֶן, כְּמוֹ שֶׁהַגּוּף מִצְטַיֵּר בַּקְּשָׁרִים שֶׁל אַרְבָּעָה יְסוֹדוֹת הָעוֹלָם. וְלָכֵן מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ, מֵאוֹתָן אַרְבַּע רוּחוֹת שֶׁל גַּן עֵדֶן שֶׁהִתְלַבְּשָׁה וְהִצְטַיְּרָה בָּהֶן. וְעַכְשָׁו קַח קֶשֶׁר זֶה שֶׁל כְּתָבִים וְלֵךְ לְדַרְכְּךְ, וְתֵן אוֹתָם לַחֲבֵרִים.</p>\n<p>בָּא רַבִּי אֶלְעָזָר וְאוֹתָם הַחֲבֵרִים וּנְשָׁקוּהוּ בְּרֹאשׁוֹ. אָמַר רַבִּי אֶלְעָזָר, בָּרוּךְ הָרַחֲמָן שֶׁשְּׁלָחֲךְ לְכָאן, שֶׁוַּדַּאי זֶהוּ בֵּרוּר הַדָּבָר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִזְמִין לְפִי פָּסוּק זֶה. נָתַן לָהֶם אוֹתוֹ צְרוֹר כְּתָבִים. כֵּיוָן שֶׁנָּטַל אוֹתוֹ רַבִּי אֶלְעָזָר וּפָתַח אוֹתוֹ, יָצָא חֶדֶר אֵשׁ וְהִקִּיפוֹ. רָאָה בּוֹ מַה שֶּׁרָאָה, וּפָרַח מִיָּדָיו.</p>\n<p>בָּכָה רַבִּי אֶלְעָזָר וְאָמַר, מִי יָכוֹל לַעֲמֹד בְּגִנְזֵי הַמֶּלֶךְ, (תהלים טו) ה' מִי יָגוּר בְּאָהֳלֶךְ מִי יִשְׁכֹּן בְּהַר קָדְשֶׁךְ. אַשְׁרֵי דֶּרֶךְ זוֹ וְאוֹתָהּ שָׁעָה שֶׁפָּגַשְׁתִּי אוֹתְךְ. וּמֵאוֹתוֹ יוֹם הָיָה שָׂמֵחַ רַבִּי אֶלְעָזָר, וְלֹא אָמַר כְּלוּם לַחֲבֵרִים. עַד שֶׁהָיוּ הוֹלְכִים, פָּגְשׁוּ בְּאֵר מַיִם אַחַת. עָמְדוּ עָלֶיהָ וְשָׁתוּ מִן הַמַּיִם.</p>"],[9522011532,"<p>אָמַר רַבִּי אֶלְעָזָר, אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים. יַעֲקֹב בָּרַח מִלִּפְנֵי אָחִיו, וְהִזְדַּמְּנָה לוֹ בְּאֵר. כֵּיוָן שֶׁהַבְּאֵר רָאֲתָה אוֹתוֹ, הַמַּיִם נוֹדְעוּ לַאֲדוֹנֵיהֶם וְעָלוּ אֵלָיו וְשָׂמְחוּ עִמּוֹ, וְשָׁם הִזְדַּוְּגָה לוֹ בַּת זוּגוֹ. מֹשֶׁה בָּרַח מִלִּפְנֵי פַרְעֹה וְהִזְדַּמְּנָה לוֹ אוֹתָהּ בְּאֵר, וְהַמַּיִם רָאוּ אוֹתוֹ וְנוֹדְעוּ לַאֲדוֹנֵיהֶם וְעָלוּ אֵלָיו, וְשָׁם הִזְדַּוְּגָה לוֹ בַּת זוּגוֹ.</p>\n<p>מַה בֵּין מֹשֶׁה לְיַעֲקֹב? בְּיַעֲקֹב כָּתוּב (בראשית כט) וַיְהִי כַּאֲשֶׁר רָאָה יַעֲקֹב אֶת רָחֵל וְגוֹ'. וַיִּגַּשׁ יַעֲקֹב וַיָּגֶל אֶת הָאֶבֶן וְגוֹ'. מַה כָּתוּב בְּמֹשֶׁה? וַיָּבֹאוּ הָרֹעִים וַיְגָרֲשׁוּם וַיָּקָם מֹשֶׁה וַיּוֹשִׁעָן וְגוֹ'. בְּוַדַּאי שֶׁמֹּשֶׁה הָיָה יוֹדֵעַ, שֶׁכֵּיוָן שֶׁרָאָה מַיִם שֶׁעוֹלִים אֵלָיו, שֶׁשָּׁם תִּזְדַּמֵּן לוֹ בַּת זוּגוֹ. וְעוֹד, שֶׁהֲרֵי רוּחַ הַקֹּדֶשׁ לֹא זָזָה מִמֶּנּוּ לְעוֹלָמִים, וּבָהּ הָיָה יוֹדֵעַ שֶׁצִּפּוֹרָה תִּהְיֶה בַּת זוּגוֹ. אָמַר מֹשֶׁה, וַדַּאי יַעֲקֹב בָּא לְכָאן וְהַמַּיִם עָלוּ אֵלָיו, וְהִזְדַּמֵּן לוֹ אָדָם שֶׁהִכְנִיסוֹ לְבֵיתוֹ וְנָתַן לוֹ כָּל מַה שֶּׁצָּרִיךְ, אַף אֲנִי כָּךְ.</p>\n<p>אָמַר אוֹתוֹ הָאִישׁ, כָּךְ לָמַדְנוּ, שֶׁיִּתְרוּ הָיָה כֹּמֶר לְכוֹכָבִים וּמַזָּלוֹת. כֵּיוָן שֶׁרָאָה שֶׁכּוֹכָבִים וּמַזָּלוֹת אֵין בָּהֶם מַמָּשׁ, נִפְרַד מֵעֲבוֹדָתָהּ. קָם הָעָם וְנִדָּה אוֹתוֹ. כֵּיוָן שֶׁרָאוּ אֶת בְּנוֹתָיו, הָיוּ מְגָרְשִׁים אוֹתָם, שֶׁהֲרֵי בַּהַתְחָלָה הֵן הָיוּ רוֹעוֹת צֹאנוֹ. כֵּיוָן שֶׁרָאָה מֹשֶׁה בְּרוּחַ הַקֹּדֶשׁ שֶׁעַל דָּבָר שֶׁל כּוֹכָבִים וּמַזָּלוֹת הָיוּ עוֹשִׂים כָּךְ, מִיָּד - וַיָּקָם מֹשֶׁה וַיּוֹשִׁעָן וַיַּשְׁק אֶת צֹאנָם, וְנַעֲשָׂה קַנַּאי לַקָּדוֹשׁ-בָּרוּךְ-הוּא בַּכֹּל.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, אַתָּה אֶצְלֵנוּ, וְלֹא יוֹדְעִים אֶת שִׁמְךְ. אָמַר, אֲנִי יוֹעֵזֶר בֶּן יַעֲקֹב. בָּאוּ הַחֲבֵרִים וּנְשָׁקוּהוּ. אָמְרוּ, וּמָה אַתָּה אֶצְלֵנוּ, וְאָנוּ לֹא הָיִינוּ יוֹדְעִים אוֹתְךְ? הָלְכוּ כְּאֶחָד כָּל אוֹתוֹ הַיּוֹם, וּלְיוֹם אַחֵר לִוּוּ אוֹתוֹ שְׁלֹשָׁה מִילִין, וְהָלַךְ לְדַרְכּוֹ.</p>\n<p>וַתֹּאמַרְן אִישׁ מִצְרִי הִצִּילָנוּ. רַבִּי חִיָּיא אָמַר, הֲרֵי בֵּאֲרוּ הַחֲבֵרִים, שֶׁנִּצְנְצָה בָהֶן רוּחַ הַקֹּדֶשׁ, וְאָמְרוּ וְלֹא יָדְעוּ מָה אָמְרוּ. לְאִישׁ שֶׁהָיָה יוֹשֵׁב בַּמִּדְבָּר, וְהָיוּ יָמִים שֶׁלֹּא אָכַל בָּשָׂר. יוֹם אֶחָד בָּא דֹּב לִטֹּל כֶּבֶשׂ אֶחָד. בָּרַח הַכֶּבֶשׂ, וְהַדֹּב אַחֲרָיו, עַד שֶׁהִגִּיעוּ לְאוֹתוֹ אִישׁ לַמִּדְבָּר. רָאָה כֶּבֶשׂ וְהֶחֱזִיק בּוֹ וּשְׁחָטוֹ, וְאָכַל בָּשָׂר.</p>\n<p>דָּבָר אַחֵר וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל - רַבִּי יְהוּדָה פָּתַח וְאָמַר, (שיר א) שְׁחוֹרָה אֲנִי וְנָאוָה וְגוֹ'. שְׁחוֹרָה אֲנִי וְנָאוָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא שְׁחוֹרָה מִן הַגָּלוּת. וְנָאוָה - שֶׁהִיא נָאוָה בְּתוֹרָה וּמִצְווֹת וּמַעֲשִׂים כְּשֵׁרִים. בְּנוֹת יְרוּשָׁלם - שֶׁעַל זֶה זַכָּאִים לָרֶשֶׁת אֶת יְרוּשָׁלַיִם שֶׁל מַעְלָה. כְּאָהֳלֵי קֵדָר - אַף עַל גַּב שֶׁהִיא קוֹדֶרֶת בַּגָּלוּת, בַּמַּעֲשִׂים הִיא כִּירִיעוֹת שְׁלֹמֹה, כַּיְרִיעוֹת שֶׁל הַמֶּלֶךְ שֶׁהַשָּׁלוֹם כֻּלּוֹ שֶׁלּוֹ.</p>"],[9522011533,"<p>רַבִּי חִיָּיא הַגָּדוֹל הָיָה הוֹלֵךְ לְבַעֲלֵי הַמִּשְׁנָה לִלְמֹד מֵהֶם. הָלַךְ לְרַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, וְרָאָה פַּרְגּוֹד אֶחָד שֶׁהָיָה מַפְסִיק בַּבַּיִת. תָּמַהּ רַבִּי חִיָּיא. אָמַר, אֶשְׁמַע דָּבָר מִפִּיו מִכָּאן.</p>\n<p>שָׁמַע שֶׁהָיָה אוֹמֵר, בְּרַח דּוֹדִי וּדְמֵה לְךְ לִצְבִי אוֹ לְעֹפֶר הָאַיָּלִים. כָּל הַכִּסּוּף שֶׁכּוֹסְפִים יִשְׂרָאֵל (מלפני) מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא שֶׁאָמַר רַבִּי שִׁמְעוֹן, תַּאֲוָתָם שֶׁל יִשְׂרָאֵל שֶׁיִּהְיֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הוֹלֵךְ וְלֹא מִתְרַחֵק, אֶלָּא בּוֹרֵחַ כִּצְבִי אוֹ כְּעֹפֶר הָאַיָּלִים.</p>\n<p>מָה הַטַּעַם? אָמַר רַבִּי שִׁמְעוֹן, אֵין חַיָּה בָּעוֹלָם עוֹשָׂה כְּמוֹ הַצְּבִי אוֹ כְּעֹפֶר הָאַיָּלִים. בִּזְמַן שֶׁהוּא בּוֹרֵחַ, הוֹלֵךְ מְעַט מְעַט וּמַחֲזִיר אֶת רֹאשׁוֹ לַמָּקוֹם שֶׁיָּצָא מִמֶּנּוּ, וּלְעוֹלָם הוּא תָּמִיד מַחֲזִיר אֶת רֹאשׁוֹ לַאֲחוֹרָיו. כָּךְ אָמְרוּ יִשְׂרָאֵל: רִבּוֹנוֹ שֶׁל עוֹלָם, אִם אָנוּ גוֹרְמִים שֶׁתִּסְתַּלֵּק מִבֵּינֵינוּ - יְהִי רָצוֹן שֶׁתִּבְרַח כְּמוֹ הַצְּבִי אוֹ כְּמוֹ עֹפֶר הָאַיָּלִים, שֶׁהוּא בּוֹרֵחַ וּמַחֲזִיר אֶת רֹאשׁוֹ לַמָּקוֹם שֶׁהִנִּיחַ. זֶהוּ שֶׁכָּתוּב (ויקרא כו) וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים לְכַלֹּתָם. דָּבָר אַחֵר - הַצְּבִי, כְּשֶׁהוּא יָשֵׁן, הוּא יָשֵׁן בְּעַיִן אַחַת, וְהָאַחֶרֶת הוּא נֵעוֹר. כָּךְ אָמְרוּ יִשְׂרָאֵל לַקָּדוֹשׁ-בָּרוּךְ- הוּא, עֲשֵׂה כְּמוֹ הַצְּבִי, שֶׁהִנֵּה לֹא יָנוּם וְלֹא יִישַׁן שׁוֹמֵר יִשְׂרָאֵל.</p>\n<p>שָׁמַע רַבִּי חִיָּיא וְאָמַר, אִם עֶלְיוֹנִים (פוסקים) עוֹסְקִים בַּבַּיִת, וַאֲנִי יוֹשֵׁב בַּחוּץ?! בָּכָה. שָׁמַע רַבִּי שִׁמְעוֹן וְאָמַר, וַדַּאי שְׁכִינָה בַּחוּץ, מִי יֵצֵא? אָמַר רַבִּי אֶלְעָזָר בְּנוֹ, אִם אֲנִי אֶשָּׂרֵף - (כחול) לֹא אֶשָּׂרֵף, שֶׁהֲרֵי הַשְּׁכִינָה מִחוּץ אֵלֵינוּ. שֶׁתִּכָּנֵס הַשְּׁכִינָה, וְתִהְיֶה אֵשׁ שְׁלֵמָה. שָׁמַע קוֹל שֶׁאוֹמֵר: עֲדַיִן לֹא נִסְמְכוּ הַסּוֹמְכִים, וְהַשְּׁעָרִים עֲדַיִן לֹא הֻתְקְנוּ, וּמִקְּטַנֵּי (ומאהלי) הַבְּשָׂמִים שֶׁל עֵדֶן, שֶׁכָּעֵת הוּא. לֹא יָצָא רַבִּי אֶלְעָזָר.</p>\n<p>יָשַׁב רַבִּי חִיָּיא, בָּכָה וְנֶאֱנַח. פָּתַח וְאָמַר, סֹב דְּמֵה לְךְ דוֹדִי לִצְבִי אוֹ לְעֹפֶר הָאַיָּלִים. נִפְתַּח שַׁעַר הַפַּרְגּוֹד, לֹא נִכְנַס רַבִּי חִיָּיא. זָקַף רַבִּי שִׁמְעוֹן אֶת עֵינָיו וְאָמַר, מִזֶּה נִשְׁמָע שֶׁנִּתְּנָה רְשׁוּת לְמִישֶׁהוּ בַּחוּץ, וְאָנוּ בִּפְנִים?! קָם רַבִּי שִׁמְעוֹן. הָלְכָה הָאֵשׁ מִמְּקוֹמָהּ עַד מְקוֹם רַבִּי חִיָּיא. אָמַר רַבִּי שִׁמְעוֹן, נִיצוֹץ אוֹר הַקְּלִיטָה בַּחוּץ, שֶׁל הַמַּפְתֵּחַ וְאָנוּ כָּאן בִּפְנִים?! הִתְאַלֵּם פִּיו שֶׁל רַבִּי חִיָּיא.</p>\n<p>כֵּיוָן שֶׁנִּכְנַס פְּנִימָה, הוֹרִיד אֶת עֵינָיו וְלֹא זָקַף רֹאשׁוֹ. אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אֶלְעָזָר בְּנוֹ, קוּם הַעֲבֵר יָדְךְ עַל פִּיו, שֶׁלֹּא יוֹדֵעַ בָּזֶה, שֶׁלֹּא רָגִיל בּוֹ. קָם רַבִּי אֶלְעָזָר וְהֶעֱבִיר יָדוֹ עַל פִּי רַבִּי חִיָּיא. פָּתַח פִּיו רַבִּי חִיָּיא וְאָמַר, רָאֲתָה עֵינִי מַה שֶּׁלֹּא רָאִיתִי. הִזְדַּקַּפְתִּי שֶׁלֹּא חָשַׁבְתִּי, שֶׁטּוֹב לָמוּת בְּאֵשׁ שֶׁל זָהָב טוֹב שֶׁדּוֹלֵק.</p>\n<p>בְּמָקוֹם שֶׁזּוֹרְקִים שְׁבִיבֵי אֵשׁ לְכָל עֵבֶר, וְכָל שְׁבִיב וּשְׁבִיב עוֹלֶה לִשְׁלֹשׁ מֵאוֹת וְשִׁבְעִים מֶרְכָּבוֹת, וְכָל מֶרְכָּבָה נִפְרֶדֶת לְאֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת, עַד שֶׁמַּגִּיעַ לְעַתִּיק הַיָּמִים שֶׁיּוֹשֵׁב עַל כִּסֵּא, וְהַכִּסֵּא מִזְדַּעֲזֵעַ מִמֶּנּוּ לְמָאתַיִם וְשִׁשִּׁים עוֹלָמוֹת.</p>\n<p>עַד שֶׁמַּגִּיעַ לִמְקוֹם עִדּוּן הַצַּדִּיקִים, עַד שֶׁנִּשְׁמָע בְּכָל הָרְקִיעִים, וְכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, וְכֻלָּם בִּזְמַן אֶחָד, תְּמֵהִים וְאוֹמְרִים: זֶהוּ רַבִּי שִׁמְעוֹן בַּר יוֹחַאי שֶׁהָיָה מַרְעִישׁ הַכֹּל, מִי יָכוֹל לַעֲמֹד לְפָנָיו. זֶהוּ הוּא רַבִּי שִׁמְעוֹן בַּר יוֹחַאי שֶׁבְּשָׁעָה שֶׁפּוֹתֵחַ פִּיו לְהַתְחִיל לַעֲסֹק בַּתּוֹרָה, מַקְשִׁיבִים לְקוֹלוֹ כָּל הַכִּסְאוֹת וְכָל הָרְקִיעִים וְכָל הַמֶּרְכָּבוֹת, וְכָל אוֹתָם שֶׁמְּשַׁבְּחִים אֶת רִבּוֹנָם.</p>\n<p>אֵין פּוֹתְחִים וְאֵין מְסַיְּמִים, כֻּלָּם נִמְצָאִים, עַד שֶׁלֹּא נִשְׁמָע (שישתמע) בְּכָל הָרְקִיעִים שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה פִּתְחוֹן פֶּה. כְּשֶׁמְּסַיֵּם רַבִּי שִׁמְעוֹן לַעֲסֹק בַּתּוֹרָה, מִי רוֹאֶה אֵיזֶה שִׁירִים? מִי רוֹאֶה אֵיזוֹ חֶדְוָה שֶׁמְּשַׁבְּחִים לְרִבּוֹנָם? מִי רוֹאֶה אֶת הַקּוֹלוֹת שֶׁהוֹלְכִים בְּכָל הָרְקִיעִים? כֻּלָּם בָּאִים בִּשְׁבִיל רַבִּי שִׁמְעוֹן וְכוֹרְעִים וּמִשְׁתַּחֲוִים לִפְנֵי רִבּוֹנָם, מַעֲלִים רֵיחוֹת שֶׁל בְּשָׂמִים שֶׁל עֵדֶן עַד עַתִּיק הַיָּמִים, וְכָל זֶה מִשּׁוּם רַבִּי שִׁמְעוֹן.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן פִּיו וְאָמַר, שֵׁשׁ דְּרָגוֹת יָרְדוּ עִם יַעֲקֹב לְמִצְרַיִם, וְכָל אַחַת וְאַחַת עֲשָׂרָה אֶלֶף רִבּוֹא. וּכְנֶגְדָּן שֵׁשׁ דְּרָגוֹת לְיִשְׂרָאֵל, וּכְנֶגְדָּן שֵׁשׁ דְּרָגוֹת לַכִּסֵּא הָעֶלְיוֹן, וּכְנֶגְדָּן שֵׁשׁ דְּרָגוֹת לַכִּסֵּא שֶׁלְּמַטָּה, שֶׁכָּתוּב שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. זֶהוּ שֶׁכָּתוּב (יחזקאל טז) רְבָבָה כְּצֶמַח הַשָּׂדֶה נְתַתִּיךְ וְגוֹ'. הֲרֵי שֵׁשׁ. וּכְנֶגְדָּן כָּתוּב וּבְנֵי יִשְׂרָאֵל פָּרוּ וַיִּשְׁרְצוּ וַיִּרְבּוּ וַיַּעַצְמוּ וְגוֹ'.</p>\n<p>בֹּא רְאֵה, כָּל אֶחָד וְאֶחָד עוֹלֶה לַעֲשָׂרָה, וְהָיוּ שִׁשִּׁים, וְאוֹתָם שִׁשִּׁים גִּבּוֹרִים שֶׁסְּבִיב הַשְּׁכִינָה, וְהֵם שִׁשִּׁים רְבָבוֹת שֶׁיָּצְאוּ עִם יִשְׂרָאֵל מִן הַגָּלוּת וְשֶׁנִּכְנְסוּ עִם יַעֲקֹב לַגָּלוּת.</p>\n<p>אָמַר לוֹ רַבִּי חִיָּיא, וַהֲרֵי הָיוּ (רואים) שִׁבְעָה וְעָלוּ לְשִׁבְעִים. אָמַר לוֹ רַבִּי שִׁמְעוֹן, שִׁבְעִים לֹא מִכָּאן. וְאִם תַּעֲלֶה בְדַעְתְּךְ שִׁבְעָה, הֲרֵי כָּתוּב (שמות כה) וְשִׁשָּׁה קָנִים יצְאִים מִצִּדֶּיהָ שְׁלֹשָׁה קְנֵי מְנֹרָה וְגוֹ'. וְקָנֶה אֶחָד הָאֶמְצָעִי לֹא בַּחֶשְׁבּוֹן, שֶׁכָּתוּב (במדבר ח) אֶל מוּל פְּנֵי הַמְּנוֹרָה יָאִירוּ וְגוֹ'.</p>"],[9522011534,"<p>עַד שֶׁהָיוּ יוֹשְׁבִים, אָמַר רַבִּי אֶלְעָזָר לְרַבִּי שִׁמְעוֹן אָבִיו, מָה רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹרִיד אֶת יִשְׂרָאֵל לְמִצְרַיִם בַּגָּלוּת? אָמַר לוֹ, שְׁאֵלָה אַחַת אַתָּה שׁוֹאֵל, אוֹ שְׁתַּיִם? אָמַר לוֹ, שְׁתַּיִם. גָּלוּת לָמָּה, וְלָמָּה דַּוְקָא לְמִצְרַיִם? אָמַר לוֹ, שְׁתַּיִם הֵן, וְחוֹזְרוֹת לִהְיוֹת אַחַת. אָמַר לוֹ, עֲמֹד בְּעָמְדְּךְ בִּשְׁבִילְךְ יִתְקַיֵּם לְמַעְלָה מִשִּׁמְךְ דָּבָר זֶה. אֱמֹר בְּנִי, אֱמֹר.</p>\n<p>פָּתַח וְאָמַר, (שיר ו) שִׁשִּׁים הֵמָּה מְלָכוֹת וּשְׁמֹנִים פִּילַגְשִׁים. שִׁשִּׁים הֵמָּה מְלָכוֹת - אוֹתָם גִּבּוֹרִים שֶׁלְּמַעְלָה מִכֹּחַ הַגְּבוּרָה שֶׁנֶּאֱחָזִים בַּקְּלִיפּוֹת (בחקיקות) שֶׁל חַיָּה הַקְּדוֹשָׁה שֶׁל יִשְׂרָאֵל. וּשְׁמֹנִים פִּילַגְשִׁים - מְמֻנִּים בַּחֲקִיקוֹת שֶׁתַּחְתֵּיהֶן בַּחֲזָרָה (באחד) אֶחָד מִמֵּאָה. וַעֲלָמוֹת אֵין מִסְפָּר - כַּנֶּאֱמַר הֲיֵשׁ מִסְפָּר לִגְדוּדָיו. וְעִם כָּל זֶה כָּתוּב, אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ. זוֹהִי הַשְּׁכִינָה הַקְּדוֹשָׁה שֶׁיּוֹצֵאת מִבַּעֲלֵי הַמָּגֵן (משנים עשר) אוֹרוֹת שֶׁזּוֹהֲרִים שֶׁמְּאִירִים לַכֹּל, וְהִיא נִקְרֵאת אֵם (בינה).</p>\n<p>כְּמוֹ זֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ, זָרַק אֶת כָּל הָעַמִּים לְכָל עֵבֶר, וּמִנָּה עֲלֵיהֶם גְּדוֹלִים, זֶהוּ שֶׁכָּתוּב (דברים ד) אֲשֶׁר חָלַק ה' אֱלֹהֶיךְ אֹתָם לְכֹל הָעַמִּים. וְהוּא לָקַח לְחֶלְקוֹ אֶת כְּנֶסֶת יִשְׂרָאֵל, זֶהוּ שֶׁכָּתוּב כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ. וְקָרָא לָהּ אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ. זוֹהִי שְׁכִינַת כְּבוֹדוֹ שֶׁהִשְׁרָה בֵינֵיהֶם, אַחַת הִיא וּמְיֻחֶדֶת לוֹ. רָאוּהָ בָּנוֹת וַיְאַשְּׁרוּהָ, כְּמוֹ שֶׁנֶּאֱמַר (משלי לא) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל וְאַתְּ עָלִית עַל כֻּלָּנָה. מְלָכוֹת וּפִילַגְשִׁים וַיְהַלְלוּהָ - אֵלּוּ גְּדוֹלֵי הָעַמִּים שֶׁנִּפְקְדוּ עֲלֵיהֶם.</p>\n<p>וְעוֹד סוֹד הַדָּבָר הוּא, שֶׁשָּׁנִינוּ, בַּעֲשָׂרָה מַאֲמָרוֹת נִבְרָא הָעוֹלָם, וּכְשֶׁתִּסְתַּכֵּל הֵם שְׁלֹשָׁה, וְהָעוֹלָם נִבְרָא בָהֶם בְּחָכְמָה וּבִתְבוּנָה וּבְדַעַת, וְהָעוֹלָם לֹא נִבְרָא אֶלָּא בִּשְׁבִיל יִשְׂרָאֵל. כְּשֶׁרָצָה לְהַעֲמִיד אֶת הָעוֹלָם, עָשָׂה אֶת אַבְרָהָם בְּסוֹד הַחָכְמָה, אֶת יִצְחָק בְּסוֹד הַתְּבוּנָה, וְאֶת יַעֲקֹב בְּסוֹד הַדַּעַת, וּבָזֶה נִקְרָא (משלי כד) וּבְדַעַת חֲדָרִים יִמָּלְאוּ. וּבְאוֹתָהּ שָׁעָה נִתְקַן כָּל הָעוֹלָם, וּמִשֶּׁנּוֹלְדוּ לְיַעֲקֹב שְׁנֵים עָשָׂר שְׁבָטִים, נִתְקַן הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>כְּשֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא חֶדְוָה רַבָּה שֶׁל הָעוֹלָם הַתַּחְתּוֹן הַזֶּה שֶׁנִּתְקַן כְּמוֹ שֶׁלְּמַעְלָה, אָמַר, אוּלַי חַס וְשָׁלוֹם יִתְעָרְבוּ בִּשְׁאָר הָעַמִּים וְיִשָּׁאֵר פְּגָם בְּכָל הָעוֹלָמוֹת. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? טִלְטֵל אֶת כֻּלָּם מִכָּאן לְכָאן, עַד שֶׁיָּרְדוּ לְמִצְרַיִם לָדוּר אֶת דִּיּוּרָם בְּעַם קְשֵׁה עֹרֶף, שֶׁמְּבַזִּים אֶת מִנְהֲגֵיהֶם וּמְבַזִּים אוֹתָם לְהִתְחַתֵּן בָּהֶם וּלְהִתְעָרֵב עִמָּהֶם, וְחוֹשְׁבִים אוֹתָם לַעֲבָדִים. הַגְּבָרִים גָּעֲלוּ בָהֶם, וְהַנְּקֵבוֹת גָּעֲלוּ בָהֶם, עַד שֶׁנִּתְקַן הַכֹּל בְּזֶרַע קֹדֶשׁ, וּבֵין כָּךְ וּבֵין כָּךְ נִשְׁלַם חֵטְא שְׁאָר הָעַמִּים, שֶׁכָּתוּב (בראשית טו) כִּי לֹא שָׁלֵם עֲוֹן הָאֱמוֹרִי עַד הֵנָּה. וּכְשֶׁיָּצְאוּ, יָצְאוּ צַדִּיקִים קְדוֹשִׁים, שֶׁכָּתוּב שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל. בָּא רַבִי שִׁמְעוֹן וּנְשָׁקוֹ בְרֹאשׁוֹ. אָמַר לוֹ, עֲמֹד בְּנִי בְּעָמְדְּךְ, כִּי הַשָּׁעָה עוֹמֶדֶת לְךְ.</p>"],[9522011535,"<p>יָשַׁב רַבִּי שִׁמְעוֹן, וְרַבִּי אֶלְעָזָר בְּנוֹ עוֹמֵד וּמְפָרֵשׁ דְּבָרִים שֶׁל סוֹדוֹת חָכְמָה, וְהָיוּ פָנָיו מְאִירוֹת כַּשֶּׁמֶשׁ. וְהַדְּבָרִים מִתְפַּזְּרִים וְטָסִים בָּרָקִיעַ. יָשְׁבוּ יוֹמַיִם וְלֹא אָכְלוּ וְלֹא שָׁתוּ, וְלֹא הָיוּ יוֹדְעִים אִם הָיָה יוֹם אוֹ לַיְלָה. כְּשֶׁיָּצְאוּ, יָדְעוּ שֶׁהָיוּ יוֹמַיִם שֶׁלֹּא טָעֲמוּ דָבָר. קָרָא עַל זֶה רַבִּי שִׁמְעוֹן, וַיְהִי שָׁם עִם ה' אַרְבָּעִים יוֹם וְאַרְבָּעִים לַיְלָה לֶחֶם לֹא אָכַל וְגוֹ'. וּמָה אִם אָנוּ בְּשָׁעָה אַחַת כָּךְ - מֹשֶׁה, שֶׁהַכָּתוּב הֵעִיד בּוֹ וַיְהִי שָׁם עִם ה' אַרְבָּעִים יוֹם וְגוֹ', עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>כְּשֶׁבָּא רַבִּי חִיָּיא לִפְנֵי רַבִּי וְסִפֵּר לוֹ אֶת הַמַּעֲשֶׂה, תָּמַהּ רַבִּי, וְאָמַר לוֹ רַבִּי שִׁמְעוֹן בֶּן גַּמְלִיאֵל אָבִיו, בְּנִי, רַבִּי שִׁמְעוֹן בַּר יוֹחַאי אַרְיֵה, וְרַבִּי אֶלְעָזָר בְּנוֹ אַרְיֵה, וְאֵין רַבִּי שִׁמְעוֹן כִּשְׁאָר אֲרָיוֹת, עָלָיו כָּתוּב (עמוס ג) אַרְיֵה שָׁאָג מִי לֹא יִירָא וְגוֹ'. וּמָה עוֹלָמוֹת שֶׁלְּמַעְלָה מִזְדַּעְזְעִים מִמֶּנּוּ - אָנוּ עַל אַחַת כַּמָּה וְכַמָּה. אִישׁ שֶׁלֹּא גָזַר תַּעֲנִית לְעוֹלָמִים עַל מַה שֶּׁשָּׁאַל וּבִקֵּשׁ, אֶלָּא הוּא גּוֹזֵר וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְקַיֵּם, הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר וְהוּא מְבַטֵּל, וְהַיְנוּ מַה שֶּׁשָּׁנִינוּ מַה שֶּׁכָּתוּב (שמואל ב כג) מוֹשֵׁל בָּאָדָם צַדִּיק מוֹשֵׁל יִרְאַת אֱלֹהִים. הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשֵׁל בָּאָדָם. וּמִי מוֹשֵׁל בַּקָּדוֹשׁ-בָּרוּךְ-הוּא? צַדִּיק, שֶׁהוּא גּוֹזֵר גְּזֵרָה, וְהַצַּדִּיק מְבַטְּלָהּ.</p>"],[9522011536,"<p>שָׁנִינוּ, אָמַר רַבִּי יְהוּדָה, אֵין לְךְ דָּבָר בַּחֲבִיבוּת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ תְפִלָּתָם שֶׁל צַדִּיקִים. וְאַף עַל גַּב שֶׁנּוֹחַ לוֹ, לִפְעָמִים שֶׁעוֹשֶׂה בַּקָּשָׁתָם וְלִפְעָמִים שֶׁלֹּא עוֹשֶׂה.</p>\n<p>שָׁנוּ רַבּוֹתֵינוּ, פַּעַם אַחַת הָיָה הָעוֹלָם צָרִיךְ מָטָר. בָּא רַבִּי אֱלִיעֶזֶר וְגָזַר אַרְבָּעִים תַּעֲנִיּוֹת וְלֹא בָא מָטָר. הִתְפַּלֵּל תְּפִלָּה וְלֹא בָא מָטָר. בָּא רַבִּי עֲקִיבָא וְעָמַד וְהִתְפַּלֵּל. אָמַר מַשִּׁיב הָרוּחַ, וְנָשְׁבָה רוּחַ. אָמַר וּמוֹרִיד הַגֶּשֶׁם, וּבָא מָטָר. חָלְשָׁה דַעְתּוֹ שֶׁל רַבִּי אֱלִיעֶזֶר. הִסְתַּכֵּל רַבִּי עֲקִיבָא בְּפָנָיו.</p>\n<p>קָם רַבִּי עֲקִיבָא לִפְנֵי הָעָם וְאָמַר, אֶמְשֹׁל לָכֶם מָשָׁל לְמָה הַדָּבָר דּוֹמֶה. רַבִּי אֱלִיעֶזֶר דּוֹמֶה לַאֲהוּב הַמֶּלֶךְ שֶׁאוֹהֵב אוֹתוֹ יוֹתֵר, וּכְשֶׁנִּכְנָס לִפְנֵי הַמֶּלֶךְ, נוֹחַ לוֹ, וְלֹא רוֹצֶה לָתֵת לוֹ בַּקָּשָׁתוֹ בְּחִפָּזוֹן, כְּדֵי שֶׁלֹּא יִפָּרֵד מִמֶּנּוּ, שֶׁנּוֹחַ לוֹ לְדַבֵּר עִמּוֹ. וַאֲנִי דּוֹמֶה לְעֶבֶד הַמֶּלֶךְ שֶׁבִּקֵּשׁ בַּקָּשָׁתוֹ לְפָנָיו, וְלֹא רוֹצֶה הַמֶּלֶךְ שֶׁיִּכָּנֵס לְשַׁעֲרֵי אַרְמוֹנוֹ, וְכָל שֶׁכֵּן לְדַבֵּר עִמּוֹ. אָמַר הַמֶּלֶךְ, תְּנוּ לוֹ בַּקָּשָׁתוֹ בִּמְהִירוּת וְלֹא יִכָּנֵס לְכָאן. כָּךְ רַבִּי אֱלִיעֶזֶר הוּא אֲהוּב הַמֶּלֶךְ, וַאֲנִי הָעֶבֶד, וְהַמֶּלֶךְ רוֹצֶה לְדַבֵּר עִמּוֹ כָּל הַיּוֹם וְלֹא יִפָּרֵד מִמֶּנּוּ, וַאֲנִי - הַמֶּלֶךְ לֹא רוֹצֶה שֶׁאֶכָּנֵס לְשַׁעֲרֵי אַרְמוֹנוֹ. וְנָחָה דַעְתּוֹ שֶׁל רַבִּי אֱלִיעֶזֶר.</p>\n<p>אָמַר לוֹ, עֲקִיבָא, בּא וְאַגִּיד לְךְ דָּבָר, שֶׁנִּרְאָה לִי בַּחֲלוֹם פָּסוּק זֶה, שֶׁכָּתוּב (ירמיה ז) וְאַתָּה אַל תִּתְפַּלֵּל בְּעַד הָעָם הַזֶּה וְאַל תִּשָּׂא בַעֲדָם רִנָּה וּתְפִלָּה וְאַל תִּפְגַּע בִּי. בּא רְאֵה, שְׁנֵים עָשָׂר הָרֵי אֲפַרְסְמוֹן (טהור) נִכְנַס אוֹתוֹ שֶׁלּוֹבֵשׁ חֹשֶׁן וְאֵפוֹד, וּבִקֵּשׁ מֵהַקָּדוֹשׁ בָּרוּךְ הוּא לָחוּס עַל הָעוֹלָם, וְעַד עַכְשָׁו הוּא תָּלוּי. אִם כָּךְ, לָמָּה חָלְשָׁה דַעְתּוֹ שֶׁל רַבִּי אֱלִיעֶזֶר? מִשּׁוּם בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים בָּזֶה.</p>\n<p>אָמַר רַבִּי אֱלִיעֶזֶר, שְׁמוֹנָה עָשָׂר הָרֵי אֲפַרְסְמוֹן (טהור) עֶלְיוֹנִים, נִכְנָסִים נִשְׁמוֹת הַצַּדִּיקִים, וְאַרְבָּעִים וְתִשְׁעָה רֵיחוֹת עוֹלִים בְּכָל יוֹם עַד אוֹתוֹ מָקוֹם שֶׁנִּקְרָא עֵדֶן, שֶׁכְּנֶגֶד זֶה נִתְּנָה תוֹרָה בְּמ\"ט פָּנִים טָמֵא, וּבְמ\"ט פָּנִים טָהוֹר. וְאַרְבָּעִים וְתֵשַׁע אוֹתִיּוֹת בִּשְׁמוֹת הַשְּׁבָטִים, אַרְבָּעִים וְתִשְׁעָה יָמִים כְּנֶגֶד הַתּוֹרָה. מ\"ט יָמִים קְדוֹשִׁים עֶלְיוֹנִים עוֹמְדִים לִטֹּל רְשׁוּת בְּכָל יוֹם מֵאֲבָנִים זוֹהֲרוֹת שֶׁחֲקוּקוֹת בְּאוֹתוֹ הַחֹשֶׁן.</p>"],[9522011537,"<p>וְאוֹתוֹ שֶׁלָּבוּשׁ בַּחֹשֶׁן יוֹשֵׁב בְּכִסֵּא קָדוֹשׁ נִכְבָּד, שֶׁאַרְבָּעָה תוֹמְכִים עוֹמְדִים מִסְתַּכְּלִים בַּחֹשֶׁן. עַל מַאֲמָרוֹ נִכְנָסִים וְעַל מַאֲמָרוֹ יוֹצְאִים, מְרִימִים עֵינַיִם וּמִסְתַּכְּלִים לְמַעְלָה, רוֹאִים צִיץ שֶׁלּוֹהֵט בְּשֵׁשׁ מֵאוֹת וְעֶשְׂרִים עֲבָרִים, וְשֵׁם הַקָּדוֹשׁ הָעֶלְיוֹן חָקוּק עָלָיו. מִזְדַּעְזְעִים וּמִתְחַלְחֲלִים. קְשׁוּרִים בְּצִדָּיו שֶׁל הַיָּמִין הַקָּדוֹשׁ, שֶׁשְּׂמֹאל נוֹטֵל בְּיָדָיו תּוֹמְכֵי הַשָּׁמַיִם, מַכְנִיס אוֹתָם וּמְגַלֶּה אוֹתָם. זֶהוּ שֶׁכָּתוּב (ישעיה לד) וְנָגֹלּוּ כַסֵּפֶר הַשָּׁמָיִם.</p>"],[9522011538,"<p>אָמַר לוֹ רַבִּי עֲקִיבָא, מַה זֶּה שֶׁכָּתוּב (שיר ז) אֶל גִּנַּת אֱגוֹז יָרַדְתִּי? אָמַר לוֹ, בּא רְאֵה, אוֹתוֹ גַּן יוֹצֵא מֵעֵדֶן, וְזוֹהִי הַשְּׁכִינָה. אֱגוֹז - זוֹ מֶרְכָּבָה עֶלְיוֹנָה קְדוֹשָׁה שֶׁל אוֹתָם אַרְבָּעָה רָאשִׁים שֶׁמְּאִירִים שֶׁנִּפְרָדִים מִן הַגָּן, כְּמוֹ הָאֱגוֹז הַזֶּה שֶׁאוֹתָם אַרְבָּעָה רָאשִׁים קְדוֹשִׁים לִפְנִים. וּמַה שֶּׁאָמַר יָרַדְתִּי, כְּמוֹ שֶׁשָּׁנִינוּ, יָרַד פְּלוֹנִי לַמֶּרְכָּבָה.</p>\n<p>אָמַר לוֹ רַבִּי עֲקִיבָא, אִם כָּךְ, הָיָה לוֹ לוֹמַר לָאֱגוֹז יָרַדְתִּי, מַה זֶּה אֶל גִּנַת אֱגוֹז יָרַדְתִּי? אָמַר לוֹ, מִשּׁוּם שֶׁזֶּהוּ שִׁבְחוֹ שֶׁל הָאֱגוֹז. מָה אֱגוֹז נִסְתָּר וְטָמִיר מִכָּל צְדָדָיו - כָּךְ הַמֶּרְכָּבָה שֶׁיּוֹצֵאת מֵהַגַּן נִסְתֶּרֶת מִכָּל צְדָדֶיהָ. וּמָה אוֹתָם אַרְבָּעָה קְרָשִׁים שֶׁבָּאֱגוֹז מִתְחַבְּרִים בְּצַד זֶה וְנִפְרָדִים בְּצַד זֶה - כָּךְ בַּמֶּרְכָּבָה מִתְחַבְּרִים בְּאַחְדוּת בְּחֶדְוָה וּשְׁלֵמוּת, וְנִפְרָד כָּל אֶחָד לְעֶבְרוֹ עַל מַה שֶּׁהִתְמַנָּה. זֶהוּ שֶׁכָּתוּב (בראשית ב) הוּא הַסֹּבֵב אֵת כָּל אֶרֶץ הַחֲוִילָה, הוּא הַהֹלֵךְ קִדְמַת אַשּׁוּר, וְכֵן כֻּלָּם.</p>\n<p>אָמַר רַבִּי עֲקִיבָא, הַלִּכְלוּךְ הַזֶּה שֶׁבִּקְלִפַּת הָאֱגוֹז לְמָה הוּא רוֹמֵז? אָמַר לוֹ, אַף עַל גַּב שֶׁהַתּוֹרָה לֹא גִלְּתָה אוֹתוֹ - בָּזֶה מִתְגַּלֶּה.</p>\n<p>בֹּא רְאֵה, (שקדים) מֵהֶם מָרִים וּמֵהֶם מְתוּקִים, וְרֶמֶז יֵשׁ לָהֶם: יֵשׁ בַּעֲלֵי דִין קָשֶׁה, וְיֵשׁ בַּעֲלֵי רֵאשִׁית, אֲבָל כָּל רֶמֶז שֶׁגִּלָּה בַּתּוֹרָה רָאִינוּ שֶׁהוּא דִּין, וְכָךְ הוּא לְיִרְמְיָה הֶרְאוּ לוֹ בְּדִין, שֶׁכָּתוּב (ירמיה א) מַקֵּל שָׁקֵד אֲנִי רֹאֶה. מַה זֶּה שָׁקֵד? שְׁקֵדִים מַמָּשׁ. וְכֵן בְּמַטֵּה אַהֲרֹן, (במדבר ז) וַיִּגְמֹל שְׁקֵדִים. וּמִן הַתֵּבָה מַמָּשׁ נִשְׁמָע שֶׁהוּא דִּין קָשֶׁה, שֶׁכָּתוּב (דניאל ט) וַיִּשְׁקֹד ה' עַל הָרָעָה, וְכֵן שֹׁקֵד אֲנִי עַל דְּבָרִי, וְכֵן כֻּלָּם. אָמַר לוֹ רַבִּי עֲקִיבָא, מַשְׁמָע כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, לִלְמֹד מִמֶּנּוּ חָכְמָה רַבָּה, שֶׁכָּתוּב (משלי טז) כֹּל פָּעַל ה' לַמַּעֲנֵהוּ. רַבִּי אֶלְעָזָר אָמַר מִכָּאן, שֶׁכָּתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד. מַה זֶּה מְאֹד? לִלְמֹד מִמֶּנּוּ חָכְמָה עֶלְיוֹנָה.</p>"],[9522011539,"<p>אָמַר רַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב (קהלת ז) גַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים? כְּמוֹ שֶׁבָּרָקִיעַ - עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ, וְהַכֹּל רוֹמֵז לְמַה שֶּׁלְּמַעְלָה. שֶׁכְּשֶׁהָיָה רוֹאֶה רַבִּי אַבָּא עֵץ אֶחָד שֶׁפִּרְיוֹ נַעֲשָׂה עוֹף שֶׁפּוֹרֵחַ מִמֶּנּוּ, הָיָה בּוֹכֶה וְאוֹמֵר: אִם הָיוּ בְּנֵי אָדָם יוֹדְעִים לְמָה רוֹמְזִים, הָיוּ קוֹרְעִים מַלְבּוּשֵׁיהֶם עַד טַבּוּרָם לְמַה שֶּׁנִּשְׁכְּחָה מֵהֶם הַחָכְמָה. כָּל שֶׁכֵּן בִּשְׁאָר מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָ רֶץ.</p>\n<p>כְּמוֹ שֶׁאָמַר רַבִּי יוֹסֵי, אִילָנוֹת, אוֹתָם שֶׁנִּרְאֲתָה מֵהֶם חָכְמָה, כְּמוֹ חָרוּב, דֶּקֶל, פִּסְתּוּק, וְכַדּוֹמֶה לָהֶם, כֻּלָּם בְּהַרְכָּבָה (מרכבה) אַחַת הֻרְכְּבוּ. כָּל אוֹתָם שֶׁעוֹשִׂים פֵּרוֹת, פְּרָט לְתַפּוּחִים, סוֹד אֶחָד הֵם, פְּרָט לַשְּׁבִילִים שֶׁנִּפְרָדִים.</p>\n<p>כָּל אוֹתָם שֶׁלֹּא עוֹשִׂים פֵּרוֹת, וְהֵם גְּדוֹלִים, פְּרָט לְעַרְבֵי נַחַל שֶׁיֵּשׁ לָהֶם סוֹד לְבַדָּם כְּמוֹ שֶׁלְּמַעְלָה, מִינִיקָה אַחַת יוֹנְקִים, וְכָל אֶחָד מֵאוֹתָם הַקְּטַנִּים, פְּרָט לָאֵזוֹב, מֵאֵם אַחַת נוֹלְדוּ.</p>\n<p>כָּל עֵשֶׂב הָאָרֶץ שֶׁמְּמֻנִּים עֲלֵיהֶם, גְּדוֹלִים תַּקִּיפִים בַּשָּׁמַיִם. לְכָל אֶחָד וְאֶחָד סוֹד לְבַדּוֹ, כְּמוֹ שֶׁלְּמַעְלָה, וְלָכֵן כָּתוּב (ויקרא יט) שָׂדְךְ לֹא תִזְרַע כִּלְאָיִם. שֶׁכָּל אֶחָד וְאֶחָד נִכְנָס לְבַדּוֹ וְיוֹצֵא לְבַדּוֹ. זֶהוּ שֶׁכָּתוּב (איוב לח) הֲיָדַעְתָּ חֻקּוֹת שָׁמָיִם אִם תָּשִׂים מִשְׁטָרוֹ בָאָרֶץ. וְכָתוּב (ישעיה מ) לְכֻלָּם בְּשֵׁם יִקְרָא. וּמַה (ש) בְּכָל מַה שֶּׁבָּעוֹלָם סוֹד בִּלְבַדּוֹ, וְלֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַלּוֹת אוֹתָם וּלְעַרְבֵּב אוֹתָם, וּקְרָאָם בְּשֵׁמוֹת - בְּנֵי יַעֲקֹב, שֶׁהֵם שְׁבָטִים קְדוֹשִׁים, שֶׁהֵם קִיּוּם הָעוֹלָם, עַל אַחַת כַּמָּה וְכַמָּה. זֶהוּ שֶׁכָּתוּב וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל.</p>"],[9522011540,"<p>רַבִּי יוֹסֵי בְּרַבִּי יְהוּדָה אָמַר, אִלּוּ נֶאֱמַר אֵלֶּה שְׁמוֹת, מַשְׁמָע שֶׁכָּךְ הוּא. עַכְשָׁו שֶׁכָּתוּב וְאֵלֶּה שְׁמוֹת, מַשְׁמָע שֶׁעַל הָרִאשׁוֹנִים מוֹסִיף, מָה הָרִאשׁוֹנִים בְּנֵי יַעֲקֹב - אַף כָּאן בְּנֵי יַעֲקֹב.</p>\n<p>אָמַר רַבִּי יְהוּדָה, חַס וְשָׁלוֹם, בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא (בראשית מו) אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה, סָבַרְתָּ שֶׁשְּׁכִינָה תֵּרֵד עִמּוֹ בְּאוֹתָהּ שָׁעָה (אמר לו, והרי כתוב אנכי ארד עמך מצרימה. עמך) מַמָּשׁ? אֶלָּא בְּשָׁעָה שֶׁהָיְתָה יְרִידָה לְבָנָיו, יָרְדָה שְׁכִינָה. זֶהוּ שֶׁכָּתוּב אָנֹכִי אֵרֵד מִצְרַיְמָה, וְאָנֹכִי אֲעַלְךְ גַּם עָלֹה. כָּל זְמַן שֶׁתִּהְיֶה לְךְ עֲלִיָּה, כִּבְיָכוֹל יֵשׁ לִי גַּם עֲלִיָּה. וּבְשָׁעָה שֶׁתִּהְיֶה לְךְ יְרִידָה, כִּבְיָכוֹל אָנֹכִי אֵרֵד עִמְּךְ. וְעַד שֶׁמֵּת יוֹסֵף וְכָל אֶחָיו וְהָיְתָה לָהֶם יְרִידָה, קָמָה שְׁכִינָה וְיָרְדָה עִמָּם. כְּמוֹ שֶׁיָּרְדוּ אֵלֶּה, כָּךְ יָרְדוּ אֵלֶּה.</p>\n<p>אָמַר (רבי יוסי ברבי יהודה) רַבִּי יְהוּדָה, מַה כָּתוּב לְמַעְלָה מִמֶּנּוּ? וַיָּמָת יוֹסֵף בֶּן מֵאָה וְעֶשֶׂר שָׁנִים וְגוֹ'. בְּאוֹתָהּ שָׁעָה שֶׁמֵּת יוֹסֵף וְכָל הַשְּׁבָטִים וְהָיְתָה לָהֶם יְרִידָה, יָרְדוּ בְּנֵי יִשְׂרָאֵל לַגָּלוּת, וּשְׁכִינָה וּמַלְאָכִים עֶלְיוֹנִים יָרְדוּ עִמָּם. זֶהוּ שֶׁכָּתוּב וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל, שֶׁהֵם נוֹסְפוּ עַל הָרִאשׁוֹנִים לָרֶדֶת לַגָּלוּת.</p>\n<p>אָמַר לוֹ, אִם כָּךְ, יַעֲקֹב הָיָה מֵת אוֹ לֹא? אָמַר לוֹ, מֵת. אָמַר לוֹ, וּמַהוּ מַה שֶּׁכָּתוּב הַבָּאִים מִצְרָיְמָה אֵת יַעֲקֹב? אִם בַּחַיִּים, אֱמֹר אֵת יַעֲקֹב, וְאִם אַחַר שֶׁמֵּת, הוֹצֵא מִשָּׁם אֵת יַעֲקֹב. אֶלָּא בֹּא תִרְאֶה, לֹא אָמַר הַכָּתוּב הַיּוֹרְדִים מִצְרַיְמָה אֵת יַעֲקֹב, שֶׁעַד עַכְשָׁו לֹא הָיְתָה יְרִידָה לְיַעֲקֹב, אֶלָּא הַבָּאִים. לָמַדְנוּ שֶׁבָּאוּ עִם יַעֲקֹב, וְהָלְכוּ לָהֶם. עַד שֶׁיָּרְדוּ אֵלֶּה לַגָּלוּת, יָרְדוּ אֵלֶּה עִמָּם. זֶהוּ שֶׁכָּתוּב וְאֵלֶּה שְׁמוֹת.</p>\n<p>רַבִּי דּוֹסְתַּאי אָמַר, בְּכָל יוֹם וָיוֹם הָיוּ בָאִים וְהוֹלְכִים לָהֶם, זֶהוּ שֶׁכָּתוּב הַבָּאִים מִצְרָיְמָה, וְלֹא כָתוּב אֲשֶׁר בָּאוּ, וְהַיְנוּ שֶׁכָּתוּב הַבָּאִים מִצְרָיְמָה. בַּתְּחִלָּה אֵת יַעֲקֹב, וְאַחַר כָּךְ כְּשֶׁהָיְתָה לָהֶם יְרִידָה, אִישׁ וּבֵיתוֹ בָּאוּ. וּבֹא רְאֵה, כָּל בְּנֵי יַעֲקֹב הָיוּ מֵתִים בְּאוֹתוֹ זְמַן, וְיָרְדוּ אֵלֶּה וְאֵלֶּה.</p>\n<p>רַבִּי יוֹסֵי וְרַבִּי אֶלְעָזָר אָמְרוּ, בְּפָרָשָׁה זוֹ יֵשׁ דְּבָרִים עֶלְיוֹנִים, שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁיָּרְדוּ הַמֶּרְכָּבוֹת וְהַמַּחֲנוֹת הַקְּדוֹשִׁים, דְּיוֹקְנֵיהֶם שֶׁל הַשְּׁבָטִים שֶׁחֲקוּקִים לְמַעְלָה, כֻּלָּם נִכְנְסוּ לָדוּר עִמָּם. זֶהוּ שֶׁכָּתוּב אִישׁ וּבֵיתוֹ בָּאוּ, וְכָתוּב רְאוּבֵן שִׁמְעוֹן לֵוִי.</p>\n<p>דָּבָר אַחֵר וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל הַבָּאִים מִצְרָיְמָה אֶת יַעֲקֹב וְגוֹ' - חָזְרָה פָּרָשָׁה זוֹ לְמַה שֶּׁאָמַר רַבִּי יוֹסֵי בְּרַבִּי יְהוּדָה, וְהַכֹּל הָיָה.</p>\n<p>וּבֹא רְאֵה, רַבִּי אֶלְעָזָר בֶּן עֲרָךְ, כְּשֶׁהָיָה מַגִּיעַ לַפָּסוּק הַזֶּה, הָיָה בּוֹכֶה. שֶׁשָּׁנִינוּ, אָמַר רַבִּי אֶלְעָזָר בֶּן עֲרָךְ, בְּשָׁעָה שֶׁהָלְכוּ יִשְׂרָאֵל לַגָּלוּת, הִתְכַּנְּסוּ כָּל נִשְׁמוֹת הַשְּׁבָטִים לִמְעָרַת הַמַּכְפֵּלָה, צָוְחוּ וְאָמְרוּ: זָקֵן זָקֵן, כְּאֵב שֶׁל בָּנִים אֵין בֶּעָמָל (של הגלות) שֶׁל הָעוֹלָם הַזֶּה. בָּנֶיךְ כֻּלָּם מְשֻׁעְבָּדִים בְּפֶרֶךְ, וְעַם אַחֵר עוֹשִׂים בָּהֶם נִקְמוֹת הָעוֹלָם.</p>\n<p>בְּאוֹתָהּ שָׁעָה הִתְעוֹרְרָה רוּחַ שֶׁל אוֹתוֹ הַזָּקֵן, בִּקֵּשׁ רְשׁוּת וְיָרַד. קָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְכָל מַרְכְּבוֹתָיו וּמַחֲנוֹתָיו וּמַלְכֵיהֶם בְּרָאשֵׁיהֶם, וְיָרְדוּ כֻלָּם עִם יַעֲקֹב וְעִם שְׁבָטָיו. שְׁבָטִים יָרְדוּ חַיִּים עִם אֲבִיהֶם, וּשְׁבָטִים יָרְדוּ מֵתִים עִם אֲבִיהֶם. זֶהוּ שֶׁכָּתוּב וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל הַבָּאִים מִצְרָיְמָה וְגוֹ', וְכָתוּב רְאוּבֵן שִׁמְעוֹן לֵוִי וְגוֹ'. וּבֹא רְאֵה, מֵתִים הָיוּ, וְיָרְדוּ, וְכָתוּב וְיוֹסֵף הָיָה בְמִצְרָיִם. אָמַר רַבִּי אַבָּא, בָּזֶה נִקְרָא (תהלים קג) כְּרַחֵם אָב עַל בָּנִים.</p>"],[9522011541,"<p>רַבִּי יְהוּדָה בַּר שָׁלוֹם הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְרַבִּי אַבָּא הָיָה עִמּוֹ. נִכְנְסוּ לְמָקוֹם אֶחָד וְלָנוּ שָׁם. אָכְלוּ. כְּשֶׁרָצוּ לִשְׁכַּב, שָׂמוּ רֹאשָׁם בְּאוֹתוֹ תֵל שֶׁל הָאָרֶץ שֶׁהָיָה שָׁם קֶבֶר אֶחָד. עַד שֶׁלֹּא נִרְדְּמוּ, קָרָא קוֹל אֶחָד מֵהַקֶּבֶר וְאָמַר, הַזֶּרַע שֶׁלִּי הוֹלֵךְ לָאֲדָמָה. שְׁתֵּים עֶשְׂרֵה שָׁנָה הָיָה שֶׁלֹּא הִתְעוֹרַרְתִּי פְּרָט לְעַכְשָׁו, שֶׁפַּרְצוּף בְּנִי אֲנִי רוֹאֶה כָּאן.</p>\n<p>אָמַר רַבִּי יְהוּדָה, מִי אַתָּה? אָמַר לוֹ, אֲנִי יְהוּדִי, וַאֲנִי יוֹשֵׁב נָזוּף, שֶׁאֵינִי יָכוֹל לְהִכָּנֵס מִשּׁוּם אוֹתוֹ צַעַר שֶׁל שְׁנִי שֶׁגָּנַב אוֹתוֹ גוֹי כְּשֶׁהָיָה קָטָן וּמַלְקֶה אוֹתוֹ כָּל יוֹם, וְהַצַּעַר שֶׁלִּי דּוֹחֶה אוֹתִי מִלְּהִכָּנֵס לִמְקוֹמִי, וּבְמָקוֹם זֶה לֹא הִתְעוֹרַרְתִּי פְּרָט לְעַכְשָׁו.</p>\n<p>אָמַר לוֹ, וְאַתֶּם הַאִם יוֹדְעִים בְּצַעַר הַחַיִּים? אָמַר לוֹ, נִשְׁבָּע בְּשַׂר הַקֶּבֶר, אִם לֹא בַּקָּשׁוֹתֵינוּ עַל הַחַיִּים, לֹא הָיוּ עוֹמְדִים אֲפִלּוּ חֲצִי יוֹם בָּעוֹלָם, וְעַכְשָׁו הִתְעוֹרַרְתִּי כָּאן, שֶׁהָיוּ אוֹמְרִים לִי בְּכָל יוֹם שֶׁבִּמְהֵרָה יָבֹא לְכָאן בְּנִי, וְלֹא יָדַעתִּי אִם בַּחַיִּים אוֹ בַּמָּוֶת.</p>\n<p>אָמַר לוֹ רַבִּי יְהוּדָה, מַה מַּעֲשֵׂיכֶם בְּאוֹתוֹ הָעוֹלָם? רָעַשׁ הַקֶּבֶר וְאָמַר, קוּמוּ לְכוּ, שֶׁעַכְשָׁו מַכִּים אֶת בְּנִי. תָּמְהוּ וּבָרְחוּ מִשָּׁם כַּחֲצִי מִיל. יָשְׁבוּ עַד שֶׁהֵאִיר הַבֹּקֶר. קָמוּ לָלֶכֶת, וְרָאוּ אִישׁ אֶחָד שֶׁהָיָה רָץ וּבוֹרֵחַ, וְהָיָה שׁוֹתֵת דָּם עַל כְּתֵפָיו. אָחֲזוּ בוֹ, וְסִפֵּר לָהֶם אֶת הַמַּעֲשֶׂה. אָמְרוּ לוֹ, מַה שִּׁמְךְ? אָמַר לָהֶם, לַחְמָא בַּר לֵיוָאֵי. אָמְרוּ, וּמָה (בן) לֵיוָאֵי בַּר לַחְמָא הָיָה אוֹתוֹ הַמֵּת. וּפָחֲדוּ לְדַבֵּר אִתּוֹ יוֹתֵר, וְלֹא חָזְרוּ. אָמַר רַבִּי אַבָּא, זֶהוּ שֶׁאָמְרוּ שֶׁתְּפִלּוֹת הַמֵּתִים מְגִנּוֹת עַל הַחַיִּים, מִנַּיִן לָנוּ? שֶׁכָּתוּב וַיַּעֲלוּ בַנֶּגֶב וַיָּבֹא עַד חֶבְרוֹן.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בֹּא רְאֵה, שְׁנֵי נְדָרִים נָדַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַעֲקֹב, אֶחָד שֶׁיֵּרֵד עִמּוֹ לָדוּר עִמּוֹ בַּגָּלוּת, וְאֶחָד שֶׁיַּעֲלֵהוּ מִקִּבְרוֹ לִרְאוֹת חֶדְוַת הַסִּיּוּעַ הַקָּדוֹשׁ שֶׁדָּר עִם בָּנָיו. זֶהוּ שֶׁכָּתוּב (בראשית מו) אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה. אָנֹכִי אֵרֵד עִמְּךְ בַּגָּלוּת, וְאָנֹכִי אֲעַלְךְ גַּם עָלֹה, כַּנֶּאֱמַר (יחזקאל לז) וְהַעֲלֵיתִי אֶתְכֶם מִקִּבְרוֹתֵיכֶם עַמִּי, וְכָתוּב שֶׁשָּׁם עָלוּ שְׁבָטִים וְגוֹ'.</p>\n<p>דָּבָר אַחֵר וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרָיִם וְגוֹ' - אָמַר רַבִּי שִׁמְעוֹן, בְּאוֹתוֹ יוֹם נִתְּנָה רְשׁוּת לְשָׂרוֹ שֶׁל מִצְרַיִם עַל כָּל שְׁאָר הָעַמִּים. שֶׁשָּׁנִינוּ, עַד שֶׁלֹּא מֵת יוֹסֵף, לֹא נִתַּן שִׁלְטוֹן לַשֻּׁלְטָן שֶׁל מִצְרַיִם עַל יִשְׂרָאֵל. כֵּיוָן שֶׁמֵּת יוֹסֵף, אָז וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרַיִם. וַיָּקָם - כְּמִי שֶׁהָיָה נָמוּךְ וְקָם.</p>"],[9522011542,"<p>(ויקם מלך חדש וכו') רַבִּי יִצְחָק פָּתַח, (שיר א) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. עַד שֶׁהַמֶּלֶךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (ישעיה מו) כֹּה אָמַר ה' מֶלֶךְ יִשְׂרָאֵל, וְכָתוּב (דברים לג) וַיְהִי בִישֻׁרוּן מֶלֶךְ. בִּמְסִבּוֹ - בֵּין כַּנְפֵי הַכְּרוּבִים. נִרְדִּי נָתַן רֵיחוֹ - שֶׁגָּרְמוּ לְהִסְתַּלֵּק מִבֵּינֵיהֶם.</p>\n<p>דָּבָר אַחֵר עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ - בְּעוֹד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה נוֹתֵן תּוֹרָה לְיִשְׂרָאֵל, שֶׁכָּתוּב (שמות לד) וַיְהִי שָׁם עִם ה' אַרְבָּעִים יוֹם וְאַרְבָּעִים לַיְלָה לֶחֶם לֹא אָכַל וְגוֹ'. בְּעוֹד שֶׁהָיָה כּוֹתֵב תּוֹרָה לְיִשְׂרָאֵל, הוֹצִיאוּ רֵיחָם הַטּוֹב, וְאָמְרוּ אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל.</p>\n<p>דָּבָר אַחֵר עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ - בְּעוֹד שֶׁהָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֵד עַל הַר סִינַי לָתֵת תּוֹרָה לְיִשְׂרָאֵל. נִרְדִּי נָתַן רֵיחוֹ - שֶׁכָּתוּב נַעֲשֶׂה וְנִשְׁמָע.</p>"],[9522011543,"<p>רַבִּי תַּנְחוּם אָמַר, לְכָל אֻמָּה וְאֻמָּה יֵשׁ שַׂר לְמַעְלָה, וּכְשֶׁנּוֹתֵן הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁלִיטָה לָזֶה - מוֹרִיד אֶת זֶה, וּכְשֶׁנּוֹתֵן שְׁלִיטָה לְאוֹתוֹ שַׂר, אֵין לוֹ שְׁלִיטָה אֶלָּא מִשּׁוּם יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב הָיוּ צָרֶיהָ לְרֹאשׁ.</p>\n<p>רַבִּי יִצְחָק אָמַר, יִשְׂרָאֵל הֵם כְּנֶגֶד כָּל שְׁאָר אֻמּוֹת הָעוֹלָם. מַה שְּׁאָר הָעַמִּים הֵם שִׁבְעִים - אַף יִשְׂרָאֵל הֵם שִׁבְעִים. זֶהוּ שֶׁכָּתוּב כָּל הַנֶּפֶשׁ לְבֵית יַעֲקֹב הַבָּאָה מִצְרַיְמָה שִׁבְעִים. וּמִי שֶׁשּׁוֹלֵט עַל יִשְׂרָאֵל, כְּאִלּוּ שׁוֹלֵט עַל כָּל הָעוֹלָם.</p>\n<p>רַבִּי אַבָּא אָמַר מִכָּאן, וּבְנֵי יִשְׂרָאֵל פָּרוּ וַיִּשְׁרְצוּ וְגוֹ' - הֲרֵי שִׁבְעָה. וְכָל דַּרְגָּה (עולה) לַעֲשָׂרָה - הֲרֵי שִׁבְעִים. מַה כָּתוּב אַחֲרָיו? וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרָיִם.</p>\n<p>אָמַר רַב הוּנָא, לָמָּה הִשְׁתַּעְבְּדוּ יִשְׂרָאֵל בְּכָל הָאֻמּוֹת? בִּשְׁבִיל שֶׁיִּשָּׁאֵר בָּהֶם הָעוֹלָם, שֶׁהֵם כְּנֶגֶד כָּל הָעוֹלָם, וְכָתוּב (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. וּמָה הוּא אֶחָד - אַף יִשְׂרָאֵל אֶחָד, שֶׁכָּתוּב (שמואל ב ז) גּוֹי אֶחָד בָּאָרֶץ. מַה שְּׁמוֹ אֶחָד וְנִפְרָד בְּשִׁבְעִים - אַף יִשְׂרָאֵל אֶחָד וְנִפְרָד בְּשִׁבְעִים.</p>"],[9522011544,"<p>רַבִּי יְהוּדָה פָּתַח, (משלי ל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ וְגוֹ', תַּחַת עֶבֶד כִּי יִמְלוֹךְ. שֶׁשָּׁנִינוּ, אֵין לְךְ אֻמָּה שְׁפָלָה וְנִקְלֵית וּבְזוּיָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ הַמִּצְרִים, וְנָתַן לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁלִיטָה מִשּׁוּם יִשְּׁרָאֵל. וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ - זוֹ הָגָר שֶׁהוֹלִידָה אֶת יִשְׁמָעֵאל, שֶׁעָשָׂה כַּמָּה רָעוֹת לְיִשְׂרָאֵל, וְשָׁלַט בָּהֶם, וְעִנָּה אוֹתָם בְּכָל מִינֵי עִנּוּיִים, וְגָזַר עֲלֵיהֶם כַּמָּה שְׁמָדוֹת, וְעַד הַיּוֹם הֵם שׁוֹלְטִים עֲלֵיהֶם, וְאֵינָם מַנִּיחִים לָהֶם לַעֲמֹד בְּדָתָם. וְאֵין לְךְ גָּלוּת קָשָׁה לְיִשְׂרָאֵל כְּמוֹ גָּלוּת יִשְׁמָעֵאל.</p>\n<p>רַבִּי יְהוֹשֻׁעַ הָיָה עוֹלֶה לִירוּשָׁלַיִם, וְהָיָה הוֹלֵךְ בַּדֶּרֶךְ. רָאָה עַרְבִי אֶחָד שֶׁהָיָה הוֹלֵךְ בַּדֶּרֶךְ וּבְנוֹ עִמּוֹ. פָּגְשׁוּ בִּיהוּדִי אֶחָד, אָמַר לִבְנוֹ, הַיְּהוּדִי הַזֶּה גֹּעַל, שֶׁמָּאַס בּוֹ אֲדוֹנוֹ. נַוֵּל אוֹתוֹ וְתִירַק לוֹ בִּזְקָנוֹ שֶׁבַע פְּעָמִים, שֶׁהוּא מִזֶּרַע שֶׁל רָמִים, שֶׁאֲנִי יָדַעְתִּי שֶׁמְּשֻׁעְבָּדִים בָּהֶם שִׁבְעִים עֲמָמִים. הָלַךְ בְּנוֹ וְתָפַס בִּזְקָנוֹ. אָמַר רַבִּי יְהוֹשֻׁעַ, רָמִים רָמִים, גּוֹזְרַנִי עַל הָעֶלְיוֹנִים שֶׁיֵּרְדוּ לְמַטָּה. עַד שֶׁלֹּא סִיֵּם, נִבְלְעוּ בִמְקוֹמָם.</p>"],[9522011545,"<p>רַבִּי יִצְחָק פָּתַח, (שיר ב) עַד שֶׁיָּפוּחַ הַיּוֹם וְנָסוּ הַצְּלָלִים וְגוֹ'. עַד שֶׁיָּפוּחַ הַיּוֹם - פָּסוּק זֶה נֶאֱמַר עַל גָּלוּת יִשְׂרָאֵל, שֶׁהֵם יִשְׁתַּעְבְּדוּ בַגָּלוּת עַד שֶׁיִּסְתַּיֵּם אוֹתוֹ יוֹם שֶׁל שִׁלְטוֹן הָאֻמּוֹת. שֶׁשָּׁנִינוּ, אָמַר רַבִּי יִצְחָק, אֶלֶף שָׁנִים הוּא שִׁלְטוֹן הָאֻמּוֹת כְּאֶחָד עַל יִשְׂרָאֵל, וְאֵין לְךְ אֻמָּה שֶׁלֹּא תִשְׁתַּעְבֵּד בָּהֶם, וְיוֹם אֶחָד הוּא כְּנֶגְדּוֹ, שֶׁכָּתוּב (זכריה יד) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה' וְגוֹ'.</p>\n<p>דָּבָר אַחֵר עַד שֶׁיָּפוּחַ הַיּוֹם - קֹדֶם שֶׁיָּפוּחַ אוֹתוֹ יוֹם שֶׁל הָאֻמּוֹת. וְנָסוּ הַצְּלָלִים - אֵלּוּ שִׁלְטוֹנִים שֶׁשָּׁלְטוּ עֲלֵיהֶם. אֵלֵךְ לִי אֶל הַר הַמּוֹר - אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵלֵךְ לִי לְנַעֵר אֶת הָאֻמּוֹת מִירוּשָׁלַיִם, שֶׁהוּא הַר הַמּוֹר, כַּכָּתוּב בְּהַר הַמּוֹרִיָּה אֲשֶׁר בִּירוּשָׁלם. וְאֶל גִּבְעַת הַלְּבוֹנָה - זֶה בֵּית הַמִּקְדָּשׁ שֶׁבְּצִיּוֹן, שֶׁכָּתוּב בּוֹ (משלי מח) יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ הַר צִיּוֹן וְגוֹ', (אמר רבי יהודה) כְּמוֹ שֶׁנֶּאֱמַר (איוב לח) לֶאֱחֹז בְּכַנְפוֹת הָאָרֶץ וְיִנָּעֲרוּ רְשָׁעִים מִמֶּנָּה. כְּמוֹ זֶה שֶׁאוֹחֵז בְּטַלִּית לְנַעֵר מִמֶּנָּה טִנֹּפֶת.</p>\n<p>אָמַר רַבִּי יוֹסֵי, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְגַּלּוֹת בִּירוּשָׁלַיִם שֶׁלְּמַטָּה וּלְטַהֵר אוֹתָהּ מִטִּנּוּפֵי הָעַמִּים, עַד שֶׁלֹּא יִשְׁתַּלֵּם אוֹתוֹ הַיּוֹם שֶׁל הָאֻמּוֹת. שֶׁאָמַר רַבִּי חִיָּיא, אֵין שִׁלְטוֹן לָאֻמּוֹת עַל יִשְׂרָאֵל אֶלָּא יוֹם אֶחָד בִּלְבַד, שֶׁהוּא יוֹמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא אֶלֶף שָׁנִים. זֶהוּ שֶׁכָּתוּב נְתָנַנִי שּמֵמָה כָּל הַיּוֹם דָּוָה. יוֹם אֶחָד בִּלְבַד, וְלֹא יוֹתֵר.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אִם יִשְׁתַּעְבְּדוּ יוֹתֵר, לֹא עַל פִּי גְזֵרַת הַמֶּלֶךְ הוּא, אֶלָּא עַל שֶׁלֹּא רוֹצִים לַחֲזֹר אֵלָיו, וְכָתוּב (דברים ל) וְהָיָה כִּי יָבאוּ עָלֶיךְ כָּל הַדְּבָרִים הָאֵלֶּה וְגוֹ', וְכָתוּב אִם יִהְיֶה נִדַּחֲךְ בִּקְצֵה הַשָּׁמָיִם מִשָּׁם יְקַבֶּצְךְ וְגוֹ'.</p>"],[9522011546,"<p>וַיֹּאמֶר אֶל עַמּוֹ הִנֵּה עַם בְּנֵי יִשְׂרָאֵל. אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה, שֶׁהֲרֵי עַל כָּל פָּנִים הַמַּלְאָךְ הַשַּׁלִּיט הַמְמֻנֶּה עַל הַמִּצְרִים הָיָה, וְכָךְ הוּא, שֶׁבְּרֹב הַפָּרָשָׁה לֹא נֶאֱמַר אֶלָּא מֶלֶךְ מִצְרַיִם סְתָם, וְהַיְנוּ הַמְמֻנֶּה הַגָּדוֹל עַל מִצְרַיִם. פַּרְעֹה מֶלֶךְ מִצְרַיִם, פַּרְעֹה מַמָּשׁ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, לְפִיכָךְ כָּתוּב וַיּאמֶר, כְּלוֹמַר הִכְנִיס בְּלִבָּם דָּבָר זֶה, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב טז) כִּי ה' אָמַר לוֹ קַלֵּל אֶת דָּוִד. מַחֲשֶׁבֶת הַלֵּב בִּלְבַד. וְכֵן (אסתר ו) וַיּאמֶר הָמָן בְּלִבּוֹ, וְכֵן (בראשית יז) וַיֹּאמֶר בְּלִבּוֹ הַלְּבֶן מֵאָה שָׁנָה. אַף כָּאן גַּם, הִכְנִיס מַחֲשָׁבָה בְּלִבָּם שֶׁאָמְרוּ רַב וְעָצוּם מִמֶּנּוּ. מַה זֶּה מִמֶּנּוּ? רָצָה לוֹמַר מְמֻנֶּה שֶׁלָּהֶם. הֵם אָמְרוּ בְּלִבָּם שֶׁחַיִל וְתֹקֶף שֶׁלָּהֶם גָּדוֹל וְתַקִּיף מִמֶּנּוּ, מֵהַשִּׁלְטוֹן שֶׁלָּהֶם.</p>\n<p>רַבִּי יִצְחָק אָמַר, כָּל אֻמּוֹת הָעוֹלָם (חוץ מישראל) מוֹשְׁכִים כֹּחָם מִשָּׂרֵיהֶם, וְיִשְׂרָאֵל מוֹשְׁכִים כֹּחָם מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם נִקְרָאִים עַם ה', וְלֹא עַם שֶׁל הַשֻּׁלְטָנִים. רַבִּי יְהוּדָה אָמַר, כָּאן נִקְרְאוּ עַמּוֹ, שֶׁכָּתוּב וַיֹּאמֶר אֶל עַמּוֹ, וְשָׁם כָּתוּב (שמות ג) רָאֹה רָאִיתִי אֶת עֳנִי עַמִּי, עַמִּי מַמָּשׁ. יִשְׂרָאֵל נִקְרְאוּ עַם ה', וּשְׁאָר הָאֻמּוֹת נִקְרְאוּ עַמּוֹ שֶׁל הַשַּׁלִּיט שֶׁלָּהֶם, שֶׁכָּתוּב (מיכה ד) כִּי כָּל הָעַמִּים יֵלְכוּ אִישׁ בְּשֵׁם אֱלֹהָיו וַאֲנַחְנוּ נֵלֵךְ בְּשֵׁם ה' אֱלֹהֵינוּ לְעוֹלָם וָעֶד.</p>\n<p>אָמַר רַבִּי אַבָּא, פָּסוּק זֶה הָיָה לוֹ לוֹמַר, (הגה עם ישראל, או) בְּנֵי יִשְׂרָאֵל רַב וְעָצוּם מִמֶּנּוּ. (אלא) מַהוּ עַם בְּנֵי? אֶלָּא עַם בְּנֵי יִשְׂרָאֵל מַמָּשׁ, מֵאוֹתוֹ יִשְׂרָאֵל שֶׁלְּמַעְלָה, שֶׁחָשְׁבוּ שֶׁעַם בְּנֵי יִשְׂרָאֵל הָיוּ, וְלֹא עַם ה', וְכָתוּב וַיָּקֻצוּ מִפְּנֵי בְּנֵי יִשְׂרָאֵל, וְלֹא כָתוּב מִפְּנֵי עַם בְּנֵי יִשְׂרָאֵל, אֶלָּא מִפְּנֵי בְּנֵי יִשְׂרָאֵל מַמָּשׁ.</p>\n<p>רַבִּי יוֹחָנָן הָיָה עוֹמֵד לִפְנֵי רַבִּי יִצְחָק. אָמַר, מָה רָאָה בָּלָק לוֹמַר (במדבר כב) הִנֵּה עַם יָצָא מִמִּצְרַיִם, וְלֹא אָמַר הִנֵּה עַם בְּנֵי יִשְׂרָאֵל? (אלא) אָמַר לוֹ רַבִּי יִצְחָק, בָּלָק מְכַשֵּׁף גָּדוֹל הָיָה, וְכֵן דֶּרֶךְ הַמְּכַשְּׁפִים לָקַחַת דָּבָר שֶׁאֵין בּוֹ חֲשָׁד, וְכֵן אֵין מַזְכִּירִים לְעוֹלָם שֵׁם אָבִיו שֶׁל אָדָם, אֶלָּא שֵׁם אִמּוֹ, דָּבָר שֶׁאֵין בּוֹ חֲשָׁד.</p>\n<p>שֶׁכֵּן דֶּרֶךְ הַשֵּׁדִים, שֶׁמְּעַיְּנִים בְּאוֹתוֹ דָבָר שֶׁאוֹמְרִים לָהֶם, אִם הוּא כּוֹזֵב - מוֹדִיעִים לוֹ דְּבָרִים כּוֹזְבִים, וְאִם הוּא אֱמֶת - כָּל מַה שֶּׁאוֹמְרִים לִזְמַן קָצָר אֱמֶת הוּא, כָּל שֶׁכֵּן לַעֲשׂוֹת מַעֲשֶׂה. רַבִּי אָחָא אָמַר, בָּלָק לָקַח דֶּרֶךְ שֶׁל קָלוֹן, הִנֵּה עַם יָצָא מִמִּצְרַיִם, כְּלוֹמַר שֶׁאֵין אָנוּ יוֹדְעִים מִמִּי הֵם.</p>\n<p>אָמַר רַבִּי יוֹחָנָן, מִפְּנֵי מָה הָעָם שֶׁל הַגְּדוֹלִים שְׁמוּרִים, וְעַמּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינָם שְׁמוּרִים? אָמַר רַבִּי יִצְחָק, אֵין דּוֹמֶה עָנִי לְעָשִׁיר. הֶעָנִי צָרִיךְ לִשְׁמֹר אֶת שֶׁלּוֹ, הֶעָשִׁיר לֹא שׁוֹמֵר אֶת שֶׁלּוֹ. וְכָל שֶׁכֵּן שֶׁיִּשְׂרָאֵל הֵם מִמֶּלֶךְ שֶׁאוֹהֵב אֱמֶת וָדִין, וְדִין רִאשׁוֹן עוֹשֶׂה בְּאַנְשֵׁי בֵיתוֹ, שֶׁרוֹצֶה שֶׁהֵם יִהְיוּ שְׁמוּרִים מֵחֵטְא יוֹתֵר מִכֻּלָּם. זֶהוּ שֶׁכָּתוּב (עמוס ג) רַק אֶתְכֶם יָדַעְתִּי מִכֹּל מִשְׁפְּחוֹת הָאֲדָמָה וְגוֹ'.</p>\n<p>רַבִּי יוֹסֵי יָצָא לַדֶּרֶךְ, וְהָיָה רַבִּי אָחָא בַּר יַעֲקֹב הוֹלֵךְ עִמּוֹ. עַד שֶׁהָיוּ הוֹלְכִים, שָׁתַק רַבִּי יוֹסֵי וְהִרְהֵר בְּדִבְרֵי הָעוֹלָם, וְרַבִּי אָחָא הִרְהֵר בְּדִבְרֵי תוֹרָה. (עד שהיו הולכים) רָאָה רַבִּי יוֹסֵי נָחָשׁ אֶחָד שֶׁהָיָה רָץ אַחֲרָיו. אָמַר רַבִּי יוֹסֵי לְרַבִּי אָחָא, רָאִיתָ אֶת הַנָּחָשׁ הַזֶּה שֶׁרָץ אַחֲרַי? אָמַר לוֹ רַבִּי אָחָא, אֲנִי לֹא רָאִיתִי אוֹתוֹ. רָץ רַבִּי יוֹסֵי, וְהַנָּחָשׁ אַחֲרָיו. נָפַל רַבִּי יוֹסֵי וְדָם שָׁתַת וְיָרַד מֵחָטְמוֹ. שָׁמַע שֶׁהָיוּ אוֹמְרִים, רַק אֶתְכֶם יָדַעְתִּי מִכֹּל מִשְׁפְּחוֹת הָאֲדָמָה וְגוֹ'. אָמַר רַבִּי יוֹסֵי, וּמָה עַל שָׁעָה אַחַת כָּךְ - מִי שֶׁמִּתְיָאֵשׁ מִמֶּנָּה עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>פָּתַח וְאָמַר, (דברים ב) כִּי ה' אֱלֹהֶיךְ בֵּרַכְךְ בְּכָל מַעֲשֵׂה יָדֶךְ יָדַע לֶכְתְּךְ וְגוֹ' הַמּוֹלִיכְךְ וְגוֹ', נָחָשׁ שָׂרָף וְעַקְרָב וְגוֹ'. נָחָשׁ שָׂרָף לָמָּה כָּאן? אֶלָּא לָקַחַת עָנְשָׁם מִיִּשְׂרָאֵל כָּל זְמַן שֶׁפּוֹרְשִׁים מֵעֵץ הַחַיִּים, שֶׁכָּתוּב כִּי הוּא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ.</p>\n<p>בֹּא רְאֵה, אָמַר רַבִּי חִיָּיא, כָּתוּב (משלי יג) חוֹשֵׂךְ שִׁבְטוֹ שׂוֹנֵא בְנוֹ וְגוֹ', וְכָתוּב (מלאכי א) אָהַבְתִּי אֶתְכֶם אָמַר ה', וְכָתוּב וְאֶת עֵשָׂו שָׂנֵאתִי. מַה זֶּה שָׂנֵאתִי? שֶׁכָּתוּב חוֹשֵׂךְ שִׁבְטוֹ שׂוֹנֵא בְנוֹ, כְּלוֹמַר שָׂנֵאתִי אוֹתוֹ, וְעַל כֵּן חָשַׂכְתִּי שֵׁבֶט מֵהֶם. כָּל שֶׁכֵּן וְכָל שֶׁכֵּן תַּלְמִידֵי חֲכָמִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא רוֹצֶה שֶׁיִּפְרְשׁוּ מֵעֵץ הַחַיִּים אֲפִלּוּ רֶגַע אֶחָד.</p>\n<p>וַיֹּאמֶר אֶל עַמּוֹ, נָתַן לָהֶם עֵצָה לַעֲשׂוֹת עִמָּהֶם רַע. אָמַר רַבִּי תַּנְחוּם, יוֹדְעִים הָיוּ הַמִּצְרִים בָּאִצְטַגְנִינוּת שֶׁלָּהֶם שֶׁסּוֹפָם לִלְקוֹת בִּגְלַל יִשְׂרָאֵל, וְלָכֵן הִקְדִּים הַשַּׁלִּיט שֶׁלָּהֶם לַעֲשׂוֹת עִמָּם רַע.</p>\n<p>רַבִּי יִצְחָק פָּגַשׁ בְּאוֹתוֹ הַר, וְרָאָה אִישׁ אֶחָד יָשֵׁן תַּחַת הָאִילָן. יָשַׁב שָׁם. עַד שֶׁיָּשַׁב, רָאָה שֶׁהָאָרֶץ מִתְחַלְחֶלֶת, וְנִשְׁבַּר אוֹתוֹ אִילָן וְנָפַל, וְרָאָה בְּקִיעִים וְגֻמּוֹת בָּאָרֶץ, וְהָאָרֶץ עוֹלָה וְיוֹרֶדֶת.</p>\n<p>הִתְעוֹרֵר אוֹתוֹ הָאִישׁ, וְצָוַח כְּנֶגֶד רַבִּי יִצְחָק וְאָמַר לוֹ: יְהוּדִי יְהוּדִי, תִּבְכֶּה וְתִנְהַם, שֶׁעַכְשָׁו מַעֲמִידִים בָּרָקִיעַ גָּדוֹל מְמֻנֶּה אֶחָד שַׁלִּיט עֶלְיוֹן, וְהוּא עָתִיד לַעֲשׂוֹת עִמָּכֶם הַרְבֵּה רַע, וּרְעִידַת הָאֲדָמָה הַזֹּאת הָיְתָה בִּגְלַלְכֶם. שֶׁכָּל פַּעַם שֶׁרוֹעֶדֶת הָאָרֶץ, כְּשֶׁקָּם מְמֻנֶּה שֶׁיַּעֲשֶׂה עִמָּכֶם רַע.</p>"],[9522011547,"<p>תָּמַהּ רַבִּי יִצְחָק וְאָמַר, וַדַּאי כָּתוּב (משלי ל) תַּחַת שָׁלוֹשׁ רָגְזֶה אֶרֶץ, וְכָתוּב תַּחַת עֶבֶד כִּי יִמְלוֹךְ. מְמֻנֶּה שֶׁהָיָה (ממגה) תַּחַת שִׁלְטוֹן אַחֵר וּמָלַךְ, וְנָתְנוּ לוֹ שִׁלְטוֹן, וְכָל שֶׁכֵּן כְּשֶׁשּׁוֹלֵט בְּיִשְׂרָאֵל.</p>\n<p>אָמַר רַבִּי חָמָא בַּר גּוּרְיָא, כְּשֶׁהִנִּיחַ אֶת יִשְׂרָאֵל תַּחַת שִׁלְטוֹן הָאֻמּוֹת, יָשַׁב וְגָעָה וּבָכָה. זֶהוּ שֶׁכָּתוּב (ירמיה יג) בְּמִסְתָּרִים תִּבְכֶּה נַפְשִׁי. אָמַר רַבִּי יוֹסֵי, בְּמִסְתָּרִים דַּוְקָא.</p>\n<p>רַבִּי יְהוּדָה נִכְנַס אֶל רַבִּי אֶלְעָזָר וּמְצָאוֹ שֶׁהָיָה יוֹשֵׁב וְיָדוֹ בְּפִיו, וְהָיָה עָצוּב. אָמַר לוֹ, בַּמָּה עוֹסֵק מֹר? אָמַר לוֹ, שֶׁכָּתוּב בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים. אִם הָאָדוֹן עָצוּב, וְכָל שֶׁכֵּן שֶׁגּוֹעֶה וּבוֹכֶה - מַה יַּעֲשׂוּ שַׁמָּשָׁיו? זֶהוּ שֶׁכָּתוּב (ישעיה לג) הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָה. מַה זֶּה חֻצָה? שֶׁאֲדוֹנָם בִּפְנִים, וְהֵם בַּחוּץ. אֲדוֹנָם בַּבָּתִּים הַפְּנִימִיִּים, וְהֵם בַּבָּתִּים הַחִיצוֹנִיִּים. מִי הֵם בָּתִּים הַפְּנִימִיִּים? אָמַר רַבִּי יִצְחָק, אוֹתָם מֵעֲשָׂרָה כִּתְרֵי הַמֶּלֶךְ.</p>\n<p>מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן, וְכִי יֵשׁ מַלְאָכִים שֶׁאֵינָם שֶׁל שָׁלוֹם? אָמַר לוֹ, כֵּן. בֹּא רְאֵה, יֵשׁ בַּעֲלֵי דִין קָשֶׁה, וְיֵשׁ בַּעֲלֵי דִין לֹא קָשֶׁה, וְיֵשׁ בַּעֲלֵי דִין (רפה) וְרַחֲמִים, וְיֵשׁ בַּעֲלֵי רַחֲמִים שֶׁאֵין בָּהֶם דִּין כְּלָל, וְאֵלֶּה נִקְרְאוּ מַלְאֲכֵי שָׁלוֹם, וְעַל אוֹתָם שֶׁלְּמַטָּה כָּתוּב (שם נ) אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם, וְכָתוּב (שם לד) וְנָמַקּוּ כָּל צְבָא הַשָּׁמַיִם.</p>\n<p>אִם כָּךְ, כָּל אוֹתָם שַׁלִּיטִים הַמְמֻנִּים עַל שְׁאָר הָעַמִּים, כְּשֶׁרוֹאִים אֶת אֲדוֹנָם עָצוּב, לָמָּה עוֹבְדִים בְּפֶרֶךְ עִם בָּנָיו? אָמַר רַבִּי אֶלְעָזָר, אֵינָם עוֹשִׂים אֶלָּא מַה שֶּׁהִצְטַוּוּ, וּרְצוֹן אֲדוֹנָם הֵם עוֹשִׂים.</p>"],[9522011548,"<p>רַבִּי דוֹסְתַּאי אָמַר, בִּזְמַן שֶׁנִּמְסָרִים בְּנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְשַׁלִּיטֵי הָעַמִּים, מִתְכַּנְּסִים שְׁנֵים עָשָׂר בָּתֵּי דִין וְנִשְׁקָעִים לְתוֹךְ תְּהוֹם רַבָּה. גּוֹעֶה הָאָדוֹן, גּוֹעִים וְרָצִים (בעלי מגגים), וְיוֹרְדוֹת שְׁתֵּי דְמָעוֹת לַשֶּׁקַע שֶׁל הַיָּם הַגָּדוֹל, זֶהוּ שֶׁכָּתוּב (תהלים לו) מִשְׁפָּטֶיךְ תְּהוֹם רַבָּה. וּמִתְגַּלְגְּלִים עֶלְיוֹנִים לְמַטָּה, מִתְבַּקְּעִים הַתַּחְתּוֹנִים, וְיוֹרְדִים מָאתַיִם וְאַרְבָּעִים דְּרָגוֹת. זֶהוּ שֶׁכָּתוּב (עמוס ג) אַרְיֵה שָׁאָג מִי לֹא יִירָא.</p>\n<p>שָׁנִינוּ, בְּשָׁעָה שֶׁמָּסַר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל לְשַׂר מִצְרַיִם, גָּזַר עֲלֵיהֶם שֶׁבַע גְּזֵרוֹת שֶׁיַּעַבְדוּ בָהֶם הַמִּצְרִים, זֶהוּ שֶׁכָּתוּב וַיְמָרֲרוּ אֶת חַיֵּיהֶם בַּעֲבדָה קָשָׁה בְּחֹמֶר וּבִלְבֵנִים וְגוֹ'. וּכְנֶגְדָּם שֶׁבַע לְטוֹב - וּבְנֵי יִשְׂרָאֵל פָּרוּ וַיִּשְׁרְצוּ וַיִּרְבּוּ וַיַּעַצְמוּ בִּמְאֹד מְאֹד וַתִּמָּלֵא הָאָרֶץ אֹתָם.</p>"],[9522011549,"<p>הָבָה נִּתְחַכְּמָה לוֹ. רַבִּי יוֹסֵי אָמַר, אֵין הָבָה אֶלָּא לְשׁוֹן הַזְמָנָה לַעֲשׂוֹת דִּין, כְּמוֹ שֶׁנֶּאֱמַר (בראשית יא) הָבָה נֵרְדָה. (שמואל א יד) הָבָה תָמִים. אָמַר רַבִּי יוֹחָנָן, הָבָה - כֻּלָּם לְשׁוֹן הַסְכָּמָה וְהַזְמָנָה, כְּמוֹ הָבָה נִבְנֶה לָּנוּ עִיר. (שופטים כ) הָבוּ לָכֶם עֵצָה. (תהלים כט) הָבוּ לַה' בְּנֵי אֵלִים.</p>\n<p>רַבִּי יִצְחָק אָמַר, הָבָה נִּתְחַכְּמָה לוֹ נִהְיָה בְּהַסְכָּמַת הַדִּין אֵלָיו. פֶּן יִרְבֶּה, וְרוּחַ הַקֹּדֶשׁ אוֹמֶרֶת כֵּן יִרְבֶּה וְכֵן יִפְרֹץ. וּמַלְאֲכֵי הַשָּׁרֵת הָיוּ לָהֶם לְשִׂכִּים וְלִצְנִינִים. זֶהוּ שֶׁכָּתוּב וַיָּקֻצוּ מִפְּנֵי בְּנֵי יִשְׂרָאֵל, שֶׁהָיוּ נֶעֱקָרִים מִמַּלְאֲכֵי הַשָּׁרֵת, כְּמוֹ שֶׁאֲנָשִׁים נֶעֱקָצִים מֵהַקּוֹצִים הַלָּלוּ.</p>"],[9522011550,"<p>אָמַר רַבִּי יוּדַאי אָמַר רַבִּי יִצְחָק, מֶה הָיְתָה מַחֲשֶׁבֶת הַמִּצְרִים שֶׁתִּמָּנַע פְּרִיָּה וּרְבִיָּה מִיִּשְׂרָאֵל וְהַשַּׁלִּיט הַמְמֻנֶּה עֲלֵיהֶם שֶׁהִכְנִיס כָּךְ בְּלִבָּם? אֶלָּא אָמַר לָהֶם, הֱיוּ יוֹדְעִים שֶׁעָתִיד בֵּן אֶחָד לָצֵאת מִיִּשְׂרָאֵל שֶׁיַּעֲשֶׂה דִּין בֵּאלֹהֵיהֶם עַל יָדוֹ.</p>\n<p>שֶׁאָמַר רַבִּי יוֹחָנָן, בְּשָׁעָה שֶׁאָמַר מֹשֶׁה וּבְכָל אֱלֹהֵי מִצְרַיִם אֶעֱשֶׂה שְׁפָטִים, הָלַךְ דּוּמָה, שָׂרוֹ שֶׁל מִצְרַיִם, אַרְבַּע מֵאוֹת פַּרְסָה. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, גְּזֵרָה נִגְזְרָה לְפָנַי, שֶׁכָּתוּב (ישעיה כד) יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְגוֹ'. בְּאוֹתָהּ שָׁעָה נִטְּלָה הַשְּׂרָרָה מִמֶּנּוּ, וְנִתְמַנָּה דוּמָה שַׂר שֶׁל גֵּיהִנֹּם לִדּוֹן שָׁם נַפְשׁוֹת הָרְשָׁעִים. וְרַבִּי יְהוּדָה אוֹמֵר, עַל הַמֵּתִים נִתְמַנָּה.</p>\n<p>אָמַר רַבִּי חֲנִינָא, כָּתוּב (במדבר לג) וּבֵאלֹהֵיהֶם עָשָׂה ה' שְׁפָטִים. וְכִי בֵּאלוֹהַּ שֶׁל כֶּסֶף וְשֶׁל זָהָב וְשֶׁל עֵץ וְשֶׁל אֶבֶן יֵשׁ שְׁפָטִים? אֶלָּא, אָמַר רַבִּי יוֹסֵי, שֶׁל כֶּסֶף וְשֶׁל זָהָב הָיוּ נִתָּכִים מֵאֲלֵיהֶם, וְשֶׁל עֵץ מִתְרַקְּבִים.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אֱלוֹהַּ שֶׁל מִצְרַיִם שֶׂה הָיָה, וְצִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת בּוֹ שְׁפָטִים, לִשְׂרֹף אוֹתוֹ בָּאֵשׁ, כְּמוֹ שֶׁנֶּאֱמַר (דברים ז) פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ, כְּדֵי שֶׁיְּהֵא רֵיחוֹ נוֹדֵף. וְעוֹד, (שמות יב) רֹאשׁוֹ עַל כְּרָעָיו וְעַל קִרְבּוֹ. וְעוֹד, שֶׁעַצְמוֹתָיו מֻשְׁלָכִים בַּשּׁוּק. וְזֹאת הָיְתָה לְמִצְרַיִם קָשָׁה מִכֻּלָּן, זֶהוּ שֶׁכָּתוּב שְׁפָטִים.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בֵּאלֹהֵיהֶם מַמָּשׁ, וְזֶהוּ שַׂר שֶׁלָּהֶם, לְקַיֵּם יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה. וְכָל זֶה הָיוּ יוֹדְעִים הַחֲכָמִים שֶׁבָּהֶם, וְכָל שֶׁכֵּן שַׂר שֶׁלָּהֶם, עַל כֵּן כָּתוּב הָבָה נִּתְחַכְּמָה לוֹ.</p>\n<p>רַבִּי יוֹחָנָן אָמַר, הַרְבֵּה עֲבוֹדָה זָרָה הָיוּ בְּמִצְרַיִם, וְנִילוּס אֱלוֹהַּ שֶׁלָּהֶם הָיָה, וּבִכְלַל אֱלֹהֵיהֶם הָיָה הוּא, וּבְכֻלָּם עָשָׂה ה' שְׁפָטִים. אָמַר רַבִּי אַבָּא, זֶה שֶׁל רַבִּי יוֹחָנָן מְדֻיָּק וּפָשׁוּט, מִשּׁוּם שֶׁאֱלֹהֵיהֶם נִלְקִים בַּתְּחִלָּה וְאַחַר כָּךְ הָאֻמָּה, וְכֵן נִילוּס נִלְקָה בַּתְּחִלָּה, וְהָעֵצִים וְהָאֲבָנִים. זֶהוּ שֶׁכָּתוּב (שמות ז) וַיְהִי הַדָּם בְּכָל אֶרֶץ מִצְרַיִם וּבָעֵצִים וּבָאֲבָנִים, שֶׁהָיוּ לָהֶם אֱלָהוּת מַמָּשׁ. וְאָמַר רַבִּי יִצְחָק, עַל צְבָא הַמָּרוֹם בַּמָּרוֹם כָּתוּב, וְנִילוּס לֹא הָיָה בַּמָּרוֹם. אָמַר רַבִּי יוֹחָנָן, רֹב מֵימָיו כְּדֻגְמָתָם בַּמָּרוֹם. אָמַר רַבִּי יִצְחָק, שַׂר שֶׁלָּהֶם נִלְקָה בַּתְּחִלָּה, וְאַחַר כָּךְ שְׁאָר אֱלֹהֵיהֶ ם.</p>\n<p>רַבִּי שִׁמְעוֹן בְּרַבִּי יוֹסֵי אוֹמֵר, לְקוּת אֻמָּה שֶׁל מִצְרַיִם מַמָּשׁ לֹא הָיָה אֶלָּא בַּיָּם, שֶׁכָּתוּב (שם יד) לֹא נִשְׁאַר בָּהֶם עַד אֶחָד. וְקֹדֶם זֶה נַעֲשָׂה שְׁפָטִים בֵּאלֹהֵיהֶם. וְעַל זֶה כָּתוּב, הָבָה נִּתְחַכְּמָה לוֹ פֶּן יִרְבֶּה וְהָיָה כִּי תִקְרֶאנָה. וְנִתְנַבְּאוּ עַל הֶעָתִיד כְּפִי מַה שֶּׁאֵרַע לָהֶם. וְנוֹסַף גַּם הוּא עַל שּׁנְאֵינוּ - נִבְּאוּ עַל מַחֲנוֹת עֶלְיוֹנִים שֶׁיִּהְיוּ שְׁרוּיִים בְּתוֹכָם. וְנִלְחַם בָּנוּ - נִבְּאוּ עַל מַה שֶּׁכָּתוּב ה' יִלָּחֵם לָכֶם וְגוֹ'. וְעָלָה מִן הָאָרֶץ, כְּמוֹ שֶׁנֶּאֱמַר וּבְנֵי יִשְׂרָאֵל יֹצְאִים בְּיָד רָמָה.</p>"],[9522011551,"<p>וַיֵּלֶךָ אִישׁ מִבֵּית לֵוִי וַיִּקַּח אֶת בַּת לֵוִי. רַבִּי אֶלְעָזָר פָּתַח, שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה. שָׁנִינוּ, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עוֹלָמוֹ, עָלָה בְחֵפֶץ לְפָנָיו, וּבָרָא אֶת הַשָּׁמַיִם בִּימִינוֹ, וְהָאָרֶץ בִּשְׂמֹאלוֹ, וְעָלָה בְחֵפֶץ לְפָנָיו לִנְהֹג הַיּוֹם וְהַלַּיְלָה. וּבָרָא הַמַּלְאָכִים הַמְמֻנִּים בְּחַסְדּוֹ בַּיּוֹם. (לומר שירה ביום, זמן החסד) וּבָרָא הַמַּלְאָכִים הַמְמֻנִּים לוֹמַר שִׁירָה בַּלַּיְלָה. זֶהוּ שֶׁכָּתוּב (תהלים כב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי. אֵלּוּ מִיָּמִין, וְאֵלּוּ מִשְּׂמֹאל, אֵלּוּ מַקְשִׁיבִים שׁירַת הַיּוֹם, וְאֵלּוּ מַקְשִׁיבִים שִׁירַת הַלַּיְלָה, שִׁירָתָם שֶׁל יִשְׂרָאֵל קָדוֹשׁ. רַבִּי יִצְחָק אָמַר, אוֹתָם שֶׁאוֹמְרִים שִׁירָה בַּלַּיְלָה, מַקְשִׁיבִים שִׁירָתָם שֶׁל יִשְׂרָאֵל בַּיּוֹם. זֶהוּ שֶׁכָּתוּב (שיר ח) חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כַּת אַחַת, כְּלוּלָה מִשָּׁלֹשׁ כִּתּוֹת, אוֹמֶרֶת שִׁירָה בַּלַּיְלָה. זֶהוּ שֶׁכָּתוּב (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, עֲשָׂרָה דְבָרִים נִבְרְאוּ בְּיוֹם רִאשׁוֹן, מֵהֶם מִדַּת לַיְלָה וּמֵהֶם מִדַּת יוֹם, וְעַל מִדַּת לַיְלָה כָּתוּב וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ, כְּמוֹ שֶׁנֶּאֱמַר (איוב טז) אַפּוֹ טָרַף, וְכָתוּב (מיכה ה) וְטָרַף וְאֵין מַצִּיל. וְחֹק לְנַעֲרֹתֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר (שמות טז) חֹק וּמִשְׁפָּט. (תהלים קמז) חֻקָּיו וּמִשְׁפָּטָיו. (שם פא) כִּי חֹק לְיִשְׂרָאֵל הוּא מִשְׁפָּט וְגוֹ'. מִכָּאן שֶׁמִּדַּת הַדִּין שׁוֹלֶטֶת בַּלַּיְלָה.</p>\n<p>וְשָׁנִינוּ, אֵלּוּ הָאוֹמְרִים שִׁירָה בַּלַּיְלָה, אֵלּוּ הֵם שָׂרִים עַל כָּל בַּעֲלֵי שִׁיר. וּכְשֶׁפּוֹתְחִים הַחַיִּים שִׁירָה, מוֹסִיפִים הָעֶלְיוֹנִים כֹּחַ לָדַעַת וּלְהַכִּיר וּלְהַשִּׂיג מַה שֶּׁלֹּא הִשִּׂיגוּ. שָׁמַיִם וָאָרֶץ מוֹסִיפִים כֹּחַ בַּשִּׁירָה הַזּוֹ.</p>\n<p>אָמַר רַבִּי נְחֶמְיָה, אַשְׁרֵי הַזּוֹכֶה לָדַעַת בְּאוֹתוֹ שִׁיר. שֶׁשָּׁנִינוּ, הַזּוֹכֶה בְּאוֹתוֹ שִׁיר, יֵדַע בְּעִנְיְנֵי הַתּוֹרָה וְהַחָכְמָה, וְיַאֲזִין וְיַחְקֹר וְיוֹסִיף כֹּחַ וּגְבוּרָה בְּמַה שֶּׁהָיָה וּבַמֶּה שֶׁעָתִיד לִהְיוֹת, וּבָזֶה זָכָה שְׁלֹמֹה לָדַעַת.</p>\n<p>שֶׁשָּׁנָה רַבִּי שִׁמְעוֹן, דָּוִד עָלָיו הַשָּׁלוֹם יָדַע בָּזֶה, וְתִקֵּן שִׁירִים וְתִשְׁבָּחוֹת הַרְבֵּה, וְרָמַז בָּהֶם הָעֲתִידוֹת לָבֹא, וְהוֹסִיף כֹּחַ וּגְבוּרָה בְּרוּחַ הַקֹּדֶשׁ. יָדַע בְּעִנְיְנֵי הַתּוֹרָה וְהַחָכְמָה, וְאִזֵּן וְחִקֵּר וְהוֹסִיף כֹּחַ וּגְבוּרָה בִּלְשׁוֹן הַקֹּדֶשׁ.</p>\n<p>וּשְׁלֹמֹה זָכָה יוֹתֵר בְּאוֹתוֹ הַשִּׁיר, וְיָדַע הַחָכְמָה, וְאִזֵּן וְחִקֵּר וְתִקֵּן מְשָׁלִים הַרְבֵּה, וְעָשָׂה סֵפֶר מֵאוֹתוֹ הַשִּׁיר מַמָּשׁ, וְהַיְנוּ שֶׁכָּתוּב (קהלת ב) עָשִׂיתִי לִי שָׁרִים וְשָׁרוֹת. כְּלוֹמַר, קָנִיתִי לִי לָדַעַת שִׁיר מֵאוֹתָם הַשִּׁירִים הָעֶלְיוֹנִים, וַאֲשֶׁר תַּחְתָּם. וְהַיְנוּ שֶׁכָּתוּב שִׁיר הַשִּׁירִים, כְּלוֹמַר, שִׁיר שֶׁל אוֹתָם שָׁרִים שֶׁל מַעְלָה. שִׁיר שֶׁכּוֹלֵל כָּל עִנְיְנֵי הַתּוֹרָה וְהַחָכְמָה וְכֹחַ וּגְבוּרָה בְּמַה שֶּׁהָיָה וְעָתִיד לִהְיוֹת. שִׁיר שֶׁהַשָּׁרִים שֶׁל מַעְלָה מְשׁוֹרְרִים.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אֵלּוּ הַשָּׁרִים עָמְדוּ עַד שֶׁנּוֹלַד לֵוִי, אֲבָל מִשֶּׁנּוֹלַד לֵוִי וְאֵילָךְ אָמְרוּ שִׁיר. כֵּיוָן שֶׁנּוֹלַד מֹשֶׁה וְנִמְשַׁח אַהֲרֹן וְנִתְקַדְּשׁוּ הַלְוִיִּם, נִשְׁלַם הַשִּׁיר, וְעָמְדוּ עַל מִשְׁמְרוֹתָם.</p>\n<p>וְאָמַר רַבִּי אֶלְעָזָר, בְּאוֹתָהּ שָׁעָה שֶׁנּוֹלַד לֵוִי, פָּתְחוּ לְמַעְלָה וְאָמְרוּ, (שיר ח) מִי יִתֶּנְךְ כְּאָח לִי יוֹנֵק שְׁדֵי אִמִּי אֶמְצָאֲךְ בַחוּץ אֶשָּׁקְךְ גַּם לֹא יָבֻזוּ לִי. כֵּיוָן שֶׁיָּצְאוּ מִשֵּׁבֶט לֵוִי הַמְּשׁוֹרְרִים שֶׁל מַטָּה, וְנִתְקַדְּשׁוּ כֻלָּם וְעָמְדוּ עַל מִשְׁמְרוֹתָם, וְנִתְקַדְּשׁוּ אֵלֶּה לְנֹכַח אֵלֶּה, חֲבֵרִים כְּאֶחָד, וְהָעוֹלָמוֹת אֶחָד, וּמֶלֶךְ אֶחָד שׁוֹכֵן עֲלֵיהֶם - בָּא שְׁלֹמֹה, וְעָשָׂה סֵפֶר מֵאוֹתוֹ שִׁיר שֶׁל אוֹתָם שָׁרִים, וְנִסְתַּם הַחָכְמָה בּוֹ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, לָמָּה נִקְרְאוּ הַשָּׁרִים שֶׁל מַטָּה לְוִיִּם? עַל שֶׁנִּלְוִים וְנֶחְבָּרִים לְמַעְלָה כְּאֶחָד, וְהַשּׁוֹמֵעַ נִלְוֶה וְנִדְבָּק נַפְשׁוֹ לְמַעְלָה. וְעַל כָּךְ אָמְרָה לֵאָה (בראשית כט) יִלָּוֶה אִישִׁי אֵלַי. רַבִּי תַּנְחוּם אָמַר, שֶׁבַּכֹּל נִלְוֶה זֶרַע לֵוִי עִם הַשְּׁכִינָה, בְּמֹשֶׁה וְאַהֲרֹן וּמִרְיָם, וּבְכָל זַרְעוֹ אַחֲרָיו, וְהֵם הַנִּלְוִים אֶל ה' לְשָׁרְתוֹ.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁעָמְדוּ הַמְּשׁוֹרְרִים לְמַעְלָה, לֹא עָמְדוּ עַל מִשְׁמַרְתָּם עַד שֶׁנּוֹלְדוּ שְׁלֹשֶׁת הָאַחִים: מֹשֶׁה, אַהֲרֹן וּמִרְיָם. מֵילָא מֹשֶׁה וְאַהֲרֹן, מִרְיָם לָמָּה? אָמַר רַבִּי יוֹסֵי, זֶהוּ שֶׁכָּתוּב וְשָׁרוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שמות טו) וַתַּעַן לָהֶם מִרְיָם.</p>\n<p>שָׁנִינוּ, בְּאוֹתָהּ שָׁעָה שֶׁנּוֹלַד לֵוִי, נְטָלוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וּבְחָרוֹ מִכָּל אֶחָיו וְהוֹשִׁיבוֹ בָּאָרֶץ, וְהוֹלִיד לִקְהָת, וּקְהָת הוֹלִיד לְעַמְרָם, וְהוּא הוֹלִיד לְאַהֲרֹן וּמִרְיָם. פֵּרַשׁ מֵאִשְׁתּוֹ, וְהֶחֱזִירָהּ. בְּאוֹתָהּ שָׁעָה הָיוּ הַמְּשׁוֹרְרִים שֶׁל מַעְלָה עוֹמְדִים וּמְשׁוֹרְרִים. גָּעַר בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא וְנִשְׁתַּכֵּךְ הַשִּׁיר, עַד שֶׁנָּטָה קַו יְמִינוֹ וְהוֹשִׁיט לְעַמְרָם.</p>\n<p>מָה הַטַּעַם נִקְרָא עַמְרָם? שֶׁיָּצָא מִמֶּנּוּ עַם רָם עַל כָּל רָמִים, וְלֹא נִזְכַּר שְׁמוֹ. מָה הַטַּעַם לֹא נִזְכַּר שְׁמוֹ? רַבִּי יְהוּדָה אָמַר בְּשֵׁם רַבִּי אֲבָהוּ, מִפְּנֵי שֶׁבְּצִנְעָה הָלַךְ, וּבְצִנְעָה חָזַר לְאִשְׁתּוֹ, כְּדֵי שֶׁלֹּא יַכִּירוּ בוֹ. זֶהוּ שֶׁכָּתוּב וַיֵּלֶךְ אִישׁ, וְלֹא נֶאֱמַר וַיֵּלֶךְ עַמְרָם, בְּפַרְהֶסְיָא. וַיִּקַּח אֶת בַּת לֵוִי, אַף הִיא בְּצִנְעָה חָזְרָה, וְלֹא נִזְכַּר שְׁמָהּ.</p>"],[9522011552,"<p>וַיֵּלֶךָ אִישׁ. רַבִּי אֲבָהוּ אָמַר, וַיֵּלֶךְ אִישׁ זֶה גַּבְרִיאֵל, שֶׁכָּתוּב (דניאל ט) וְהָאִישׁ גַּבְרִיאֵל. שֶׁהָלַךְ הוּא וְהֶחֱזִירָהּ לְעַמְרָם. רַבִּי יְהוּדָה אָמַר, עַמְרָם מַמָּשׁ הָיָה, וְלֹא נִזְכַּר שְׁמוֹ מִפְּנֵי שֶׁהֲלִיכָה זוֹ לֹא הָיְתָה מִמֶּנּוּ לְהִזְדַּוֵּג לְאִשְׁתּוֹ, אֶלָּא מִלְמַעְלָה.</p>\n<p>רַבִּי יִצְחָק אָמַר, בְּאַהֲרֹן וּמִרְיָם לֹא נֶאֱמַר זִוּוּג אֲבוֹתָם בַּתּוֹרָה, וּבְמֹשֶׁה כָּתוּב וַיִּקַּח אֶת בַּת לֵוִי, לְהוֹרוֹת שֶׁהַשְּׁכִינָה נִקְרֵאת עַל שֵׁם לֵוִי. וְלֹא הָיָה עַמְרָם רָאוּי לְהוֹלִיד לְמֹשֶׁה, עַד שֶׁנָּטַל חֵלֶק בַּשְּׁכִינָה, וְהוֹלִיד לְמֹשֶׁה. זֶהוּ שֶׁכָּתוּב וַיִּקַּח אֶת בַּת לֵוִי. וּלְפִיכָךְ כָּתוּב וַתֵּרֶא אֹתוֹ כִּי טוֹב הוּא.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, זָכָה עַמְרָם שֶׁיָּצָא מִמֶּנּוּ בֵּן שֶׁזָּכָה לְקוֹל גָּדוֹל, שֶׁכָּתוּב (שמות יט) וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל. וְעַמְרָם זָכָה לְבַת קוֹל, שֶׁכָּתוּב וַיִּקַּח אֶת בַּת לֵוִי, כְּלוֹמַר בַּת קוֹל. וּלְפִיכָךְ כָּתוּב וַיֵּלֶךְ, כְּלוֹמַר, שֶׁהָלַךְ לְמַדְרֵגָה זוֹ. שָׁנִינוּ, כְּשֶׁנּוֹלַד מֹשֶׁה, יִחֵד הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁמוֹ עָלָיו, שֶׁכָּתוּב וַתֵּרֶא אֹתוֹ כִּי טוֹב הוּא, וְכָתוּב (תהלים קמט) טוֹב ה' לַכֹּל, וְכָתוּב טַעֲמוּ וּרְאוּ כִּי טוֹב ה'.</p>"],[9522011553,"<p>וַיְהִי בַיָּמִים הָרַבִּים הָהֵם. רַבִּי יְהוֹשֻׁעַ מִסִּכְנִין אָמַר, וַיְהִי בַיָּמִים הָרַבִּים הָהֵם - סוֹף גָּלוּתָם הָיָה, שֶׁהָיוּ יִשְׂרָאֵל מְשֻׁעְבָּדִים בְּכָל עֲבוֹדָה. בַּיָּמִים הָרַבִּים הָהֵם - שֶׁהָיוּ רַבִּים לְיִשְׂרָאֵל בְּמִצְרַיִם. וְכֵיוָן שֶׁנִּשְׁתַּלֵּם קֵץ גָּלוּתָם מַה כָּתוּב? וַיָּמָת מֶלֶךְ מִצְרַיִם. מָה הַטַּעַם? שֶׁהוּרַד שַׂר מִצְרַיִם מִמַּעֲלָתוֹ וְנָפַל מִגַּאֲוָתוֹ. וְכֵיוָן שֶׁנָּפַל מֶלֶךְ מִצְרַיִם, שֶׁהוּא שַׂר שֶׁלָּהֶם, זָכַר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל וְשָׁמַע תְּפִלָּתָם.</p>"],[9522011554,"<p>אָמַר רַבִּי יְהוּדָה, בֹּא וּרְאֵה שֶׁכָּךְ הוּא, שֶׁכָּל זְמַן שֶׁהַשַּׂר שֶׁלָּהֶם נִתְּנָה לוֹ שְׂרָרָה עַל יִשְׂרָאֵל, לֹא נִשְׁמַע צַעֲקָתָם שֶׁל יִשְׂרָאֵל. כֵּיוָן שֶׁנָּפַל הַשַּׂר שֶׁלָּהֶם, כָּתוּב וַיָּמָת מֶלֶךְ מִצְרַיִם, וּמִיָּד - וַיֵּאָנְחוּ בְנֵי יִשְׂרָאֵל מִן הָעֲבֹדָה וַיִּזְעָקוּ וַתַּעַל שַׁוְעָתָם אֶל הָאֱלֹהִים. שֶׁעַד אוֹתָהּ שָׁעָה לֹא נַעֲנוּ בְצַעֲקָתָם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, בֹּא וּרְאֵה רַחֲמָנוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. כְּשֶׁהוּא מְרַחֵם עַל יִשְׂרָאֵל, כּוֹפֶה לְמִדַּת הַדִּין וּמוֹרִידָהּ וּמְרַחֵם עֲלֵיהֶם, וְהַיְנוּ שֶׁשָּׁנִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹרִיד שְׁתֵּי דְמָעוֹת לַיָּם הַגָּדוֹל. מָהֵם אוֹתָם שְׁתֵּי דְמָעוֹת? אָמַר רַבִּי יוֹסֵי, לֹא דָּבָר בָּרוּר מַה הֵם, שֶׁהֲרֵי אָמַר לוֹ לְאוֹב עֲצָמוֹת, שֶׁהָיָה מְשַׁקֵּר וּדְבָרָיו שִׁקְרִיִּים.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, לֹא הוֹלְכִים אַחַר אוֹב עֲצָמוֹת, שֶׁבֵּרוּר הַדָּבָר הוּא, שֶׁשָּׁנִינוּ, בַּעֲשָׂרָה כִּתְרֵי הַמֶּלֶךְ יֵשׁ שְׁתֵּי דְמָעוֹת לַקָּדוֹשׁ- בָּרוּךְ-הוּא, וְהֵן שְׁתֵּי מִדּוֹת דִּין, שֶׁהַדִּין בָּא מִשְּׁתֵּיהֶן, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נא) שְׁתַּיִם הֵנָּה קֹרְאֹתַיִךְ. וּכְשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא זוֹכֵר אֶת בָּנָיו, הוּא מוֹרִיד אוֹתָם לַיָּם הַגָּדוֹל, שֶׁהוּא יָם הַחָכְמָה, לְהַמְתִּיקָן, וְהוֹפֵךְ מִדַּת הַדִּין לְמִדַּת הָרַחֲמִים וּמְרַחֵם עֲלֵיהֶם. אָמַר רַבִּי יְהוּדָה, שְׁתֵּי דְמָעוֹת, שֶׁמֵּהֶן בָּאוֹת הַדְּמָעוֹת, מֵהֶן בָּא הַדִּין.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּתוּב (שמות יד) וְהִנֵּה מִצְרַיִם נֹסֵעַ אַחֲרֵיהֶם. וְאָמַר רַבִּי יוֹסֵי, זֶה שַׂר שֶׁל מִצְרַיִם הוּא, וְאַתָּה אָמַרְתָּ וַיָּמָת מֶלֶךְ מִצְרַיִם זֶה שַׂר שֶׁל מִצְרַיִם?! אָמַר רַבִּי יִצְחָק, הַדָּבָר הַזֶּה מְסַיֵּעַ לְאוֹתוֹ שֶׁלְּמַעְלָה. כָּתוּב כָּאן וְהִנֵּה מִצְרַיִם, וְכָתוּב שָׁם וַיָּמָת מֶלֶךְ מִצְרַיִם. מְלַמֵּד שֶׁעַכְשָׁו לֹא הָיָה מֶלֶךְ, שֶׁהוֹרִידוּהוּ מִגְּדֻלָּתוֹ, וּלְפִיכָךְ כָּתוּב וְהִנֵּה מִצְרַיִם וְלֹא כָתוּב מֶלֶךְ מִצְרַיִם. וּמַה שֶּׁאָמַר וַיָּמָת, כְּמוֹ שֶׁנֶּאֱמַר (שם ד) כִּי מֵתוּ כָּל הָאֲנָשִׁים הַמְבַקְשִׁים אֶת נַפְשֶׁךְ.</p>\n<p>אָמַר רַבִּי יִצְחָק אָמַר רַבִּי יְהוֹשֻׁעַ, בֹּא רְאֵה, כָּל מַלְכֵי מִצְרַיִם פַּרְעֹה שְׁמָם, וּבְכָאן לֹא נֶאֱמַר אֶלָּא מֶלֶךְ מִצְרַיִם סְתָם. וּבִמְקוֹמוֹ פַּרְעֹה, וְהוּא פַּרְעֹה מַמָּשׁ. בּא רְאֵה, בְּעוֹד שֶׁיֵּשׁ שִׁלְטוֹן שֶׁלְּמַעְלָה, יֵשׁ שִׁלְטוֹן בָּעָם שֶׁלְּמַטָּה. כְּשֶׁהָעֳבַר הַשִּׁלְטוֹן שֶׁלְּמַעְלָה, מָעֳבָר הַשִּׁלְטוֹן שֶׁלְּמַטָּה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּתוּב (זכריה יד) הִנֵּה יוֹם בָּא לַה' וְגוֹ' וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה' וְגוֹ'. וְכִי שְׁאָר הַיָּמִים אֵינָם שֶׁלּוֹ? אֶלָּא, אָמַר רַבִּי אַבָּא, מְלַמֵּד שֶׁשְּׁאָר הַיָּמִים נִתָּנִים לְשָׂרִים, וְאוֹתוֹ יוֹם אֵינוֹ שֶׁל הַשָּׂרִים, אֶלָּא שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּדֵי לַעֲשׂוֹת דִּין בְּעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, מִפְּנֵי שֶׁבְּאוֹתוֹ יוֹם יִפְּלוּ כָּל הַשָּׂרִים מִמַּעֲלָתָם, וְעַל זֶה כָּתוּב וְנִשְׂגָּב ה' לְבַדּוֹ בַּיּוֹם הַהוּא, שֶׁאוֹתוֹ יוֹם לֹא יִהְיֶה מַעֲלָה לְשָׂרִים.</p>"],[9522011555,"<p>אָמַר רַבִּי אַבָּא, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִּין בַּשָּׂרִים שֶׁל מַעְלָה, מַה כָּתוּב? (ישעיה לד) כִּי רִוְּתָה בַשָּׁמַיִם חַרְבִּי. וְכִי חֶרֶב יֵשׁ לַה'? אֶלָּא, אָמַר רַבִּי יִצְחָק, חֶרֶב יֵשׁ לוֹ, שֶׁכָּתוּב חֶרֶב לַה' מָלְאָה דָּם, וְכָתוּב וּבְחַרְבּוֹ אֶת כָּל בָּשָׂר.</p>\n<p>אָמַר רַבִּי אַבָּא, הַחֶרֶב הַזֶּה הוּא הַדִּין שֶׁעוֹשֶׂה, שֶׁכָּתוּב (דברי הימים א כא) וַיַּרְא אֶת מַלְאַךְ ה' עֹמֵד בֵּין הָאָרֶץ וּבֵין הַשָּׁמַיִם וְחַרְבּוֹ שְׁלוּפָה בְּיָדוֹ. וְכִי חֶרֶב שְׁלוּפָה הָיְתָה בְּיַד הַמַּלְאָךְ? אֶלָּא שֶׁהָיְתָה הָרְשׁוּת נְתוּנָה בְיָדוֹ לַעֲשׂוֹת דִּין.</p>\n<p>וַהֲרֵי אָמַר רַבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, אָמַר לִי מַלְאַךְ הַמָּוֶת, אִם לֹא שֶׁאֲנִי חָס עַל כְּבוֹד הַבְּרִיּוֹת, אֶפְרַע לָהֶם אֶת בֵּית הַשְּׁחִיטָה כַּבְּהֵמָה. אָמַר רַבִּי אַבָּא, הַכֹּל מִשּׁוּם שֶׁנִּתָּן רְשׁוּת בְּיָדוֹ לַעֲשׂוֹת גְּמַר דִּין. זֶהוּ שֶׁכָּתוּב (יהושע ה) וְחַרְבּוֹ שְׁלוּפָה בְּיָדוֹ. הָרְשׁוּת נְתוּנָה בְּיָדוֹ לַעֲשׂוֹת דִּין. אִם כָּךְ, מַה זֶּה וַיָּשֶׁב חַרְבּוֹ אֶל נְדָנָהּ? אָמַר רַבִּי אַבָּא, שֶׁנֶּחֱזַר הַדִּין לְבַעַל הַדִּין, וְהָרְשׁוּת לְמִי שֶׁהָרְשׁוּת שֶׁלּוֹ.</p>"],[9522011556,"<p>וַיֵּאָנְחוּ בְנֵי יִשְׂרָאֵל. וַיִּתְאַנְּחוּ לֹא כָתוּב, אֶלָּא וַיֵּאָנְחוּ, כְּלוֹמַר, נִתְאַנְּחוּ (האניחו) לוֹ לְמַעְלָה, (כלומר נאנחו למטה) שֶׁהָאֲנָחָה הָיְתָה בִּשְׁבִילָם לְמַעְלָה.</p>\n<p>רַבִּי בְּרֶכְיָה אָמַר, בְּנֵי יִשְׂרָאֵל שֶׁלְּמַעְלָה הָיוּ, וּמִי הֵם בְּנֵי יִשְׂרָאֵל? אוֹתָם שֶׁנִּקְרְאוּ בְּנֵי הָעֲבוֹדָה, כְּלוֹמַר, אוֹתָם שֶׁהֵם מִן הָעֲבוֹדָה שֶׁל מַעְלָה. וַתַּעַל שַׁוְעָתָם אֶל הָאֱלֹהִים, שֶׁעַד אוֹתָהּ שָׁעָה לֹא עָלְתָה שַׁוְעָתָם לְפָנָיו.</p>\n<p>אָמַר רַבִּי יִצְחָק, כְּשֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין בְּפָמַלְיָא שֶׁל מַעְלָה, אוֹתוֹ דִין מַה יִּהְיֶה? אָמַר רַבִּי אֶלְעָזָר, מַעֲבִיר אוֹתָם בְּאוֹתוֹ נְהַר דִּינוּר, וּמַעֲבִירָם מִשִּׁלְטוֹנָם, וּמְמַנֶּה שַׁלִּיטִים אֲחֵרִים שֶׁל שְׁאָר עַמִּים. אָמַר לוֹ, וַהֲרֵי כָּתוּב מְשָׁרְתָיו אֵשׁ לֹהֵט? אָמַר לוֹ, יֵשׁ אֵשׁ קָשָׁה מֵאֵשׁ, וְיֵשׁ אֵשׁ שֶׁדּוֹחָה אֵשׁ.</p>"],[9522011557,"<p>אָמַר רִבִּי יִצְחָק, שלשה עניינים כאן, אֲנָחָה, שַׁוְעָה, צְעָקָה, וְכָל אֶחָד מִתְפָּרֵשׁ מֵהָאַחֵר. אֲנָחָה - שֶׁכָּתוּב וַיֵּאָנְחוּ בְנֵי יִשְׂרָאֵל. צְעָקָה - שֶׁכָּתוּב וַיִּצְעָקוּ. שַׁוְעָה - שֶׁכָּתוּב וַתַּעַל שַׁוְעָתָם. וְכָל אֶחָד לְבַדּוֹ מִתְפָּרֵשׁ, וְכֻלָּם עָשׂוּ יִשְׂרָאֵל. אָמַר רַבִּי יְהוּדָה, צְעָקָה וְשַׁוְעָה עָשׂוּ, אֲנָחָה לֹא עָשׂוּ, מַשְׁמָע מִשֶּׁכָּתוּב וַיֵּאָנְחוּ, וּלְמַעְלָה הָיְתָה הָאֲנָחָה בִּשְׁבִילָם.</p>\n<p>צְעָקָה וְשַׁוְעָה בַּמֶּה הִתְפָּרְשׁוּ? אָמַר רַבִּי יִצְחָק, אֵין לְךְ שַׁוְעָה אֶלָּא בִּתְפִלָּה, שֶׁנֶּאֱמַר (תהלים לט) שִׁמְעָה תְפִלָּתִי ה' וְשַׁוְעָתִי הַאֲזִינָה. אֵלֶיךְ ה' שִׁוַּעְתִּי. שִׁוַּעְתִּי אֵלֶיךְ וַתִּרְפָּאֵנִי. צְעָקָה, שֶׁצּוֹעֵק וְאֵינוֹ אוֹמֵר כְּלוּם. אָמַר רַבִי יְהוּדָה, הִלְכָךְ גְּדוֹלָה צְעָקָה מִכֻּלָּם, שֶׁצְּעָקָה הִיא בַּלֵּב. זֶהוּ שֶׁכָּתוּב (איכה ב) צָעַק לִבָּם אֶל ה'. צְעָקָה וּזְעָקָה דָּבָר אֶחָד הוּא, וְזֶה קְרוֹבָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא יוֹתֵר מִתְּפִלָּה וַאֲנָחָה, שֶׁכָּתוּב (שמות כב) כִּי אִם צָעֹק יִצְעַק אֵלַי שָׁמֹעַ אֶשְׁמַע צַעֲקָתוֹ.</p>\n<p>אָמַר רַבִּי בְּרֶכְיָה, בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁמוּאֵל (שמואל א טו) נִחַמְתִּי כִּי הִמְלַכְתִּי אֶת שָׁאוּל לְמֶלֶךְ, מַה כָּתוּב? וַיִּחַר לִשְׁמוּאֵל, וַיִּצְעַק אֶל ה' כָּל הַלַּיְלָה. הִנִּיחַ הַכֹּל וְלָקַח צְעָקָה, מִשּׁוּם שֶׁהִיא קְרוֹבָה לַקָּדוֹשׁ- בָּרוּךְ-הוּא יוֹתֵר מִכֻּלָּם. זֶהוּ שֶׁכָּתוּב וְעַתָּה הִנֵּה צַעֲקַת בְּנֵי יִשְׂרָאֵל בָּאָה אֵלָי.</p>\n<p>שָׁנוּ רַבּוֹתֵינוּ, זֶה מִי שֶׁמִּתְפַּלֵּל וּבוֹכֶה וְצוֹעֵק עַד שֶׁלֹּא יָכוֹל לִרְחֹשׁ בִּשְׂפָתָיו - תְּפִלָּה זוֹ שְׁלֵמָה, שֶׁהִיא בַּלֵּב, וּלְעוֹלָם לֹא חוֹזֶרֶת רֵיקָם. אָמַר רַבִּי יְהוּדָה, גְּדוֹלָה צְעָקָה שֶׁקּוֹרַעַת גְּזַר דִּינוֹ שֶׁל אָדָם מִכָּל יָמָיו.</p>\n<p>רַבִּי יִצְחָק אָמַר, גְּדוֹלָה צְעָקָה שֶׁמּוֹשֶׁלֶת עַל מִדַּת הַדִּין שֶׁל מַעְלָה. רַבִּי יוֹסֵי אָמַר, גְּדוֹלָה צְעָקָה שֶׁמּוֹשֶׁלֶת בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. בִּשְׁבִיל צְעָקָה נוֹחֵל הָאָדָם הָעוֹלָם הַזֶּה וְהָעוֹלָם הַבָּא, שֶׁכָּתוּב (תהלים קז) וַיִּצְעֲקוּ אֶל ה' בַּצַּר לָהֶם מִמְּצוּקוֹתֵיהֶם יַצִּילֵם.</p>"],[9522011558,"<p>וּמֹשֶׁה הָיָה רֹעֶה אֶת צֹאן יִתְרוֹ חֹתְנוֹ כֹּהֵן מִדְיָן. רַבִּי שִׁמְעוֹן פָּתַח, (שיר ב) דּוֹדִי לִי וַאֲנִי לוֹ הָרֹעֶה בַּשּׁוֹשַׁנִּים. אָמַר רַבִּי שִׁמְעוֹן, אוֹי לָהֶם לַבְּרִיּוֹת שֶׁאֵינָם מַשְׁגִּיחִים וְאֵינָם יוֹדְעִים, בְּשָׁעָה שֶׁעָלָה בְּמַחֲשָׁבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא עוֹלָמוֹ, כָּל הָעוֹלָמוֹת עָלוּ בְמַחֲשָׁבָה אַחַת, וּבְמַחֲשָׁבָה זוֹ נִבְרְאוּ כֻלָּם, זֶהוּ שֶׁכָּתוּב כֻּלָּם בְּחָכְמָה עָשִׂיתָ. וּבְמַחֲשָׁבָה זוֹ, שֶׁהִיא הַחָכְמָה, נִבְרָא הָעוֹלָם הַזֶּה וְהָעוֹלָם שֶׁל מַעְלָה.</p>\n<p>נָטָה יְמִינוֹ, וּבָרָא הָעוֹלָם שֶׁל מַעְלָה. נָטָה שְׂמֹאלוֹ, וּבָרָא אֶת הָעוֹלָם הַזֶּה. זֶהוּ שֶׁכָּתוּב (ישעיה מח) אַף יָדִי יָסְדָה אֶרֶץ וִימִינִי טִפְּחָה שָׁמָיִם קֹרֵא אֲנִי אֲלֵיהֶם יַעַמְדוּ יַחְדָּו. וְכֻלָּם בְּרֶגַע אַחַת (ובשעה אחת נבראו), וְעָשָׂה הָעוֹלָם הַזֶּה כְּנֶגֶד הָעוֹלָם שֶׁל מַעְלָה. וְכָל מַה שֶּׁיֵּשׁ לְמַעְלָה, כְּדֻגְמָתוֹ לְמַטָּה. וְכָל מַה שֶּׁיֵּשׁ לְמַטָּה, כְּדֻגְמָתוֹ בַּיָּם, וְהַכֹּל אֶחָד. בָּרָא בָּעֶלְיוֹנִים הַמַּלְאָכִים - בָּרָא בָּעוֹלָם הַזֶּה בְּנֵי אָדָם, בָּרָא בַּיָּם לִוְיָתָן, כְּמוֹ שֶׁנֶּאֱמַר (שמות לז) לְחַבֵּר אֶת הָאֹהֶל לִהְיוֹת אֶחָד.</p>\n<p>כָּתוּב בָּאָדָם, כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם, וְכָתוּב (תהלים ח) וַתְּחַסְּרֵהוּ מְּעַט מֵאֱלֹהִים. אִם בְּנֵי אָדָם חֲשׁוּבִים בְּמַעֲשֵׂיהֶם (במעשיו) כָּל זֶה, וְהֵם אֲבוּדִים (מטפה) מֵעֲפַר הַבְּאֵר, בַּמֶּה בָּאִים לִשְׁאֹב מִמֶּנּוּ? וּבָחַר בָּעֶלְיוֹנִים, וּבָחַר בְּיִשְׂרָאֵל. לָעֶלְיוֹנִים לֹא קָרָא בָּנִים. לַתַּחְתּוֹנִים קָרָא בָּנִים. זֶהוּ שֶׁכָּתוּב (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. הוּא קָרָא לָהֶם בָּנִים, וְהֵם קָרְאוּ לוֹ אָב, שֶׁכָּתוּב (ישעיה סג) כִּי אַתָּה אָבִינוּ. וְכָתוּב דּוֹדִי לִי וַאֲנִי לוֹ. הוּא בָּחַר בִּי, וַאֲנִי בָּחַרְתִּי בּוֹ.</p>\n<p>הָרֹעָה בַּשּׁוֹשַׁנִּים - הוּא רוֹעֶה בַּשּׁוֹשַׁנִּים, אַף עַל פִּי שֶׁהַקּוֹצִים סָבִיב לָהֶם, וְאֵין אַחֵר יָכוֹל לִרְעוֹת בַּשּׁוֹשַׁנִּים כְּמוֹתוֹ. דָּבָר אַחֵר הָרֹעֶה בַּשּׁוֹשַׁנִּים - מַה שּׁוֹשָׁן זֶה הוּא אָדם וּמֵימָיו לְבָנִים, כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מַנְהִיג עוֹלָמוֹ מִמִּדַּת הַדִּין לְמִדַּת הָרַחֲמִים, וְכָתוּב (שם א) אִם יִהְיֶה חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ.</p>\n<p>רַבִּי אַבָּא הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְהָיָה עִמּוֹ רַבִּי יִצְחָק. עַד שֶׁהָיוּ הוֹלְכִים, פָּגַשׁ אֶת אוֹתָם וְרָדִים. נָטַל אֶחָד רַבִּי אַבָּא בְּיָדוֹ וְהָיָה הוֹלֵךְ. פָּגַשׁ בָּהֶם רַבִּי יוֹסֵי. אָמַר, וַדַּאי שֶׁשְּׁכִינָה כָּאן, וַאֲנִי רָאִיתִי בִּידֵי רַבִּי אַבָּא לִלְמֹד חָכְמָה רַבָּה, שֶׁהֲרֵי יָדַעְתִּי שֶׁרַבִּי אַבָּא לֹא נָטַל אֶת זֶה אֶלָּא לְהַרְאוֹת חָכְמָה.</p>\n<p>אָמַר רַבִּי אַבָּא, שֵׁב, בְּנִי, שֵׁב. יָשְׁבוּ. הֵרִיחַ רַבִּי אַבָּא בְּאוֹתוֹ הַוֶּרֶד. אָמַר, וַדַּאי אֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא עַל הָרֵיחַ, שֶׁהֲרֵי רָאִיתִי שֶׁאֵין נֶפֶשׁ מִתְקַיֶּמֶת אֶלָּא עַל רֵיחַ, וְלָכֵן הֲדַס בְּמוֹצָאֵי שַׁבָּת.</p>\n<p>פָּתַח וְאָמַר, דּוֹדִי לִי וַאֲנִי לוֹ הָרֹעֶה בַּשּׁוֹשַׁנִּים. מִי גָרַם לִי שֶׁאֲנִי לְדוֹדִי וְדוֹדִי לִי? מִפְּנֵי שֶׁהוּא מַנְהִיג עוֹלָמוֹ בַּשּׁוֹשַׁנִּים. מַה שּׁוֹשָׁן יֵשׁ בּוֹ רֵיחַ וְהוּא אָדם, מוֹצְקִין אוֹתוֹ וְהוּא מִתְהַפֵּךְ לְלָבָן, וּלְעוֹלָם רֵיחוֹ לֹא זָז - כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מַנְהִיג עוֹלָמוֹ בְּדֶרֶךְ זֶה, שֶׁאִלְמָלֵא כֵן לֹא יִתְקַיֵּם הָעוֹלָם בִּשְׁבִיל הָאָדָם הַחוֹטֵא. וְהַחוֹטֵא נִקְרָא אָדם, כְּמוֹ שֶׁנֶּאֱמַר אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. מַקְרִיב קָרְבָּנוֹ לָאֵשׁ שֶׁהוּא אָדם. זוֹרֵק הַדָּם סָבִיב לַמִּזְבֵּחַ שֶׁהוּא אָדם. מִדַּת הַדִּין אָדם. מוֹצְקִין אוֹתוֹ (הריח), וְעוֹלֶה הֶעָשָׁן כֻּלּוֹ לָבָן, וְאָז הָאָדֹם נֶהְפָּךְ לְלָבָן, נֶהְפָּךְ מִדַּת הַדִּין לְמִדַּת הָרַחֲמִים.</p>\n<p>וּבֹא רְאֵה, כָּל מִדַּת הַדִּין אֵין צָרִיךְ הָרֵיחַ שֶׁלּוֹ אֶלָּא מִצַּד אֹדֶם. וְהַיְנוּ שֶׁאָמַר רַבִּי יְהוּדָה, מַהוּ שֶׁכָּתוּב (מלכים א יח) וַיִּתְגּוֹדְדוּ כְּמִשְׁפָּטָם וְגוֹ' עַד שְׁפָךְ דָּם עֲלֵיהֶם? אֶלָּא הָיוּ יוֹדְעִים שֶׁלֹּא יַשִּׂיגוּ מִמִּדַּת הַדִּין כִּרְצוֹנָם, זוּלָתִי בָּאֹדֶם.</p>\n<p>אָמַר רַבִּי יִצְחָק, וְעוֹד - אֹדֶם וְלָבָן נִקְרָב לְעוֹלָם, וְהָרֵיחַ עוֹלֶה מִשְּׁתֵּיהֶן. מָה הַשּׁוֹשָׁן אָדם וְלָבָן - כָּךְ רֵיחַ הַקָּרְבָּן. וְהַקָּרְבָּן מֵאָדם וְלָבָן. בֹּא וּרְאֵה מֵרֵיחַ הַקְּטֹרֶת, שֶׁהַסַּמָּנִים, מֵהֶם אֲדֻמִּים וּמֵהֶם לְבָנִים, כְּגוֹן הַלְּבוֹנָה שֶׁהוּא לָבָן, מָר דְּרוֹר אָדם, וְהָרֵיחַ עוֹלֶה מֵאָדם וְלָבָן. וְעַל כֵּן מַנְהִיג עוֹלָמוֹ בַּשּׁוֹשַׁנִּים, שֶׁהוּא אָדם וְלָבָן, וְכָתוּב (יחזקאל מד) לְהַקְרִיב לִי חֵלֶב וָדָם.</p>\n<p>כְּנֶגֶד זֶה אָדָם מַקְרִיב חֶלְבּוֹ וְדָמוֹ ומִתְכַּפֵּר לוֹ, זֶה אָדם וְזֶה לָבָן. מָה הַשּׁוֹשָׁן שֶׁהוּא אָדם וְהוּא לָבָן אֵין מוֹצְקִין אוֹתוֹ לַחֲזֹר כֻּלּוֹ לָבָן אֶלָּא בָּאֵשׁ - כָּךְ הַקָּרְבָּן אֵין מוֹצְקִין אוֹתוֹ לַחֲזר כֻּלּוֹ לָבָן אֶלָּא בָּאֵשׁ. עַכְשָׁו, מִי שֶׁיּוֹשֵׁב בְּתַעֲנִיתוֹ וּמַקְרִיב חֶלְבּוֹ וְדָמוֹ, אֵינוֹ נִצְמָק לַחֲזֹר כֻּלּוֹ לָבָן אֶלָּא בָּאֵשׁ. שֶׁאָמַר רַבִּי יְהוּדָה, מִתּוֹךְ תַּעֲנִיתוֹ שֶׁל אָדָם מַחֲלִישִׁין אֵיבָרָיו, וְגוֹבֵר עָלָיו הָאֵשׁ. וּבְאוֹתָהּ שָׁעָה צָרִיךְ לְהַקְרִיב חֶלְבּוֹ וְדָמוֹ בְּאוֹתוֹ הָאֵשׁ, וְהוּא הַנִּקְרָא מִזְבַּח כַּפָּרָה.</p>\n<p>וְהַיְנוּ שֶׁרַבִּי אֶלְעָזָר, כְּשֶׁהָיָה יוֹשֵׁב בְּתַעֲנִית, הָיָה מִתְפַּלֵּל וְאוֹמֵר: גָּלוּי וְיָדוּעַ לְפָנֶיךְ ה' אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי שֶׁהִקְרַבְתִּי לְפָנֶיךְ חֶלְבִּי וְדָמִי, וְהִרְתַּחְתִּי אוֹתָם בַּחֲמִימוּת חֻלְשַׁת גּוּפִי, יְהִי רָצוֹן מִלְּפָנֶיךְ שֶׁיְּהֵא הָרֵיחַ הָעוֹלֶה מִפִּי בְּשָׁעָה זוֹ כְּרֵיחַ הָעוֹלֶה מֵהַקָּרְבָּן בְּאֵשׁ הַמִּזְבֵּחַ, וְתִרְצֵנִי.</p>\n<p>נִמְצָא שֶׁאָדָם הוּא מַקְרִיב בְּתַעֲנִיתוֹ הַחֵלֶב וְהַדָּם, (והאש) וְהָרֵיחַ שֶׁעוֹלֶה מִפִּיו הוּא מִזְבַּח כַּפָּרָה, וּלְפִיכָךְ תִּקְּנוּ הַתְּפִלָּה בִּמְקוֹם הַקָּרְבָּן, וּבִלְבַד שֶׁיִּתְכַּוֵּן לְמַה שֶּׁאָמַרְנוּ. אָמַר רַבִּי יִצְחָק, מִכָּאן וּלְהָלְאָה כָּתוּב (במדבר לא) כָּל דָּבָר אֲשֶׁר יָבֹא בָאֵשׁ תַּעֲבִירוּ בָאֵשׁ וְטָהֵר. אָמַר רַבִּי יוֹסֵי, כְּשֶׁהָיָה בֵּית הַמִּקְדָּשׁ קַיָּם, אָדָם מַקְרִיב קָרְבָּנוֹ בְּעִנְיָן זֶה וּמִתְכַּפֵּר לוֹ. עַכְשָׁו תְּפִלָּתוֹ שֶׁל אָדָם מְכַפֵּר לוֹ בִּמְקוֹם הַקָּרְבָּן, כְּמוֹ זֶה.</p>\n<p>דָּבָר אַחֵר דּוֹדִי לִי וַאֲנִי לוֹ הָרֹעֶה בַּשּׁוֹשַׁנִּים - מָה הַשּׁוֹשַׁנִּים קוֹצִים מְצוּיִים בְּתוֹכָם, אַף הַקָּדוֹשׁ בָּרוּךְ הוּא מַנְהִיג עוֹלָמוֹ בְּצַדִּיקִים וּרְשָׁעִים. מָה הַשּׁוֹשַׁנִּים, אִלְמָלֵא הַקּוֹצִים אֵין הַשּׁוֹשַׁנִּים מִתְקַיְּמִים, כָּךְ אִלְמָלֵא הָרְשָׁעִים אֵין הַצַּדִּיקִים נִכָּרִים. שֶׁאָמַר רַבִּי יְהוּדָה, בַּמֶּה הַצַּדִּיקִים נִכָּרִים? מִתּוֹךְ שֶׁיֵּשׁ רְשָׁעִים, שֶׁאִלְמָלֵא רְשָׁעִים אֵין הַצַּדִּיקִים נִכָּרִים. דָּבָר אַחֵר הָרֹעֶה בַּשּׁוֹשַׁנִּים - הַמַּנְהִיג עוֹלָמוֹ בְּשֵׁשׁ שָׁנִים, וְהַשְּׁבִיעִית שַׁבָּת לַה'. דָּבָר אַחֵר בַּשּׁוֹשַׁנִּים - בְּאוֹתָם שֶׁשּׁוֹנִים בַּתּוֹרָה.</p>"],[9522011559,"<p>וּמֹשֶׁה הָיָה רֹעֶה אֶת צֹאן יִתְרוֹ חֹתְנוֹ כֹּהֵן מִדְיָן. רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים כו) מִזְמוֹר לְדָוִד ה' רֹעִי לֹא אֶחְסָר. כְּלוֹמַר, ה' רֹעִי - ה' הָרוֹעֶה שֶׁלִּי. מָה הָרוֹעֶה מַנְהִיג אֶת הַצֹּאן וּמוֹלִיכָם לְמִרְעֶה טוֹב, לְמִרְעֶה שָׁמֵן, בִּמְקוֹם נַחֲלֵי מַיִם, מְיַשֵּׁר הֲלִיכָתָן בְּצֶדֶק וּבְמִשְׁפָּט - אַף הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּתוּב בִּנְאוֹת דֶּשֶׁא יַרְבִּיצֵנִי עַל מֵי מְנֻחוֹת יְנַהֲלֵנִי נַפְשִׁי יְשׁוֹבֵב.</p>\n<p>אָמַר רַבִּי יוֹסֵי, דֶּרֶךְ הָרוֹעֶה לִנְהֹג בְּצֶדֶק אֶת צֹאנוֹ, לְהַרְחִיקָם מִן הַגָּזֵל, לְהַנְהִיגָם בְּמִישׁוֹר, וְהַשֵּׁבֶט בְּיָדוֹ שֶׁלֹּא יִטּוּ יָמִין וּשְׂמֹאל. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא רוֹעֶה אֶת יִשְׂרָאֵל לְהַנְהִיגָם בְּמִישׁוֹר, וּבְכָל עֵת הַשֵּׁבֶט בְּיָדוֹ שֶׁלֹּא יִטּוּ יָמִין וּשְׂמֹאל.</p>\n<p>דָּבָר אַחֵר וּמֹשֶׁה הָיָה רֹעֶה - אָמַר רַבִּי יוֹסֵי, תֵּדַע לְךְ, שֶׁכָּל זְמַן שֶׁהָרוֹעֶה חָכָם לְנַהֵל אֶת צֹאנוֹ, הוּא מוּכָן לְקַבֵּל עֹל מַלְכוּת שָׁמַיִם. אִם הָרוֹעֶה שׁוֹטֶה, עָלָיו נִקְרָא (משלי כו) תִּקְוָה לִכְסִיל מִמֶּנּוּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, מֹשֶׁה חָכָם הָיָה, וּבָקִי לִנְהֹג אֶת צֹאנוֹ. בֹּא וּרְאֵה מִדָּוִד, שֶׁנֶּאֱמַר (שמואל א טז) וְהִנֵּה רֹעֶה בַּצֹאן. לְלַמֶּדְךְ שֶׁדָּוִד חָכָם גָּדוֹל הָיָה, וְהָיָה רוֹעֶה צֹאנוֹ כַּדִּין וְכַשּׁוּרָה, לְפִיכָךְ עָשָׂהוּ הַקָּדוֹשׁ בָּרוּךְ הוּא מֶלֶךְ עַל כָּל יִשְׂרָאֵל. וְלָמָּה צֹאן וְלֹא בָּקָר? אָמַר רַבִּי יְהוּדָה, יִשְׂרָאֵל נִקְרָאִים צֹאן, שֶׁנֶּאֱמַר (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם. וְכָתוּב כְּצֹאן קָדָשִׁים כְּצֹאן יְרוּשָׁלם.</p>\n<p>מָה הַצּאן, כְּשֶׁיִּקָּרְבוּ עַל הַמִּזְבֵּחַ, בִּשְׁבִילָם זוֹכֶה לְחַיֵּי הָעוֹלָם הַבָּא - כָּךְ הַמַּנְהִיג לְיִשְׂרָאֵל כַּדִּין וְכַשּׁוּרָה, בִּשְׁבִילָם זוֹכֶה לְחַיֵּי הָעוֹלָם הַבָּא. וְעוֹד, הָרוֹעֶה אֶת הַצּאן, כְּשֶׁהַצּאן יוֹלְדוֹת, הָרוֹעֶה נוֹטֵל אוֹתָם טְלָאִים בְּחֵיקוֹ, כְּדֵי שֶׁלֹּא יִלְאוּ וְיִיגָעוּ, וּמוֹלִיכָם אַחֲרֵי אִמּוֹתָם וּמְרַחֵם עֲלֵיהֶם - כָּךְ הַמַּנְהִיג לְיִשְׂרָאֵל צָרִיךְ לְהַנְהִילָם בְּרַחֲמִים, וְלֹא בְּאַכְזָרִיּוּת. וְכֵן אָמַר מֹשֶׁה, כִּי תֹאמַר אֵלַי, שָׂאֵהוּ בְחֵיקֶיךְ וְגוֹ'.</p>\n<p>מָה הָרוֹעֶה אֶת הַצֹּאן, כְּשֶׁהוּא רוֹעֶה טוֹב, מַצִּיל אֶת הַצּאן מִן הַזְּאֵבִים וּמִן הָאֲרָיוֹת - כָּךְ הַמַּנְהִיג לְיִשְׂרָאֵל, אִם הוּא טוֹב, מַצִּילָם מִן הָעַכּוּ\"ם, וּמִדִּין שֶׁל מַטָּה, וּמִדִּין שֶׁל מַעְלָה, וּמַדְרִיכָם לְחַיֵּי הָעוֹלָם הַבָּא. כָּךְ מֹשֶׁה, רוֹעֶה נֶאֱמָן הָיָה, וְרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁכְּדַאי הוּא לִרְעוֹת אֶת יִשְׂרָאֵל בְּאוֹתוֹ הַדִּין מַמָּשׁ, שֶׁהָיָה רוֹעֶה אֶת הַצּאן לַכְּשָׂבִים כְּפִי הָרָאוּי לָהֶם, וְהַנְּקֵבוֹת כְּפִי הָרָאוּי לָהֶם.</p>\n<p>וּלְפִיכָךָ כָּתוּב וּמֹשֶׁה הָיָה רֹעֶה אֶת צֹאן יִתְרוֹ חֹתְנוֹ, וְלֹא שֶׁלּוֹ, שֶׁאָמַר רַבִּי יוֹסֵי, וְכִי מִי שֶּׁנָּתַן אֶת צִפּוֹרָה בִּתּוֹ לְמֹשֶׁה, לֹא נָתַן לוֹ צֹאן וּבָקָר? וַהֲלֹא יִתְרוֹ עָשִׁיר הָיָה? אֶלָּא מֹשֶׁה לֹא הָיָה רוֹעֶה אֶת צֹאנוֹ, כְּדֵי שֶׁלֹּא יֹאמְרוּ: בִּשְׁבִיל שֶׁהָיָה צֹאנוֹ עִמּוֹ, הָיָה רוֹעֶה אוֹתָם בְּטוֹב. וְלָכֵן כָּתוּב אֶת צֹאן יִתְרוֹ חֹתְנוֹ, וְלֹא אֶת שֶׁלּוֹ. כֹּהֵן מִדְיָן - רַבִּי תַּנְחוּם אָמַר, אַף עַל גַּב שֶׁהָיָה עוֹבֵד כּוֹכָבִים וּמַזָּלוֹת, בִּשְׁבִיל שֶׁעָשָׂה עִמּוֹ חֶסֶד הָיָה רוֹעֶה צֹאנוֹ כַּדִּין וְכַשּׁוּרָה, בְּמִרְעֶה טוֹב שָׁמֵן וְדָשֵׁן.</p>\n<p>וַיִּנְהַג אֶת צֹאנוֹ אַחַר הַמִּדְבָּר. רַבִּי יוֹסֵי אָמַר, מֹשֶׁה, מִיּוֹם שֶׁנּוֹלַד, לֹא זָזָה מִמֶּנּוּ רוּחַ הַקֹּדֶשׁ. רָאָה בְּרוּחַ הַקֹּדֶשׁ שֶׁאוֹתוֹ מִדְבָּר הָיָה קָדוֹשׁ, וּמוּכָן לְקַבֵּל עֹל מַלְכוּת שָׁמַיִם עָלָיו. מֶה עָשָׂה? הִנְהִיג אֶת הַצֹּאן אַחַר הַמִּדְבָּר. רַבִּי יִצְחָק אָמַר, אַחַר הַמִּדְבָּר עַל כָּל פָּנִים, וְלֹא בַּמִּדְבָּר, שֶׁלֹּא רָצָה שֶׁיִּכָּנְסוּ בְתוֹכוֹ, אֶלָּא הִרְחִיקָם אַחַר הַמִּדְבָּר.</p>\n<p>וַיָּבֹא אֶת הַר הָאֱלֹהִים חֹרֵבָה, הוּא לְבַדּוֹ בְּלֹא הַצּאן. אָמַר רַבִּי יְהוּדָה, אֶבֶן זוֹ שֶׁמְּקַבֶּלֶת בַּרְזֶל, כְּשֶׁרוֹאָה אוֹתוֹ, (מחטא) מְדַלֶּגֶת עָלָיו. כָּךְ מֹשֶׁה וְהַר סִינַי, כְּשֶׁנִּרְאוּ זֶה עִם זֶה, דִּלֵּג עָלָיו. זֶהוּ שֶׁכָּתוּב וַיָּבא אֶל הַר הָאֱלֹהִים חֹרֵבָה.</p>\n<p>אָמַר רַבִּי אַבָּא, מוּכָנִים הָיוּ מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית זֶה עִם זֶה, וְאוֹתוֹ הַיּוֹם נִתְרַגֵּשׁ הָהָר לְמוּל מֹשֶׁה. וְכֵיוָן שֶׁרָאָהוּ שֶׁנִּכְנַס לְתוֹכוֹ וְדִלֵּג בּוֹ, עָמַד הָהָר. מְלַמֵּד שֶׁשְּׂמֵחִים הָיוּ זֶה עִם זֶה.</p>\n<p>אָמַר רַבִּי יַנַּאי, יוֹדֵעַ הָיָה מֹשֶׁה שֶׁאוֹתוֹ הַר, הַר הָאֱלֹהִים הוּא, שֶׁכָּתוּב וַיָּבא אֶל הַר הָאֱלֹהִים. שֶׁשָּׁנִינוּ, מָה רָאָה מֹשֶׁה בְּאוֹתוֹ הַר? רָאָה עוֹפוֹת שֶׁהָיוּ פוֹרְחִים וּפוֹרְשִׂים כַּנְפֵיהֶם, וְלֹא הָיוּ נִכְנָסִים בּוֹ.</p>\n<p>רַבִּי יִצְחָק (אמר רבי יצחק) אוֹמֵר, רָאָה הָעוֹפוֹת פּוֹרְחִים וְטָסִים מִשָּׁם, וְנוֹפְלִים לְרַגְלָיו שֶׁל מֹשֶׁה. מִיָּד הִרְגִּישׁ בָּעִנְיָן, וְהֶעֱמִיד אֶת הַצּאן אַחַר הַמִּדְבָּר, וְהוּא נִכְנַס לְבַדּוֹ.</p>\n<p>וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. רַבִּי תַּנְחוּם אוֹמֵר, שְׁעַת הַמִּנְחָה הָיְתָה, שֶׁמִּדַּת הַדִּין שׁוֹלֶטֶת בּוֹ. רַבִּי יוֹחָנָן אָמַר, וַהֲרֵי כָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ. מִדַּת חֶסֶד אָמַר, וְלֹא מִדַּת הַדִּין. אָמַר רַבִּי יִצְחָק, מִשֶּׁיּוֹצֵא הָאוֹר עַד שֶׁנּוֹטֶה לָרֶדֶת נִקְרָא יוֹם, וְהוּא מִדַּת חֶסֶד. מִשֶּׁנּוֹטֶה לָרֶדֶת נִקְרָא עֶרֶב, וְהוּא מִדַּת הַדִּין. וְהַיְנוּ שֶׁכָּתוּב (בראשית א) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם.</p>\n<p>אָמַר רַבִּי יוֹחָנָן, שְׁעַת הַמִּנְחָה הוּא מִשֵּׁשׁ שָׁעוֹת וּלְמַטָּה. שֶׁלָּמַדְנוּ, רַבִּי יִצְחָק אוֹמֵר, מַהוּ שֶׁכָּתוּב (שמות טז) בֵּין הָעַרְבַּיִם תֹּאכְלוּ בָשָׂר וּבַבֹּקֶר תִּשְׂבְּעוּ לָחֶם? בֵּין הָעַרְבַּיִם, שֶׁהִיא שְׁעַת הַדִּין, תֹּאכְלוּ בָשָׂר. וְכָתוּב הַבָּשָׂר עוֹדֶנּוּ בֵּין שִׁנֵּיהֶם וְאַף ה' חָרָה בָעָם, מִשּׁוּם שֶׁבֵּין הָעַרְבַּיִם, דִּין הַמַּלְכוּת שׁוֹלֵט. וּבַבֹּקֶר תִּשְׂבְּעוּ לָחֶם, מִשּׁוּם שֶׁאוֹתָהּ שָׁעָה נִקְרֵאת חֶסֶד, וְכָתוּב (תהלים נב) חֶסֶד אֵל כָּל הַיּוֹם. וְכָתוּב (בראשית א) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם. שֶׁהוּא מֵהַבֹּקֶר.</p>\n<p>רַבִּי תַּנְחוּם אוֹמֵר, זֶה אָדם וְזֶה לָבָן. אָדם - בֵּין הָעַרְבַּיִם, שֶׁכָּתוּב (שמות טז) בֵּין הָעַרְבַּיִם תֹּאכְלוּ בָשָׂר. וְלָבָן בַּבֹּקֶר, שֶׁכָּתוּב וּבַבֹּקֶר תִּשְׂבְּעוּ לָחֶם. רַבִּי יִצְחָק אָמַר, כָּתוּב (שם יב) וְשָׁחֲטוּ אֹתוֹ כָּל קְהַל עֲדַת יִשְׂרָאֵל בֵּין הָעַרְבָּיִם וְגוֹ', שֶׁהִיא שָׁעָה לַעֲשׂוֹת דִּין. רַבִּי יְהוּדָה אָמַר, לָמַדְנוּ מִשְּׁנֵי כְבָשִׂים שֶׁבְּכָל יוֹם - הָאֶחָד מִתְקָרֵב כְּנֶגֶד מִדַּת הַחֶסֶד, וְהַשֵּׁנִי כְּנֶגֶד מִדַּת הַדִּין.</p>\n<p>וְאָמַר רַבִּי יְהוּדָה, מַהוּ שֶׁכָּתוּב (שמות כט) אֶת הַכֶּבֶשׂ הָאֶחָד תַּעֲשֶׂה בַבֹּקֶר, וְלֹא כָתוּב אֶת הַכֶּבֶשׂ הָרִאשׁוֹן? אֶלָּא אֶת הַכֶּבֶשׂ הָאֶחָד, מְיֻחָד, כְּנֶגֶד מִדַּת הַחֶסֶד. שֶׁבְּכָל מָקוֹם, שֵׁנִי לֹא נֶאֱמַר בּוֹ כִּי טוֹב.</p>\n<p>רַבִּי תַּנְחוּם אָמַר, לְפִיכָךְ יִצְחָק תִּקֵּן תְּפִלַּת הַמִּנְחָה, שֶׁהִיא כְּנֶגֶד מִדַּת הַדִּין. אָמַר רַבִּי יִצְחָק, מִכָּאן (ירמיה ו) אוֹי לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. כִּי פָנָה הַיּוֹם - זֶה מִדַּת הַחֶסֶד. כִּי יִנָּטוּ צִלְלֵי עָרֶב - שֶׁכְּבָר גָּבַר מִדַּת הַדִּין. אַבְרָהָם תִּקֵּן תְּפִלַּת שַׁחֲרִית כְּנֶגֶד מִדַּת הַחֶסֶד.</p>\n<p>שָׁנוּ רַבּוֹתֵינוּ, בְּאוֹתָהּ שָׁעָה שֶׁעָלָה מֹשֶׁה לְהַר סִינַי, מָה הַטַּעַם הִתְגַּלָּה לוֹ בְּשַׁלְהֲבוֹת אֵשׁ שֶׁהוּא דִּין? אָמַר רַבִּי יַעֲקֹב, (כעין) כָּעֵת הַשָּׁעָה הָיְתָה (השעה) גּוֹרֶמֶת. רַבִּי יוֹסֵי אָמַר, הַכֹּל לְגֶזַע אֶחָד מִשְׁתָּרֵשׁ. כָּתוּב וַיָּבֹא אֶל הַר הָאֱלֹהִים חֹרֵבָה, וְכָתוּב (דברים ט) וּבְחֹרֵב הִקְצַפְתֶּם אֶת ה'. וְכָתוּב וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. מִתּוֹךְ שֶׁהֵם עֲתִידִים לִהְיוֹת כַּסְּנֶה, כְּמוֹ זֶה שֶׁכָּתוּב (ישעיה לג) קוֹצִים כְּסוּחִים בָּאֵשׁ יִצַּתּוּ.</p>"],[9522011560,"<p>אָמַר רַבִּי יְהוּדָה, מִכָּאן לָמַדְנוּ רַחֲמָנוּתוֹ שֶׁל מָקוֹם עַל הָרְשָׁעִים, שֶׁכָּתוּב וְהִנֵּה הַסְּנֶה בּעֵר בָּאֵשׁ - לַעֲשׂוֹת בָּהֶם דִּין בָּרְשָׁעִים. וְהַסְּנֶה אֵינֶנּוּ אֻכָּל - (לעשות) אֵין בָּהֶם כְּלָיָה. בֹּעֵר בָּאֵשׁ - עַל כָּל פָּנִים, רֶמֶז לָאֵשׁ שֶׁל גֵּיהִנֹּם. אֲבָל הַסְּנֶה אֵינֶנּוּ אֻכָּל - לִהְיוֹת בָּהֶם כְּלָיָה.</p>\n<p>דָּבָר אַחֵר וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ, מָה הַטַּעַם לְמֹשֶׁה בְּלַבַּת אֵשׁ וְלִשְׁאָר הַנְּבִיאִים לֹא? אָמַר רַבִּי יְהוּדָה, אֵין מֹשֶׁה כִּשְׁאָר הַנְּבִיאִים. שֶׁשָּׁנִינוּ, מִי שֶׁקָּרֵב לָאֵשׁ, בָּהּ נִשְׂרָף, וּמשֶׁה קָרַב לָאֵשׁ וְלֹא נִשְׂרַף, שֶׁכָּתוּב (שמות כ) וּמֹשֶׁה נִגַּשׁ אֶל הָעֲרָפֶל אֲשֶׁר שָׁם הָאֱלֹהִים, וְכָתוּב וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה.</p>\n<p>רַבִּי אַבָּא אָמַר, זֶה שֶׁל מֹשֶׁה, יֵשׁ לְהִסְתַּכֵּל בּוֹ בְּחָכְמָה עֶלְיוֹנָה עַל מַה כָּתוּב כִּי מִן הַמַּיִם מְשִׁיתִהוּ. מִי שֶׁנִּמְשַׁךְ מִן הַמַּיִם, (דין עליון) לֹא פוֹחֵד מֵאֵשׁ. שֶׁשָּׁנִינוּ, אָמַר רַבִּי יְהוּדָה, מִמָּקוֹם שֶׁנִּגְזַר מֹשֶׁה לֹא נִגְזַר אִישׁ אַחֵר. אָמַר רַבִּי יוֹחָנָן, בְּעֶשֶׂר דְּרָגוֹת נִתְקַן, שֶׁכָּתוּב (במדבר יב) בְּכָל בֵּיתִי נֶאֱמָן הוּא. וְלֹא נֶאֱמַן בֵּיתִי. אַשְׁרֵי חֶלְקוֹ שֶׁל הָאִישׁ שֶׁאֲדוֹנוֹ מֵעִיד עָלָיו כָּךְ.</p>\n<p>אָמַר רַב דִּימִי, וַהֲרֵי כָּתוּב (דברים לד) וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה. וְאָמַר רַבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, בְּיִשְׂרָאֵל לֹא קָם, אֲבָל בְּאֻמּוֹת הָעוֹלָם קָם, וּמִיהוּ? בִּלְעָם. אָמַר לוֹ, וַדַּאי יָפֶה אָמַרְתָּ. שָׁתַק. כְּשֶׁבָּא רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, בָּאוּ וְשָׁאֲלוּ לְפָנָיו דָּבָר זֶה.</p>\n<p>פָּתַח וְאָמַר, אֶשְׁכּוֹל שֶׁל זֶפֶת, יִתְעָרֵב בַּאֲפַרְסְמוֹן טוֹב? חַס וְשָׁלוֹם! אֶלָּא וַדַּאי כָּךְ הוּא, בְּאֻמּוֹת הָעוֹלָם קָם, וּמִיהוּ? בִּלְעָם. מֹשֶׁה מַעֲשָׂיו לְמַעְלָה, וּבִלְעָם לְמַטָּה. מֹשֶׁה הִשְׁתַּמֵּשׁ בְּכֶתֶר הַמֶּלֶךְ הָעֶלְיוֹן שֶׁלְּמַעְלָה, וּבִלְעָם הִשְׁתַּמֵּשׁ בִּכְתָרִים תַּחְתּוֹנִים לֹא קְדוֹשִׁים לְמַטָּה. וּבְאוֹתָהּ צוּרָה מַמָּשׁ כָּתוּב, (יהושע יג) וְאֶת בִּלְעָם בֶּן בְּעוֹר הַקּוֹסֵם הָרְגוּ בְנֵי יִשְׂרָאֵל בַּחֶרֶב. וְאִם עוֹלֶה עַל דַּעְתְּךְ יוֹתֵר, לֵךְ שְׁאַל אֶת אֲתוֹנוֹ. בָּא רַבִּי יוֹסֵי וְנָשַׁק יָדָיו. אָמַר, הֲרֵי הַחֶמְדָּה (היין) שֶׁבְּלִבִּי יָצָא הַחוּצָה.</p>\n<p>שֶׁכָּךָ מַשְׁמָע, שֶׁיֵּשׁ עֶלְיוֹנִים וְתַחְתּוֹנִים, יָמִין וּשְׂמֹאל, רַחֲמִים וְדִין, יִשְׂרָאֵל וְעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. יִשְׂרָאֵל מִשְׁתַּמְּשִׁים בִּכְתָרִים עֶלְיוֹנִים קְדוֹשִׁים - עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת בִּכְתָרִים תַּחְתּוֹנִים לֹא קְדוֹשִׁים. אֵלֶּה שֶׁל יָמִין, וְאֵלֶּה שֶׁל שְׂמֹאל. וְעַל כָּל פָּנִים נִפְרָדִים נְבִיאִים עֶלְיוֹנִים מִנְּבִיאִים תַּחְתּוֹנִים, נְבִיאֵי קֹדֶשׁ מִנְּבִיאִים שֶׁלֹּא מִקֹּדֶשׁ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כְּמוֹ שֶׁהָיָה מֹשֶׁה נִבְדָּל מִכָּל הַנְּבִיאִים בִּנְבוּאָה קְדוֹשָׁה עֶלְיוֹנָה, כָּךְ הָיָה בִּלְעָם נִבְדָּל מִשְּׁאָר הַנְּבִיאִים וּמְכַשְּׁפִים בִּנְבוּאָה לֹא קְדוֹשָׁה לְמַטָּה. וְעַל כָּל פָּנִים מֹשֶׁה הָיָה לְמַעְלָה, וּבִלְעָם לְמַטָּה, וְכַמָּה דְרָגוֹת וּדְרָגוֹת מַפְרִידוֹת בֵּינֵיהֶם.</p>\n<p>אָמַר רַבִּי יוֹחָנָן אָמַר רַבִּי יִצְחָק, מֹשֶׁה הָיָה מְהַרְהֵר וְאוֹמֵר, שֶׁמָּא חַס וְשָׁלוֹם יִשְׂרָאֵל יִכְלוּ בָּעֲבוֹדָה הַקָּשָׁה הַזּוֹ, זֶהוּ שֶׁכָּתוּב וַיַּרְא בְּסִבְלוֹתָם, לְפִיכָךְ - וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ וְגוֹ', וַיַּרְא וְהִנֵּה הַסְּנֶה בֹּעֵר בָּאֵשׁ וְגוֹ'. כְּלוֹמַר, מְשֻׁעְבָּדִים הֵם בַּעֲבוֹדָה קָשָׁה, אֲבָל וְהַסְּנֶה אֵינֶנּוּ אֻכָּל. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִבְדִּילָם מִכָּל הָעַמִּים וְקָרָא לָהֶם בָּנִים, שֶׁכָּתוּב (דברים יז) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם.</p>"],[9522011561,"<p>וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה וַיֹּאמֶר אֵלָיו אֲנִי ה' וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי וְגוֹ'. רַבִּי אַבָּא פָּתַח, (ישעיה כו) בִּטְחוּ בַה' עֲדֵי עַד כִּי בְּיָהּ ה' צוּר עוֹלָמִים. בִּטְחוּ בַּה' - כָּל בְּנֵי הָעוֹלָם צְרִיכִים לְהִתְחַזֵּק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא וְלִהְיוֹת בִּטְחוֹנָם בּוֹ.</p>\n<p>אִם כָּךְ, מַהוּ עֲדֵי עַד? אֶלָּא בִּשְׁבִיל שֶׁיִּהְיֶה הַתֹּקֶף שֶׁל הָאָדָם בְּמָקוֹם שֶׁהוּא קִיּוּם וְקִשּׁוּר שֶׁל הַכֹּל, וְנִקְרָא עַד, וַהֲרֵי פֵּרְשׁוּהָ, כְּמוֹ שֶׁנֶּאֱמַר בַּבֹּקֶר יֹאכַל עַד. וְעַד, זֶה מָקוֹם שֶׁאָחוּז לְכָל הַצְּדָדִים, לְצַד זֶה וּלְצַד זֶה, לְהִתְקַיֵּם וְלִקְשֹׁר קֶשֶׁר שֶׁלֹּא יָזוּז.</p>\n<p>וְהָ\"עַד\" הַזֶּה תְּשׁוּקַת הַכֹּל בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מט) עַד תַּאֲוַת גִּבְעֹת עוֹלָם. מִי הֵם גִּבְעֹת עוֹלָם? אֵלֶּה הֵם שְׁתֵּי הָאִמָּהוֹת הַנְּקֵבוֹת, יוֹבֵל וּשְׁמִטָּה, שֶׁנִּקְרָאוֹת גִּבְעֹת עוֹלָם. עוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קו) מִן הָעוֹלָם וְעַד הָעוֹלָם. (יובל ושמטה, כל אחד מהם נקרא עולם, והם נקראים גבעת עולם).</p>\n<p>וּתְשׁוּקָתָם בָּעַד הַזֶּה, שֶׁהוּא קִיּוּם שֶׁל כָּל הַצְּדָדִים. (מה הטעם) תְּשׁוּקַת הַיּוֹבֵל אֶל עַד, לְעַטֵּר אוֹתוֹ וּלְהַשְׁפִּיעַ עָלָיו בְּרָכוֹת, וּלְהָרִיק עָלָיו מַעְיָנוֹת מְתוּקִים. זֶהוּ שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶנָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ. תְּשׁוּקַת הַשְּׁמִטָּה לְהִתְבָּרֵךְ מִמֶּנּוּ וְלִהְיוֹת מְאִירָה מִמֶּנּוּ. וַדַּאי שֶׁעַד זֶה הוּא תַּאֲוַת גִּבְעֹת עוֹלָם.</p>\n<p>מִשּׁוּם כָּךְ, בִּטְחוּ בַה' עֲדֵי עַד, שֶׁהֲרֵי מִשָּׁם וּלְמַעְלָה מָקוֹם טָמִיר (הוא) וְגָנוּז הוּא, שֶׁלֹּא יָכוֹל לְהִתְדַּבֵּק. מָקוֹם הוּא שֶׁמִּמֶּנּוּ יָצְאוּ וְהִצְטַיְּרוּ הָעוֹלָמוֹת, זֶהוּ שֶׁכָּתוּב כִּי בְיָהּ ה' צוּר עוֹלָמִים. וְהוּא מָקוֹם גָּנוּז וְסָתוּם, וְעַל זֶה בִּטְחוּ בַה' עֲדֵי עַד. עַד כָּאן יֵשׁ רְשׁוּת לְכָל אָדָם לְהִסְתַּכֵּל בּוֹ, מִכָּאן וָהָלְאָה אֵין רְשׁוּת לְאָדָם לְהִסְתַּכֵּל בּוֹ, שֶׁהֲרֵי הוּא גָּנוּז מֵהַכֹּל, וּמִי הוּא יָהּ? יְהֹוָה. שֶׁמִּשָּׁם הִצְטַיְּרוּ כָּל הָעוֹלָמוֹת, וְאֵין מִי שֶׁעוֹמֵד עַל אוֹתוֹ מָקוֹם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, הַכָּתוּב מוֹכִיחַ עָלָיו, שֶׁכָּתוּב (דברים ד) כִּי שְׁאַל נָא לְיָמִים רִאשׁוֹנִים וְגוֹ'. עַד כָּאן יֵשׁ רְשׁוּת לְאָדָם לְהִסְתַּכֵּל, מִכָּאן וּלְהָלְאָה אֵין מִי שֶׁיָּכוֹל לַעֲמֹד עָלָיו.</p>\n<p>דָּבָר אַחֵר בִּטְחוּ בַה' עֲדֵי עַד - כָּל יְמֵי הָאָדָם צָרִיךְ לְהִתְחַזֵּק בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, (שכך אמר דוד, (תהלים כה) אלהי בך בטחתי אל אבושה אל יעלצו אויבי לי) וּמִי שֶׁשָּׂם בּוֹ בִּטְחוֹנוֹ וְתָקְפּוֹ כָּרָאוּי, לֹא יְכוֹלִים לְהָרַע לוֹ כָּל בְּנֵי הָעוֹלָם. (שכך אמר דוד, (תהלים כה) אלהי בך בטחתי אל אבושה אל יעלצו אויבי לי) שֶׁכָּל מִי שֶׁשָּׂם תָּקְפּוֹ בַּשֵּׁם הַקָּדוֹשׁ, מִתְקַיֵּם בָּעוֹלָם.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁהָעוֹלָם מִתְקַיֵּם בִּשְׁמוֹ הַקָּדוֹשׁ. זֶהוּ שֶׁכָּתוּב כִּי בְּיָהּ ה' צוּר עוֹלָמִים, צַיַּר הָעוֹלָמִים. שֶׁהֲרֵי בִּשְׁתֵּי אוֹתִיּוֹת נִבְרְאוּ הָעוֹלָמוֹת, הָעוֹלָם הַזֶּה וְהָעוֹלָם הַבָּא. הָעוֹלָם הַזֶּה נִבְרָא בְּדִין, וְעַל דִּין עוֹמֵד, זֶהוּ שֶׁכָּתוּב בְּרֵאשִׁית בָּרָא אֱלֹהִים. מָה הַטַּעַם? כְּדֵי שֶׁיִּנְהֲגוּ בְּנֵי אָדָם בְּדִין, וְלֹא יֵצְאוּ מֵהַדֶּרֶךְ הַחוּצָה.</p>\n<p>בֹּא רְאֵה, כָּתוּב וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה, גְּזֵרַת הַדִּין שֶׁעוֹמֶדֶת עָלָיו. מַה כָּתוּב לְמַעְלָה? (שמות ה) וַיָּשָׁב מֹשֶׁה אֶל ה' וַיֹּאמַר אֲדנָ\"י, בְּאָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד. רָאָה תָקְפּוֹ שֶׁל מֹשֶׁה בְּרֵאשִׁית נְבוּאָתוֹ, לֹא נָחָה רוּחוֹ בַּמָּקוֹם הַזֶּה, אָמַר, אֲדנָי לָמָה הֲרֵעֹתָה לָעָם הַזֶּה וְגוֹ', וּמֵאָז בָּאתִי אֶל פַּרְעֹה לְדַבֵּר בִּשְׁמֶךְ הֵרַע לָעָם הַזֶּה וְהַצֵּל לֹא הִצַּלְתָּ אֶת עַמֶּךְ. מִי הוּא שֶׁיֹּאמַר כָּךְ? אֶלָּא מֹשֶׁה, שֶׁיָּדַע שֶׁדַּרְגָּה אַחֶרֶת עֶלְיוֹנָה מְעֻתֶּדֶת לוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, בְּרֵאשִׁית שֶׁנִּתַּן לוֹ הַבַּיִת, צִוָּה אוֹתָהּ כְּאִישׁ שֶׁמְּצַוֶּה אֶת בֵּיתוֹ וְאוֹמֵר כָּל מַה שֶּׁרוֹצֶה לְלֹא פַּחַד. אַף כָּךְ מֹשֶׁה לְבֵיתוֹ אָמַר וְלֹא פָחַד.</p>\n<p>דָּבָר אַחֵר וַיְדַבֵּר אֱלֹהִים - גְּזֵרַת הַדִּין. (משום כך) וַיֹּאמֶר אֵלָיו אֲנִי ה' - דַּרְגָּה אַחֶרֶת שֶׁל רַחֲמִים. וְכָאן נִקְשָׁר הַכֹּל כְּאֶחָד, דִּין וְרַחֲמִים. זֶהוּ שֶׁכָּתוּב וַיֹּאמֶר אֵלָיו אֲנִי ה'. אָמַר רַבִּי שִׁמְעוֹן (רבי יוסי), אִם כָּתוּב וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה אֲנִי ה', הָיִיתִי אוֹמֵר כָּךְ. אֶלָּא לֹא כָתוּב, אֶלָּא וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה בַּהַתְחָלָה, וְאַחַר כָּךְ וַיֹּאמֶר אֵלָיו אֲנִי ה', שֶׁמַּשְׁמָע דַּרְגָּה אַחַר דַּרְגָּה.</p>\n<p>וְאָמַר רַבִּי יוֹסֵי, מֹשֶׁה אִלְמָלֵא שֶׁהָיָה בַּעַל הַבַּיִת, אִישׁ הָאֱלֹהִים, הָיָה נֶעֱנָשׁ עַל מַה שֶּׁאָמַר, אֲבָל מִשּׁוּם זֶה לֹא נֶעֱנַשׁ. לְאָדָם שֶׁנָּפְלָה לוֹ קְטָטָה בְּאִשְׁתּוֹ, וְאָמַר לָהּ דְּבָרִים. הִיא הִתְחִילָה לְהִתְרַעֵם. כֵּיוָן שֶׁהִתְחִילָה דָּבָר, הָיָה שָׁם הַמֶּלֶךְ, נָטַל הַמֶּלֶךְ אֶת הַדִּבּוּר, וְהִיא שָׁתְקָה וּפָסְקָה לְדַבֵּר. אָמַר לוֹ הַמֶּלֶךְ: וְכִי לֹא יָדַעְתָּ שֶׁאֲנִי הַמֶּלֶךְ וּלְפָנַי דִּבַּרְתָּ דְּבָרִים אֵלּוּ? כִּבְיָכוֹל אַף כָּךְ מֹשֶׁה, וַיָּשָׁב מֹשֶׁה אֶל ה' וַיֹּאמַר אֲדנָי לָמָה הֲרֵעֹתָה וְגוֹ'. מִיָּד - וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה, הִתְחִיל לְהִתְרַעֵם. מִיָּד נָטַל הַמֶּלֶךְ הַדִּבּוּר וַיֹּאמֶר אֵלָיו אֲנִי ה', וְלֹא יָדַעְתָּ שֶׁאֲנִי הוּא הַמֶּלֶךְ וּלְפָנַי דִּבַּרְתָּ דְּבָרִים אֵלֶּה?!</p>\n<p>וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי. לָמָּה שׁוֹנֶה הַשֵּׁם כָּאן מֵאֵלֶּה שֶׁלְּמַעְלָה? אֶלָּא, לְמֶלֶךְ שֶׁהָיְתָה לוֹ בַת שֶׁלֹּא נִשְּׂאָה, וְהָיָה לוֹ אָהוּב. כְּשֶׁרָצָה הַמֶּלֶךְ לְדַבֵּר עִם אוֹתוֹ אָהוּב, שׁוֹלֵחַ אֶת בִּתּוֹ לְדַבֵּר עִמּוֹ, וְהָיָה הַמֶּלֶךְ עַל יַד בִּתּוֹ מְדַבֵּר עִמּוֹ. בָּא זְמַן בִּתּוֹ לְהִנָּשֵׂא. אוֹתוֹ יוֹם שֶׁנִּשְּׂאָה אָמַר הַמֶּלֶךְ: קִרְאוּ אֶת הַבַּת מַלְכָּה גְּבִירָה. וְאָמַר לָהּ: עַד כָּאן דִּבַּרְתִּי עַל יָדֵךְ עִם מִי שֶׁדִּבַּרְתִּי, מִכָּאן וָהָלְאָה אֲנִי אוֹמַר לְבַעְלֵךְ, וְהוּא יֹאמַר לְמִי שֶׁצָּרִיךְ. לְיָמִים אָמַר לָהּ בַּעְלָהּ דְּבָרִים לִפְנֵי הַמֶּלֶךְ, וְעַד שֶׁהִיא הִתְחִילָה לְדַבֵּר, נָטַל הַמֶּלֶךְ אֶת הַדָּבָר וְאָמַר לוֹ: וְכִי אֵינִי הַמֶּלֶךְ?! שֶׁעַד הַיּוֹם הַזֶּה לֹא דִבֵּר אִישׁ עִמִּי אֶלָּא עַל יְדֵי בִּתִּי, (עד שלא נשאה) וַאֲנִי נָתַתִּי לְךְ אֶת בִּתִּי וְדִבַּרְתִּי עִמְּךְ בְּגָלוּי מַה שֶּׁלֹּא עָשִׂיתִי לְאַחֵר.</p>\n<p>כָּךָ, וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי, כְּשֶׁהִיא בְּבֵיתִי טֶרֶם שֶׁנִּשְּׂאָה, וְלֹא דִבְּרוּ עִמִּי פָּנִים בְּפָנִים כְּמוֹ שֶׁעָשִׂיתִי לְךְ, וְאַתָּה בְּרֵאשִׁית דְּבָרְךְ דִּבַּרְתָּ לְבִתִּי לְפָנַי דְּבָרִים אֵלּוּ? אֶלָּא מִשּׁוּם כָּךְ וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי וּשְׁמִי ה' לֹא נוֹדַעְתִּי לָהֶם, לְדַבֵּר עִמָּם בְּדַרְגָּה זוֹ שֶׁדִּבַּרְתִּי בָּהּ עִמְּךְ.</p>\n<p>רַבִּי יוֹסֵי (רבי ייסא) פָּתַח, (תהלים כד) לְדָוִד מִזְמוֹר לַה' הָאָרֶץ וּמְלוֹאָהּ תֵּבֵל וְיֹשְׁבֵי בָהּ. הָאָרֶץ - זוֹ הָאָרֶץ הַקְּדוֹשָׁה שֶׁל יִשְׂרָאֵל שֶׁהִיא עוֹמֶדֶת לְהִשָּׁקוֹת מִמֶּנּוּ וּלְהִתְבָּרֵךְ מִמֶּנּוּ בָּרִאשׁוֹנָה, וְאַחַר כָּךְ מִמֶּנָּה נִשְׁקָה כָּל הָעוֹלָם. תֵּבֵל וְיֹשְׁבֵי בָהּ - אֵלּוּ שְׁאָר הָאֲרָצוֹת שֶׁשּׁוֹתוֹת מִמֶּנָּה. מִנַּיִן לָנוּ? שֶׁכָּתוּב (תהלים ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק.</p>\n<p>כִּי הוּא עַל יַמִּים יְסָדָהּ - אֵלּוּ שִׁבְעָה עַמּוּדִים שֶׁהָאָרֶץ נִסְמֶכֶת עֲלֵיהֶם, וְהֵם שִׁבְעָה יַמִּים, וְיָם כִּנֶּרֶת שׁוֹלֵט עֲלֵיהֶם. אָמַר רַבִּי יְהוּדָה, אַל תֹּאמַר שֶׁשּׁוֹלֶטֶת עֲלֵיהֶם, אֶלָּא שֶׁמִּתְמַלֵּאת מֵהֶם. וְעַל נְהָרוֹת יְכוֹנְנֶהָ, מִי אֵלּוּ הַנְּהָרוֹת? אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר (תהלים צג) נָשְׂאוּ נְהָרוֹת קוֹלָם יִשְׂאוּ נְהָרוֹת דָּכְיָם, אוֹתָם נְהָרוֹת כְּמוֹ שֶׁנֶּאֱמַר (בראשית ד) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן, וּמִשּׁוּם כָּךְ וְעַל נְהָרוֹת יְכוֹנְנֶהָ.</p>\n<p>בֹּא רְאֵה, אֶרֶץ זוֹ נִקְרֵאת אֶרֶץ יִשְׂרָאֵל. יַעֲקֹב שֶׁהוּא יִשְׂרָאֵל לָמָּה לֹא שׁוֹלֵט עַל זֶה כְּמוֹ מֹשֶׁה, שֶׁהֲרֵי כָּתוּב וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי וְלֹא יוֹתֵר?</p>\n<p>אֶלָּא יַעֲקֹב, הֲרֵי בֵּאַרְנוּ, נָטַל הַבַּיִת שֶׁלְּמַטָּה, וְנֶעֱזַב מִמֶּנּוּ הַבַּיִת שֶׁלְּמַעְלָה, וְעִם הַבַּיִת שֶׁלְּמַטָּה הִתְקִין אֶת הַבַּיִת שֶׁלְּמַעְלָה בִּשְׁנֵים עָשָׂר שְׁבָטִים וּבְשִׁבְעִים עֲנָפִים, וַהֲרֵי פֵּרְשׁוּהָ. מֹשֶׁה נָטַל אֶת הַבַּיִת שֶׁלְּמַעְלָה, וְעָזַב אֶת הַבַּיִת שֶׁלְּמַטָּה, וְלָכֵן כָּתוּב בְּיַעֲקֹב בְּאֵל שַׁדַּי. בְּאֵל שַׁדַּי דִּבֵּר עִם הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא יוֹתֵר. וּשְׁמִי ה' לֹא נוֹדַעְתִּי לָהֶם, לְדַבֵּר עִמָּם בְּדַרְגָּה זוֹ שֶׁהִיא עֶלְיוֹנָה.</p>\n<p>וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב. אָמַר רַבִּי חִיָּיא, בְּחִיר הָאָבוֹת הָיָה יַעֲקֹב, שֶׁהוּא שְׁלֵמוּת הַכֹּל. בְּכֻלָּם כָּתוּב אֶל אַבְרָהָם, אֶל יִצְחָק, וּבוֹ הִתּוֹסְפָה אוֹת אַחַת, שֶׁכָּתוּב וְאֶל יַעֲקֹב. הִתּוֹסְפָה בּוֹ ו', לְהַרְאוֹת שֶׁהוּא שָׁלֵם יוֹתֵר מִכֻּלָּם, וְעִם כָּל זֶה לֹא זָכָה לְהִשְׁתַּמֵּשׁ בּוֹ כְּמֹשֶׁה.</p>\n<p>וְגַם הֲקִמֹתִי אֶת בְּרִיתִי אִתָּם לָתֵת לָהֶם אֶת אֶרֶץ כְּנָעַן, מִשּׁוּם שֶׁנִּמּוֹלוּ. שֶׁכָּל מִי שֶׁנִּמּוֹל, יוֹרֵשׁ אֶת הָאָרֶץ, שֶׁהֲרֵי לֹא יוֹרֵשׁ אֶרֶץ אֶלָּא צַדִּיק, וְכָל מִי שֶׁנִּמּוֹל נִקְרָא צַדִּיק, שֶׁכָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ. כָּל מִי שֶׁנִּמּוֹל וְשׁוֹמֵר אוֹת הַבְּרִית הַ את, נִקְרָא צַדִּיק. בֹּא רְאֵה מִיּוֹסֵף, שֶׁכָּל יָמָיו לֹא נִקְרָא צַדִּיק עַד שֶׁשָּׁמַר אוֹתָהּ בְּרִית, אוֹת בְּרִית הַקֹּדֶשׁ. כֵּיוָן שֶׁשָּׁמַר אוֹתוֹ, נִקְרָא צַדִּיק, יוֹסֵף הַצַּדִּיק.</p>"],[9522011562,"<p>רַבִּי שִׁמְעוֹן הָיָה יוֹשֵׁב יוֹם אֶחָד, וְרַבִּי אֶלְעָזָר בְּנוֹ (עמו), וְרַבִּי אַבָּא עִמּוֹ. אָמַר רַבִּי אֶלְעָזָר, פָּסוּק זֶה שֶׁכָּתוּב וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב וְגוֹ', מַהוּ וָאֵרָא? וַאֲדַבֵּר הָיָה צָרִיךְ (לכתב) ! אָמַר לוֹ, אֶלְעָזָר בְּנִי, זֶהוּ סוֹד עֶלְיוֹן.</p>\n<p>בֹּא רְאֵה, יֵשׁ גְּוָנִים שֶׁנִּרְאִים וְיֵשׁ גְּוָנִים שֶׁלֹּא נִרְאִים. וְאֵלּוּ וָאֵלּוּ הֵם סוֹד עֶלְיוֹן שֶׁל הָאֱמוּנָה, וּבְנֵי אָדָם לֹא יוֹדְעִים אוֹתוֹ וְלֹא מִסְתַּכְּלִים בּוֹ. וְאֵלֶּה שֶׁנִּרְאִים לֹא זָכָה בָּהֶם אָדָם, עַד שֶׁבָּאוּ הָאָבוֹת וְעָמְדוּ עֲלֵיהֶם, וְעַל זֶה כָּתוּב וָאֵרָא, שֶׁרָאוּ אוֹתָם גְּוָנִים שֶׁהִ תְגַּלּוּ.</p>\n<p>וּמָה הַגְּוָנִים שֶׁהִתְגַּלּוּ? אוֹתָם שֶׁל אֵל שַׁדַּי, שֶׁהֵם גְּוָנִים שֶׁל מַרְאֶה עֶלְיוֹן (מראה של גונים עליונים), וְאֵלּוּ נִרְאִים. וְהַגְּוָנִים שֶׁלְּמַעְלָה נִסְתָּרִים שֶׁלֹּא נִרְאִים, לֹא עָמַד אִישׁ עֲלֵיהֶם פְּרָט לְמֹשֶׁה. וְעַל זֶה כָּתוּב וּשְׁמִי ה' לֹא נוֹדַעְתִּי לָהֶם, לֹא הִתְגַּלֵּיתִי לָהֶם בִּגְוָנִים עֶלְיוֹנִים. וְאִם תֹּאמַר שֶׁהָאָבוֹת לֹא הִכִּירוּ אוֹתָם - אֶלָּא הֵם הִכִּירוּ אוֹתָם מִתּוֹךְ אֵלּוּ שֶׁהִתְגַּלּוּ.</p>\n<p>כָּתוּב (דניאל יב) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזהַר הָרָקִיעַ וּמַצְדִּיקֵי הָרַבִּים כַּכּוֹכָבִים לְעוֹלָם וָעֶד. וְהַמַּשְׂכִּלִים יַזְהִרוּ, מִי הֵם הַמַּשְׂכִּילִים? אֶלָּא זֶהוּ אוֹתוֹ חָכָם שֶׁיִּסְתַּכֵּל עַל דְּבָרִים מֵעַצְמוֹ שֶׁלֹּא יְכוֹלִים בְּנֵי אָדָם לְדַבֵּר בַּפֶּה, וּלְאֵלֶּה קוֹרְאִים מַשְׂכִּילִים. יַזְהִרוּ כְּזֹהַר הָרָקִיעַ. מִי (הזהר) הוּא הָרָקִיעַ? זֶהוּ הָרָקִיעַ שֶׁל מֹשֶׁה, שֶׁעוֹמֶדֶת בָּאֶמְצַע, וְהַזֹּהַר שֶׁלּוֹ הוּא נִסְתָּר וְלֹא הִתְגַּלָּה מֵהַגָּוֶן שֶׁלּוֹ, עוֹמֵד עַל אוֹתוֹ רָקִיעַ שֶׁלֹּא מֵאִיר שֶׁנִּרְאִים בּוֹ הַגְּוָנִים, וְאוֹתָם גְּוָנִים, אַף עַל פִּי שֶׁנִּרְאִים בּוֹ, לֹא זוֹהֲרִים כְּמוֹ זהַר, מִשּׁוּם שֶׁהֵם גְּוָנִים סְתוּמִים.</p>\n<p>בֹּא רְאֵה, אַרְבָּעָה אוֹרוֹת הֵם, שְׁלֹשָׁה מֵהֶם נִסְתָּרִים, וְאֶחָד שֶׁהִתְגַּלָּה. אוֹר שֶׁמֵּאִיר. אוֹר שֶׁזּוֹהֵר. (והם) וְהוּא מֵאִיר כְּזהַר הַשָּׁמַיִם בְּטֹהַר. אוֹר שֶׁל אַרְגָּמָן, שֶׁנּוֹטֵל כָּל הָאוֹרוֹת. אוֹר שֶׁלֹּא מֵאִיר מִסְתַּכֵּל לְאֵלֶּה וְנוֹטֵל אוֹתָם, וְנִרְאִים אוֹתָם הַמְּאוֹרוֹת בּוֹ כַּעֲשָׁשִׁית נֶגֶד הַשֶּׁמֶשׁ.</p>\n<p>וְאֵלֶּה הַשְּׁלֹשָׁה שֶׁאָמַרְנוּ נִסְתָּרִים וְעוֹמְדִים עַל זֶה שֶׁהִתְגַּלָּה, וְסוֹד זֶה הָעַיִן. בֹּא רְאֵה, בָּעַיִן יֵשׁ שְׁלֹשָׁה גְוָנִים שֶׁהִתְגַּלּוּ רְשׁוּמִים בּוֹ, וְכֻלָּם לֹא זוֹהֲרִים, מִשּׁוּם שֶׁעוֹמְדִים בְּאוֹר שֶׁלֹּא מֵאִיר. וְאֵלֶּה הֵם כְּמוֹ שֶׁאוֹתָם הַנִּסְתָּרִים שֶׁעוֹמְדִים עֲלֵיהֶם, וְאֵלֶּה הֵם שֶׁנִּרְאוּ לָאָבוֹת לָדַעַת אוֹתָם נִסְתָּרִים שֶׁזּוֹהֲרִים מִתּוֹךְ אֵלֶּה שֶׁלֹּא זוֹהֲרִים, וְאוֹתָם שֶׁזּוֹהֲרִים וְהֵם סְתוּמִים, הִתְגַּלּוּ לְמֹשֶׁה בְּאוֹתוֹ רָקִיעַ שֶׁלּוֹ, וְאֵלֶּה עוֹמְדִים עַל אוֹתָם גְּוָנִים שֶׁנִּרְאִים בּוֹ בָּעַיִן.</p>\n<p>וְסוֹד זֶה סוֹתֵם עֵינֶיךְ וּמְסוֹבֵב גַּלְגַּלְּךְ, וְיִתְגַּלּוּ אוֹתָם גְּוָנִים שֶׁמְּאִירִים, שֶׁזּוֹהֲרִים, וְלֹא נִתְּנָה רְשׁוּת לִרְאוֹת אֶלָּא בְּעֵינַיִם סְתוּמוֹת, מִשּׁוּם שֶׁאוֹתָם נִסְתָּרִים עֶלְיוֹנִים עוֹמְדִים עַל אוֹתָם גְּוָנִים שֶׁנִּרְאִים, שֶׁלֹּא זוֹהֲרִים.</p>\n<p>וְעַל זֶה קָרָאנוּ, מֹשֶׁה זָכָה בְּאַסְפַּקְלַרְיָה הַמְּאִירָה שֶׁעוֹמֶדֶת עַל אוֹתָהּ שֶׁלֹּא מְאִירָה. שְׁאָר בְּנֵי הָעוֹלָם בְּאוֹתָהּ אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה. הָאָבוֹת הָיוּ רוֹאִים מִתּוֹךְ הַגְּוָנִים הַלָּלוּ שֶׁהִתְגַּלּוּ, אוֹתָם סְתוּמִים, שֶׁעוֹמְדִים עֲלֵיהֶם שֶׁלֹּא מְאִירִים, וְלָכֵן כָּתוּב וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי, בְּאוֹתָם גְּוָנִים שֶׁנִּרְאִים.</p>\n<p>וּשְׁמִי ה' לֹא נוֹדַעְתִּי לָהֶם - אֵלּוּ גְוָנִים עֶלְיוֹנִים נִסְתָּרִים שֶׁזּוֹהֲרִים שֶׁזָּכָה בָהֶם מֹשֶׁה לְהִסְתַּכֵּל בָּהֶם. וְסוֹד זֶה, שֶׁהָעַיִן סָתוּם וְגָלוּי. סָתוּם - רוֹאֶה אַסְפַּקְלַרְיָה הַמְּאִירָה. נִגְלֶה - רוֹאֶה אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה. וְעַל זֶה וָאֵרָא, בְּאַסְפַּקְלַרְיָה שֶׁלּא מְאִירָה, שֶׁהִיא בְּהִתְגּלּוּת, בָּהּ כָּתוּב רְאִיָּה. וְאוּלָם בְּאַסְפַּקְלַרְיָה שֶׁמְּאִירָה שֶׁהִיא בַּסֵּתֶר, כָּתוּב בָּהּ יְדִיעָה, שֶׁכָּתוּב לֹא נוֹדַעְתִּי. בָּאוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְנָשְׁקוּ יָדָיו. בָּכָה רַבִּי אַבָּא וְאָמַר, אוֹי כְּשֶׁתִּסְתַּלֵּק מִן הָעוֹלָם וְיִשָּׁאֵר הָעוֹלָם יָתוֹם מִמְּךְ, מִי יָכוֹל לְהָאִיר דִּבְרֵי תוֹרָה?</p>\n<p>פָּתַח רַבִּי אַבָּא וְאָמַר, (שמואל א כה) וַאֲמַרְתֶּם כֹּה לֶחָי וְאַתָּה שָׁלוֹם וּבֵיתְךְ שָׁלוֹם וְכֹל אֲשֶׁר לְךְ שָׁלוֹם. וַאֲמַרְתֶּם כֹּה לֶחָי, וְכִי דָוִד לֹא הָיָה יוֹדֵעַ בּוֹ בְּנָבָל שֶׁהוּא אוֹמֵר בִּשְׁבִילוֹ וַאֲמַרְתֶּם כֹּה לֶחָי? אֶלָּא אוֹתוֹ יוֹם, יוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה הָיָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב בְּדִין עַל הָעוֹלָם, וּבִשְׁבִיל הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא אָמַר וַאֲמַרְתֶּם כֹּה לֶחָי, לִקְשֹׁר כֹּה לֶחָי, שֶׁכָּל הַחַיִּים תְּלוּיִים בּוֹ. וְאַתָּה שָׁלוֹם, מַה זֶּה וְאַתָּה? אַתָּה הָיָה צָרִיךְ (לכתב) ! אֶלָּא וְאַתָּה, הַכֹּל לַקָּדוֹשׁ-בָּרוּךְ-הוּא אָמַר, כְּדֵי לִקְשֹׁר קֶשֶׁר הָאֱמוּנָה וְכָרָאוּי.</p>\n<p>מִכָּאן לָמַדְנוּ שֶׁאָסוּר לְהַקְדִּים שָׁלוֹם לְאָדָם רָשָׁע, וְאִם צָרִיךְ, יַקְדִּים לוֹ כְּמוֹ דָּוִד שֶׁבֵּרַךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִרְאָה שֶׁאָמַר בִּגְלָלוֹ. וְאִם תֹּאמַר שֶׁזּוֹ רַמָּאוּת - לֹא, שֶׁהֲרֵי כָּל מַה שֶׁמַּעֲלֶה לַקָּדוֹשׁ- בָּרוּךְ-הוּא וְנִרְאֶה שֶׁבִּשְׁבִילוֹ אָמַר - אֵינוֹ רַמָּאוּת. וּמִי שֶׁמַּקְדִּים שָׁלוֹם לְצַדִּיק כְּאִלּוּ הִקְדִּים לַקָּדוֹשׁ-בָּרוּךְ- הוּא, כָּל שֶׁכֵּן מֹר, שֶׁהוּא שָׁלוֹם לְמַעְלָה וּלְמַטָּה.</p>"],[9522011563,"<p>וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי וּשְׁמִי ה' לֹא נוֹדַעְתִּי לָהֶם. רַבִּי חִזְקִיָּה פָּתַח, (תהלים לב) אַשְׁרֵי אָדָם לֹא יַחְשֹׁב ה' לוֹ עָוֹן וְגוֹ'. כַּמָּה אֲטוּמִים הֵם בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים וְלֹא מִסְתַּכְּלִים עַל מָה עוֹמְדִים בָּעוֹלָם, שֶׁהֲרֵי כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה אֶת הָאָדָם בַּדְּיוֹקָן שֶׁלּוֹ וְהִתְקִינוֹ בְתִקּוּנָיו, כְּדֵי שֶׁיִּשְׁתַּדֵּל בַּתּוֹרָה וְיֵלֵךְ בִּדְרָכָיו.</p>\n<p>שֶׁהֲרֵי כְּשֶׁנִּבְרָא אָדָם, מֵעֲפַר הַמִּקְדָּשׁ שֶׁלְּמַטָּה נִתְקַן, וְאַרְבָּעָה צִדְדֵי הָעוֹלָם הִתְחַבְּרוּ בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא בֵּית הַמִּקְדָּשׁ. וְאוֹתָם אַרְבָּעָה צִדְדֵי הָעוֹלָם הִתְחַבְּרוּ בְּאַרְבָּעָה צְדָדִים, שֶׁהֵם יְסוֹדוֹת הָעוֹלָם אֵ\"שׁ רוּ\"חַ וּמַיִ\"ם וְעָפָ\"ר, וְהִתְחַבְּרוּ אַרְבָּעָה צְדָדִים אֵלּוּ בְּאַרְבָּעָה צִדְדֵי (יסודות) הָעוֹלָם, וְהִתְקִין מֵהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא גּוּף אֶחָד בְּתִקּוּן עֶלְיוֹן, וְגוּף זֶה הִתְחַבֵּר מִשְּׁנֵי עוֹלָמוֹת, מֵהָעוֹלָם הַתַּחְתּוֹן הַזֶּה וּמֵהָעוֹלָם שֶׁלְּמַעְלָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה, אַרְבָּעָה רִאשׁוֹנִים הֵם סוֹד הָאֱמוּנָה, וְהֵם אָבוֹת שֶׁל כָּל עוֹלָמוֹת, וְסוֹד הַמֶּרְכָּבָה הָעֶלְיוֹנָה הַקְּדוֹשָׁה. וְאוֹתָם אַרְבָּעָה יְסוֹדוֹת, אֵ\"שׁ רוּ\"חַ וּמַיִ\"ם וְעָפָ\"ר, אֵלֶּה הֵם סוֹד עֶלְיוֹן. (ואלו הם האבות, שכל העולמות אבות של הכל) וּמֵהֶם יוֹצְאִים זָהָ\"ב וָכֶסֶ\"ף וּנְחֹשֶׁ\"ת וּבַרְזֶ\"ל, וְתַחַת אֵלּוּ מַתָּכוֹת אֲחֵרוֹת שֶׁדּוֹמִים לָהֶם (כמו שאלו).</p>\n<p>בֹּא רְאֵה, אֵ\"שׁ רוּ\"חַ וּמַיִ\"ם וְעָפָ\"ר אֵלֶּה הֵם הָרִאשׁוֹנִים וְהַשָּׁרָשִׁים שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה, וְתַחְתּוֹנִים וְעֶלְיוֹנִים עוֹמְדִים עֲלֵיהֶם. וְאֵלֶּה הֵם אַרְבָּעָה, לְאַרְבָּעָה צִדְדֵי הָעוֹלָם, וְעוֹמְדִים בְּאַרְבָּעָה אֵלּוּ: צָפוֹ\"ן וְדָרוֹ\"ם וּמִזְרָ\"ח וּמַעֲרָ\"ב. אֵלּוּ הֵם אַרְבָּעָה צְדָדִים שֶׁל הָעוֹלָם, וְעוֹמְדִים בְּאַרְבָּעָה אֵלּוּ. אֵ\"שׁ לְצַד צָפוֹ\"ן, רוּ\"חַ לְצַד מִזְרָ\"ח. מַיִ\"ם לְצַד דָּרוֹ\"ם. מִשּׁוּם שֶׁהַדָּרוֹם הוּא חַם וְיָבֵשׁ. מַיִם קָרִים וְלַחִים. עָפָ\"ר לְצַד מַעֲרָ\"ב. וְאַרְבָּעָה אֵלּוּ קְשׁוּרִים בְּאַרְבָּעָה אֵלּוּ, וְכֻלָּם אֶחָד, וְאֵלֶּה עוֹשִׂים אַרְבַּע מַתָּכוֹת, שֶׁהֵם זָהָ\"ב וָכֶסֶ\"ף וּנְחֹשֶׁ\"ת וּבַרְזֶ\"ל. הֲרֵי הֵם שְׁנֵים עָשָׂר, וְכֻלָּם אֶחָד.</p>\n<p>בֹּא רְאֵה, הָאֵשׁ הִיא בִּשְׂמֹאל, לְצַד צָפוֹן, שֶׁהֲרֵי הָאֵשׁ בּוֹ תֹּקֶף הַחֲמִימוּת, וְהַיֹּבֶשׁ שֶׁלּוֹ חָזָק. וְצָפוֹן הַהֵפֶךְ שֶׁלּוֹ, וְנִמְזָגִים אֶחָד בְּאֶחָד וְהוּא אֶחָד. מַיִם לְיָמִין, וְהוּא לְצַד דָּרוֹם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לְחַבְּרָם (להחזירם) כְּאֶחָד, עוֹשֶׂה מֶזֶג זֶה כְּמֶזֶג זֶה.</p>\n<p>הַצָפוֹן הוּא קַר וְלַח, הָאֵשׁ חַם וְיָבֵשׁ. הֶחֱלִיפָם לְצַד דָּרוֹם. דָּרוֹם הוּא חַד וְיָבֵשׁ. הַמַּיִם קָרִים וְלַחִים. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹזֵג אוֹתָם כְּאֶחָד, שֶׁיּוֹצְאִים מַיִם מִדָּרוֹם וְנִכְנָסִים לַצָּפוֹן, וּמִצָּפוֹן שׁוֹפְעִים מַיִם. יוֹצֵא אֵשׁ מִצָּפוֹן, וְנִכְנָס בְּתֹקֶף הַדָּרוֹם, וּמִדָּרוֹם יוֹצֵא תֹּקֶף הַחֲמִימוּת לָעוֹלָם, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לוֹוֶה זֶה מִזֶּה, וְכָל אֶחָד וְאֶחָד מַלְוֶה לַחֲבֵרוֹ מִשֶּׁלּוֹ כָּרָאוּי לוֹ. כְּמוֹ זֶה רוּחַ וּמִזְרָח, כְּדֵי שֶׁיַּלְוֶה כָּל אֶחָד לַחֲבֵרוֹ, וְנִכְלָלִים זֶה בָּזֶה לְהִתְחַבֵּר כְּאֶחָד.</p>\n<p>בֹּא רְאֵה, אֵשׁ מִצַּד זֶה, מַיִם מִצַּד זֶה, וְהֵם מַחֲלֹקֶת. נִכְנֶסֶת רוּחַ בֵּינֵיהֶם וְאוֹחֶזֶת אֶת שְׁנֵי הַצְּדָדִים. זֶהוּ שֶׁכָּתוּב (בראשיתא) וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, שֶׁהֲרֵי אֵשׁ עוֹמֶדֶת לְמַעְלָה בְּצַד זֶה, וּמַיִם עוֹמְדִים עַל פְּנֵי הָאָרֶץ. רוּחַ נִכְנֶסֶת בֵּינֵיהֶם וְאוֹחֶזֶת אֶת שְׁנֵי הַצְּדָדִים וּמַפְרִידָה מַחֲלֹקֶת. הֶעָפָר, הַמַּיִם עוֹמְדִים עָלָיו, וְרוּחַ וְאֵשׁ, וּמְקַבֶּלֶת מִכֻּלָּם בַּכֹּחַ שֶׁל שְׁלֹשֶׁת אֵלֶּה שֶׁעוֹמְדִים עָלָיו.</p>\n<p>בֹּא רְאֵה. רוּחַ וּמִזְרָח. מִזְרָח חַם וְלַח, רוּחַ (קר ויבש. הצד שהוא יבש) חַם וְלַח הִיא, וְלָכֵן אוֹחֵז אֶת שְׁנֵי הַצְּדָדִים, שֶׁהֲרֵי אֵשׁ חַם וְיָבֵשׁ, וּמַיִם קָרִים וְלַחִים. רוּחַ הוּא חַם וְלַח. הַצַּד שֶׁהוּא חַם אָחוּז בָּאֵשׁ. הַצַּד שֶׁהוּא לַח אָחוּז בַּמַּיִם. וְעַל זֶה יֵשׁ הַסְכָּמָה בֵּינֵיהֶם, וּמַפְרִיד מַחֲלֹקֶת שֶׁל אֵשׁ וּמַיִם.</p>\n<p>עָפָר הוּא קַר וְיָבֵשׁ, וְלָכֵן מְקַבֵּל עָלָיו אֶת כֻּלָּם, וְכֻלָּם עוֹשִׂים בּוֹ מַעֲשֵׂיהֶם, וּמְקַבֵּל מִכֻּלָּם לְהוֹצִיא בְּכֹחָם מָזוֹן לָעוֹלָם, מִשּׁוּם שֶׁבַּמַּעֲרָב נֶאֱחָז הֶעָפָר שֶׁהוּא קַר וְיָבֵשׁ, וְצַד שֶׁהוּא קַר אָחוּז בַּצָּפוֹן שֶׁהוּא קַר וְלַח, שֶׁהֲרֵי קֹר נֶאֱחָז בְּקֹר. מִשּׁוּם כָּךְ צָפוֹן נֶאֱחָז בַּמַּעֲרָב בְּצַד זֶה. דָּרוֹם שֶׁהוּא חַם וְיָבֵשׁ, בְּאוֹתוֹ הַיֹּבֶשׁ שֶׁלּוֹ אוֹחֵז אֶת הַיֹּבֶשׁ שֶׁל הַמַּעֲרָב בְּצַד אַחֵר, וְנֶאֱחָז מַעֲרָב בִּשְׁנֵי צְדָדִים.</p>\n<p>וְכֵן נֶאֱחָז דָּרוֹם בַּמִּזְרָח, שֶׁהֲרֵי חֲמִימוּת הַדָּרוֹם נֶאֱחֶזֶת בַּחֲמִימוּת הַמִּזְרָח. וּמִזְרָח נֶאֱחָז בַּצָּפוֹן, שֶׁהֲרֵי לַחוּתוֹ נֶאֱחֶזֶת בְּלַחוּת הַצָּפוֹן. עַכְשָׁו נִמְצָא דְּרוֹמִי\"ת מִזְרָחִי\"ת. מִזְרָחִי\"ת צְפוֹנִי\"ת. צְפוֹנִי\"ת מַעֲרָבִי\"ת. מַעֲרָבִי\"ת דְּרוֹמִי\"ת. וְכֻלָּם כְּלוּלִים זֶה בָּזֶה לְהִשְׁתַּלְשֵׁל אֶחָד בְּאֶחָד.</p>\n<p>כְּמוֹ כֵן צָפוֹן עוֹשֶׂה זָהָב, שֶׁמִּצַּד תֹּקֶף הָאֵשׁ נַעֲשֶׂה זָהָב, וְהַיְנוּ שֶׁכָּתוּב (איוב לז) מִצָּפוֹן זָהָב יֶאֱתֶה. שֶׁאֵשׁ אָחוּז בֶּעָפָר וְנַעֲשֶׂה זָהָב, וְהַיְנוּ שֶׁכָּתוּב (שם כח) וְעַפְרוֹת זָהָב לוֹ. וְסוֹד זֶה שְׁנַיִם כְּרוּבִים זָהָב.</p>\n<p>מַיִם נֶאֱחָזִים בֶּעָפָר, וּקְרִירוּת בְּלַחוּת עוֹשֶׂה כֶסֶף, כָּעֵת הֲרֵי עָפָר נֶאֱחָז בִּשְׁנֵי צְדָדִים, בַּזָּהָב וּבַכֶּסֶף, וְנִתָּן בֵּינֵיהֶם. רוּחַ אוֹחֶזֶת אֶת הַמַּיִם, וְאוֹחֶזֶת (תמיהה, במה שאמר רוח קר ויבש, שאם כן, רוח ועפר שוים בטבעם, אבל יש אומרים כי רוח חם ולח, ואם כן נוכל לומר שאוחז הרוח לשני צדדים אש חם ויבש, ורוח חם ולח. הצד שהוא חם אוחז באש, והצד שהוא לח אוחז במים, ומפריד מחלקת של אש ומים. עפר הוא קר ויבש, ומים קרים ולחים, והצד הקר אוחז בעפר בצד הקר. נמצא שעפר מקבל עליו כלם, משום כך אחוז לשני הצדדים, שהרי אש חם ויבש, מים קר ולח. ע\"כ) אֶת הָאֵשׁ, וּמוֹצִיאָה שְׁנַיִם כְּאֶחָד, שֶׁהוּא עֵין נְחֹשֶׁת קָלָל. וְעָפָר שֶׁאָמַרְנוּ, כְּשֶׁהוּא לְבַדּוֹ בַּיֹּבֶשׁ וְהַקֹּר שֶׁלּוֹ, יוֹצֵא בַּרְזֶל, וְסִימָנְךְ - (קהלת י) אִם קֵהָה הַבַּרְזֶל וְגוֹ'.</p>\n<p>וְעָפָר זֶה נֶאֱחָז בְּכֻלָּם, וְכֻלָּם עוֹשִׂים בּוֹ כַּצּוּרָה שֶׁלָּהֶם. בּא רְאֵה, בְּלֹא עָפָר אֵין זָהָב וְכֶסֶף וּנְחֹשֶׁת, שֶׁהֲרֵי כָּל אֶחָד וְאֶחָד מַלְוֶה לַחֲבֵרוֹ מִשֶּׁלּוֹ לְהִתְקַשֵּׁר זֶה בָּזֶה. וְהֶעָפָר נֶאֱחָז בְּכֻלָּם, מִשּׁוּם שֶׁשְּׁנֵי צְדָדִים אוֹחֲזִים אוֹתוֹ, אֵשׁ וּמַיִם. וְרוּחַ נִקְרֶבֶת לוֹ בִּשְׁבִיל שְׁנֵי אֵלֶּה וְעוֹשֶׂה בּוֹ מַעֲשֶׂה.</p>\n<p>נִמְצָא שֶׁכְּשֶׁמִּתְחַבֵּר עָפָר עִמָּם, עוֹשֶׂה וּמוֹלִיד עֲפָרוֹת אֲחֵרִים כְּמוֹ שֶׁלָּהֶם, כְּמוֹ שֶׁזָּהָב מוֹלִיד עֲפַר פְּסֹלֶת יְרֻקָּה, שֶׁהִיא כְּמוֹ זָהָב מַמָּשׁ. כְּמוֹ שֶׁכֶּסֶף שֶׁמּוֹלִיד עֹפֶרֶת, וּכְמוֹ שֶׁנְּחֹשֶׁת הָעֶלְיוֹנָה מוֹלִידָה בְּדִיל שֶׁהוּא נְחֹשֶׁת קְטַנָּה. כְּמוֹ שֶׁבַּרְזֶל מוֹלִיד בַּרְזֶל, וְסִימָנְךְ - (משליכז) בַּרְזֶל בְּבַרְזֶל יָחַד.</p>\n<p>בֹּא רְאֵה, אֵשׁ רוּחַ מַיִם וְעָפָר, כֻּלָּם אֲחוּזִים זֶה בָּזֶה וּקְשׁוּרִים זֶה בָּזֶה, וְאֵין בָּהֶם פֵּרוּד. וְהֶעָפָר הַזֶּה, כְּשֶׁהוּא מוֹלִיד אַחַר כָּךְ, לֹא מִתְקַשְּׁרִים זֶה בָּזֶה כְּאוֹתָם עֶלְיוֹנִים, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים, בְּאֵלֶּה הָיָה פֵּרוּד.</p>\n<p>מִשּׁוּם שֶׁהֲרֵי הֶעָפָר, כְּשֶׁהא מוֹלִיד בַּכֹּחַ שֶׁל שְׁלֹשֶׁת הָעֶלְיוֹנִים, מוֹצִיא אַרְבָּעָה נְהָרוֹת שֶׁשָּׁם נִמְצָאוֹת אֲבָנִים יְקָרוֹת, וְהֵם בְּמָקוֹם אֶחָד, שֶׁכָּתוּב שָׁם הַבְּדֹלַח וְאֶבֶן הַשֹּׁהַם. וְאוֹתָן אֲבָנִים יְקָרוֹת הֵן שְׁתֵּים עֶשְּׂרֵה, וְהֵן לְאַרְבָּעָה צִדְדֵי הָעוֹלָם כְּנֶגֶד שְׁנֵים עָשָׂר שְׁבָטִים, שֶׁכָּתוּב (שמות כח) וְהָאֲבָנִים תִּהְיֶיןָ עַל שְׁמוֹת בְּנֵי יִשְׂרָאֵל שְׁתֵּים עֶשְׂרֵה עַל שְׁמוֹתָם. וּשְׁנֵים עָשָׂר הַבָּקָר הַלָּלוּ שֶׁהֵם תַּחַת הַיָּם.</p>\n<p>בֹּא רְאֵה, כָּל אַרְבַּעַת הַצְּדָדִים הָעֶלְיוֹנִים שֶׁאָמַרְנוּ, אַף עַל גַּב שֶׁנִּקְשָׁרִים זֶה בָּזֶה, וְהֵם הַקִּיּוּם שֶׁלְּמַעְלָה וָמַטָּה, קִיּוּם שֶׁל הָעוֹלָם יוֹתֵר הוּא הָרוּחַ, מִשּׁוּם שֶׁהַכֹּל עוֹמֵד בִּגְלָלוֹ, וְנֶפֶשׁ לֹא עוֹמֶדֶת אֶלָּא בָּרוּחַ, שֶׁאִם נִגְרַעַת הָרוּחַ אֲפִלּוּ רֶגַע אֶחָד, אֵין הַנֶּפֶשׁ יְכוֹלָה לְהִתְקַיֵּם, וְסוֹד זֶה כָּתוּב (משלי יט) גַּם בְּלֹא דַעַת נֶפֶשׁ לֹא טוֹב. נֶפֶשׁ בְּלִי רוּחַ אֵינָהּ טוֹב, וְלֹא יְכוֹלָה לְהִתְקַיֵּם.</p>\n<p>וּבֹא רְאֵה, אוֹתָם שְׁנֵים עָשָׂר שֶׁאָמַרְנוּ, שֶׁהֵם שְׁתֵּים עֶשְּׂרֵה אֲבָנִים, הֵם שְׁנֵים עָשָׂר בָּקָר שֶׁתַּחַת הַיָּם. מִשּׁוּם כָּךְ נָטְלוּ אוֹתָם שְׁנֵים עָשָׂר נְשִׂיאִים (במדבר ז) כָּל הַבָּקָר לָעֹלָה שְׁנֵים עָשָׂר פָּרִים וְגוֹ'. וְהַכֹּל הוּא סוֹד עֶלְיוֹן, וּמִי שֶׁיַּשְׁגִּיחַ בַּדְּבָרִים הַלָּלוּ, יַשְׁגִּיחַ בְּסוֹד הַחָכְמָה הָעֶלְיוֹנָה, שֶׁהָעִקָּר שֶׁל הַכֹּל בָּהּ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, מַה שֶּׁאָמַר רַבִּי חִזְקִיָּה, שֶׁכְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם, מֵעֲפַר הַמִּקְדָּשׁ שֶׁלְּמַטָּה נִבְרָא, וּמֵעֲפַר הַמִּקְדָּשׁ שֶׁלְּמַעְלָה נִתְּנָה בּוֹ נְשָׁמָה, וּכְמוֹ שֶׁכְּשֶׁנִּבְרָא מֵהֵעָפָר שֶׁלְּמַטָּה הִתְחַבְּרוּ בוֹ שְׁלֹשָׁה צְדָדִים יְסוֹדוֹת הָעוֹלָם, כָּךְ גַּם כְּשֶׁנִּבְרָא מִן הֶעָפָר שֶׁלְּמַעְלָה הִתְחַבְּרוּ בוֹ שְׁלֹשָׁה יְסוֹדוֹת שֶׁל הָעוֹלָם וְהִשְׁתַּלֵּם הָאָדָם, וְהַיְנוּ שֶׁכָּתוּב (תהלים לב) אַשְׁרֵי אָדָם לֹא יַחְשֹׁב ה' לוֹ עָוֹן וְאֵין בְּרוּחוֹ רְמִיָּה. אֵימָתַי לֹא יַחְשֹׁב ה' לוֹ עָון? בִּזְמַן שֶׁאֵין בְּרוּחוֹ רְמִיָּה.</p>\n<p>בֹּא רְאֵה, מֹשֶׁה נִתְקַן יוֹתֵר מֵהָאָבוֹת, מִשּׁוּם שֶׁדִּבֵּר עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, מַדְרֵגָה יוֹתֵר עֶלְיוֹנָה מִכֻּלָּם, וּמֹשֶׁה מִפְּנִים בֵּית הַמֶּלֶךְ הָעֶלְיוֹן הָיָה, וְעַל זֶה כָּתוּב וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב וְגוֹ', וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים.</p>"],[9522011564,"<p>לָכֵן אֱמֹר לִבְנֵי יִשְׂרָאֵל אֲנִי ה' וְהוֹצֵאתִי אֶתְכֶם. רַבִּי יְהוּדָה אָמַר, פָּסוּק זֶה הוּא הָפוּךְ, שֶׁכָּתוּב וְהוֹצֵאתִי אֶתְכֶם מִתַּחַת סִבְלֹת מִצְרַיִם בָּרִאשׁוֹנָה, וְאַחַר כָּךְ וְהִצַּלְתִּי אֶתְכֶם מֵעֲבוֹדָתָם, וְאַחַר כָּךְ וְגָאַלְתִּי אֶתְכֶם. הָיָה לוֹ לוֹמַר מִתְּחִלָּה וְגָאַלְתִּי אֶתְכֶם, וְאַחַר כָּךְ וְהוֹצֵאתִי אֶתְכֶם! אֶלָּא עִקָּר שֶׁל הַכֹּל בָּרִאשׁוֹנָה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַשֵּׂר לָהֶם בַּמֻּבְחָר שֶׁל הַכֹּל בָּרִאשׁוֹנָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, וַהֲרֵי הַמֻּבְחָר שֶׁבַּכֹּל וְלָקַחְתִּי אֶתְכֶם לִי לְעָם וְהָיִיתִי לָכֶם לֵאלֹהִים, וְאָמַר אוֹתוֹ לְבַסּוֹף? אָמַר לוֹ, בְּאוֹתוֹ זְמַן אֵין הַמֻּבְחָר אֶלָּא הַיְצִיאָה, שֶׁחָשְׁבוּ שֶׁלֹּא יֵצְאוּ מֵעַבְדוּתָם לְעוֹלָמִים, מִשּׁוּם שֶׁהָיוּ רוֹאִים שָׁם שֶׁכָּל הָאֲסִירִים שֶׁהָיוּ בֵינֵיהֶם, קוֹשְׁרִים אוֹתָם בְּקִשְׁרֵי כִשּׁוּף, וְלֹא יְכוֹלִים לָצֵאת מִבֵּינֵיהֶם לְעוֹלָמִים. וְלָכֵן הִתְבַּשְּׂרוּ בְּמַה שֶּׁחָבִיב עֲלֵיהֶם מִכֹּל.</p>\n<p>וְאִם תֹּאמַר, אַף עַל גַּב שֶׁיָּצְאוּ, הֲרֵי אוּלַי יֵלְכוּ (חילותם) אַחֲרֵיהֶם לְהַזִּיק לָהֶם - כָּתוּב וְהִצַּלְתִּי אֶתְכֶם מֵעֲבוֹדָתָם. וְאִם תֹּאמַר, הֲרֵי יֵצְאוּ וְיִנָּצְלוּ וְלֹא תִהְיֶה לָהֶם גְּאֻלָּה - תַּלְמוּד לוֹמַר וְגָאַלְתִּי אֶתְכֶם בִּזְרוֹעַ נְטוּיָה. וְאִם תֹּאמַר לֹא יְקַבְּלֵם - הֲרֵי כָּתוּב וְלָקַחְתִּי. וְאִם תֹּאמַר, כְּשֶׁיְּקַבְּלֵם לֹא יְבִיאֵם לָאָרֶץ - הֲרֵי כָּתוּב וְהֵבֵאתִי אֶתְכֶם וְגוֹ'.</p>"],[9522011565,"<p>וְלָקַחְתִּי אֶתְכֶם לִי לְעָם וְהָיִיתִי לָכֶם לֵאלֹהִים וִידַעְתֶּם כִּי אֲנִי ה' אֱלֹהֵיכֶם וְגוֹ'. מִצְוָה זוֹ רִאשׁוֹנָה שֶׁל כָּל הַמִּצְווֹת. רֵאשִׁית רִאשׁוֹנָה לְכָל הַמִּצְווֹת - לָדַעַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בַּכְּלָל. מַה זֶּה בַּכְּלָל? לָדַעַת שֶׁיֵּשׁ שַׁלִּיט עֶלְיוֹן שֶׁהוּא רִבּוֹן הָעוֹלָם, וּבָרָא אֶל כָּל הָעוֹלָמוֹת, שָׁמַיִם וָאָרֶץ וְכָל חֵילוֹתֵיהֶם. וְזֶהוּ בַּכְּלָל. וְסוֹף הַכֹּל בִּפְרָט, לָדַעַת אוֹתוֹ בִּפְרָט.</p>\n<p>וּכְלָל וּפְרָט הוּא רֹאשׁ וָסוֹף, סוֹד שֶׁל זָכָר וּנְקֵבָה כְּאֶחָד, וְנִמְצָא אָדָם בָּעוֹלָם הַזֶּה שֶׁמִּתְעַסֵּק בִּכְלָל וּפְרָט, אָדָם בָּעוֹלָם הַזֶּה הוּא כְּלָל וּפְרָט. תִּקּוּן שֶׁל הָעוֹלָם הַזֶּה הוּא כְּלָל וּפְרָט. מִשּׁוּם כָּךְ, רֵאשִׁית הַכֹּל - שֶׁיֵּשׁ לָדַעַת שֶׁיֵּשׁ שַׁלִּיט וְדַיָּן עַל הָעוֹלָם, וְהוּא רִבּוֹן כָּל הָעוֹלָמִים, וּבָרָא אֶת הָאָדָם מִן הֶעָפָר, וְנָפַח בְּאַפָּיו נִשְׁמַת חַיִּים, וְזֶהוּ בְּדֶרֶךְ כְּלָל.</p>\n<p>כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם לֹא הָיוּ מַכִּירִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁבָּא מֹשֶׁה אֲלֵיהֶם, לִמֵּד אוֹתָם מִצְוָה רִאשׁוֹנָה זוֹ, שֶׁכָּתוּב וִידַעְתֶּם כִּי אֲנִי ה' אֱלֹקֵיכֶם הַמּוֹצִיא אֶתְכֶם וְגוֹ'. וְאִלְמָלֵא מִצְוָה זוֹ, לֹא הָיוּ יִשְׂרָאֵל מַאֲמִינִים בְּכָל אוֹתָם נִסִּים וּגְבוּרוֹת שֶׁעָשָׂה לָהֶם בְּמִצְרַיִם. כֵּיוָן שֶׁיָּדְעוּ מִצְוָה זוֹ בְּדֶרֶךְ כְּלָל, נַעֲשׂוּ לָהֶם נִסִּים וּגְבוּרוֹת.</p>\n<p>וּלְסוֹף אַרְבָּעִים שָׁנָה, שֶׁכְּשֶׁהִשְׁתַּדְּלוּ בְּכָל אוֹתָן מִצְווֹת שֶׁל הַתּוֹרָה שֶׁלִּמֵּד אוֹתָם מֹשֶׁה, בֵּין אוֹתָן שֶׁנּוֹהֲגוֹת בָּאָרֶץ וּבֵין אוֹתָן שֶׁנּוֹהֲגוֹת בְּחוּץ לָאָרֶץ, אָז לִמֵּד אוֹתָם בְּדֶרֶךְ פְּרָט. זֶהוּ שֶׁכָּתוּב (דברים ד) וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבוֹתָ אֶל לְבָבֶךְ. הַיּוֹם דַּוְקָא, מַה שֶּׁלֹּא הָיָה רְשׁוּת מִקֹּדֶם לָכֵן. כִּי ה' הוּא הָאֱלֹהִים - זֶה בְּדֶרֶךְ פְּרָט. בְּדָבָר זֶה כַּמָּה סוֹדוֹת וּסְתָרִים יֵשׁ בּוֹ, וְזֶה וְאוֹתוֹ שֶׁבַּהַתְחָלָה הַכֹּל דָּבָר אֶחָד, זֶה בִּכְלָל וְזֶה בִּפְרָט.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב (משלי א) יִרְאַת ה' רֵאשִׁית דָּעַת - הַתֵּרוּץ, זֶה בְּדֶרֶךְ פְּרָט לָדַעַת מִי הִיא יִרְאַת ה'. וְאַף עַל גַּב שֶׁיֵּשׁ לָאָדָם לִירָא מִמֶּנּוּ עַד שֶׁלֹּא יֵדַע, אֲבָל כָּאן כָּתוּב רֵאשִׁית דַּעַת, לָדַעַת אוֹתוֹ שֶׁהֲרֵי הוּא רֵאשִׁית, לָדַעַת אוֹתוֹ בְּדֶרֶךְ פְּרָט.</p>\n<p>לָכֵן מִצְוָה רִאשׁוֹנָה לְהַכִּיר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְלָל וּפְרָט, בַּהַתְחָלָה וּבַסּוֹף, וְסוֹד זֶה - (ישעיה מד) אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן. אֲנִי רִאשׁוֹן בִּכְלָל, וַאֲנִי אַחֲרוֹן בִּפְרָט. וְהַכֹּל בִּכְלָל אֶחָד וְסוֹד אֶחָד. כֵּיוָן שֶׁיֵּדַע אֶת זֶה בִּכְלָל, יַשְׁלִים אֶת כָּל אֵיבָרָיו, וּמִי הֵם? מָאתַיִם אַרְבָּעִים וּשְׁמוֹנֶה מִצְווֹת, שֶׁהֵם מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵיבְרֵי הָאָדָם. כֵּיוָן שֶׁהִשְׁתַּלֵּם בָּהֶם עַל זֶה בִּכְלָל, אָז יֵדַע בְּדֶרֶךְ פְּרָט, שֶׁזֶּה הוּא רְפוּאָה לְכֻלָּם, וְיֵדַע אֶת כָּל יְמוֹת הַשָּׁנָה שֶׁמִּתְחַבְּרִים לָתֵת רְפוּאָה לְכָל הָאֵיבָרִים.</p>\n<p>וְאִם תֹּאמַר, כָּל יְמוֹת הַשָּׁנָה אֵיךְ נוֹתְנִים רְפוּאָה לְכָל הָאֵיבָרִים? וַדַּאי כָּךְ הוּא לְמַעְלָה וּלְמַטָּה. הַשָּׁנָה וְהַיָּמִים שֶׁלָּהּ נוֹתְנִים רְפוּאָה לְכָל הָאֵיבָרִים, לְמַעְלָה וּלְמַטָּה, (בזמן) שֶׁהָאֵיבָרִים מְרִיקִים בְּרָכוֹת לִימוֹת הַשָּׁנָה, וְאָז רְפוּאָה וְחַיִּים תְּלוּיִים עָלֵינוּ מִלְמַעְלָה וּמִתְמַלְּאִים מֵהַכֹּל. מִי גָרַם לָהֶם? יְמוֹת הַשָּׁנָה.</p>\n<p>אַף כָּךְ גַּם לְמַטָּה, כְּשֶׁאָדָם יַשְׁלִים אֶת גּוּפוֹ בְּאוֹתָן מִצְווֹת הַתּוֹרָה, אֵין לְךְ כָּל יוֹם שֶׁלֹּא בָא לְהִתְבָּרֵךְ מִמֶּנּוּ, וּכְשֶׁהֵם מִתְבָּרְכִים מִמֶּנּוּ, אָז חַיִּים וּרְפוּאָה תְּלוּיִים עָלָיו מִלְמַעְלָה. מִי גָרַם לוֹ? אוֹתָם יְמוֹת הַשָּׁנָה. יְמוֹת הַשָּׁנָה, כְּמוֹ שֶׁמִּתְבָּרְכִים מִלְמַעְלָה מִסּוֹד שֶׁל אָדָם, כָּךְ גַּם מִתְבָּרְכִים לְמַטָּה מִסּוֹד שֶׁל אָדָם.</p>\n<p>אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה, בְּאוֹתָם מִצְווֹת הַתּוֹרָה, שֶׁנִּקְרָאִים אָדָם, שֶׁכָּתוּב (יחזקאל לד) אָדָם אַתֶּם. אַתֶּם קְרוּיִים אָדָם, וְאֻמּוֹת הָעוֹלָם לֹא קְרוּיִים אָדָם. וּמִשּׁוּם שֶׁיִּשְׂרָאֵל נִקְרְאוּ אָדָם, יֵשׁ לָהֶם לְהִשְׁתַּדֵּל בְּאוֹתָן מִצְווֹת הַתּוֹרָה לִהְיוֹת הַכֹּל אֶחָד בְּסוֹד שֶׁל אָדָם.</p>\n<p>כְּשֶׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹרָה לְיִשְׂרָאֵל עַל הַר סִינַי, דָּבָר רִאשׁוֹן הוּא אָנֹכִי. אָנֹכִי עוֹלֶה לְסוֹדוֹת (עולמות) רַבִּים, וְכָאן הוּא סוֹד שֶׁל מִצְוָה רִאשׁוֹנָה לְהַכִּיר אוֹתוֹ בַּכְּלָל. מִשּׁוּם שֶׁכָּתוּב אָנֹכִי, הֲרֵי רוֹמֵז שֶׁיֵּשׁ אֱלוֹהַּ שַׁלִּיט עֶלְיוֹן (שהוא) עַל הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא, מִצְוָה רִאשׁוֹנָה בִּכְלָל. בִּפְרָט, מִשּׁוּם שֶׁכָּתוּב (בראשית כא) ה' אֱלֹהֶיךְ. זֶה פְּרָט, וְזֶה כְּלָל וּפְרָט, מִצְוָה רִאשׁוֹנָה, שֶׁצָּרִיךְ לָדַעַת בָּרֹאשׁ וּבַסּוֹף כְּפִי שֶׁבֵּאַרְנוּ. (ע\"כ רעיא מהימנא).</p>"],[9522011566,"<p>וַיְדַבֵּר מֹשֶׁה כֵּן אֶל בְּנֵי יִשְׂרָאֵל וְלֹא שָׁמְעוּ אֶל מֹשֶׁה מִקֹּצֶר רוּחַ. מַה זֶּה מִקֹּצֶר רוּחַ? אָמַר רַבִּי יְהוּדָה, שֶׁלֹּא הָיוּ נָחִים וְלֹא הָיוּ אוֹסְפִים לְתוֹכָם רוּחַ. אָמַר רַבִּי שִׁמְעוֹן, מִקֹּצֶר רוּחַ - שֶׁעֲדַיִן לֹא יָצָא יוֹבֵל לָתֵת לָהֶם מְנוּחָה. וְרוּחַ אַחֲרוֹנָה עֲדַיִן לֹא שָׁלְטָה לַעֲשׂוֹת מִנְהָגָם, וְאָז הָיוּ בְּצָרוֹת שֶׁל רוּחַ, מוּעָקָה שֶׁל רוּחַ. מִיהוּ? רוּחַ אַחֲרוֹנָה, כְּמוֹ שֶׁאָמַרְנוּ. (שעד שלא נתן היובל ברכה על הרוח הזו להתקים הגפש התחתונה, ולא שולטת הרוח הזו על הגפש אלא כאשר מתברכת מהיובל, אז תהיה רוח. ומי היא הרוח הזו, ' יעקב, שכתוב ותחי רוח יעקב וגו').</p>"],[9522011567,"<p>בֹּא רְאֵה, כָּתוּב הֵן בְּנֵי יִשְׂרָאֵל לֹא שָׁמְעוּ אֵלַי וְאֵיךְ יִשְׁמָעֵנִי פַרְעֹה וַאֲנִי עֲרַל שְׂפָתָיִם. מַה זֶּה וַאֲנִי עֲרַל שְׂפָתָיִם, וַהֲרֵי בַּתְּחִלָּה כָּתוּב לֹא אִישׁ דְּבָרִים אָנֹכִי וְגוֹ' כִּי כְבַד פֶּה וּכְבַד לָשׁוֹן אָנֹכִי, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מֵשִׁיב לוֹ, מִי שָׂם פֶּה לָאָדָם וְכוּ', וְהוּא אָמַר וְאָנֹכִי אֶהְיֶה עִם פִּיךְ, הֲתַעֲלֶה עַל דַּעְתְּךְ שֶׁלֹּא הָיָה כָּךְ? וְעַתָּה אוֹמֵר וַאֲנִי עֲרַל שְׂפָתָיִם, אִם כָּךְ, אֵיפֹה הַדָּבָר שֶׁהִבְטִיחַ לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרִאשׁוֹנָה?</p>\n<p>אֶלָּא סוֹד הוּא. מֹשֶׁה הוּא קוֹל, וְהַדִּבּוּר שֶׁהוּא הַדִּבּוּר שֶׁלּוֹ הָיָה בַּגָּלוּת, וְהוּא הָיָה אָטוּם מִלְּפָרֵשׁ דְּבָרִים, וּמִשּׁוּם כָּךְ אָמַר וְאֵיךְ יִשְׁמָעֵנִי פַרְעֹה, בְּעוֹד שֶׁהַדָּבָר שֶׁלִּי הִיא בַּגָּלוּת שֶׁלּוֹ, שֶׁהֲרֵי אֵין לִי דָּבָר. הֲרֵינִי קוֹל דָּבָר גָּרוּעַ, שֶׁהִיא בַּגָּלוּת, וְלָכֵן שִׁתֵּף הַקָּדוֹשׁ בָּרוּךְ הוּא עִמּוֹ אֶת אַהֲרֹן.</p>\n<p>בֹּא רְאֵה, כָּל זְמַן שֶׁהַדִּבּוּר הָיָה בַּגָּלוּת, הַקּוֹל הִסְתַּלֵּק מִמֶּנּוּ, וְהַדִּבּוּר הָיָה אָטוּם בְּלִי קוֹל. כְּשֶׁבָּא מֹשֶׁה בָּא הַקּוֹל, וּמֹשֶׁה הָיָה קוֹל בְּלִי דִבּוּר, מִשּׁוּם שֶׁהָיָה בַּגָּלוּת, וְכָל זְמַן שֶׁהַדִּבּוּר הָיָה בַּגָּלוּת, מֹשֶׁה הָלַךְ בְּקוֹל בְּלִי דִבּוּר, וְכָךְ הָלַךְ עַד שֶׁקָּרְבוּ לְהַר סִינַי וְנִתְּנָה תּוֹרָה, וּבְאוֹתוֹ זְמַן הִתְחַבֵּר קוֹל בְּדִבּוּר, וְאָז הַדָּבָר דִּבֵּר, זֶהוּ שֶׁכָּתוּב וַיְדַבֵּר אֱלֹהִים אֶת כָּל הַדְּבָרִים הָאֵלֶּה. וְאָז מֹשֶׁה נִמְצָא שָׁלֵם בַּדָּבָר כָּרָאוּי, קוֹל וְדִבּוּר אֶחָד בִּשְׁלֵמוּת.</p>\n<p>וְעַל כָּךְ מֹשֶׁה הִתְרַעֵם, שֶׁהַדִּבּוּר נִגְרַע מִמֶּנּוּ, פְּרָט לְאוֹתוֹ זְמַן שֶׁדִּבְּרָה לִרְגֹז עָלָיו, בִּזְמַן שֶׁכָּתוּב וּמֵאָז בָּאתִי אֶל פַּרְעֹה לְדַבֵּר בִּשְׁמֶךְ, מִיָּד - וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה. בֹּא רְאֵה שֶׁכָּךְ הוּא, שֶׁהִתְחִיל דָּבָר לְדַבֵּר וּמַפְסִיק אוֹתוֹ, מִשּׁוּם שֶׁעֲדַיִן לֹא הִגִּיעַ זְמַן שֶׁכָּתוּב וַיְדַבֵּר אֱלֹהִים וְגוֹ'. וּפָסַק וְהִשְׁלִים הַקּוֹל. זֶהוּ שֶׁכָּתוּב וַיֹּאמֶר אֵלָיו אֲנִי ה'. מִשּׁוּם שֶׁהַדִּבּוּר הָיָה בַּגָּלוּת וְלֹא הִגִּיעַ זְמַן לְדַבֵּר. (ובא ראה)</p>\n<p>מִשּׁוּם כָּךְ מֹשֶׁה לֹא הָיָה שָׁלֵם בַּדָּבָר בַּתְּחִלָּה, (שכך נראה) שֶׁהוּא קוֹל, וּבָא בִּשְׁבִיל דִּבּוּר לְהוֹצִיא אוֹתָהּ מִן הַגָּלוּת. כֵּיוָן שֶׁיָּצָא מִן הַגָּלוּת וְהִתְחַבְּרוּ קוֹל וְדִבּוּר כְּאֶחָד בְּהַר סִינַי, הִשְׁתַּלֵּם מֹשֶׁה וְנִרְפָּא, וְנִמְצָא אָז קוֹל וְדִבּוּר כְּאֶחָד בִּשְׁלֵמוּת.</p>\n<p>בֹּא רְאֵה, כָּל הַיָּמִים שֶׁהָיָה מֹשֶׁה בְּמִצְרַיִם שֶׁרָצָה לְהוֹצִיא הַדִּבּוּר מִן הַגָּלוּת, לֹא דִבֵּר דָּבָר שֶׁהוּא דִּבּוּר. כֵּיוָן שֶׁיָּצְאָה מִן הַגָּלוּת וְהִתְחַבֵּר קוֹל בְּדִבּוּר, אוֹתוֹ דָּבָר שֶׁהוּא דִּבּוּר הִנְהִיג וְהוֹלִיךְ אֶת יִשְׂרָאֵל, אֲבָל לֹא דִבֵּר, עַד שֶׁקָּרְבוּ לְהַר סִינַי וּפָתַח בַּתּוֹרָה, שֶׁכָּךְ רָאוּי. וְאִם תֹּאמַר, כִּי אָמַר אֱלֹהִים פֶּן יִנָּחֵם הָעָם, לֹא כָתוּב כִּי דִבֵּר, אֶלָּא כִּי אָמַר, שֶׁהוּא רְצוֹן הַלֵּב בַּחֲשַׁאי, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה וַיֹּאמֶר אֵלָיו אֲנִי ה'. רַבִּי יְהוּדָה פָּתַח, קַמְתִּי אֲנִי לִפְתֹּחַ לְדוֹדִי וְדוֹדִי חָמַק עָבָר וְגוֹ'. קַמְתִּי אֲנִי לִפְתֹּחַ לְדוֹדִי - זֶה קוֹל. בֹּא רְאֵה, כְּנֶסֶת יִשְׂרָאֵל, כְּשֶׁהִיא בַּגָּלוּת, קוֹל מִסְתַּלֵּק מִמֶּנָּה, וְהַדִּבּוּר נִשְׁתַּתֵּק מִמֶּנָּה, כְּמוֹ שֶׁנֶּאֱמַר נֶאֱלַמְתִּי דוּמִיָּה. וְאִם מִתְעוֹרֵר דָּבָר, מַה כָּתוּב? וְדוֹדִי חָמַק עָבָר, שֶׁהֲרֵי קוֹל הִסְתַּלֵּק מִמֶּנָּה וְנִפְסַק הַדִּבּוּר, וְעַל זֶה וַיְדַבֵּר אֱלֹהִים אֶל מֹשֶׁה. הִתְחִילָה לְדַבֵּר, וְהִפְסִיקָה וְשָׁתְקָה. אַחַר כָּךְ הִשְׁלִים הַקּוֹל וְאָמַר וַיֹּאמֶר אֵלָיו אֲנִי ה'.</p>\n<p>וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב. בְּיַעֲקֹב תּוֹסֶפֶת וָא\"ו, שֶׁהוּא בְּחִיר הָאָבוֹת, כְּמוֹ שֶׁנֶּאֱמַר אֱלֹהֵי אַבְרָהָם אֱלֹהֵי יִצְחָק וֵאלֹהֵי יַעֲקֹב. בְּיַעֲקֹב תּוֹסֶפת וָא\"ו. אָמַר רַבִּי יוֹסֵי, אִם כָּךְ, הֲרֵי כָּתוּב אֲנִי ה' אֱלֹהֵי אַבְרָהָם אָבִיךְ וֵאלֹהֵי יִצְחָק. הֲרֵי בְּיִצְחָק תּוֹסֶפֶת וָא\"ו?</p>\n<p>אָמַר לוֹ, יָפֶה הָיָה, מִשּׁוּם שֶׁיַּעֲקֹב הָיָה קַיָּם, וְהִכְלִיל אֶת יַעֲקֹב בְּיִצְחָק, (שהיה מת) שֶׁחָשְׁכוּ עֵינָיו וְהָיָה כְמֵת, שֶׁהֲרֵי בְּעוֹד הָאָדָם קַיָּם בָּעוֹלָם הַזֶּה, לֹא נִזְכָּר עָלָיו הַשֵּׁם הַקָּדוֹשׁ, וְעַל כֵּן הִכְלִיל אוֹתוֹ בְּיִצְחָק. עַכְשָׁו שֶׁמֵּת יַעֲקֹב, בָּא הַדָּבָר לִמְקוֹמוֹ. זֶהוּ שֶׁכָּתוּב וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב, בְּתוֹסֶפֶת ו'.</p>\n<p>בְּאֵל שַׁדָּי - נִרְאֵיתִי לָהֶם מִתּוֹךְ אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה, וְלֹא נִרְאֵיתִי מִתּוֹךְ אַסְפַּקְלַרְיָה הַמְּאִירָה. וְאִם תֹּאמַר שֶׁהֲרֵי הִשְׁתַּמְּשׁוּ בִּנְקֵבָה לְבַד וְלֹא יוֹתֵר - בֹּא רְאֵה שֶׁאֵינָם נִפְרָדִים לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב וְגַם הֲקִמֹתִי אֶת בְּרִיתִי אִתָּם, שֶׁהֲרֵי הַבְּרִית הִתְחַבְּרָה עִמָּהּ.</p>\n<p>מֵהַקָּדוֹשׁ בָּרוּךְ הוּא יֵשׁ לָאָדָם לִלְמֹד, שֶׁהֲרֵי הוּא אָמַר שֶׁלֹּא נוֹדָע לָהֶם, שֶׁכָּתוּב בְּאֵל שַׁדָּי, וְכָתוּב וְגַם הֲקִמֹתִי אֶת בְּרִיתִי אִתָּם, כְּדֵי לְקַיֵּם הַבְּרִית בְּיִחוּד אֶחָד, וְגַם הֲקִמֹתִי אֶת בְּרִיתִי אִתָּם וְגוֹ'. הֲרֵי נֶאֱמַר, מִי שֶׁזּוֹכֶה לִבְרִית יוֹרֵשׁ אֶת הָאָרֶץ.</p>"],[9522011568,"<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ מְצוּיִים יוֹם אֶחָד לִפְנֵי רַבִּי שִׁמְעוֹן. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, גּוּרוּ לָכֶם מִפְּנֵי חֶרֶב כִּי חֵמָה עֲונוֹת חָרֶב לְמַעַן תֵּדְעוּן שַׁדּוּן. שַׁדִּין כָּתוּב. גּוּרוּ לָכֶם מִפְּנֵי חֶרֶב, אֵיזוֹ חֶרֶב? זוֹ (ויקרא כו) חֶרֶב נֹקֶמֶת נְקַם בְּרִית, שֶׁהֲרֵי חֶרֶב זוֹ עוֹמֶדֶת לְהִסְתַּכֵּל עַל מִי שֶׁמְּשַׁקֵּר בַּבְּרִית. שֶׁכָּל מִי שֶׁמְּשַׁקֵּר בַּבְּרִית, הַנְּקָמָה שֶׁנּוֹקְמִים מִמֶּנּוּ זוֹ הַחֶרֶב הַזּוֹ.</p>\n<p>זֶהוּ שֶׁכָּתוּב כִּי חֵמָה עֲונוֹת חָרֶב. מָה הַטַּעַם? מִשּׁוּם שֶׁמִּי שֶׁמְּשַׁקֵּר בַּבְּרִית, מַפְרִיד אֶת הַתְּשׁוּקָה, וְלֹא נוֹטֵל מִי שֶׁנּוֹטֵל, וְלֹא נוֹתֵן לִמְקוֹמוֹ, שֶׁהֲרֵי לֹא הִתְעוֹרֵר אֶל מְקוֹמוֹ. וְכָל מִי שֶׁשּׁוֹמֵר אֶת הַבְּרִית הַזּוֹ, הוּא גוֹרֵם לַהִתְעוֹרְרוּת שֶׁל בְּרִית זוֹ לִמְקוֹמָהּ, וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>מִי מְעוֹרֵר בְּרִית זוֹ לִמְקוֹמָהּ? כְּשֶׁנִּמְצָאִים צַדִּיקִים בָּעוֹלָם. מִנַּיִן לָנוּ? מִכָּאן, שֶׁכָּתוּב וְגַם הֲקִמֹתִי אֶת בְּרִיתִי אִתָּם לָתֵת לָהֶם אֶת אֶרֶץ כְּנָעַן אֵת אֶרֶץ מְגֻרֵיהֶם. מַה זֶּה מְגֻרֵיהֶם? כְּמוֹ שֶׁנֶּאֱמַר גּוּרוּ לָכֶם מִפְּנֵי חֶרֶב, מִשּׁוּם שֶׁהוּא מָקוֹם שֶׁמַּטִּיל מָגוֹר בָּעוֹלָם, וְעַל זֶה גּוּרוּ לָכֶם מִפְּנֵי חֶרֶב.</p>\n<p>אֲשֶׁר גָּרוּ בָהּ, מִיּוֹם שֶׁהִתְקָרְבוּ לַקָּדוֹשׁ-בָּרוּךְ-הוּא פָּחֲדוּ בָהּ פַּחַד, וּפַחַד (ופחדו פחד) עֶלְיוֹן בָּהּ לִשְׁמֹר מִצְווֹתָיו. שֶׁאִם בָּזֶה לֹא יַטִּיל פַּחַד (שהרי אם לא יטיל) עַל רֹאשׁ הָאָדָם, לֹא יִפְחַד מֵהַקָּדוֹשׁ בָּרוּךְ הוּא לְעוֹלָמִים בִּשְׁאָר מִצְווֹתָיו.</p>\n<p>בֹּא רְאֵה, בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה, כְּשֶׁמִּתְעוֹרְרִים יִשְׂרָאֵל אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא וְצוֹוְחִים כְּנֶגְדּוֹ, מַה כָּתוּב? וָאֶזְכֹּר אֶת בְּרִיתִי, שֶׁהֲרֵי בַּבְּרִית יֵשׁ זָכוֹר, וְאָז מִתְעוֹרֶרֶת תְּשׁוּקָה לִקְשֹׁר הַכֹּל בְּקֶשֶׁר אֶחָד. כֵּיוָן שֶׁבְּרִית זוֹ מִתְעוֹרֶרֶת, הֲרֵי הַקֶּשֶׁר שֶׁל הַכֹּל מִתְעוֹרֵר. וָאֶזְכֹּר אֶת בְּרִיתִי, לְזַוְּגוֹ בִּמְקוֹמוֹ. וְעַל כָּךְ, לָכֵן אֱמֹר לִבְנֵי יִשְׂרָאֵל אֲנִי ה'.</p>"],[9522011569,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה וְאֶל אַהֲרֹן וַיְצַוֵּם אֶל בְּנֵי יִשְׂרָאֵל וְאֶל פַּרְעֹה מֶלֶךְ מִצְרָיִם. רַבִּי יוֹסֵי אָמַר, אֶל בְּנֵי יִשְׂרָאֵל - לְהַנְהִיגָם בְּנַחַת כָּרָאוּי. וְאֶל פַּרְעֹה - לִנְהֹג בּוֹ כָּבוֹד, וּפֵרְשׁוּהָ.</p>\n<p>אָמַר רַבִּי יֵיסָא, לָמָּה סָמַךְ כָּאן אֵלֶּה רָאשֵׁי בֵית אֲבתָם? אֶלָּא, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, הַנְהִיגוּ אֶת בְּנֵי יִשְׂרָאֵל בְּנַחַת. שֶׁאַף עַל גַּב שֶׁהֵם יוֹשְׁבִים בַּעֲבוֹדָה קָשָׁה, הֵם מְלָכִים בְּנֵי מְלָכִים, וּמִשּׁוּם כָּךְ כָּתוּב אֵלֶּה רָאשֵׁי בֵית אֲבתָם. אֵלֶּה שֶׁאַתָּה רוֹאֶה, הֵם רָאשֵׁי בֵּית אָבוֹת.</p>\n<p>אָמַר רַבִּי חִיָּיא, שֶׁכֻּלָּם לֹא שִׁקְּרוּ בְּמִנְהֲגֵיהֶם, וְלֹא הִתְעָרְבוּ בְּעַם אַחֵר, אֵלֶּה הֵם שֶׁעָמְדוּ בִּמְקוֹמָם הַקָּדוֹשׁ וְלֹא שִׁקְּרוּ לְהִתְעָרֵב בַּמִּצְרִיִּים. אָמַר רַבִּי אָחָא, בִּשְׁבִיל לְהָבִיא אֶת מֹשֶׁה וְאֶת אַהֲרֹן, שֶׁהֵם רְאוּיִים לְהוֹצִיא אֶת יִשְׂרָאֵל וּלְדַבֵּר לְפַרְעֹה וְלִרְדּוֹת אוֹתָם בְּמַקֵּל, מִשּׁוּם שֶׁכָּל רָאשֵׁי יִשְׂרָאֵל לֹא נִמְצְאוּ כְמוֹתָם.</p>\n<p>בֹּא רְאֵה, וְאֶלְעָזָר בֶּן אַהֲרֹן לָקַח לוֹ מִבְּנוֹת פּוּטִיאֵל לוֹ לְאִשָּׁה וַתֵּלֶד לוֹ אֶת פִּינְחָס אֵלֶּה רָאשֵׁי אֲבוֹת הַלְוִיִּם. וְכִי אֵלֶּה רָאשֵׁי, וַהֲרֵי הוּא לְבַדּוֹ הָיָה? אֶלָּא מִשּׁוּם שֶׁפִּנְחָס קִיֵּם כַּמָּה אֲלָפִים וּרְבָבוֹת מִיִּשְׂרָאֵל וְהוּא קִיֵּם אֶת רָאשֵׁי הָאָבוֹת, (לוים) כָּתוּב בּוֹ אֵלֶּה.</p>\n<p>עוֹד, וַתֵּלֶד לוֹ אֶת פִּינְחָס אֵלֶּה רָאשֵׁי. אֲבֵדַת רָאשֵׁי הַלְוִיִּים נִמְצְאָה בּוֹ. וּמַה שֶּׁהֵם נִגְרְעוּ וְנִשְׂרְפוּ - הוּא הִשְׁלִים, וְהִרְוִיחַ אֶת הַכְּהֻנָּה שֶׁלָּהֶם, וְשָׁרְתָה בּוֹ הַצּוּרָה שֶׁל שְׁנֵיהֶם. אֲבֵדַת רָאשֵׁי הַלְוִיִּם נִמְצֵאת בּוֹ. וּמִי הֵם? נָדָב וַאֲבִיהוּא, שֶׁהִפְרִידוּ אוֹת הַבְּרִית מִמְּקוֹמוֹ, וְהוּא בָּא וְחִבֵּר אוֹתָם, לָכֵן נִתְּנָה לוֹ הַיְרֻשָּׁה וְהָרוּחַ שֶׁל שְׁנֵיהֶם, וְנִזְכַּר כָּאן עַל מַה שֶּׁיִּהְיֶה אַחַר כָּךְ.</p>\n<p>וְאִם תֹּאמַר, לָמָּה נִזְכַּר כָּאן פִּנְחָס? אֶלָּא רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אַהֲרֹן בְּשָׁעָה שֶׁאָמַר וָאֶזְכֹּר אֶת בְּרִיתִי, שֶׁעֲתִידִים שְׁנֵי בְנֵי אַהֲרֹן לִפְגֹּם אֶת הַבְּרִית הַזּוֹ, וְעַכְשָׁו שֶׁהוּא שׁוֹלֵחַ אוֹתוֹ לְמִצְרַיִם, רָצָה לְהַעֲבִיר אֶת אַהֲרֹן שֶׁלֹּא לָלֶכֶת בִּשְׁלִיחוּת זוֹ. כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁעָמַד פִּנְחָס וְקִיֵּם אֶת הַבְּרִית הַזּוֹ בִּמְקוֹמָהּ וְתִקֵּן אֶת הָעַקְמִימוּת שֶׁלָּהֶם, מִיָּד - הוּא אַהֲרֹן וּמֹשֶׁה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, עַכְשָׁו הוּא אַהֲרֹן, הוּא אַהֲרֹן שֶׁל הַהַתְחָלָה.</p>\n<p>הוּא אַהֲרֹן וּמֹשֶׁה אֲשֶׁר אָמַר ה' לָהֶם הוֹצִיאוּ אֶת בְּנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרַיִם וְגוֹ'. הוּא אַהֲרֹן וּמֹשֶׁה, הֵם אַהֲרֹן וּמֹשֶׁה הָיָה צָרִיךְ (לכתב) ! אֶלָּא לְהַכְלִיל זֶה בָּזֶה, רוּחַ בְּמַיִם. הוּא מֹשֶׁה וְאַהֲרֹן - לְהַכְלִיל מַיִם בְּרוּחַ, וְעַל זֶה כָּתוּב הוּא וְלֹא הֵם.</p>"],[9522011570,"<p>רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא הָיוּ מְצוּיִים לַיְלָה אֶחָד בְּבֵית מְלוֹנָם בְּלוֹד. קָמוּ לְהִתְעַסֵּק בַּתּוֹרָה. פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבֹתָ אֶת לְבָבֶךְ כִּי ה' הוּא הָאֱלֹהִים. פָּסוּק זֶה כָּךְ צָרִיךְ (לכתב): וְיָדַעְתָּ הַיּוֹם כִּי ה' הוּא הָאֱלֹהִים וַהֲשֵׁבתָ אֶל לְבָבֶךְ. (אלא אשריו מי שמשתדל בתורה.) עוֹד, (בא ראה) וַהֲשֵׁבֹתָ אֶל לִבֶּךְ הָיָה צָרִיךְ (לכתב) !</p>\n<p>אֶלָּא, אָמַר מֹשֶׁה, אִם אַתָּה רוֹצֶה לַעֲמֹד עַל זֶה וְלָדַעת כִּי ה' הוּא הָאֱלֹהִים - וַהֲשֵׁבֹתָ אֶל לְבָבֶךְ, וְאָז תֵּדַע אוֹתוֹ. לְבָבְךְ זֶה יֵצֶר טוֹב וְיֵצֶר רַע, שֶׁנִּכְלָל זֶה בָּזֶה, וְהוּא אֶחָד. אָז תִּמְצָא כִּי ה' הוּא הָאֱלֹהִים, שֶׁהֲרֵי נִכְלָל זֶה בָּזֶה וְהוּא אֶחָד, וְעַל זֶה וַהֲשֵׁבֹתָ אֶל לְבָבֶךְ לָדַעַת הַדָּבָר.</p>\n<p>עוֹד, אָמַר רַבִּי אֶלְעָזָר, רְשָׁעִים עוֹשִׂים פְּגָם לְמַעְלָה. מַהוּ הַפְּגָם? שֶׁהַשְּׂמֹאל לֹא נִכְלָל בַּיָּמִין, שֶׁיֵּצֶר הָרָע לֹא נִכְלָל בְּיֵצֶר טוֹב מִשּׁוּם חֲטָאֵי בְּנֵי הָאָדָם, וּפְגָם לֹא עוֹשִׂים אֶלָּא לָהֶם מַמָּשׁ, זֶהוּ שֶׁכָּתוּב שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם. כִּבְיָכוֹל עוֹשִׂים וְלֹא עוֹשִׂים. עוֹשִׂים - כְּדֵי שֶׁלֹּא יִמָּשְׁכוּ עֲלֵיהֶם בְּרָכוֹת שֶׁלְּמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר, וְלֹא עוֹשִׂים - שֶׁהֲרֵי הַשָּׁמַיִם נוֹטְלִים אוֹתָם לְעַצְמָם בְּרָכוֹת מַה שֶּׁצְּרִיכִים, וְלֹא נוֹטְלִים לְהַמְשִׁיךְ לְמַטָּה, וַדַּאי שֶׁזֶּהוּ מוּמָם שֶׁל אוֹתָם רְשָׁעִים.</p>\n<p>עוֹד, לוֹ בְּו', שֶׁלֹּא נִכְלָל יָמִין בִּשְׂמֹאל, בִּשְׁבִיל שֶׁלֹּא יִתְמַשְּׁכוּ הַבְּרָכוֹת לְמַטָּה. לֹא בְּאָלֶ\"ף, שֶׁהֲרֵי לֹא נוֹטְלִים לְהִמָּשֵׁךְ לַתַּחְתּוֹנִים. מִי גָרַם אֶת זֶה? מִשּׁוּם שֶׁרְשָׁעִים מַפְרִידִים יֵצֶר רַע מִיֵּצֶר טוֹב, וְנִדְבָּקִים בְּיֵצֶר רַע.</p>\n<p>בֹּא רְאֵה, יְהוּדָה בָּא מִצַּד הַשְּׂמֹאל וְנִדְבָּק בַּיָּמִין כְּדֵי לְנַצֵּחַ עַמִּים וְלִשְׁבֹּר חֵילָם. שֶׁאִם לֹא נִדְבָּק בַּיָּמִין, לֹא יִשְׁבֹּר אֶת חֵילָם. וְאִם תֹּאמַר לָמָּה בְּיָמִין, וַהֲרֵי שְׂמֹאל מְעוֹרֵר דִּינִים בָּעוֹלָם?</p>\n<p>אֶלָּא סוֹד זֶה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא דָּן אֶת יִשְׂרָאֵל, אֵינוֹ דָּן אוֹתָם אֶלָּא מִצַּד הַשְּׂמֹאל, כְּדֵי שֶׁיִּהְיֶה דוֹחֶה אוֹתָם בַּשְּׂמֹאל וּמְקָרֵב בַּיָּמִין. אֲבָל לִשְׁאָר הָעַמִּים דּוֹחֶה אוֹתָם בַּיָּמִין וּמְקָרֵב אוֹתָם בַּשְּׂמֹאל, וְסִימָנְךְ גֵּר צֶדֶק, דּוֹחֶה אוֹתָם בַּיָּמִין, כְּמוֹ שֶׁכָּתוּב (שמות טו) יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ יְמִינְךְ ה' תִּרְעַץ אוֹיֵב. מְקָרֵב אוֹתָם בַּשְּׂמֹאל, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>מִשּׁוּם כָּךְ, יְהוּדָה שֶׁהוּא מִצַּד שְׂמֹאל, נִדְבָּק בַּיָּמִין, וּמַסָּעוֹתָיו לְיָמִין, וְאוֹתָם שֶׁעִמּוֹ הִתְחַבְּרוּ כֻּלָּם לְיָמִין. יִשָּׂשכָר שֶׁעוֹסֵק בַּתּוֹרָה שֶׁהוּא יָמִין, שֶׁכָּתוּב מִימִינוֹ אֵשׁ דָּת לָמוֹ. זְבוּלוּן שֶׁהוּא תּוֹמֵךְ הַתּוֹרָה יָמִין, כַּנֶּאֱמַר שׁוֹק הַיָּמִין. וְלָכֵן יְהוּדָה נִקְשָׁר מִצַּד זֶה וָזֶה. צָפוֹן בְּמַיִם, שְׂמֹאל בְּיָמִין.</p>\n<p>רְאוּבֵן שֶׁחָטָא לְאָבִיו שָׁרָה בַּיָּמִין, וְהִתְקַשֵּׁר בַּשְּׂמֹאל, וְנִדְבַּק בּוֹ. וְלָכֵן אוֹתָם שֶׁנִּמְצְאוּ עִמּוֹ הֵם שְׂמֹאל. שִׁמְעוֹן שֶׁהוּא שְׂמֹאל מִצַּד שֶׁל שׁוֹר, שֶׁכָּתוּב וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. גָּד שׁוֹק שְׂמֹאל, כָּתוּב (בראשית מט) גָּד גְּדוּד יְגוּדֶנּוּ וְהוּא יָגֻד עָקֵב. כָּאן נִדְבַּק דָּרוֹם בְּאֵשׁ, יָמִין בִּשְׂמֹאל.</p>"],[9522011571,"<p>וְעַל זֶה זֶה שֶׁאָמַרְנוּ וַהֲשֵׁבתָ אֶל לְבָבֶךְ, לְהַכְלִילָם כְּאֶחָד, שְׂמֹאל בַּיָּמִין. אָז תֵּדַע (דברים ד) כִּי ה' הוּא הָאֱלֹהִים. אָמַר רַבִּי אַבָּא, וַדַּאי כָּךְ הוּא, וְעַכְשָׁו יָדוּעַ, הוּא אַהֲרֹן וּמֹשֶׁה, הוּא מֹשֶׁה וְאַהֲרֹן, רוּחַ בְּמַיִם, וּמַיִם בְּרוּחַ, לִהְיוֹת אֶחָד, וְעַל זֶה כָּתוּב הוּא.</p>\n<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (שם ו) וְאָהַבְתָּ אֶת ה' אֱלֹהֶיךְ בְּכָל לְבָבְךְ וּבְכָל נַפְשְׁךְ וּבְכָל מְאֹדֶךְ. כְּמוֹ זֶה כָּאן נִרְמָז הַיִּחוּד הַקָּדוֹשׁ, וְאַזְהָרָה הוּא לָאָדָם לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי בְּאַהֲבָה עֶלְיוֹנָה. בְּכָל לְבָבְךְ - זֶה יָמִין וּשְׂמֹאל (קדוש) שֶׁנִּקְרָאִים יֵצֶר טוֹב וְיֵצֶר רַע. וּבְכָל נַפְשְׁךְ - זוֹ נֶפֶשׁ דָּוִד שֶׁנִּתְּנָה בֵינֵיהֶם. וּבְכָל מְאֹדֶךְ - לְהַכְלִילָם לְמַעְלָה בְּמָקוֹם שֶׁאֵין בּוֹ שִׁעוּר. כָּאן הוּא יִחוּד שָׁלֵם לֶאֱהֹב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כָּרָאוּי.</p>\n<p>עוֹד, וּבְכָל מְאֹדֶךְ - זֶה יַעֲקֹב, שֶׁהוּא אָחוּז לְכָל הַצְּדָדִים, וְהַכֹּל הוּא יִחוּד שָׁלֵם כָּרָאוּי, מִשּׁוּם כָּךְ הוּא אַהֲרֹן וּמֹשֶׁה, הוּא מֹשֶׁה וְאַהֲרֹן, הַכֹּל הוּא אֶחָד בְּלִי פֵרוּד.</p>"],[9522011572,"<p>כִּי יְדַבֵּר אֲלֵכֶם פַּרְעֹה לֵאמֹר. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים קיט) מָה אָהַבְתִּי תוֹרָתֶךְ כָּל הַיּוֹם הִיא שִׂיחָתִי. וְכָתוּב חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ עַל מִשְׁפְּטֵי צִדְקֶךְ. בֹּא רְאֵה, דָּוִד הוּא מֶלֶךְ יִשְׂרָאֵל, וְהִצְטָרֵךְ לָדוּן אֶת הָעָם, לְהַנְהִיג אֶת יִשְׂרָאֵל כְּרוֹעֶה הַמַּנְהִיג צֹאנוֹ שֶׁלֹּא יִסְטוּ מִדֶּרֶךְ הָאֱמֶת. הֲרֵי בַּלַּיְלָה כָּתוּב חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ עַל מִשְׁפְּטֵי צִדְקֶךְ, וְהוּא מִתְעַסֵּק בַּתּוֹרָה וּבַתִּשְׁבָּחוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁמַּגִּיעַ הַבֹּקֶר.</p>\n<p>וְהוּא מְעוֹרֵר אֶת הַבּקֶר, כְּמוֹ שֶׁכָּתוּב (שם נז) עוּרָה כְבוֹדִי עוּרָה הַנֵּבֶל וְכִנּוֹר אָעִירָה שָּׁחַר. כְּשֶׁבָּא הַיּוֹם, אָמַר פָּסוּק זֶה, מָה אָהַבְתִּי תוֹרָתֶךְ כָּל הַיּוֹם הִיא שִׂיחָתִי. מַה זֶּה כָּל הַיּוֹם הִיא שִׂיחָתִי? אֶלָּא מִכָּאן לָמַדְנוּ, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה לְהַשְׁלִים הַדִּין עַל בֻּרְיוֹ, כְּאִלּוּ קִיֵּם אֶת הַתּוֹרָה כֻּלָּהּ. מִשּׁוּם כָּךְ כָּל הַיּוֹם הִיא שִׂיחָתִי.</p>\n<p>בֹּא רְאֵה, בַּיּוֹם הִתְעַסֵּק בַּתּוֹרָה לְהַשְׁלִים הַדִּינִים, וּבַלַּיְלָה הִתְעַסֵּק בְּשִׁירוֹת וְתִשְׁבָּחוֹת עַד שֶׁבָּא הַיּוֹם. מָה הַטַּעַם? כָּל הַיּוֹם הִתְעַסֵּק לְהַשְׁלִים הַדִּינִים כְּדֵי לְהַכְלִיל שְׂמֹאל בַּיָּמִין, בַּלַּיְלָה, כְּדֵי לְהַכְלִיל דַּרְגַּת הַלַּיְלָה בַּיּוֹם.</p>\n<p>וּבֹא רְאֵה, בִּימֵי דָוִד הַמֶּלֶךְ הָיָה מַקְרִיב כָּל אוֹתָם חַיְתוֹ שָׂדַי אֶל הַיָּם. כֵּיוָן שֶׁבָּא שְׁלֹמֹה, יָצָא הַיָּם וְהִתְמַלֵּא וְהִשְׁקָה אוֹתָם. אֵיזֶה מֵהֶם נִשְׁקִים בָּרִאשׁוֹנָה? הֲרֵי פֵּרְשׁוּהָ, אֵלּוּ הַתַּנִּינִים הַגְּדוֹלִים הָעֶלְיוֹנִים, שֶׁכָּתוּב בָּהֶם (בראשית א) וּמִלְאוּ אֶת הַמַּיִם בַּיַּמִּים.</p>"],[9522011573,"<p>אָמַר רַבִּי אֶלְעָזָר, בְּצַד יָמִין הָעֶלְיוֹן יוֹצְאִים שְׁלֹשָׁה עָשָׂר מַעְיָנוֹת עֶלְיוֹנִים נְהָרוֹת עֲמֻקִּים. אֵלֶּה עוֹלִים וְאֵלֶּה יוֹרְדִים. כָּל אֶחָד נִכְנָס בַּחֲבֵרוֹ. אֶחָד מוֹצִיא רֹאשׁוֹ וּמַכְנִיס אוֹתוֹ בִּשְׁנֵי גוּפִים, גּוּף אֶחָד הַמֵּאִיר נוֹטֵל מִיָּמִין לְמַעְלָה, מַפְרִיד לְמַטָּה אֶלֶף יְאוֹרִים שֶׁיּוֹצְאִים לְאַרְבָּעָה צְדָדִים.</p>\n<p>מֵאוֹתָם נְהָרוֹת וּמַעְיָנוֹת שְׁלֹשָׁה עָשָׂר, נִפְרָדִים שְׁלֹשָׁה עָשָׂר יְאוֹרִים. נִכְנָסִים וְנוֹטְלִים מַיִם אַרְבַּע מֵאוֹת וְתִשְׁעִים וְתִשְׁעָה יְאוֹרִים וָחֵצִי מִצַּד זֶה, וְאַרְבַּע מֵאוֹת וְתִשְׁעִים וְתִשְׁעָה יְאוֹרִים מִצַּד זֶה בִּשְׂמֹאל. נִשְׁאָר חֲצִי מִכָּאן וַחֲצִי מִכָּאן, וְנַעֲשֶׂה אֶחָד. זֶה נִכְנָס בֵּין הַיְאוֹרִים וְנַעֲשֶׂה נָחָשׁ.</p>\n<p>רֹאשׁוֹ אָדם כַּשּׁוֹשַׁנָּה. קַשְׂקַשָּׂיו קָשִׁים כְּבַרְזֶל. כְּנָפָיו כְּנָפַיִם שָׁטִים וְנִפְרָדִים לְכָל אוֹתָם יְאוֹרִים. כְּשֶׁעוֹלֶה זְנָבוֹ (אליו), מַכֶּה וּבוֹעֵט אֶת שְׁאָר הַדָּגִים. אֵין מִי שֶׁיָּקוּם לְפָנָיו.</p>\n<p>פִּיו לוֹהֵט אֵשׁ. כְּשֶׁנּוֹסֵעַ בְּכָל אוֹתָם יְאוֹרִים מִזְדַּעְזְעִים שְׁאָר הַתַּנִּינִים, וּבוֹרְחִים וְנִכְנָסִים לַיָּם. אַחַת לְשִׁבְעִים שָׁנָה רוֹבֵץ לְצַד זֶה, וְאַחַת לְשִׁבְעִים שָׁנָה רוֹבֵץ לְצַד זֶה. אֶלֶף יְאוֹרִים חָסֵר אֶחָד מִתְמַלְּאִים מִמֶּנּוּ. תַּנִּין זֶה רוֹבֵץ בֵּין אוֹתָם יְאוֹרִים.</p>\n<p>כְּשֶׁנּוֹסֵעַ, יוֹצֵאת פִּסַּת יָד שֶׁל אֵשׁ בַּקְּלִפּוֹת. כֻּלָּם עוֹמְדִים וְזוֹעֲפִים בְּזַעְפָּם, (ועומדים בענפיו) מִתְעָרְבִים אוֹתָם יְאוֹרִים לְעֵין (העין) תְּכֵלֶת שְׁחוֹרָה. וְגַלְגַּלִּים נוֹסְעִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. זוֹקֵף זְנָבוֹ, מַכֶּה לְמַעְלָה, מַכֶּה לְמַטָּה, וְכֻלָּם בּוֹרְחִים לְפָנָיו.</p>\n<p>עַד שֶׁלְּצַד צָפוֹן עוֹמֶדֶת שַׁלְהֶבֶת אֵשׁ אַחַת, וְהַכָּרוֹז יוֹצֵא: הִתְיַצְּבוּ זְקֵנוֹת וְהִתְפַּזְּרוּ לְאַרְבַּע זָוִיּוֹת, הֲרֵי הִתְעוֹרֵר מִי שֶׁשָּׂם קוֹלָר עַל פְּנֵי הַתַּנִּין, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאלכט) וְנָתַתִּי חַחִים בִּלְחָיֶיךְ וְגוֹ'. אָז כֻּלָּם הִתְפַּזְּרוּ, וְלוֹקְחִים אֶת הַתַּנִּין וְנוֹקְבִים פָּנָיו בְּצַד הַלְּחָיַיִם, וּמַכְנִיסִים אוֹתוֹ לְתוֹךְ נֶקֶב תְּהוֹם רַבָּה עַד שֶׁנִּשְׁבָּר כֹּחוֹ, וְאָז מַחֲזִירִים אוֹתוֹ לְנַהֲרוֹתָיו (לנחיריו).</p>\n<p>אַחַת לְשִׁבְעִים שָׁנָה עוֹשִׂים לוֹ כָּךְ, כְּדֵי שֶׁלֹּא יְקַלְקֵל מְקוֹמוֹתוֹהֶם שֶׁל הָרְקִיעִים וְעַמּוּדֵיהֶם, וַעֲלֵיהֶם הַכֹּל מוֹדִים וּמְבָרְכִים וְאוֹמְרִים, (תהלים צה) בּוֹאוּ נִשְׁתַּחֲוֶה וְנִכְרָעָה נִבְרְכָה לִפְנֵי ה' עוֹשֵׂנוּ.</p>\n<p>הַתַּנִּינִים נִכְנָסִים (העליונים) לְמַעְלָה, עוֹמְדִים אוֹתָם שֶׁמִּתְבָּרְכִים, כְּמוֹ שֶׁנֶּאֱמַר (בראשית א) וַיְבָרֶךְ אֹתָם אֱלֹהִים. אֵלּוּ שׁוֹלְטִים עַל כָּל שְׁאָר הַדָּגִים, שֶׁכָּתוּב וּמִלְאוּ אֶת הַמַּיִם בַּיַּמִּים. וְעַל זֶה כָּתוּב (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ.</p>"],[9522011574,"<p>אֶשְׁכּל הַכֹּפֶר דּוֹדִי לִי. אֶשְׁכֹּל - זוֹ הָאֵם הָעֶלְיוֹנָה. מָה אֶשְׁכּוֹל מִתְקַשֵּׁט בְּכַמָּה עָלִים בְּכַמָּה זְמוֹרוֹת לְיִשְׂרָאֵל שֶׁאוֹכְלִים אוֹתוֹ, כָּךְ הַשְּׁכִינָה הָעֶלְיוֹנָה מִתְקַשֶּׁטֶת בְּכַמָּה קִשּׁוּטִים שֶׁל שְׁמוֹנָה כֵלִים, מִכַּמָּה קָרְבָּנוֹת, מִכַּמָּה מִינֵי תַכְשִׁיטִים שֶׁל כַפָּרָה לְבָנֶיהָ, וְהִיא עוֹמֶדֶת בָּהֶם לִפְנֵי הַמֶּלֶךְ, וּמִיָּד - וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם, וְנוֹתֶנֶת (להם משאלותם) לָנוּ אֶת בַּקָּשׁוֹתֶיהָ בַּבְּרָכוֹת הַלָּלוּ שֶׁתִּקְּנוּ רַבּוֹתֵינוּ בַּתְּפִלָּה לְבַקֵּשׁ לִפְנֵי הַמֶּלֶךְ.</p>\n<p>בְּאוֹתוֹ זְמַן כָּל הַדִּינִים שֶׁל הַשְּׁכִינָה הַתַּחְתּוֹנָה, שֶׁהִיא הוה\"י אֲדנָ\"י, מִתְהַפְּכִים לְרַחֲמִים, כְּמוֹ זֶה יהו\"ה, לְקַיֵּם (ישעיה ה) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ - יהו\"ה. אִם יַאְדִּימוּ כַתּוֹלָע - הוה\"י. כַּצֶּמֶר יִהְיוּ - יהו\"ה. בְּכָל דִּינִים זֶה (כל הדינים של זה) מִתְלַבְּנִים מֵהַשְּׁכִינָה הָעֶלְיוֹנָה.</p>\n<p>וְהִיא הַשְּׁכִינָה הוה\"י, (בראשית ג) לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים. וּפֵרְשׁוּהָ רַבּוֹתֵינוּ, שֶׁמִּתְהַפֶּכֶת לִפְעָמִים רַחֲמִים, לִפְעָמִים דִּין, לִפְעָמִים אֲנָשִׁים, וְלִפְעָמִים נָשִׁים. לִפְעָמִים דִּין כְּמוֹ זֶה הוה\"י. לִפְעָמִים רַחֲמִים כְּמוֹ זֶה יהו\"ה. שֶׁהֲרֵי הוּא מִצַּד שֶׁל עֵץ הַחַיִּים, כָּל הַדִּינִים מִתְהַפְּכִים לְרַחֲמִים. וּמִצַּד שֶׁל עֵץ הַדַּעַת טוֹב וָרָע, כָּל הָרַחֲמִים מִתְהַפְּכִים לְדִין, לָדוּן בָּהֶם אֶת אוֹתָם שֶׁעוֹבְרִים עַל דִּבְרֵי הַתּוֹרָה.</p>\n<p>וְעֵץ זֶה בָּעוֹלָם הַבָּא, שֶׁהוּא בִּינָה, כָּל שְׁמוֹת הַדִּין מִתְהַפְּכִים בָּהּ (לדין) לְרַחֲמִים, מִשּׁוּם זֶה פֵּרְשׁוּהָ רַבּוֹתֵינוּ, לֹא כְּמוֹ הָעוֹלָם הַזֶּה הָעוֹלָם הַבָּא, וּמִשּׁוּם כָּךְ בִּינָה הִיא לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, שֶׁמִּתְהַפֶּכֶת מִדִּין לְרַחֲמִים לַצַּדִּיקִים, לָתֵת לָהֶם שָׂכָר בָּעוֹלָם הַבָּא. מַלְכוּת, לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת מֵרַחֲמִים לְדִין לָדוּן בָּהּ אֶת הָרְשָׁעִים בָּעוֹלָם הַזֶּה.</p>\n<p>אֲבָל מֵעֵץ הַדַּעַת טוֹב וָרָע, שֶׁהוּא כְּמוֹ הַמַּטֶּה, לִפְעָמִים מִתְהַפְּכִים הַנָּשִׁים לְשֵׁדוֹת, וַאֲנָשִׁים לְשֵׁדִים, וּמִשּׁוּם זֶה (בראשית כט) וַיַּגֵּד יַעֲקֹב לְרָחֵל. וּמִשּׁוּם זֶה פֵּרְשׁוּהָ רַבּוֹתֵינוּ, שֶׁאֵין לוֹ לְאָדָם לְשַׁמֵּשׁ עִם אִשְׁתּוֹ עַד שֶׁיְּסַפֵּר עִמָּהּ, שֶׁמָּא נִתְחַלְּפָה לוֹ בְּשֵׁדָה, מִשּׁוּם שֶׁלַּהַט בְּעֵץ הַדַּעַת טוֹב וָרָע מִתְהַפֶּכֶת מִטּוֹב לָרָע. וְאִם תֹּאמַר שֶׁהַמְּכַשְּׁפִים שֶׁל פַּרְעֹה, שֶׁכָּתוּב וַיַּעֲשׂוּ כֵן הַחַרְטֻמִּים בְּלָטֵיהֶם, הָיוּ מְהַפְּכִים אוֹתָם הַמַּטּוֹת שֶׁלָּהֶם לִנְחָשִׁים. וּמִצַּד שֶׁל אֵלֶּה הַהִתְהַפְּכוּת יְכוֹלִים לְהִתְהַפֵּךְ. (ע\"כ תוספתא)</p>"],[9522011575,"<p>וְאָמַרְתָּ אֶל אַהֲרֹן קַח אֶת מַטְּךְ. מָה הַטַּעַם מַטֵּה אַהֲרֹן וְלא מַטֵּה מֹשֶׁה? אֶלָּא אוֹתוֹ שֶׁל מֹשֶׁה יוֹתֵר קָדוֹשׁ, שֶׁנֶּחְקַק בַּגָּן הָעֶלְיוֹן בַּשֵּׁם הַקָּדוֹשׁ, וְלֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְטַמֵּא אוֹתוֹ בְּאוֹתָם מַטּוֹת שֶׁל הַמְּכַשְּׁפִים, וְלֹא עוֹד, אֶלָּא לִכְפּוֹת אוֹתָם לְכָל אוֹתָם הַבָּאִים מִצַּד הַשְּׂמֹאל, מִשּׁוּם שֶׁאַהֲרֹן בָּא מִיָּמִין, וְהַשְּׂמֹאל נִכְפֶּה לַיָּמִין.</p>\n<p>רַבִּי חִיָּיא שָׁאַל אֶת רַבִּי יוֹסֵי, הֲרֵי גָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאוֹתָם מְכַשְּׁפִים יַעֲשׂוּ תַנִּינִים, מָה הַגְּבוּרָה לַעֲשׂוֹת לִפְנֵי פַרְעֹה תַּנִּינִים? אָמַר לוֹ, מִשּׁוּם שֶׁמִּשָּׁם הִיא הָרֵאשִׁית לְהַלְקוֹת, וּמֵרֵאשִׁית הַתַּנִּין מַתְחִיל שִׁלְטוֹנוֹ, (לשלטונו, ומתחלת שלטונו התחיל להלקות) אָז שְׂמֵחִים כָּל הַמְּכַשְּׁפִים, שֶׁהֲרֵי רֹאשׁ הַחָכְמָה שֶׁל הַנָּחָשׁ שֶׁלָּהֶם כָּךְ הָיְתָה. מִיָּד חָזַר אוֹתוֹ תַנִּין שֶׁל אַהֲרֹן לְעֵץ יָבֵשׁ וּבָלַע אוֹתָם.</p>\n<p>וְעַל זֶה תָּמְהוּ וְיָדוּע שֶׁשִּׁלְטוֹן עֶלְיוֹן יֵשׁ בָּאָרֶץ, שֶׁהֵם חָשְׁבוּ שֶׁזֶּה לְמַטָּה (למעלה), חוּץ מֵהֶם אֵין שִׁלְטוֹן לַעֲשׂוֹת דָּבָר, וְאָז וַיִּבְלַע מַטֵּה אַהֲרֹן. דַּוְקָא מַטֵּה אַהֲרֹן שֶׁחָזַר לְעֵץ וּבָלַע אוֹתָם.</p>\n<p>וְלָכֵן עָשָׂה אַהֲרֹן שְׁנֵי אוֹתוֹת, אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה. אֶחָד לְמַעְלָה, תַּנִּין עֶלְיוֹן שֶׁשּׁוֹלֵט עַל אוֹתָם שֶׁלָּהֶם. אֶחָד לְמַטָּה, שֶׁשּׁוֹלֵט הָעֵץ עַל הַתַּנִּין שֶׁלָּהֶם. וּפַרְעֹה הָיָה חָכָם מִכָּל מְכַשְּׁפָיו, וְהִסְתַּכֵּל שֶׁשִּׁלְטוֹן הָעֶלְיוֹן שׁוֹלֵט עַל הָאָרֶץ, שׁוֹלֵט לְמַעְלָה וְשׁוֹלֵט לְמַטָּה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אִם תֹּאמַר שֶׁכָּל מַה שֶּׁעוֹשִׂים הַמְכַשְּׁפִים אֵינוֹ אֶלָּא בְּמַרְאִית הָעַיִן, שֶׁכָּךְ נִרְאֶה וְלֹא יוֹתֵר - בָּא לְהַשְׁמִיעֵנוּ וַיִּהְיוּ דַּוְקָא, שֶׁכָּתוּב וַיִּהְיוּ לְתַנִּינִם. וְאָמַר רַבִּי יוֹסֵי, אֲפִלּוּ אוֹתָם תַּנִּינִים שֶׁלָּהֶם חַזְרוּ לִהְיוֹת עֵצִים, וְעֵץ אַהֲרֹן בָּלַע אוֹתָם.</p>\n<p>כָּתוּב (יחזקאל כט) הִנְנִי עָלֶיךְ פַּרְעֹה מֶלֶךְ מִצְרַיִם הַתַּנִּים הַגָּדוֹל הָרֹבֵץ בְּתוֹךְ יְאֹרָיו. מִשָּׁם רֵאשִׁית לְמַטָּה בַּשִּׁלְטוֹן שֶׁלָּהֶם, אֲבָל חָכְמָתָם לְמַטָּה מִכָּל הַדְּרָגוֹת (הם).</p>\n<p>בֹּא רְאֵה, חָכְמָתָם בִּדְרָגוֹת תַּחְתּוֹנוֹת לִכְפּוֹתָם לְאוֹתָן דְּרָגוֹת בִּדְרָגוֹת עֶלְיוֹנוֹת, רֹאשׁ שִׁלְטוֹנָם וְעִקָּר שֶׁלָּהֶם לְמַטָּה מֵאוֹתוֹ תַּנִּין, וּמִשְׁתַּלְשְׁלִים בַּתַּנִּין, שֶׁהֲרֵי מִשָּׁם נוֹטֵל חַיִל דַּרְגָּה עֶלְיוֹנָה שֶׁלָּהֶם, מַשְׁמַע שֶׁכָּתוּב אֲשֶׁר אַחַר הָרֵחָיִם.</p>\n<p>רַבִּי חִיָּיא הָיָה יוֹשֵׁב יוֹם אֶחָד עַל דֶּלֶת שַׁעַר שֶׁל אוּשָׁא. רָאָה אֶת רַבִּי אֶלְעָזָר קַטְפִירָא (סוג עוף) טָס אֵלָיו. אָמַר לוֹ לְרַבִּי אֶלְעָזָר, מַשְׁמָע שֶׁאֲפִלּוּ בְּדַרְכְּךְ הַכֹּל מִשְׁתּוֹקְקִים לָלֶכֶת אַחֲרֶיךְ. הֶחֱזִיר רֹאשׁוֹ וְרָאָה אוֹתוֹ. אָמַר, וַדַּאי יֵשׁ אֶצְלוֹ שְׁלִיחוּת, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה שְׁלִיחוּת בַּכֹּל, וְכַמָּה שְׁלוּחִים יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ- הוּא, שֶׁלֹּא תֹאמַר דְּבָרִים שֶׁיֵּשׁ בָּהֶם רוּחַ בִּלְבַד, אֶלָּא אֲפִלּוּ אוֹתָם דְּבָרִים שֶׁאֵין בָּהֶם רוּחַ.</p>\n<p>פָּתַח וְאָמַר, (חבקוק ב) כִּי אֶבֶן מִקִּיר תִּזְעָק וְכָפִיס מֵעֵץ יַעֲנֶנָּה. כַּמָּה יֵשׁ לָאָדָם לְהִזָּהֵר מֵחֲטָאָיו שֶׁלֹּא יֶחֱטָא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאִם יֹאמַר מִי יָעִיד בּוֹ? הֲרֵי אַבְנֵי בֵיתוֹ וְעֵצִים שֶׁל בֵּיתוֹ יָעִידוּ בוֹ. וְלִפְעָמִים הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה בָהֶם שְׁלִיחוּת. בּא רְאֵה, מַטֵּה אַהֲרֹן שֶׁהוּא עֵץ יָבֵשׁ, הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה בּוֹ אֶת רֵאשִׁית הַנִּסִּים, וּשְׁתֵּי שְׁלִיחֻיּוֹת נַעֲשׂוּ בוֹ. אֶחָד שֶׁהוּא עֵץ יָבֵשׁ וּבָלַע אֶת אוֹתָם הַתַּנִּינִים שֶׁלָּהֶם, וְאֶחָד שֶׁהֲרֵי לְשָׁעָה אַחַת חָזַר בְּרוּחַ וְנַעֲשָׂה בְּרִיָּה.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, תִּפַּח רוּחָם שֶׁל אוֹתָם שֶׁאוֹמְרִים, שֶׁלֹּא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת מֵתִים, וְאֵיךְ יַעֲשֶׂה מֵהֶם בְּרִיָּה חֲדָשָׁה. יָבֹאוּ יִרְאוּ אוֹתָם הַטִּפְּשִׁים אֶת הָרְשָׁעִים, הָרְחוֹקִים מִן הַתּוֹרָה, רְחוֹקִים מִמֶּנּוּ, בְּיַד אַהֲרֹן הָיָה מַטֶּה, עֵץ יָבֵשׁ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לְפִי שָׁעָה הָפַךְ אוֹתוֹ לִבְרִיָּה מְשֻׁנָּה בְּרוּחַ וָגוּף. אוֹתָם גּוּפִים שֶׁהָיוּ בָהֶם רוּחוֹת וּנְשָׁמוֹת קְדוֹשׁוֹת וְשָׁמְרוּ אֶת מִצְווֹת הַתּוֹרָה וְהִשְׁתַּדְּלוּ בַּתּוֹרָה יוֹמָם וָלַיְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא טָמַן אוֹתָם בְּעָפָר - אַחַר כָּךְ בַּזְּמַן שֶׁיְּחַדֵּשׁ אֶת הָעוֹלָם עַל אַחַת כַּמָּה וְכַמָּה שֶׁיַּעֲשֶׂה אוֹתָם בְּרִיָּה חֲדָשָׁה.</p>\n<p>אָמַר רַבִּי חִיָּיא, וְלֹא עוֹד, אֶלָּא שֶׁאוֹתוֹ גוּף שֶׁהָיָה, יָקוּם. מַשְׁמָע שֶׁכָּתוּב (ישעיה כו) יִחְיוּ מֵתֶיךְ וְלֹא כָתוּב יִבְרָא, מַשְׁמָע שֶׁהֵם בְּרִיּוֹת אֲבָל יִחְיוּ. שֶׁהֲרֵי עֶצֶם אַחַת נִשְׁאֶרֶת מִן הַגּוּף תַּחַת הָאֲדָמָה, וְהִיא לֹא נִרְקֶבֶת וְלֹא תִבְלֶה בֶּעָפָר לְעוֹלָמִים, וּבְאוֹתוֹ זְמַן הַקָּדוֹשׁ בָּרוּךְ הוּא יְבָרֵךְ אוֹתוֹ, וְיַעֲשֶׂה אוֹתוֹ כְּמוֹ שְׂאוֹר שֶׁבָּעִסָּה, וְתַעֲלֶה וְתִתְפַּשֵּׁט לְאַרְבַּע פִּנּוֹת, וּמִמֶּנָּה יִשְׁתַּכְלֵל הַגּוּף וְכָל אֵיבָרָיו, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יִתֵּן בּוֹ רוּחַ אַחַר כָּךְ. אָמַר לוֹ רַבִּי אֶלְעָזָר, כָּךְ הוּא. וּבֹא רְאֵה, אוֹתָהּ עֶצֶם בַּמָּה הִתְרַכְּכָה? בְּטַל, שֶׁכָּתוּב כִּי טַל אוֹרוֹת טַלֶּךְ וְגוֹ'.</p>"]]});
